# v1.6.580 — for #396 P2 ORGANIC. Per-step watchdog timeout +
# explicit failure-stub emission. The pre-v1.6.580 runner invoked
# the L1..L13 step generators sequentially without any per-step
# guard; if a step hung (network-bound oracle fetch, expensive
# per-document AST walking, malformed RST/MD inputs that defeat
# a walker), the runner produced no traceback, no log line, and
# no stub failure record — downstream `phase23_completion_audit`
# saw the missing file as "step emitted nothing" rather than
# "step failed", masking incomplete extraction.
#
# This module-level scaffolding provides:
#   * `_V1_6_580_StepTimeout` exception class.
#   * `_v1_6_580_step_timeout(seconds, step_name)` context
#     manager using SIGALRM (POSIX-only; falls through to no-op
#     on Windows where SIGALRM is unavailable).
#   * `_v1_6_580_run_step_with_watchdog(...)` wrapper that
#     invokes a step function under the watchdog; on timeout
#     OR unexpected exception, writes a stub `<layer>.json`
#     with `phase1_step_timeout=true` / `phase1_step_error=true`
#     + the failure metadata.
#
# Chip-AGNOSTIC: pure runner-hygiene scaffolding; no chip-class
# string literal participates.

class _V1_6_580_StepTimeout(Exception):
    """v1.6.580 — for #396 P2 ORGANIC. Raised by the watchdog
    when a phase1 step exceeds its per-step timeout budget."""
    pass


def protocol_dispatch_decision(ic_class: str):
    """ORGANIC-20260531 (v0.2.32) — fail-closed protocol-synth dispatch gate.

    The [14e/15] R55 block dispatches the ~80 hand-wired built-in protocol
    synths only if the detected ``ic_class`` is in the reachability set. If
    ``detect_ic_class`` ever returns a class that NO dispatch block fires for,
    the whole protocol-synth chain was SILENTLY skipped (the inline structural
    detectors — the real gate — never ran). This pure helper makes the decision
    EXPLICIT and testable:

    Returns a dict::

        {
          "reachable": bool,        # True  -> run the synth chain
          "ic_class": str,
          "dispatch_classes": sorted list,
          "all_ic_classes": sorted list,
          "signal": None | dict,    # explicit skip signal when NOT reachable
        }

    ``signal`` (a JSON-serialisable payload) is non-None ONLY when the class is
    unreachable — the caller writes it to ``reports/phase1/
    protocol_dispatch_skipped.json`` so the skip surfaces loudly instead of
    being masked. General: keyed purely on the class-taxonomy string, never on
    a chip / vendor / benchmark name.
    """
    from ic_class_profile import (
        protocol_synth_dispatch_classes as _dc,
        ALL_IC_CLASSES as _all,
    )
    dispatch = _dc()
    reachable = ic_class in dispatch
    signal = None
    if not reachable:
        signal = {
            "_schema_version": "1",
            "_comment": (
                "Phase-1 protocol-synth dispatch was SKIPPED because "
                "detect_ic_class returned an ic_class that is not in the "
                "dispatch reachability set. This is an EXPLICIT fail-closed "
                "signal (ORGANIC-20260531): the ~80 built-in protocol synths "
                "did not run for this class. Either the class is genuinely "
                "non-protocol (benign) or it must be added to "
                "PROTOCOL_SYNTH_DISPATCH_CLASSES in ic_class_profile.py."),
            "ic_class": ic_class,
            "dispatch_classes": sorted(dispatch),
            "all_ic_classes": sorted(_all),
            "unreachable": True,
        }
    return {
        "reachable": reachable,
        "ic_class": ic_class,
        "dispatch_classes": sorted(dispatch),
        "all_ic_classes": sorted(_all),
        "signal": signal,
    }


def _v1_6_580_log_runner_event(project, line: str) -> None:
    """v1.6.580 — for #396 P2. Append a single event line to the
    runner.log file under <project>/reports/phase1/. Best-effort:
    silently swallows exceptions on filesystem failure (the stub
    JSON is the authoritative record). Chip-AGNOSTIC."""
    try:
        report_dir = _pl.report_path(
            project, "phase1/runner.log").parent
        report_dir.mkdir(parents=True, exist_ok=True)
        log_path = report_dir / "runner.log"
        with open(log_path, "a", encoding="utf-8") as f:
            f.write(f"[v1.6.580] {line}\n")
    except Exception:
        return


class _v1_6_580_step_timeout:  # noqa: N801 — keep snake_case for ctx
    """v1.6.580 — for #396 P2 ORGANIC. Context manager that sets
    a SIGALRM-based per-step watchdog. Raises
    `_V1_6_580_StepTimeout` from inside the block when the alarm
    fires. On Windows (no SIGALRM), enters a no-op context so
    the runner still works (but without timeout protection).
    Chip-AGNOSTIC."""

    def __init__(self, seconds: int, step_name: str):
        self.seconds = max(1, int(seconds or 60))
        self.step_name = str(step_name or "unknown")
        self._old_handler = None
        self._alarmed = False

    def __enter__(self):
        try:
            import signal
            if not hasattr(signal, "SIGALRM"):
                return self
            def _handler(signum, frame):
                raise _V1_6_580_StepTimeout(
                    f"phase1 step '{self.step_name}' exceeded "
                    f"{self.seconds}s")
            self._old_handler = signal.signal(
                signal.SIGALRM, _handler)
            signal.alarm(self.seconds)
            self._alarmed = True
        except Exception:
            return self
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        try:
            import signal
            if self._alarmed and hasattr(signal, "SIGALRM"):
                signal.alarm(0)
                if self._old_handler is not None:
                    signal.signal(signal.SIGALRM, self._old_handler)
        except Exception:
            pass
        return False  # do not swallow exceptions


def _v1_6_580_write_failure_stub(
        project: Path, layer_name: str, payload: Dict[str, Any]
        ) -> None:
    """v1.6.580 — for #396 P2. Write a stub `<layer>.json` under
    `<project>/generated_docs/` carrying the failure metadata.
    Skips write when a real (non-stub) L-doc already exists for
    that layer. Chip-AGNOSTIC."""
    try:
        gd = _pl.generated_docs_dir(project)
        gd.mkdir(parents=True, exist_ok=True)
    except Exception:
        return
    stub_path = gd / f"{layer_name}.json"
    if stub_path.is_file():
        # Don't clobber a successful run.
        try:
            existing = json.loads(stub_path.read_text(
                encoding="utf-8"))
            if (isinstance(existing, dict)
                    and not existing.get("phase1_step_timeout")
                    and not existing.get("phase1_step_error")):
                return
        except Exception:
            pass
    payload = dict(payload)
    payload.setdefault("layer", layer_name)
    payload.setdefault("schema_version", 2)
    try:
        _stamp.dump(stub_path, payload)
    except Exception:
        return


def _v1_6_580_run_step_with_watchdog(
        step_fn,
        step_name: str,
        layer_name: str,
        project: Path,
        timeout_s: int = 60,
        ) -> Tuple[bool, Any]:
    """v1.6.580 — for #396 P2 ORGANIC. Run `step_fn(project)` (or
    `step_fn()` if it takes no args) under the SIGALRM watchdog.
    On timeout OR unexpected exception, write a stub
    `<layer>.json` carrying the failure metadata, log a runner
    event line, and return (False, None). On success return
    (True, step_result). Chip-AGNOSTIC."""
    try:
        with _v1_6_580_step_timeout(timeout_s, step_name):
            result = step_fn()
        return True, result
    except _V1_6_580_StepTimeout as e:
        stub = {
            "phase1_step_timeout": True,
            "step_name": step_name,
            "layer": layer_name,
            "timeout_s": int(timeout_s),
            "error": str(e),
            "extraction_strategy": "step_timeout_stub_v1_6_580",
        }
        _v1_6_580_write_failure_stub(project, layer_name, stub)
        _v1_6_580_log_runner_event(
            project,
            f"STEP_TIMEOUT layer={layer_name} step={step_name} "
            f"timeout={timeout_s}s",
        )
        return False, None
    except Exception as e:
        stub = {
            "phase1_step_error": True,
            "step_name": step_name,
            "layer": layer_name,
            "error_class": type(e).__name__,
            "error_message": str(e)[:1000],
            "extraction_strategy": "step_error_stub_v1_6_580",
        }
        _v1_6_580_write_failure_stub(project, layer_name, stub)
        _v1_6_580_log_runner_event(
            project,
            f"STEP_ERROR layer={layer_name} step={step_name} "
            f"{type(e).__name__}: {str(e)[:300]}",
        )
        return False, None


def _run(cmd: List[str], timeout: int = 60) -> Tuple[int, str, str]:
    try:
        cp = subprocess.run(cmd, capture_output=True, text=True,
                            timeout=timeout)
        return cp.returncode, cp.stdout, cp.stderr
    except FileNotFoundError:
        return 127, "", f"COMMAND_NOT_FOUND: {cmd[0]}"
    except subprocess.TimeoutExpired:
        return 124, "", f"TIMEOUT after {timeout}s"


def extract_pdf(p: Path) -> str:
    rc, out, _ = _run(["pdftotext", "-layout", str(p), "-"], timeout=60)
    return out if rc == 0 else ""


def extract_docx(p: Path) -> str:
    try:
        import docx
        d = docx.Document(str(p))
        parts = [para.text for para in d.paragraphs]
        for tbl in d.tables:
            for row in tbl.rows:
                parts.append("\t".join(c.text for c in row.cells))
        return "\n".join(parts)
    except Exception as e:
        return f"[docx-extract-failed: {e}]"


def _looks_like_binary_garbage(raw: bytes, text: str) -> bool:
    """ORGANIC-20260531-legacy-binary-office-doc-ingestion-depth (B).

    Chip-AGNOSTIC structural test for an un-decoded binary blob. Returns
    True when the decoded ``text`` is dominated by control characters
    (fraction of chars outside the printable/whitespace set above 5%) OR
    the raw bytes contain a NUL byte (OLE/BIFF compound files always do).
    Used so a legacy .doc/.xls that no decoder could read returns "" (the
    skip path records it as a KNOWN gap) instead of feeding raw OLE/BIFF
    bytes to every downstream L-doc extractor.
    """
    if not text:
        return False
    if b"\x00" in raw:
        return True
    ctrl = 0
    for ch in text:
        o = ord(ch)
        # Printable ASCII + common whitespace are "good"; everything else
        # in the C0/C1 control range counts as binary noise. CJK / latin-1
        # accented prose (o >= 0xA0) is NOT penalised.
        if o in (0x09, 0x0A, 0x0D):
            continue
        if 0x20 <= o <= 0x7E:
            continue
        if o >= 0xA0:
            continue
        ctrl += 1
    return ctrl > 0.05 * len(text)


def _libreoffice_convert_to_text(p: Path, target_filter: str) -> str:
    """ORGANIC-20260531-legacy-binary-office-doc-ingestion-depth (A).

    Headless LibreOffice conversion of a legacy binary office file to
    text. Mirrors doc_extract.py: copy to an ASCII-stem temp (handles
    CJK filenames), convert with `soffice`/`libreoffice`, and on failure
    retry with an isolated `-env:UserInstallation` profile. Returns the
    decoded text or "" when LibreOffice is unavailable / produced nothing.
    Chip-AGNOSTIC.
    """
    import tempfile
    soffice = shutil.which("soffice") or shutil.which("libreoffice")
    if not soffice:
        return ""
    try:
        with tempfile.TemporaryDirectory(prefix="lo_extract_") as td:
            tdp = Path(td)
            ascii_in = tdp / ("doc_" + str(abs(hash(p.name)))[:12] + p.suffix)
            shutil.copy2(p, ascii_in)
            _run([soffice, "--headless", "--convert-to", target_filter,
                  "--outdir", str(tdp), str(ascii_in)], timeout=180)
            cands = sorted(tdp.glob("*.txt")) + sorted(tdp.glob("*.csv"))
            for c in cands:
                if c.stat().st_size > 0:
                    return c.read_text(encoding="utf-8", errors="ignore")
    except Exception:
        pass
    # Retry with an isolated profile (LibreOffice sometimes refuses to
    # run headless against a shared user profile).
    try:
        with tempfile.TemporaryDirectory(prefix="lo_profile_") as profile_td, \
                tempfile.TemporaryDirectory(prefix="lo_out_") as out_td:
            tdp = Path(out_td)
            ascii_in = tdp / ("doc_" + str(abs(hash(p.name)))[:12] + p.suffix)
            shutil.copy2(p, ascii_in)
            _run([soffice, "--headless",
                  f"-env:UserInstallation=file://{profile_td}",
                  "--convert-to", target_filter,
                  "--outdir", str(tdp), str(ascii_in)], timeout=180)
            cands = sorted(tdp.glob("*.txt")) + sorted(tdp.glob("*.csv"))
            for c in cands:
                if c.stat().st_size > 0:
                    return c.read_text(encoding="utf-8", errors="ignore")
    except Exception:
        pass
    return ""


def extract_doc_legacy(p: Path) -> str:
    rc, out, _ = _run(["antiword", str(p)], timeout=60)
    if rc == 0 and out:
        return out
    rc, out, _ = _run(["catdoc", str(p)], timeout=60)
    if rc == 0 and out:
        return out
    # ORGANIC-20260531 (A): LibreOffice headless tier before the raw-byte
    # last resort. Decodes a real Word 97-2003 .doc to prose when
    # antiword/catdoc are absent but soffice/libreoffice is on PATH.
    lo = _libreoffice_convert_to_text(p, "txt:Text")
    if lo and lo.strip():
        return lo
    # ORGANIC-20260531 (B): last resort raw-byte decode — but NEVER feed
    # raw OLE bytes downstream. If the decoded string looks binary, return
    # "" so the existing skip path records it as a KNOWN gap instead.
    try:
        raw = p.read_bytes()
    except Exception:
        return ""
    decoded = raw.decode("utf-8", errors="ignore")
    if _looks_like_binary_garbage(raw, decoded):
        return ""
    return decoded


def extract_xls_legacy(p: Path) -> str:
    """ORGANIC-20260531-legacy-binary-office-doc-ingestion-depth (C).

    Decode a legacy .xls (BIFF) workbook. Tier 1: xlrd (BIFF reader),
    emitting tab-joined rows per sheet, mirroring extract_xlsx. Tier 2:
    LibreOffice headless --convert-to csv. Returns "" when neither is
    available so the skip path records the .xls gap (never raw BIFF
    bytes). Chip-AGNOSTIC.
    """
    try:
        import xlrd  # BIFF reader for legacy .xls
        wb = xlrd.open_workbook(str(p))
        out: List[str] = []
        for sheet in wb.sheets():
            out.append(f"=== sheet: {sheet.name} ===")
            for r in range(sheet.nrows):
                vals = sheet.row_values(r)
                if any(v not in (None, "") for v in vals):
                    out.append("\t".join(
                        str(v) if v not in (None, "") else "" for v in vals))
        if out:
            return "\n".join(out)
    except Exception:
        pass
    # Tier 2: LibreOffice headless CSV conversion.
    lo = _libreoffice_convert_to_text(p, "csv:Text")
    if lo and lo.strip():
        return lo
    return ""


def extract_xlsx(p: Path) -> str:
    try:
        import openpyxl
        wb = openpyxl.load_workbook(str(p), data_only=True)
        out: List[str] = []
        for sheet in wb.sheetnames:
            out.append(f"=== sheet: {sheet} ===")
            ws = wb[sheet]
            for row in ws.iter_rows(values_only=True):
                if any(c is not None for c in row):
                    out.append("\t".join(
                        str(c) if c is not None else "" for c in row))
        return "\n".join(out)
    except Exception as e:
        return f"[xlsx-extract-failed: {e}]"


def extract_pptx(p: Path) -> str:
    try:
        import pptx
        pres = pptx.Presentation(str(p))
        out: List[str] = []
        for i, slide in enumerate(pres.slides, 1):
            out.append(f"=== slide {i} ===")
            for shape in slide.shapes:
                if shape.has_text_frame:
                    for para in shape.text_frame.paragraphs:
                        text = "".join(r.text for r in para.runs)
                        if text.strip():
                            out.append(text)
                if shape.has_table:
                    for row in shape.table.rows:
                        out.append("\t".join(c.text for c in row.cells))
        return "\n".join(out)
    except Exception as e:
        return f"[pptx-extract-failed: {e}]"


# v1.6.350 — for #247 P3 ORGANIC. SPICE-netlist extractor. The
# doc-extractor dispatcher (`extract_one`) previously had no branch
# for SPICE-netlist extensions, so analog ICs that ship a top-cell
# netlist alongside their PDF datasheet got an empty L1.pin_table /
# L9.submodules / L5.design_parameters even when every chip-top pad,
# subcircuit, and design parameter sat in plain ASCII inside the
# `.cir` / `.sp` / `.spice` / `.cdl` file.
#
# Chip-AGNOSTIC: SPICE syntax is industry-standard and identical
# across every analog / mixed-signal IC. No chip-class literal
# participates in the regexes.
_V1_6_350_SPICE_NETLIST_SUFFIXES = frozenset({
    ".cir", ".sp", ".spice", ".cdl", ".net", ".ckt",
})

# v1.7.72 — for #499 defect 1. HDL-source extensions. Verilog /
# SystemVerilog design and package files are plain ASCII exactly like
# the SPICE netlists above; `extract_one` had no branch for them, so a
# design that stages its parameter / CSR package as ground truth had
# that document silently converted to the empty string. Chip-AGNOSTIC:
# these are IEEE-1364 / IEEE-1800 file-name conventions, not a
# chip-class literal.
_V1_7_72_HDL_SOURCE_SUFFIXES = frozenset({
    ".sv", ".v", ".svh", ".vh",
})

# `* pin <NAME>,<NET>` or `* pin <NAME> <NET>` — canonical SPICE
# pin-comment line used by Cadence Virtuoso, Synopsys, Mentor.
_V1_6_350_RE_SPICE_PIN_COMMENT = re.compile(
    r"^\s*\*\s*pin\s+(\w+)\s*[,\s]\s*(\w+)\s*$",
    re.MULTILINE | re.IGNORECASE,
)
# v1.6.401 — for #291 P3: relax pin-comment regex to also accept
# the single-token form `* pin NAME` that KLayout/Magic emit when
# the pad has no distinct bonded net or the LVS runset leaves the
# net bare. Net group is optional; emit with net=None when absent.
# Strict superset of v1.6.350: every two-token input that matched
# v1.6.350 still matches.
# Chip-AGNOSTIC: `* pin` is the canonical comment grammar.
_V1_6_401_RE_SPICE_PIN_COMMENT = re.compile(
    r"^\s*\*\s*pin\s+(?P<name>\w+)"
    r"(?:\s*[,\s]\s*(?P<net>\w+))?\s*$",
    re.MULTILINE | re.IGNORECASE,
)
# `.subckt <NAME> <PORT1> <PORT2> ...` — subcircuit header.
_V1_6_350_RE_SPICE_SUBCKT = re.compile(
    r"^\.subckt\s+(\w+)\s+([\w\s]+)$",
    re.MULTILINE | re.IGNORECASE,
)
# v1.6.353 — for #250 P4 KLayout/Magic-extracted netlist `|` net-alias
# delimiter + hierarchical `/` + decimal `.` + dash `-` in port-list.
# Extends v1.6.350 port character class. Strict SUPERSET of the
# v1.6.350 regex: every input that matched v1.6.350 still matches.
# Chip-AGNOSTIC: `|`, `/`, `.`, `-` are standard layout-extraction
# delimiters across open PDKs (sky130, SG13G2, gf180).
_RE_SPICE_SUBCKT_V1_6_353 = re.compile(
    r"^\.subckt\s+(\w+)\s+([\w\s|/.\-]+)$",
    re.MULTILINE | re.IGNORECASE,
)
# v1.6.355 — for #250 R2 Magic/KLayout split-net suffix `NET$N` support.
# Same `$` is the open-PDK extraction convention for splitting a single
# logical net into per-metal-layer fragments (e.g. CORE$1, CORE$2).
# Strict superset of v1.6.353 char class.
# The port class uses HORIZONTAL whitespace only. `\s` matches a newline, and
# under re.MULTILINE `$` matches at ANY line end, so a greedy `\s`-bearing
# class ran the header past its own line and swallowed the subckt BODY into the
# port list. MEASURED on a three-port cell:
#     `.subckt blk a b c` / `R1 a b 1k` / `.ends blk`
#         -> ports ['a','b','c','R1','a','b','1k','.ends','blk']
# and on an interface-only declaration `.subckt blk a b c` / `.ends blk`
#         -> ports ['a','b','c','.ends','blk']
# Only a comment line between header and body stopped it, so the bug was
# invisible on netlists that happen to carry one. Every consumer of
# `L9.submodules[].ports` was reading device names and literals as pins.
# The `+` continuation join above still works: it REMOVES the newline, so a
# folded pin list is one physical line by the time this scans.
_RE_SPICE_SUBCKT_V1_6_355 = re.compile(
    r"^\.subckt[ \t]+(\w+)[ \t]+([\w|/.\-$][\w|/.\-$ \t]*)$",
    re.MULTILINE | re.IGNORECASE,
)
# v1.6.355 — for #250 R2 strip Magic/KLayout `$N` split-net suffix
# and record `split_net_index`. Requires digits after `$`; bare
# trailing `$` is preserved verbatim (no match).
_RE_V1_6_355_SPLIT_NET_SUFFIX = re.compile(r"^(?P<base>.+?)\$(?P<idx>\d+)$")
# v1.6.448 — for #322 P2 canonical SPICE / KLayout LVS pin
# declaration with `+` continuation rows. The bare regex line-bound
# scan in v1.6.350/353/355 reads only the FIRST physical line of a
# `.SUBCKT NAME pin1 pin2 ...` header and silently drops every pin
# that lives on a `+ pinN+1 pinN+2 ...` continuation row. Real-world
# analog IC netlists routinely run 30-100 pins, none of which fit on
# a single 80-column header line — so a 45-pin .SUBCKT collapses to
# the 8 pins visible on the first line.
#
# Strategy: pre-process the netlist text by joining every `+ ...`
# continuation row to the preceding physical line BEFORE the regex
# scan runs. The grammar is the SPICE canonical: a line whose first
# non-whitespace character is `+` continues the previous logical
# line. After the join, the existing v1.6.355 single-line regex
# captures the full pin list. Strict superset of v1.6.355 — files
# without `+` continuation rows are unchanged byte-for-byte.
#
# Chip-AGNOSTIC: `+` continuation is the canonical SPICE / KLayout
# LVS / Cadence / Synopsys / Mentor grammar. No chip-name literals,
# no PDK-specific tokens.
_V1_6_448_RE_SPICE_CONTINUATION = re.compile(
    r"\n\+\s*", re.MULTILINE,
)


def _v1_6_448_join_spice_continuations(text: str) -> str:
    """v1.6.448 — for #322 P2 ORGANIC. Pre-process SPICE-netlist text
    by joining every `+` continuation row to its preceding physical
    line so that downstream `^...$` single-line regex scans pick up
    the full `.SUBCKT NAME pin1 pin2 ...` pin list across continuation
    rows.

    The canonical SPICE continuation grammar is: a line whose first
    non-whitespace character is `+` continues the previous logical
    line. A leading `+` followed by zero or more spaces is replaced
    with a single space; the trailing physical-line newline is
    consumed so the previous-line regex sees one merged logical line.

    Strict superset of the v1.6.355 walker — text without `+`
    continuation rows is byte-identical on return.

    Chip-AGNOSTIC: pure SPICE structural grammar.
    """
    if not isinstance(text, str) or not text:
        return text or ""
    return _V1_6_448_RE_SPICE_CONTINUATION.sub(" ", text)


# `.param NAME=VALUE` — single-line parameter definition.
_V1_6_350_RE_SPICE_PARAM = re.compile(
    r"^\.param\s+(\w+)\s*=\s*([\d.eE+\-]+\w*)\s*$",
    re.MULTILINE | re.IGNORECASE,
)


# v1.6.449 — for #323 P2 ORGANIC. SATA-protocol-context regex.
# Only protocol-name tokens (industry-standard, NOT chip-class
# literals) so this regex is chip-AGNOSTIC. The role of this gate
# is to corroborate the v1.6.121 `sata_timing_extractor` cluster
# (which fires on any document with two of {37.5, 75, 150} MHz)
# — a generic FPGA-fmax README on a non-SATA IC frequently lists
# 75 / 150 MHz as max-frequency claims for Spartan-6 / Kintex-7 /
# Artix-7, with no SATA mention. Without this gate the extractor
# emits `sata_sys_clk_75_mhz` / `sata_sys_clk_150_mhz` into the L8
# timing constants of any RV-CPU benchmark, polluting Phase 2.
#
# Allowed corroborating tokens: SATA (and variants SATAI / SATAII /
# SATAIII), the line-rate unit Gbps, the SATA-protocol acronyms
# OOB / NCQ / AHCI, litesata (LiteX SATA IP), SerDes, and the
# SATA-named clock-domain literals (sata_tx, sata_rx, sata_clk_ref).
_V1_6_449_RE_SATA_CONTEXT = re.compile(
    r"\b(SATA|Gbps|OOB|NCQ|AHCI|litesata|SerDes|SerDes-PHY|"
    r"sata_tx|sata_rx|sata_clk_ref|"
    r"SATAI|SATAII|SATAIII)\b",
    re.IGNORECASE,
)


def _v1_6_449_should_emit_sata_timing(file_text, mhz_hits) -> bool:
    """v1.6.449 — for #323 P2 ORGANIC. Chip-class context gate for
    the v1.6.121 `sata_timing_extractor` SATA-spec literal picker.

    Returns ``True`` only when BOTH conditions hold:
      1. The extractor returned at least 2 cluster hits (preserve
         the v1.6.121 `_MIN_HITS_PER_FILE=2` cluster floor — pure
         single-MHz mentions never promote).
      2. The same file contains at least one SATA-protocol token
         per ``_V1_6_449_RE_SATA_CONTEXT`` — pure protocol names
         (SATA / Gbps / OOB / NCQ / AHCI / litesata / SerDes /
         SATAI-III), industry-standard literals that are NOT
         chip-class identifiers.

    When either condition fails the cluster is treated as a
    coincidental MHz match (typical RV-CPU README listing FPGA
    fmax claims of 75 / 150 MHz with no SATA semantics) and
    silently dropped. The fallback path is to leave the L8
    timing-constants slot empty for that file; the existing
    `_flag_no_X_in_input` book-keeping records the empty result.

    Chip-AGNOSTIC: ``file_text`` is any extracted doc body and the
    corroboration regex carries only industry-standard SATA
    protocol tokens — no chip-class literals.
    """
    if not isinstance(file_text, str) or not file_text:
        return False
    try:
        if len(mhz_hits) < 2:
            return False
    except TypeError:
        return False
    if not _V1_6_449_RE_SATA_CONTEXT.search(file_text):
        return False
    return True


def _v1_6_353_normalize_subckt_port(port: str) -> dict:
    """v1.6.353 — for #250 P4 KLayout/Magic net-alias normalizer.

    Split ``PAD|RES`` (KLayout extraction convention where the
    primary name is followed by net aliases separated by ``|``) into
    ``{"name": "PAD", "aliases": ["RES"]}``. Multi-way aliases
    ``A|B|C`` become ``{"name": "A", "aliases": ["B", "C"]}``.
    Inputs without ``|`` yield ``aliases: []``.

    Chip-AGNOSTIC: ``|`` is the KLayout/Magic SPICE extraction
    convention across SG13G2 / sky130 / gf180 PDKs.
    """
    if not isinstance(port, str):
        return {"name": "", "aliases": []}
    if "|" in port:
        parts = [p for p in port.split("|") if p]
        if parts:
            return {"name": parts[0], "aliases": parts[1:]}
        return {"name": port, "aliases": []}
    return {"name": port, "aliases": []}


def _v1_6_355_normalize_subckt_port(port: str) -> dict:
    """v1.6.355 — for #250 R2 Magic/KLayout split-net suffix normalizer.

    Normalize one `.subckt` port literal:
      * split `PAD|RES` (KLayout net-alias) into ``{name, aliases}``
        (v1.6.353 contract preserved)
      * strip `NET$N` split-net suffix and record ``split_net_index``
        (new v1.6.355 behavior). The split-net rule applies to the
        BASE name only, not aliases — aliases are preserved verbatim
        after the pipe split. This keeps the schema small and
        unambiguous; alias-level split-net merging (if ever needed)
        can layer on top in a future ORGANIC follow-on.
      * bare trailing `$` with no digit is preserved verbatim
        (regex requires digits after `$`, so no strip occurs).

    v1.6.433 — for #310 P3. ALSO record the ``canonical_name`` —
    the `<base>_split<N>` form that uniquely identifies the split
    pin instance. Downstream consumers (L9 promotion, by-name
    look-ups) use ``canonical_name`` instead of ``name`` to keep
    distinct split pins distinct.

    Chip-AGNOSTIC: ``|`` and ``$N`` are PDK-agnostic extraction
    conventions across Magic / KLayout / SG13G2 / sky130 / gf180.
    """
    if not isinstance(port, str):
        return {"name": "", "aliases": []}
    # Pipe alias split (v1.6.353 contract preserved verbatim).
    if "|" in port:
        parts = [p for p in port.split("|") if p]
        if parts:
            name = parts[0]
            aliases = parts[1:]
        else:
            name = port
            aliases = []
    else:
        name = port
        aliases = []
    # Split-net suffix strip (v1.6.355 new behavior) — base name only.
    split_idx = None
    m = _RE_V1_6_355_SPLIT_NET_SUFFIX.match(name)
    if m:
        name = m.group("base")
        try:
            split_idx = int(m.group("idx"))
        except ValueError:
            split_idx = None
    # v1.6.433 — for #310 P3 ORGANIC. ONLY add the `canonical_name`
    # / `base_name` fields when the pin actually carries a split-net
    # suffix. Plain pins keep the legacy `{name, aliases}` dict
    # shape so all existing v1.6.353 / v1.6.355 schema consumers
    # continue to read the same keys. When a split-net suffix is
    # present, `canonical_name = <base>_split<N>` uniquely
    # identifies the instance so by-name look-ups downstream stop
    # collapsing two distinct pins into one.
    out = {"name": name, "aliases": aliases}
    if split_idx is not None:
        out["split_net_index"] = split_idx
        out["base_name"] = name
        out["canonical_name"] = f"{name}_split{split_idx}"
    return out


def _v1_6_350_parse_spice_metadata(text: str):
    """v1.6.350 — for #247 P3 ORGANIC. Parse a SPICE-netlist body
    and return ``{subckts: [...], pins: [...], params: [...]}``.

    * ``subckts[]`` — one entry per `.subckt` header with
      ``{name, ports[]}``.
    * ``pins[]`` — one entry per `* pin <NAME>,<NET>` comment with
      ``{name, net}``.
    * ``params[]`` — one entry per `.param NAME=VALUE` line with
      ``{name, value}``.

    All entries stamp ``extraction_strategy = "spice_netlist_v1"``
    for provenance.

    Chip-AGNOSTIC: pure SPICE structural-syntax regex.
    """
    out = {"subckts": [], "pins": [], "params": []}
    if not isinstance(text, str) or not text:
        return out
    # v1.6.448 — for #322 P2 ORGANIC. Join `+` continuation rows to
    # the preceding `.SUBCKT NAME pin1 pin2 ...` header line BEFORE
    # the single-line regex scan runs. Canonical SPICE / KLayout LVS
    # netlists fold long pin lists across continuation rows; without
    # the join the line-bound scan sees only the first 6-10 pins.
    # Strict superset of v1.6.355 — text without continuation rows is
    # byte-identical on return so all v1.6.355 fixtures still pass.
    text = _v1_6_448_join_spice_continuations(text)
    # v1.6.355 — for #250 R2. Use the v1.6.355 regex (strict superset
    # of v1.6.353; adds `$` to the port char class) so KLayout / Magic
    # layout-extracted netlists with `NET$N` split-net suffixes parse
    # instead of being skipped. Each port token is normalized via
    # `_v1_6_355_normalize_subckt_port`, which extends the v1.6.353
    # `|`-alias split with a `$N` split-net-suffix strip + optional
    # `split_net_index` field. The legacy `ports` list keeps the
    # base-name string only (alias-stripped, `$N` stripped), so the
    # v1.6.350 schema for downstream consumers stays compatible.
    for m in _RE_SPICE_SUBCKT_V1_6_355.finditer(text):
        name = (m.group(1) or "").strip()
        port_blob = (m.group(2) or "").strip()
        if not name:
            continue
        port_tokens = [p for p in port_blob.split() if p]
        ports_normalized = [
            _v1_6_355_normalize_subckt_port(p) for p in port_tokens
        ]
        # Legacy `ports` keeps the canonical base name (alias-stripped,
        # split-net suffix stripped) so v1.6.350 schema consumers
        # continue to work unchanged.
        # v1.6.433 — for #310 P3 ORGANIC. Use `canonical_name`
        # (`<base>_split<N>` for Magic split-net, plain name for
        # everything else) so multiple split-net pins with the same
        # base no longer collapse to a single duplicate entry in the
        # `ports` list. Pure structural deconfliction; downstream
        # consumers still see the base name via `base_name` field on
        # `ports_normalized[]` when needed.
        ports_legacy = [pn.get("canonical_name") or pn["name"]
                        for pn in ports_normalized]
        out["subckts"].append({
            "name": name,
            "ports": ports_legacy,
            "ports_normalized": ports_normalized,
            "extraction_strategy": "spice_netlist_v1",
        })
    # v1.6.401 — for #291 P3. Switched from v1.6.350 two-token-only
    # regex to v1.6.401 net-optional form so single-token pin
    # comments (`* pin NAME`) emitted by KLayout/Magic when the
    # pad lacks a distinct bonded net are no longer dropped.
    # v1.6.350 constant remains exported for backward compat with
    # any external pinned test.
    for m in _V1_6_401_RE_SPICE_PIN_COMMENT.finditer(text):
        pname = (m.group("name") or "").strip()
        pnet_raw = m.group("net")
        pnet = (pnet_raw or "").strip() if pnet_raw else None
        if not pname:
            continue
        out["pins"].append({
            "name": pname,
            "net": pnet,
            "extraction_strategy": "spice_netlist_v1",
        })
    for m in _V1_6_350_RE_SPICE_PARAM.finditer(text):
        pname = (m.group(1) or "").strip()
        pval = (m.group(2) or "").strip()
        if not pname:
            continue
        out["params"].append({
            "name": pname,
            "value": pval,
            "extraction_strategy": "spice_netlist_v1",
        })
    return out


def extract_one(p: Path) -> str:
    suf = p.suffix.lower()
    if suf == ".pdf":
        return extract_pdf(p)
    if suf == ".docx":
        return extract_docx(p)
    if suf == ".doc":
        return extract_doc_legacy(p)
    if suf == ".xlsx":
        return extract_xlsx(p)
    # ORGANIC-20260531-legacy-binary-office-doc-ingestion-depth (C):
    # legacy BIFF .xls — xlrd / LibreOffice / else skip (no raw BIFF bytes).
    if suf == ".xls":
        return extract_xls_legacy(p)
    if suf == ".pptx":
        return extract_pptx(p)
    if suf in (".txt", ".md"):
        try:
            return p.read_text(encoding="utf-8", errors="ignore")
        except Exception:
            return ""
    # v1.6.55 — closes ORGANIC-20260509-phase1-input-format-coverage-gap
    # (GitHub issue #3 BUG 2). Adds support for .odt / .rst / .adoc /
    # .html / extension-less plain-text files. Each converter is
    # best-effort and chip-AGNOSTIC.
    if suf == ".odt":
        return extract_odt(p)
    if suf in (".rst", ".adoc", ".asciidoc"):
        # RST and AsciiDoc markup is mostly readable as plain text.
        # The token harvester downstream is regex-based and tolerant.
        try:
            return p.read_text(encoding="utf-8", errors="ignore")
        except Exception:
            return ""
    if suf in (".html", ".htm"):
        return extract_html(p)
    # v1.6.93 — closes GitHub issue #26
    # (phase1-skip-ext-silent-drop-svg-dia). SVG and DIA are XML text
    # whose <text>/<title> and <dia:string> labels populate L9.submodules.
    # Tier 1 extraction via stdlib (xml.etree + gzip) — chip-AGNOSTIC.
    if suf == ".svg":
        return _extract_svg(p)
    if suf == ".dia":
        return _extract_dia(p)
    # v1.6.143 (#56) — raster image OCR Tier-2 ingest path.
    # `.png` / `.jpg` / etc. were previously dropped via `_SKIP_EXT`
    # so the v1.6.124 OCR scaffolding (png_ocr_extractor) never had
    # a chance to write `input_doc/<name>.png.txt`. Routing
    # rasters through `_extract_image_ocr` lets OCR text feed the
    # same extracted_docs map every other converter populates,
    # which downstream pickers (L9 submodule extraction, etc.)
    # already consume. Honors the existing PHASE2A_ENABLE_OCR
    # feature-flag + graceful-degradation contract — when OCR is
    # unavailable returns empty string and the caller records a
    # specific skip reason in extraction_skipped.json so the
    # silent-drop class of bugs stays visible.
    if suf in (".jpg", ".jpeg", ".png", ".gif", ".bmp",
                ".tiff", ".tif"):
        return _extract_image_ocr(p)
    # v1.6.350 — for #247 P3 ORGANIC. SPICE-netlist extensions
    # (`.cir`, `.sp`, `.spice`, `.cdl`, `.net`, `.ckt`). SPICE
    # syntax is plain-ASCII industry-standard; the file body is
    # read verbatim and downstream extractors pick `* pin` /
    # `.subckt` / `.param` lines for L1.pin_table / L9.submodules /
    # L5.design_parameters respectively. Chip-AGNOSTIC: SPICE
    # syntax is identical across every analog / mixed-signal IC.
    if suf in _V1_6_350_SPICE_NETLIST_SUFFIXES:
        try:
            return p.read_text(encoding="utf-8", errors="replace")
        except Exception:
            return ""
    # v1.7.72 — for #499 defect 1. HDL source (`.sv` / `.v` / `.svh` /
    # `.vh`) is the one plain-ASCII industry-standard format that fell
    # through this dispatch to `""`. A design that names an HDL package
    # as its parameter / CSR ground truth had that document silently
    # dropped: the runner recorded the drop in
    # `extraction_skipped.json` ("converter for extension '.sv'
    # returned empty") while every downstream metric read a clean zero.
    #
    # The asymmetry was the tell: SPICE netlists directly above are
    # ingested verbatim as plain ASCII, and extension-less files get a
    # text sniff — Verilog / SystemVerilog is not less plain-text than
    # either. Read verbatim, exactly like the SPICE branch; the
    # `typedef enum` harvester (`_hdl_enum.parse_typedef_enums`) then
    # lifts the declarations downstream. Chip-AGNOSTIC: HDL syntax is
    # identical across every digital IC.
    if suf in _V1_7_72_HDL_SOURCE_SUFFIXES:
        try:
            return p.read_text(encoding="utf-8", errors="replace")
        except Exception:
            return ""
    if suf == "":
        # Extension-less file — sniff and accept if it looks like text.
        return extract_extensionless_text(p)
    return ""


def extract_odt(p: Path) -> str:
    """ODT is a ZIP archive containing content.xml. Extract via
    Python's stdlib zipfile + xml.etree (no third-party deps)."""
    try:
        import zipfile
        import xml.etree.ElementTree as ET
        with zipfile.ZipFile(str(p)) as z:
            with z.open("content.xml") as f:
                tree = ET.parse(f)
        root = tree.getroot()
        # Strip XML namespaces; concatenate visible text.
        texts: List[str] = []
        for elem in root.iter():
            if elem.text and elem.text.strip():
                texts.append(elem.text)
            if elem.tail and elem.tail.strip():
                texts.append(elem.tail)
        return "\n".join(texts)
    except Exception:
        return ""


def extract_html(p: Path) -> str:
    """Strip HTML tags. No third-party dep — `re.sub` works because
    spec docs do not depend on subtle HTML semantics."""
    try:
        raw = p.read_text(encoding="utf-8", errors="ignore")
    except Exception:
        return ""
    # Drop <script> / <style> blocks entirely first.
    raw = re.sub(r"<(script|style)[^>]*>.*?</\1>", " ",
                 raw, flags=re.DOTALL | re.IGNORECASE)
    # Drop remaining tags.
    raw = re.sub(r"<[^>]+>", " ", raw)
    # Collapse whitespace.
    raw = re.sub(r"\s+", " ", raw)
    return raw.strip()


def extract_extensionless_text(p: Path) -> str:
    """Sniff the first 4 KB; if it looks like plain text (no NUL
    bytes, ≥95% printable / whitespace), return it as text. Avoids
    accidentally ingesting binary files saved without an extension."""
    try:
        head = p.read_bytes()[:4096]
    except Exception:
        return ""
    if not head:
        return ""
    if b"\x00" in head:
        return ""
    printable = sum(1 for b in head
                    if 0x20 <= b < 0x7F or b in (0x09, 0x0A, 0x0D))
    if printable / max(1, len(head)) < 0.95:
        return ""
    try:
        return p.read_text(encoding="utf-8", errors="ignore")
    except Exception:
        return ""


# v1.6.93 — closes GitHub issue #26.
#
# .svg and .dia were silently dropped by the prior _SKIP_EXT tuple even
# though both are XML text whose labels populate L9.submodules. The two
# extractors below are stdlib-only (xml.etree.ElementTree + gzip), so
# they require no new dependency, and chip-AGNOSTIC — they match by file
# extension and well-known XML element names, not by IC-specific
# vocabulary.

# v1.6.143 (#56) — raster image OCR converter. Honors the existing
# png_ocr_extractor feature-flag (PHASE2A_ENABLE_OCR=1) + import
# graceful-degradation contract. Returns empty string when OCR is
# not available; the caller (extract()) records a SPECIFIC skip
# reason (feature_flag_off vs tesseract_not_installed) so the
# silent-drop failure mode #56 reported stays observable.
def _extract_image_ocr(p: Path) -> str:
    """Tier-2 raster image OCR. Returns OCR text on success, empty
    string when OCR is unavailable (feature-flag off OR
    pytesseract/PIL missing OR the file is unreadable)."""
    try:
        import png_ocr_extractor as _ocr
    except Exception:
        return ""
    if not _ocr.is_ocr_runtime_available():
        return ""
    try:
        return _ocr._ocr_one(p) or ""
    except Exception:
        return ""


def _image_ocr_skip_reason() -> str:
    """Human-readable reason why a raster image was not OCRed, used
    by extraction_skipped.json when `_extract_image_ocr` returns
    empty. Distinguishes feature-flag-off from tesseract-missing."""
    try:
        import png_ocr_extractor as _ocr
    except Exception:
        return ("raster_image_no_ocr — png_ocr_extractor module not "
                "importable")
    if not _ocr.is_ocr_feature_enabled():
        return ("raster_image_no_ocr — PHASE2A_ENABLE_OCR not set; "
                "Tier-2 OCR deferred. Set PHASE2A_ENABLE_OCR=1 and "
                "install pytesseract+PIL+tesseract to enable.")
    try:
        import pytesseract  # noqa: F401
        from PIL import Image  # noqa: F401
    except ImportError as e:
        return (f"raster_image_no_ocr — OCR feature flag set but "
                f"runtime dep missing: {e}. Install pytesseract+PIL "
                f"and the system `tesseract` binary.")
    import shutil
    if not shutil.which("tesseract"):
        return ("raster_image_no_ocr — OCR feature flag set + Python "
                "deps present but system `tesseract` binary not on "
                "PATH; install OS package (e.g. apt install "
                "tesseract-ocr).")
    return ("raster_image_no_ocr — OCR pipeline available but "
            "returned empty text for this image (likely no readable "
            "labels rendered)")


def _extract_svg(p: Path) -> str:
    """Walk an SVG file and return one label per line in document order.

    Collects the text content of every <text> and <title> element,
    namespace-aware (the SVG default namespace is
    http://www.w3.org/2000/svg). Returns "" on any parse error so the
    caller's empty-text branch records the file in
    extraction_skipped.json with reason='converter returned empty'.
    """
    try:
        import xml.etree.ElementTree as ET
        tree = ET.parse(str(p))
    except Exception:
        return ""
    root = tree.getroot()
    labels: List[str] = []
    for elem in root.iter():
        tag = elem.tag
        # ElementTree expands `{ns}local` for namespaced elements; strip
        # the namespace before matching so both
        #   <text>foo</text>            (no namespace)
        #   <svg:text>foo</svg:text>    (xmlns="http://www.w3.org/2000/svg")
        # are caught uniformly.
        if "}" in tag:
            tag = tag.split("}", 1)[1]
        if tag not in ("text", "title", "tspan", "desc"):
            continue
        # itertext() gathers every descendant text node (handles
        # <text><tspan>foo</tspan></text> nesting common in editors).
        text = "".join(elem.itertext()).strip()
        if text:
            labels.append(text)
    return "\n".join(labels)


def _extract_dia(p: Path) -> str:
    """Walk a Dia (.dia) file and return one label per line.

    Dia files are gzip-compressed XML. We decompress with stdlib gzip
    then parse with xml.etree.ElementTree. Each <dia:string> element is
    typically wrapped in `#...#` padding (Dia's literal-string convention)
    which we strip. Returns "" on any error so the caller logs the file
    in extraction_skipped.json.
    """
    try:
        import gzip
        import xml.etree.ElementTree as ET
        with open(str(p), "rb") as fh:
            raw = fh.read()
        try:
            xml_bytes = gzip.decompress(raw)
        except OSError:
            # Some Dia files are stored uncompressed; try the raw bytes.
            xml_bytes = raw
        root = ET.fromstring(xml_bytes)
    except Exception:
        return ""
    labels: List[str] = []
    for elem in root.iter():
        tag = elem.tag
        if "}" in tag:
            tag = tag.split("}", 1)[1]
        if tag != "string":
            continue
        text = "".join(elem.itertext())
        # Dia wraps literal strings in '#'; strip leading/trailing '#'.
        text = text.strip()
        text = text.strip("#").strip()
        if text:
            labels.append(text)
    return "\n".join(labels)


# ---------------------------------------------------------------------------
# Pattern regexes (chip-AGNOSTIC)
# ---------------------------------------------------------------------------
_HEX_BYTE_RE   = re.compile(r"\b0x([0-9a-fA-F]{2})\b")
_OPCODE_PAT    = re.compile(
    r"^\s*([0-9a-fA-F]{2})\s+(?:[\|\t,]\s*)?([A-Z][A-Z_0-9]{2,30})",
    re.MULTILINE,
)
# v1.6.558 — for #378 P3 ORGANIC. Stricter non-newline opcode regex
# + image-derived source skip. Replaces the call-site use of
# `_OPCODE_PAT` for the Strategy 2 free-form `0xNN MNEM` walker only.
# Python's ``\s`` includes newline so the prior pattern matched the
# pair ``0xDC</text>\n<text>DIB`` glued across two SVG ``<text>``
# labels; constrain to space + tab only. Image-derived source files
# (``images__*.txt``, ``*__svg.txt``, ``*__png.txt``,
# ``*__pdf_image.txt``) carry SVG/PDF label text one entity per line
# — these are never authoritative opcode-table sources; skip them in
# defence-in-depth. Chip-AGNOSTIC: pure regex tightening + filename
# class filter.
_V1_6_558_OPCODE_PAT = re.compile(
    r"0x(?P<hex>[0-9A-Fa-f]{1,4})"
    r"[ \t]+(?:[\|,][ \t]*)?"
    r"(?P<mnem>[A-Z][A-Z0-9_]{1,15})",
    re.MULTILINE,
)
# v1.6.245 (#106) — bare-hex opcode form `NN MNEM` (no `0x` prefix),
# e.g. `70 SET_STATE`. The v1.6.558 tightening (above) added the
# mandatory `0x` prefix to defeat SVG/PDF cross-line label glue, but
# in doing so dropped the legacy bare-hex table form that real opcode
# tables also use. This sibling pattern restores it while keeping the
# anti-glue guards: it is anchored to START-OF-LINE (`^`) and uses a
# non-newline `[ \t]+` separator, so a stray hex token mid-prose or a
# label split across two lines cannot match. The opcode-synthesis
# gate + image-source skip still apply at the callsite. Chip-AGNOSTIC:
# pure structural regex.
_V1_6_245_BARE_OPCODE_PAT = re.compile(
    r"^[ \t]*(?P<hex>[0-9A-Fa-f]{2})"
    r"[ \t]+(?:[\|,][ \t]*)?"
    r"(?P<mnem>[A-Z][A-Z0-9_]{1,15})",
    re.MULTILINE,
)
_V1_6_558_IMAGE_SOURCE_RE = re.compile(
    r"(?:^|/)(?:images?__|.*__svg|.*__png|.*__pdf_image)",
    re.IGNORECASE,
)


def _v1_6_558_is_image_derived_source(fname):
    """Return True when ``fname`` (a key from the extracted-docs map)
    looks like an SVG / PNG / PDF-page-image-derived text dump. These
    files carry block-diagram label text one entity per line and were
    the source of cross-line ``0xNN MNEM`` false-positives at v1.6.557.
    """
    if not isinstance(fname, str) or not fname:
        return False
    return bool(_V1_6_558_IMAGE_SOURCE_RE.search(fname))


# ---------------------------------------------------------------------------
# for #454 — Strategy-2 ROW-SHAPE refusal.
#
# The Strategy-2 walkers (`_V1_6_558_OPCODE_PAT` / `_V1_6_245_BARE_OPCODE_PAT`)
# match a `<hex> <MNEMONIC>` pair on any single line of any extracted doc.
# The opcode-synthesis precondition is a DOCUMENT-level gate, so once it
# opens the walkers scrape the WHOLE document — including chapters that
# have the same two-column shape but carry no commands at all:
#
#   * a connector / pin-assignment table  -> `<pin index> <signal name>`
#   * a rate or capacity prose line       -> `<number> <unit>`
#   * a numeric-range declaration         -> `<lo>-<hi>` (the HI is matched)
#
# Each scraped row then receives a synthetic `response_opcode_hex = op + 1`
# and a single-byte echo `response_payload_template`, i.e. a fabricated
# command that no document ever declared.
#
# The predicates below refuse a row on its SHAPE alone. They are
# vocabulary-free on purpose — they key on notation and column layout, never
# on signal / rail / protocol names, so no design or vendor literal enters
# the logic:
#
#   `signal_name_notation`      the SIGNAL column (the token right after the
#                               matched hex, NOT the human-readable
#                               description column) is an active-low name
#                               `NAME#`, or a differential-pair / lane
#                               designator `NAMEp(3)` / `NAMEn3` /
#                               `NAMEp1 ("TX1+")`. Command mnemonics are
#                               never written in either notation.
#   `repeated_index_signal_column`
#                               the row carries a SECOND `<index> <signal>`
#                               column group — the two-up layout a connector
#                               pinout is printed in. A command table has one
#                               opcode per row.
#   `physical_unit_after_value` the value is DECIMAL and is followed by a
#                               physical unit of rate / capacity / frequency.
#                               An opcode encoding never carries a unit.
#   `hex_range_upper_bound`     the matched hex is the UPPER bound of an
#                               `0xAA-0xBB` range, so it is half of a
#                               declaration, not an encoding.
#
# Measured over the whole benchmark corpus that ships its input document
# (204 candidate rows / 17 designs): 64 rows refused, 0 of them from a real
# command-code table (0 false refusals against 63 genuine command rows).
# Refusals are COUNTED into the emitted L3 doc rather than dropped silently,
# so an empty `opcodes[]` can be told apart from a parser miss.
#
# Deliberately NOT refused: object-dictionary index tables, data-type /
# encoding tables, EtherType tables and register maps. Those rows are
# syntactically IDENTICAL to command rows (`0x1000  VAR  Device type` has
# the same shape as `0x00  PUT_PC  Put a posted transaction`); no row-level
# signal separates them, so filtering them would be guesswork.
# chip-AGNOSTIC.
# ---------------------------------------------------------------------------
_I454_RE_PHYSICAL_UNIT_AFTER_VALUE = re.compile(
    r"^[ \t]*\d{1,4}[ \t]+"
    r"(?:[GMKkTm]?[Bb][ \t]*/[ \t]*s"      # 10 GB/s, 26 MB/s, 25 Gb/s
    r"|[GMKkTm][Bb]\b(?![A-Za-z])"          # 16 GB, 512 MB
    r"|[GMk]?Hz"                            # 33 MHz
    r"|[GMk]?T[ \t]*/[ \t]*s)\b"            # 20 GT/s
)
_I454_RE_ACTIVE_LOW_SIGNAL = re.compile(r"^[A-Za-z][A-Za-z0-9_]*#")
_I454_RE_DIFF_PAIR_SIGNAL = re.compile(
    r"^[A-Za-z]{2,}[pn]\(\d+\)"             # HSOp(0) / HSIn(11)
    r"|^[A-Za-z]{3,}[pn]\d+\b"              # SSTXp1 / SSRXn2
    r"|^[A-Za-z]+[pn]\d?[ \t]*\(\"?[TR]X\d*[+\-−]\"?\)"
)
_I454_RE_SECOND_INDEX_SIGNAL_COLUMN = re.compile(
    r"\S[ \t]{2,}(?:[A-Z]?\d{1,3}|[A-Z]\d{1,2})[ \t]{2,}"
    r"[A-Za-z][A-Za-z0-9_()+\-]*"
)
_I454_RE_HEX_RANGE_UPPER_BOUND = re.compile(
    r"0x[0-9A-Fa-f]{1,4}[ \t]*[-–—][ \t]*$"
)


def _i454_signal_column(row_line, hex_token):
    """Return the row's SIGNAL / MNEMONIC column — the text starting at the
    token right after the matched hex. Explicitly NOT the trailing
    human-readable description column: a description may legitimately quote
    a rail or pin name while the row is still a command row.
    """
    if not isinstance(row_line, str) or not isinstance(hex_token, str):
        return ""
    for tok in ("0x" + hex_token, hex_token):
        idx = row_line.find(tok)
        if idx >= 0:
            return row_line[idx + len(tok):].lstrip(" \t|,")
    return ""


def _i454_non_command_row_reason(row_line, hex_token):
    """Return a short reason string when ``row_line`` is structurally NOT a
    command-table row, else None.

    ``row_line`` is the full source line the Strategy-2 walker matched and
    ``hex_token`` the hex it captured (without any ``0x`` prefix). Pure
    function of the row's shape — see the block comment above for the
    predicate set and its measured behaviour. chip-AGNOSTIC.
    """
    if not isinstance(row_line, str) or not row_line.strip():
        return None
    if _I454_RE_PHYSICAL_UNIT_AFTER_VALUE.match(row_line.lstrip("\r\n")):
        return "physical_unit_after_value"
    signal = _i454_signal_column(row_line, hex_token or "")
    if _I454_RE_ACTIVE_LOW_SIGNAL.match(signal) or \
            _I454_RE_DIFF_PAIR_SIGNAL.match(signal):
        return "signal_name_notation"
    if _I454_RE_SECOND_INDEX_SIGNAL_COLUMN.search(row_line):
        return "repeated_index_signal_column"
    head = row_line
    for tok in ("0x" + (hex_token or ""), hex_token or ""):
        idx = row_line.find(tok)
        if idx > 0:
            head = row_line[:idx]
            break
    if _I454_RE_HEX_RANGE_UPPER_BOUND.search(head):
        return "hex_range_upper_bound"
    return None


# ---------------------------------------------------------------------------
# for #454 follow-up — Strategy-1 BIT-POSITION-RULER row refusal.
#
# The Strategy-1 walker reads a 4-column row as
# `<rx_len> <tx_len> <tx_addr> <opcode_hex>`. A bus-protocol figure that
# draws a data word as adjacent bit fields prints its axis in exactly that
# shape — a run of DECIMAL bit indices:
#
#     31           24 23           16 15            8 7             0
#
# The walker reads column 4 as HEX, so the decimal bit index 16 becomes
# opcode `0x16`, and the callsite then synthesises `response_opcode_hex =
# op + 1`. The result is a command that no document ever declared.
#
# This was previously suppressed downstream by a HARD-CODED LIST OF EIGHT
# HEX VALUES in `phase1_post_process.HALLUC_PATTERNS`. That list was
# removed with this predicate because it was the wrong instrument twice
# over: it deleted those eight values out of ANY design's command table
# (a genuine `0x24`-class command was indistinguishable from the artefact),
# and it caught the artefact only where the ruler happened to land on one
# of its eight values — measured over six ruler offsets of the same shape
# it stopped four and let two through, while the predicate below stops all
# six.
#
# The predicate describes what a ruler IS, with no value and no vocabulary
# in it: the row is NOTHING BUT a strictly-descending run of decimal
# integers that partitions a contiguous range into equal-width fields —
#
#   * every token on the row is a plain decimal integer (a command row
#     carries a mnemonic, a byte group or a description after the opcode;
#     a ruler carries nothing else),
#   * an EVEN count of at least four of them, strictly descending,
#   * each consecutive `<hi> <lo>` pair spans the same width, >= 2, and
#   * every INNER boundary is adjacent (`lo_of_field_k == hi_of_field_k+1
#     + 1`), which is what makes the fields contiguous rather than an
#     arbitrary descending number sequence.
#
# Fail-open by construction: a ruler carrying a trailing caption is NOT
# refused. Refusals are counted into `non_command_row_refusal_count`
# alongside the Strategy-2 ones, so the silence stays visible.
# chip-AGNOSTIC.
# ---------------------------------------------------------------------------
_I454_RE_PLAIN_DECIMAL = re.compile(r"^\d+$")
_I454_RULER_MIN_FIELDS = 2          # >= 2 fields, i.e. >= 4 columns
_I454_RULER_MIN_FIELD_WIDTH = 2     # excludes a `3 2 1 0` degenerate run


def _i454_bit_position_ruler_row(row_line):
    """True when ``row_line`` is a bit-position ruler — a figure axis that
    partitions a contiguous numeric range into equal-width adjacent fields
    — rather than a command-table row. Pure function of the row's shape;
    see the block comment above. chip-AGNOSTIC.
    """
    if not isinstance(row_line, str) or not row_line.strip():
        return False
    values = []
    for tok in row_line.split():
        if not _I454_RE_PLAIN_DECIMAL.match(tok):
            # Anything that is not a bare decimal (a mnemonic, a hex byte,
            # a description, a caption) means the row carries content a
            # ruler does not have.
            return False
        values.append(int(tok))
    if len(values) < 2 * _I454_RULER_MIN_FIELDS or len(values) % 2:
        return False
    if any(values[i] <= values[i + 1] for i in range(len(values) - 1)):
        return False
    widths = {values[i] - values[i + 1] for i in range(0, len(values), 2)}
    if len(widths) != 1 or min(widths) < _I454_RULER_MIN_FIELD_WIDTH:
        return False
    # Inner boundaries: the low end of one field abuts the high end of the
    # next. This is what makes the run a PARTITION of one range.
    return all(values[i] == values[i + 1] + 1
               for i in range(1, len(values) - 1, 2))


# v0.1.90 — for ORGANIC-20260530-phase1-large-doc-hang. Several L-doc
# generators (L1 datasheet, L2 FRS, L4 reset-value prose lift, L5
# bullet-kv specs, L11 FSM-state classify, ...) run a PER-ITEM scan
# over the FULL extracted body of every document: for each register /
# token / candidate they `re.finditer`/`re.search` the entire text.
# That is O(items x text-length) and is fine for ordinary spec docs
# (a few hundred KB) but becomes effectively non-terminating on a
# pathologically large extraction — e.g. a 30 MB Bluetooth Core Spec
# PDF that renders to ~7.8 MB of text, where the runner froze for >1h
# at the L-doc emit phase.
#
# The guard is GENERAL and purely SIZE-based (no protocol / benchmark
# name): any single extracted document whose text exceeds
# `_LARGE_DOC_SCAN_CAP_BYTES` is truncated at the cap before being
# handed to the L-doc generators. Normal-size docs (every one of the
# 47 non-BLE benchmarks is well under the cap) are returned byte-for-
# byte unchanged, so their L*.json output is identical. Only a doc
# larger than the cap is bounded — and a 2 MB excerpt of a spec
# already carries the structural facts (datasheet header, register
# table, command set, FSM states) the extractors look for; the tail
# is overwhelmingly repeated normative prose that only inflates the
# per-item scan cost without adding new structured facts (the bare-
# hex prose scrape over that tail was itself the false-positive source
# flagged in the v1.6.558 / [14e3] sweep).
_LARGE_DOC_SCAN_CAP_BYTES = 2 * 1024 * 1024  # 2 MB per document


def _cap_extracted_for_scan(extracted: Dict[str, str]
                            ) -> Dict[str, str]:
    """Return a copy of ``extracted`` in which any single document whose
    text exceeds ``_LARGE_DOC_SCAN_CAP_BYTES`` is truncated to the cap
    (on a line boundary when one is available within the last 64 KB, so
    the truncation never splits a table row mid-line). Documents at or
    under the cap are passed through unchanged (same object), so the
    common case allocates nothing extra and produces identical output.

    GENERAL / chip-AGNOSTIC: size threshold only, no protocol literal.
    """
    if not isinstance(extracted, dict) or not extracted:
        return extracted
    capped: Dict[str, str] = {}
    n_trimmed = 0
    for fname, text in extracted.items():
        if isinstance(text, str) and len(text) > _LARGE_DOC_SCAN_CAP_BYTES:
            cut = text[:_LARGE_DOC_SCAN_CAP_BYTES]
            # Prefer a line boundary so a markdown/RST table row is not
            # split mid-line by the cut. Only honour the boundary when
            # it falls within the last 64 KB of the window (else keep
            # the hard cut to guarantee the cap is respected).
            nl = cut.rfind("\n")
            if nl >= _LARGE_DOC_SCAN_CAP_BYTES - 64 * 1024:
                cut = cut[:nl]
            capped[fname] = cut
            n_trimmed += 1
        else:
            capped[fname] = text
    if n_trimmed:
        print(f"      [large-doc guard] {n_trimmed} document(s) exceeded "
              f"{_LARGE_DOC_SCAN_CAP_BYTES // (1024 * 1024)} MB; truncated "
              f"to the cap for the per-item L-doc scans")
    return capped
_VERDICT_BYTE_RE = re.compile(
    r"\bbyte\s*\[\s*(\d+)\s*\]\s*[=:]?\s*0x([0-9a-fA-F]{2})\b",
    re.IGNORECASE,
)
_SECTION_HEADER_RE = re.compile(
    r"^\s*(\d+(?:\.\d+)*)[\.\s]+([A-Z][\w\s\-,/]+?)\s*$",
    re.MULTILINE,
)

# v1.6.334 — for #232 P2 ORGANIC. Multi-shape section-header
# coverage. The legacy `_SECTION_HEADER_RE` only matched numbered
# `1.2.3 Title` shape; modern docs use Markdown ATX (`## Title`),
# RST underline (`Title\n=====`), and AsciiDoc (`== Title`). On
# those docs L2.frs_sections came out empty.
#
# Three regex set covers the four canonical shapes; the heading
# is stamped with `heading_shape` ∈ {numbered, md_atx, rst_underline,
# adoc}. Chip-AGNOSTIC: pure docs-tooling grammar; no chip literal.

# Markdown ATX heading: `## Title`, `### Title`, `#### Title`.
# Restrict the depth to 2-4 so isolated `# Title` (typically the
# document title) and `##### / ######` (deep sub-sub-headings) do
# not blow up the section count.
# ORGANIC #630 — the title's FIRST char admits ASCII-uppercase OR any
# non-ASCII letter (CJK / accented Latin / Greek / Cyrillic …). The old
# `[A-Z]` anchor dropped EVERY CJK-titled heading (`## 功能定義`), so a
# content-rich CJK L2 spec mined ZERO sections and under-filled the L2 ≥15
# typed-field floor. `[^\x00-\x7F\W\d_]` = a non-ASCII word char that is not a
# digit/underscore (a non-ASCII LETTER); the ASCII path stays byte-identical
# (lowercase-led prose still rejected) so the downstream noise guards
# (install-verb / FPGA-token / short-caps) are unaffected. chip-AGNOSTIC.
_V1_6_630_TITLE_FIRST = r"(?:[A-Z]|[^\x00-\x7F\W\d_])"
_V1_6_334_RE_SECTION_HEADER_MD_ATX = re.compile(
    r"^\s*(#{2,4})\s+(" + _V1_6_630_TITLE_FIRST + r"[\w\s\-,/()&]+?)\s*#*\s*$",
    re.MULTILINE,
)

# AsciiDoc heading: `== Title`, `=== Title`. Same depth range
# (level-1 `= Title` is the doctitle).
_V1_6_334_RE_SECTION_HEADER_ADOC = re.compile(
    r"^\s*(={2,4})\s+(" + _V1_6_630_TITLE_FIRST + r"[\w\s\-,/()&]+?)\s*$",
    re.MULTILINE,
)

# RST setext underline: a `Title` line followed by an underline
# line of 3+ chars of `=`, `-`, `~`, `^`, `"`, `*`, `+`, or `#`.
# The title is captured on the line BEFORE the underline.
# v1.6.474 — for #341 P3 ORGANIC. Replace `[\w\s\-,/()&]` (which
# included `\n` via `\s` and let greedy matching span across
# paragraphs, fusing two H2 sections into one multi-line "title")
# with `[\w \t\-,/()&]` — only horizontal whitespace inside the
# title is allowed. This is required for the v1.6.474 lenient width
# check, otherwise a narrow `~~~` underline 4 paragraphs below
# could be paired with an arbitrary earlier title.
_V1_6_334_RE_SECTION_HEADER_RST_UNDERLINE = re.compile(
    r"^(" + _V1_6_630_TITLE_FIRST + r"[\w \t\-,/()&]{1,79})\n"
    r"([=\-~^\"*+#]{3,})\s*$",
    re.MULTILINE,
)


def _v1_6_357_slice_section_body(text: str,
                                  heading_end: int,
                                  next_heading_start: Optional[int],
                                  max_chars: int = 800) -> str:
    """v1.6.357 — for #252 P3. Slice the prose body between a
    section heading and the NEXT section heading. Returns a clean
    string with blank-only lines stripped (leading/trailing whitespace
    trimmed) and capped at ``max_chars`` (with a trailing `…` suffix
    when truncated).

    If ``next_heading_start`` is None (last heading in file), slices
    to the end of the document.

    Chip-AGNOSTIC: pure docs-tooling helper; no chip-class literal
    participates.
    """
    if not isinstance(text, str) or not text:
        return ""
    try:
        hs = max(0, int(heading_end))
    except (TypeError, ValueError):
        return ""
    if next_heading_start is None:
        he = len(text)
    else:
        try:
            he = min(len(text), int(next_heading_start))
        except (TypeError, ValueError):
            he = len(text)
    if he <= hs:
        return ""
    raw = text[hs:he]
    # Strip blank-only lines from the head and tail; collapse internal
    # runs of blank lines down to a single blank line (preserve
    # paragraph structure) but keep the body otherwise intact.
    lines = raw.splitlines()
    # Trim leading blank-only lines.
    while lines and not lines[0].strip():
        lines.pop(0)
    # Trim trailing blank-only lines.
    while lines and not lines[-1].strip():
        lines.pop()
    body = "\n".join(lines)
    if len(body) > max_chars:
        body = body[:max_chars] + "…"
    return body


# v1.6.444 — for #320 P3 ORGANIC. Markdown setext heading
# detector. Markdown's setext-style heading (`Title\n====` for
# H1, `Title\n----` for H2) shares the underline shape with RST
# setext underline. Pre-v1.6.444 the multi-shape header walker
# stamped every underline-style heading as `rst_underline`
# regardless of source file extension; on a pure-Markdown README
# this caused 32 of 50 L2.frs_sections to be mis-labelled as
# RST, which broke downstream Markdown-aware renderers (Sphinx
# pipeline, human_docs generator) that key off `heading_shape`
# to pick the right token mapper.
#
# Fix: when the caller passes `source_path` and the suffix is
# `.md` (or `.markdown`), re-label every underline-style match
# as `md_setext`. RST / AsciiDoc / unknown-extension paths keep
# the existing labels (`rst_underline` / `adoc_underline` /
# `rst_underline` fallback). Chip-AGNOSTIC: filename-shape only.
_V1_6_444_MD_EXT = frozenset({".md", ".markdown", ".mdown", ".mkd"})
_V1_6_444_RST_EXT = frozenset({".rst", ".rest"})
_V1_6_444_ADOC_EXT = frozenset({".adoc", ".asciidoc", ".asc"})


def _v1_6_444_underline_shape_label(source_path) -> str:
    """v1.6.444 — for #320 P3 ORGANIC. Return the canonical
    underline-shape label for the given source file:
        * .md / .markdown / .mdown / .mkd → "md_setext"
        * .rst / .rest                    → "rst_underline"
        * .adoc / .asciidoc / .asc        → "adoc_underline"
        * unknown / None                   → "rst_underline"
          (preserves legacy behaviour when caller can't supply
          a source path).
    Chip-AGNOSTIC.
    """
    if not source_path or not isinstance(source_path, str):
        return "rst_underline"
    # Take the suffix from the last `.` in the basename so paths
    # like `docs/source__foo.md` still resolve to `.md`.
    last_slash = max(source_path.rfind("/"), source_path.rfind("\\"))
    basename = source_path[last_slash + 1:]
    dot = basename.rfind(".")
    if dot < 0:
        return "rst_underline"
    ext = basename[dot:].lower()
    if ext in _V1_6_444_MD_EXT:
        return "md_setext"
    if ext in _V1_6_444_RST_EXT:
        return "rst_underline"
    if ext in _V1_6_444_ADOC_EXT:
        return "adoc_underline"
    return "rst_underline"


def _v1_6_334_extract_multi_shape_section_headers(
        text: str,
        source_path: str = None) -> List[Dict[str, Any]]:
    """v1.6.334 — for #232 P2 ORGANIC. Extract section headers across
    Markdown ATX (`## Title`), RST setext underline (`Title\\n====`),
    AsciiDoc (`== Title`), and the legacy numbered shape
    (`1.2.3 Title`) covered by `_SECTION_HEADER_RE`. Returns a list of
    dicts:

        {"section_id": <str>, "title": <str>, "heading_shape": <str>,
         "match_pos": <int>, "match_end": <int>}

    Where `heading_shape` ∈ {numbered, md_atx, md_setext,
    rst_underline, adoc, adoc_underline}.
    Results are sorted by `match_pos` so caller can stamp positional
    metadata. Duplicate (title, shape) pairs are de-duplicated.

    v1.6.357 — for #252 P3. Now also returns ``match_end`` so the
    caller can slice the prose body between this heading and the
    next one (replaces the literal pointer string
    `"see input_doc/<fname>"` in `frs_sections[].content`).

    v1.6.444 — for #320 P3 ORGANIC. The optional `source_path`
    parameter (default None for backward compat) re-labels the
    `rst_underline` shape to `md_setext` / `adoc_underline` based
    on the file's extension. Pure-Markdown README files no longer
    pollute `L2.frs_sections` with rst_underline rows.

    Chip-AGNOSTIC: pure docs-tooling grammar.
    """
    if not isinstance(text, str) or not text:
        return []
    out: List[Dict[str, Any]] = []
    seen: Set[Tuple[str, str]] = set()

    def _push(title: str, sec_id: str, shape: str,
              pos: int, end: int) -> None:
        title = title.strip()
        if not title:
            return
        key = (title.lower(), shape)
        if key in seen:
            return
        seen.add(key)
        out.append({
            "section_id": sec_id,
            "title": title,
            "heading_shape": shape,
            "match_pos": pos,
            "match_end": end,
        })

    # v1.6.444 — derive the canonical underline-shape label from
    # the source-file extension. Pure structural; no chip-name
    # literal.
    underline_shape = _v1_6_444_underline_shape_label(source_path)
    # v1.6.477 — for #342 R2 ORGANIC. If the source path / dict-key
    # matches the image-mined extraction file shape, skip ALL walkers
    # (numbered + ATX + AsciiDoc + setext) — the one-token-per-line
    # SVG-text content is structurally noise. Chip-AGNOSTIC.
    if _v1_6_477_skip_svg_text_for_headings(source_path):
        return []
    # Numbered (legacy `_SECTION_HEADER_RE`).
    for m in _SECTION_HEADER_RE.finditer(text):
        title = m.group(2)
        # v1.6.477 — for #342 R2 ORGANIC Defect B. Reject SVG-
        # extracted short-caps labels (`A0` / `WFI` / `CSR` /
        # `A2` / `A3`) that match the numbered-shape regex when the
        # SVG-text content begins with a digit prefix. Real numbered
        # headings are mixed case + > 6 chars OR have spaces.
        if _v1_6_477_reject_short_caps_numbered(title):
            continue
        _push(title, m.group(1), "numbered", m.start(), m.end())
    # Markdown ATX.
    for m in _V1_6_334_RE_SECTION_HEADER_MD_ATX.finditer(text):
        depth_hashes = m.group(1)
        sec_id = f"h{len(depth_hashes)}"
        _push(m.group(2), sec_id, "md_atx", m.start(), m.end())
    # AsciiDoc.
    for m in _V1_6_334_RE_SECTION_HEADER_ADOC.finditer(text):
        depth_eq = m.group(1)
        sec_id = f"h{len(depth_eq)}"
        _push(m.group(2), sec_id, "adoc", m.start(), m.end())
    # RST setext / Markdown setext / AsciiDoc setext underline.
    # v1.6.444: shape label is now driven by file extension.
    # v1.6.474 — for #341 P3 ORGANIC. Relax the strict width gate
    # (`abs(len(title) - len(underline)) > 3` rejected 10-char-narrower
    # underlines that Sphinx parses leniently). The new rule:
    # underline must be ≥ 3 chars (regex already enforces) AND must
    # be no MORE than 10 chars wider than the title (catches stray
    # `--------` separator lines). NARROWER underlines are always
    # accepted because docutils setext parsing is lenient on the
    # narrower side — writers commonly eyeball-align without trailing
    # dashes. This recovers RST H3 subsections under H2 parents
    # documented across the 8-IC benchmark.
    for m in _V1_6_334_RE_SECTION_HEADER_RST_UNDERLINE.finditer(text):
        title = m.group(1)
        underline = m.group(2)
        # v1.6.474 — for #341 P3 ORGANIC. Reject multi-line titles —
        # the regex's `[\w\s\-,/()&]{1,79}` class includes `\n` so a
        # greedy match can span paragraph boundaries. Pre-v1.6.474 the
        # strict ±3 width check incidentally hid this because multi-
        # line titles are always much wider than their underline; the
        # new lenient check would otherwise accept them.
        if "\n" in title.strip():
            continue
        # v1.6.474 — Sphinx-lenient width check.
        u_len = len(underline.rstrip())
        t_len = len(title.rstrip())
        # Narrower OK (lenient docutils); cap over-wide at +10.
        if u_len > t_len + 10:
            continue
        # v1.6.475 — for #342 P3 ORGANIC. Belt-and-braces SVG-token
        # guard. Reject very short SCREAMING-SNAKE / ALPHANUMERIC
        # labels (≤6 chars, no lowercase letters, no spaces) whose
        # underline width EQUALS the title width — that shape is
        # exactly what SVG block-diagram ASCII-art emits when a
        # label is drawn inside a box made of `---`. Even with the
        # SVG-path guard in place (caller-side) this defends against
        # renamed SVG-text companion files. Genuine setext titles
        # are usually multi-word prose ("Pipeline Stages",
        # "Privilege Modes") or contain at least one lowercase
        # letter ("Architecture", "Memory Map").
        title_stripped = title.strip()
        if (len(title_stripped) <= 6
                and " " not in title_stripped
                and "\t" not in title_stripped
                and u_len == t_len
                and re.fullmatch(r"[A-Z0-9_]+", title_stripped)):
            continue
        # Underline character determines the depth in RST convention:
        # `=` → h1, `-` → h2, `~` → h3, `^` → h4, others → unknown.
        # Markdown setext only defines `=` (h1) and `-` (h2); use
        # the same depth map — extra chars in MD context will surface
        # as h5/h-unknown but the shape label is still md_setext.
        u_char = underline[0]
        depth_map = {"=": 1, "-": 2, "~": 3, "^": 4}
        depth = depth_map.get(u_char, 5)
        _push(title, f"h{depth}", underline_shape,
              m.start(), m.end())
    out.sort(key=lambda d: d["match_pos"])
    return out
_PIN_TABLE_LINE_RE = re.compile(
    r"\b(input|output|inout|bidir|power|ground)\b",
    re.IGNORECASE,
)

# A whitespace-delimited token carrying a path separator: a file path, never a
# port declaration nor a port name. Masked out of the narrative line-scan
# before the direction anchor is searched and before names are tokenised.
_PATHLIKE_TOKEN_RE = re.compile(r"\S*[/\\]\S*")

# v1.6.252 — for #111 ORGANIC. CSR / regmap / ISA-spec / bit-field
# docs must NEVER trigger OTP-evidence extraction. The L4/L11 OTP
# bracket-field scanner used a loose filename gate (`otp|table|
# regmap|register`) that admitted `control_status_registers.rst`
# and any other CSR doc whose canonical bit-field rows shaped like
# `MODE[0]`, `MSTATUS[31]` then drove a fabricated OTP layout
# template. Even when the allow-list is tightened to OTP-specific
# vocabulary, this deny-list keeps the gate honest if anyone
# broadens the trigger later. Chip-AGNOSTIC: pure filename pattern
# (canonical CSR / regmap / bit-field doc naming), no chip-class
# literal.
_OTP_EVIDENCE_FILENAME_DENY = re.compile(
    r"(?i)(?:^|[/_.-])(?:"
    r"csr|control[-_]?status[-_]?register[s]?|"
    r"regmap|register[-_]?map|"
    r"bit[-_]?fields?|"
    r"opcode[-_]?map|"
    r"isa[-_]?spec"
    r")(?:[/_.-]|$)"
)

# v1.6.248 — for #110. The L1 pin / L9 port extractors read every
# file in `extracted` indiscriminately, including build / config
# files copied into `input/docs/` (Doxyfile, Makefile, conf.py,
# *.yml, requirements.txt, …). Doxygen tag names (`HAVE_DOT=YES`),
# Makefile target keys, and YAML config keys were mis-tokenised
# into fake port names (`stl`, `quiet`, `yes`, `warn_logfile`).
# A canonical filename / suffix deny-list short-circuits before
# the port regex runs. chip-AGNOSTIC: pure filename-vocabulary
# filter, no chip-class literal.
_L1_L9_PORT_SOURCE_DENY = frozenset({
    "Doxyfile", "Makefile", "GNUmakefile", "make.bat",
    "conf.py", "requirements.txt", "requirements-dev.txt",
    ".gitignore", ".editorconfig",
    "install.sh", "configure", "configure.ac",
    "setup.py", "setup.cfg", "pyproject.toml",
    "package.json", "package-lock.json",
    "tox.ini", "pytest.ini", "CITATION.cff",
})
_L1_L9_PORT_SOURCE_DENY_SUFFIX = (
    ".yml", ".yaml", ".toml", ".cfg", ".ini",
    ".mk", ".cmake", ".bat", ".bashrc",
)


def _is_port_source_allowed(fname: str) -> bool:
    """v1.6.248 (#110) — return False when `fname` looks like a
    build/config file that must not contribute to L1.pin_table
    or L9.top_ports. Caller short-circuits at the start of its
    file loop."""
    import os
    basename = os.path.basename(str(fname or ""))
    if basename in _L1_L9_PORT_SOURCE_DENY:
        return False
    bl = basename.lower()
    for suf in _L1_L9_PORT_SOURCE_DENY_SUFFIX:
        if bl.endswith(suf):
            return False
    return True


# v1.6.248 — for #108. Cross-wire the v1.6.241 RST grid Interface
# table parser to L1.pin_table + L9.top_ports (it currently feeds
# only L7.debug_observability). Real RV `integration.rst` ships a
# 4-column Signal|Width|Dir|Description grid; the existing
# `_l7_iface_row_re` only handles 3-column Signal|Type|Description.
# New regex captures the 4-column form and exposes width too.

# v1.6.423 — for #302 R2 NOT VERIFIED feedback. The v1.6.420
# helper `_v1_6_420_parse_width_cell` accepts parametric /
# placeholder tokens (`*`, `N`, `WIDTH`, `DATA_WIDTH-1`,
# `(variable)`, `var`, `-`) and was wired into the
# `rst_list_table_signals` walker. But the real-benchmark
# trace ports in 4-col AsciiDoc / RST pipe-table grids never
# reach that walker — they flow through
# `rst_grid_interface_table` whose `_RE_L1_L9_RST_IFACE_4COL`
# width capture is `(?P<width>\d{1,3}|)` (strict numeric or
# empty). Any row whose width cell is `*` / `N` / `DATA_WIDTH`
# fails the row regex outright and the WHOLE row is dropped.
# Fix: extend the width sub-pattern to a permissive variant
# shared between 4COL and NCOL_SUFFIX, then route the captured
# width through `_v1_6_420_parse_width_cell` at emit time so
# numeric → int, parametric → None + strategy suffix.
#
# Chip-AGNOSTIC: pure structural grammar (numeric / SV-identifier
# / placeholder / dash / empty); no chip-class literal.
#
# v1.0.44 — for #664 ORGANIC. Three more chip-AGNOSTIC width-cell
# idioms were dropping the WHOLE port-table row (the row fell through
# to the width-less #627 backtick walker, so multi-bit buses landed
# with null width in L1.pin_table → L9.top_ports):
#   (d) `<N>-bit` / `N-bit` / `<IDENT>-bit` — number-or-identifier +
#       `-bit` suffix (e.g. `8-bit`, `1-bit`, `N-bit`), optionally
#       wrapped in markdown emphasis (`<...>` / angle-quoted), possibly
#       trailing prose `N-bit(...)`;
#   (e) a leading bracketed width `[M:L]` / `[WIDTH-1:0]` sitting alone
#       in the cell (`[31:0]`, `[WIDTH-1:0]`);
#   (f) a cell that merely CONTAINS a `[...:...]` bracket inside prose
#       (`N-bit([size-1:0], parameter size 預設 32)`).
# All three are routed through `_add_pin` → `_parse_port_width` (extended
# for the `N-bit` idiom) so msb/lsb/bits/width_symbolic populate the row.
# Pure structural grammar; no chip/vendor/SKU literal.
#
# v1.0.78 — for #731 ORGANIC. A leading APPROXIMATION MARKER on the width
# cell (`~10-bit`, `≈10-bit`, `approx 10-bit`, `about 8`, `~=32-bit`) made
# the whole width-cell match fail (so the row dropped from the structured
# 4COL/DIR2 walker into the width-less GFM fallback). `_V1_6_731_APPROX_PFX`
# is an OPTIONAL non-capturing leading marker prepended to the N-bit /
# numeric / bracket alternatives; `_parse_port_width` strips the same marker
# before resolving the integer. Chip-AGNOSTIC: pure approximation grammar.
_V1_6_731_APPROX_PFX = r"(?:[~≈]\s*=?\s*|\bapprox(?:imately)?\.?\s+|\babout\s+)?"
# Anchored, REQUIRED form (drop the trailing `?`) used by `_parse_port_width`
# to strip a leading marker before resolving the integer. `.match` returns
# None when no marker is present, so a clean `8`/`8-bit` cell is untouched.
_RE_V1_6_731_APPROX_PFX_LEAD = re.compile(
    r"^(?:[~≈]\s*=?\s*|\bapprox(?:imately)?\.?\s+|\babout\s+)"
)
_V1_6_423_WIDTH_CELL_PERMISSIVE = (
    r"(?P<width>"
    + _V1_6_731_APPROX_PFX +
    r"(?:"
    r"\[[^\]\n]{1,40}\][^|\n]{0,60}|"                    # leading bracket [M:L]/[WIDTH-1:0] (+ trailing prose) (#664e)
    r"[^|\n]{0,40}\[[^\]:\n]{0,40}:[^\]\n]{0,40}\][^|\n]{0,40}|"  # cell CONTAINS a [...:...] bracket (#664f)
    r"<?[A-Za-z0-9_]+>?\s*-\s*bit\b[^|\n]{0,40}|"        # <N>-bit / N-bit / <IDENT>-bit (+ trailing) (#664d)
    r"\d{1,4}|"                                          # numeric
    r"\*|"                                               # AsciiDoc placeholder
    r"[A-Za-z][A-Za-z0-9_]*(?:\s*[+\-*/]\s*\d+)?|"       # IDENT / IDENT-1 / IDENT+1
    r"\(?\s*variable\s*\)?|"                             # (variable) / variable
    r"-|"                                                # dash placeholder
    r""                                                  # empty
    r")"
    r")"
)

# v1.0.78 — for #731 ORGANIC. The signal-name cell of the 4COL / DIR2 grids
# may carry trailing PARENTHETICAL ALIAS PROSE after the backticked primary
# name (`` `o_sram_data` (or `o_sram_wdata`) ``). The old capture demanded a
# closing backtick (or the column `|`) immediately after the name, so any row
# with ` (or `alt`)` prose failed the signal cell and the WHOLE row dropped
# from the width-bearing 4COL/DIR2 path into the width-less GFM fallback.
# This shared signal-cell prefix anchors `(?P<signal>...)` on the FIRST
# backticked identifier, then tolerates (but does NOT capture) an optional
# trailing `(or `alt`)` / `(或 `alt`)` group — the SAME grammar as
# `_RE_V610_ALIAS_GROUP` — up to the next column delimiter. The alias is
# therefore ATTACHED (i.e. consumed as prose, not promoted as a second
# top-level port), and the row stays on the width-bearing 4COL/DIR2 path so
# the primary port keeps its stated bus width. Chip-AGNOSTIC: pure alias
# grammar + GFM cell delimiter; no chip / vendor / SKU literal.
_V1_6_731_ALIAS_PROSE = (
    r"(?:\s*[(（]\s*(?:or|或)\s+[`][A-Za-z][A-Za-z0-9_\[\]:.\/]*[`]\s*[)）])?"
)
_V1_6_731_SIGNAL_CELL = (
    r"^[ \t]*\|\s*[`]{0,2}"
    r"(?P<signal>[a-zA-Z_][\w]{0,40}(?:\[[^\]\n]{1,40}\])?)"
    r"[`]{0,2}" + _V1_6_731_ALIAS_PROSE + r"\s*\|"
)

_RE_L1_L9_RST_IFACE_4COL = re.compile(
    # v1.6.249 — for #108 field-agent round-2 feedback. Real RV
    # `integration.rst` grids use abbreviated direction cells
    # (`in` / `out` / `io`) instead of `input` / `output` /
    # `inout`. v1.6.248 strict full-word regex missed every row.
    # `_DIR_ABBR_TO_FULL` below normalises the captured direction.
    # v1.6.265 — for #123 Shape C. Allow optional bracket suffix
    # on the signal name (`irq_fast_i[14:0]`). `_strip_name_bracket`
    # inside `_add_pin` recovers the bracket as the width.
    # v1.6.268 — for #125 ORGANIC round-2. Allow optional leading
    # whitespace before `|`: RST `.. table::` directive blocks the
    # entire grid 2 spaces (the directive's `:widths:` / `:class:`
    # options force body indent). The old `^\|` matched 0 rows on
    # any chip whose Interface table was wrapped in `.. table::`.
    # v1.6.423 — for #302 R2. Width sub-pattern lifted out to
    # `_V1_6_423_WIDTH_CELL_PERMISSIVE` so parametric tokens
    # (`*`, `N`, `DATA_WIDTH-1`, `(variable)`, `-`) match instead
    # of dropping the entire row.
    # v1.0.78 — for #731 ORGANIC. Signal cell shared with the alias-prose
    # tolerance (`_V1_6_731_SIGNAL_CELL`).
    _V1_6_731_SIGNAL_CELL
    + r"\s*[`]{0,2}" + _V1_6_423_WIDTH_CELL_PERMISSIVE + r"[`]{0,2}\s*\|"
    r"\s*(?P<dir>input|output|inout|in|out|io)\s*\|"
    # v1.6.251 — same rationale as the 2-col fix below. Allow
    # inline RST backticked markup in the description cell so rows
    # carrying :ref:/:func:/literal-code roles are not dropped.
    r"\s*(?P<desc>[^|\n]{0,200}?)\s*\|",
    re.MULTILINE,
)
_DIR_ABBR_TO_FULL = {
    "in":     "input",
    "out":    "output",
    "io":     "inout",
    "input":  "input",
    "output": "output",
    "inout":  "inout",
}

# v0.2.62 — ORGANIC-20260606-l9-ports-empty-submodule-pollution (#431).
# The 4COL grid above hard-codes the `signal | WIDTH | DIR | desc` column
# ORDER; the equally common `signal | DIR | WIDTH | desc` ordering
# (`| Port | Dir | Width | Description |`) matched ZERO rows, so a fully
# defined external-interface table fed L1.pin_table (and the L9 cascade)
# exactly the rows the suffix-heuristic N-col fallback happened to like —
# the filing's project surfaced with 1/5 ports. Same permissive width
# cell, same dir alternation; only the column order differs.
_RE_L1_L9_RST_IFACE_4COL_DIR2 = re.compile(
    # v1.0.78 — for #731 ORGANIC. Same alias-prose-tolerant signal cell as
    # the 4COL walker (`_V1_6_731_SIGNAL_CELL`).
    _V1_6_731_SIGNAL_CELL
    + r"\s*(?P<dir>input|output|inout|in|out|io)\s*\|"
    r"\s*[`]{0,2}" + _V1_6_423_WIDTH_CELL_PERMISSIVE + r"[`]{0,2}\s*\|"
    r"\s*(?P<desc>[^|\n]{0,200}?)\s*\|",
    re.MULTILINE,
)

# v1.6.250 — for #108 field-agent round-3 feedback. Real RV
# `integration.rst` also ships **2-column** grid rows that only
# carry `signal | description` (no width / direction cells). The
# v1.6.249 4-col regex requires four cells and silently drops these
# rows. The 2-col fallback infers direction from canonical RTL
# suffix convention (`_o` → output, `_i`/`_ni` → input, `_io` →
# inout, fallback input). Chip-AGNOSTIC: pure structural pattern +
# RTL naming convention, no chip-class literal.
_RE_L1_L9_RST_IFACE_2COL = re.compile(
    # v1.6.251 — for #108 field-agent round-4 feedback. Real RST
    # 2-col grid descriptions contain inline backticked markup
    # (`:ref:` / `:func:` / literal `code`). v1.6.250 forbade
    # backticks (and other quotes) in the desc class and silently
    # dropped any row whose description used canonical RST inline
    # roles. Only forbid pipe / newline now — the cell delimiter
    # itself remains the only structural terminator.
    # v1.6.265 — for #123 Shape C. Optional bracket suffix on
    # signal name (`irq_fast_i[14:0]`).
    # v1.6.268 — for #125 ORGANIC round-2. Same `.. table::`
    # leading-whitespace tolerance as the 4-col regex above.
    r"^[ \t]*\|\s*[`]{0,2}(?P<signal>[a-zA-Z_][\w]{0,40}(?:\[[^\]\n]{1,40}\])?)[`]{0,2}\s*\|"
    r"\s*(?P<desc>[^|\n]{1,200}?)\s*\|\s*$",
    re.MULTILINE,
)
_RE_DIR_SUFFIX_OUTPUT = re.compile(r"(?:_o|_out|_oz)$", re.IGNORECASE)
_RE_DIR_SUFFIX_INOUT  = re.compile(r"(?:_io|_b)$", re.IGNORECASE)
_RE_DIR_SUFFIX_INPUT  = re.compile(r"(?:_i|_ni|_in)$", re.IGNORECASE)

# v1.6.565 — for #384 P3 ORGANIC. Third RST grid Interface table
# layout: `| signal | direction | description |` (3 columns; no
# Width column). Canonical Sphinx documentation form across
# RV / SoC debug / load-store / interrupt interfaces. The 4COL
# walker requires a width cell and the 2COL walker requires
# exactly two cells; neither matches the 3-col shape, so the
# entire grid was silently dropped before v1.6.565.
#
# Defence: the direction cell MUST carry a canonical direction
# keyword (`input` / `output` / `inout` / `in` / `out` / `i/o`)
# — this rejects header rows whose middle cell is literal
# `Direction` / `Dir`. Description cell allows backticked /
# pipe-free text up to 200 chars.
#
# Chip-AGNOSTIC: pure RST grid grammar + universal RTL direction
# vocabulary; no chip-class string literal.
_V1_6_565_RE_L1_L9_RST_IFACE_3COL = re.compile(
    r"^[ \t]*\|\s*[`]{0,2}"
    r"(?P<signal>[a-zA-Z_][\w]{0,40}(?:\[[^\]\n]{1,40}\])?)"
    r"[`]{0,2}\s*\|"
    r"\s*(?P<dir>input|output|inout|in|out|i/o)\s*\|"
    r"\s*(?P<desc>[^|\n]{0,200}?)\s*\|\s*$",
    re.IGNORECASE | re.MULTILINE,
)

# v1.6.270 — for #123 ORGANIC round-3. N-column RST grid row where
# only the FIRST cell is structurally validated. Canonical example
# is the RV interrupt-controller table:
#   `| ``irq_fast_i[14:0]`` | 30:16 | 15 fast, local interrupts |`
# which has 3 cells (signal | id | desc) and matches neither the
# 4-col grid (no input/output/inout dir cell) nor the strict 2-col
# grid (it has 3 cells, not 2). Gate is intentionally narrow: the
# signal cell MUST carry an RTL direction suffix (`_o` / `_i` /
# `_ni` / `_io`) so we don't sweep up narrative-table rows that
# happen to share grid syntax. Description is the LAST cell of the
# row. Chip-AGNOSTIC: pure RTL naming convention.
_RE_L1_L9_RST_IFACE_NCOL_SUFFIX = re.compile(
    r"^[ \t]*\|\s*[`]{0,2}(?P<signal>[a-zA-Z_][\w]{0,40}(?:\[[^\]\n]{1,40}\])?)[`]{0,2}\s*\|"
    r"(?P<middle>(?:[^|\n]{0,120}\|){1,4})"
    r"\s*(?P<desc>[^|\n]{0,200}?)\s*\|\s*$",
    re.MULTILINE,
)


# v1.6.265 — for #123 ORGANIC. Universal port-width parser used
# by every L1 / L9 port extractor. Accepts:
#   - bare integer `32`                         → (32, 31, 0, None)
#   - bracketed M:L `[31:0]` / `[ 3 : 0 ]`      → (32, 31, 0, None)
#   - bracketed symbolic `[N-1:0]` / `[WIDTH-1:0]` → (None, None, 0, "N-1:0")
# Returns (width:Optional[int], msb:Optional[int], lsb:Optional[int],
#          width_symbolic:Optional[str]).
_RE_PORT_WIDTH_BRACKET = re.compile(
    r"\[\s*(?P<msb>\d+)\s*:\s*(?P<lsb>\d+)\s*\]"
)
_RE_PORT_WIDTH_SYMBOLIC = re.compile(
    r"\[\s*(?P<expr>[A-Za-z_][A-Za-z0-9_]*(?:\s*[-+]\s*\d+)?\s*"
    r":\s*\d+)\s*\]"
)
# v1.0.44 — for #664 ORGANIC. The `<N>-bit` natural-language width idiom:
# a leading integer + `-bit` suffix (`8-bit`, `1-bit`, `32-bit`),
# optionally markdown-emphasis-wrapped (`<8-bit>`). Chip-AGNOSTIC.
# v1.0.78 — for #731 ORGANIC. Tolerate an OPTIONAL leading approximation
# marker (`~10-bit`, `≈10-bit`, `approx 10-bit`, `about 8-bit`, `~=32-bit`)
# via the shared `_V1_6_731_APPROX_PFX`. The marker is non-capturing, so the
# resolved integer `n` is the bare bit count regardless of the marker.
_RE_PORT_WIDTH_NBIT = re.compile(
    r"^<?\s*" + _V1_6_731_APPROX_PFX + r"\s*(?P<n>\d{1,4})\s*-\s*bit\b"
)
# Strip a bracket suffix off a signal name and return (bare_name, bracket).
_RE_NAME_BRACKET_SUFFIX = re.compile(
    r"^(?P<bare>[A-Za-z_][\w]*)"
    r"(?P<bracket>\[[^\]\n]{1,40}\])\s*$"
)


def _parse_port_width(
    cell_or_name: Optional[str],
) -> Tuple[Optional[int], Optional[int], Optional[int], Optional[str]]:
    """Chip-AGNOSTIC width parser used by every port extractor.

    `cell_or_name` may be:
      - the Width column cell of a port table (`32`, `1`, `4`)
      - a bracketed Verilog port-decl width (`[31:0]`)
      - a signal name with bracket suffix (`irq_fast_i[14:0]`)
    Returns the canonical (width, msb, lsb, width_symbolic) tuple.
    For symbolic cases the integer `width` is None and the textual
    form is preserved in `width_symbolic` so downstream consumers
    can resolve at elaboration time."""
    if cell_or_name is None:
        return (None, None, None, None)
    s = str(cell_or_name).strip().strip("`").strip()
    if not s:
        return (None, None, None, None)
    # v1.0.78 — for #731 ORGANIC. Strip a leading approximation marker
    # (`~10`, `≈8`, `approx 32`, `about 16`, `~=10-bit`) before resolving the
    # integer, so an approximated width cell carries its stated bus width
    # instead of falling through to width=None. `_RE_PORT_WIDTH_NBIT` already
    # tolerates the same marker internally; stripping here additionally lets a
    # bare numeric (`~10`) and the GFM/multitable fallback path resolve.
    # Chip-AGNOSTIC: pure approximation grammar; no chip literal.
    m_apx = _RE_V1_6_731_APPROX_PFX_LEAD.match(s)
    if m_apx and m_apx.end() < len(s):
        s = s[m_apx.end():].strip()
    if s.isdigit():
        n = int(s)
        return (n, n - 1, 0, None)
    # v1.0.44 — for #664 ORGANIC. The `<N>-bit` / `N-bit` natural-language
    # width idiom. A LEADING INTEGER + `-bit` (e.g. `8-bit`, `1-bit`,
    # `32-bit`) resolves to a concrete width (N, N-1, 0, None); but only
    # when no symbolic bracket `[expr:lsb]` is also present in the cell —
    # if one is, prefer the bracket (it carries the real parametric range,
    # e.g. `N-bit([size-1:0], parameter size 預設 32)`). A NON-numeric
    # leading token (`N-bit`, `<N>-bit`) falls through to the bracket
    # search below so its embedded `[expr:lsb]` becomes width_symbolic.
    # Chip-AGNOSTIC: pure idiom grammar; no chip literal.
    if _RE_PORT_WIDTH_SYMBOLIC.search(s) is None:
        m_nbit = _RE_PORT_WIDTH_NBIT.match(s)
        if m_nbit:
            n = int(m_nbit.group("n"))
            return (n, n - 1, 0, None)
    m = _RE_PORT_WIDTH_BRACKET.search(s)
    if m:
        try:
            msb, lsb = int(m.group("msb")), int(m.group("lsb"))
            return (abs(msb - lsb) + 1, msb, lsb, None)
        except ValueError:
            pass
    m = _RE_PORT_WIDTH_SYMBOLIC.search(s)
    if m:
        return (None, None, 0, m.group("expr").replace(" ", ""))
    return (None, None, None, None)


def _strip_name_bracket(name: str) -> Tuple[str, Optional[str]]:
    """Return (bare_name, bracket_str_or_None) for a signal token
    that may carry a width suffix: `irq_fast_i[14:0]` →
    (`irq_fast_i`, `[14:0]`). Used to recover Shape C — the
    name-suffix bracket — that the 4-col / 2-col / list-table
    regexes used to drop silently."""
    if not isinstance(name, str):
        return (name, None)
    m = _RE_NAME_BRACKET_SUFFIX.match(name.strip())
    if m:
        return (m.group("bare"), m.group("bracket"))
    return (name, None)


# v1.6.266 — for #125 ORGANIC. Width-aware port-merge scoring.
# Two extractors may emit the same port name from the same file
# (e.g. a `.NAME()` instantiation example AND a structured RST
# grid table listing the same NAME). The first-emitter-wins dedup
# kept the bind entry (no width) over the grid entry (width=32);
# this scoring rule promotes the richer entry. Chip-AGNOSTIC.
_STRUCTURED_PORT_STRATEGIES = frozenset({
    "rst_grid_interface_table",
    "rst_grid_interface_table_2col",
    "rst_list_table_signals",
    "markdown_bullet_under_heading",
    "verilog_port_decl",
    "verilog_port_decl_indented",
})


def _port_entry_score(entry: Dict[str, Any]) -> int:
    """Score how informative a candidate port entry is. Higher
    wins on a name collision. Pure structural / typed-field
    rubric — no chip-class literal."""
    score = 0
    w = entry.get("width")
    if w not in (None, ""):
        score += 4
    if entry.get("msb") is not None:
        score += 1
    if entry.get("description"):
        score += 2
    if entry.get("io_standard") not in (None, "", "see datasheet"):
        score += 1
    es = entry.get("extraction_strategy")
    if es in _STRUCTURED_PORT_STRATEGIES:
        score += 2
    if es == "verilog_port_bind":
        score -= 1
    return score


# v1.6.262 — for #120 ORGANIC. RST `.. list-table::` POSITIVE parse
# for L1.pin_table / L9.top_ports. Sibling of v1.6.258 #118 (which
# only added the REJECT path that stopped header rows leaking into
# the bullet picker). When the list-table caption text or the
# header row identifies a port/signal table AND the table carries
# a direction column, body rows are emitted as pins with
# `extraction_strategy = "rst_list_table_signals"`. Chip-AGNOSTIC:
# pure RST grammar + port-vocabulary detection, no chip-class
# literal.
_RE_RST_LIST_TABLE_CAPTION_PORTLIKE = re.compile(
    r"(?i)(?:^|\W)(?:signals?|ports?|pins?|interface|i/?o)\b"
)


def _rst_list_table_iter_blocks(text: str):
    """Yield (caption, header_cells, body_rows) tuples for every
    `.. list-table::` directive in `text`. Each row is a list of
    cell-text strings (trimmed). Empty when the directive has no
    parsable body."""
    if not text:
        return
    for lm in _RE_RST_LIST_TABLE_DIRECTIVE.finditer(text):
        line_end = text.find("\n", lm.end())
        caption = text[lm.end():line_end if line_end >= 0 else len(text)].strip()
        # Walk the indented body collecting rows; each row begins
        # with `* -` and each subsequent cell with `  -`. Stop at
        # the first zero-indent non-blank line.
        idx = (line_end + 1) if line_end >= 0 else len(text)
        rows: List[List[str]] = []
        current: Optional[List[str]] = None
        cell_buf: List[str] = []
        while idx < len(text):
            nl = text.find("\n", idx)
            line = text[idx:nl if nl >= 0 else len(text)]
            stripped = line.lstrip()
            # Zero-indent non-blank line ends the directive body.
            if stripped and line == stripped and not stripped.startswith("*"):
                break
            # Skip RST option lines like `:header-rows: 1`,
            # `:widths: 15 10 10 65`, etc. — they sit indented
            # before the first `* -` row and must not be parsed
            # as cells.
            if (current is None
                    and stripped.startswith(":")
                    and ":" in stripped[1:]):
                if nl < 0:
                    break
                idx = nl + 1
                continue
            if stripped.startswith("* -"):
                if current is not None:
                    if cell_buf:
                        current.append(" ".join(cell_buf).strip())
                        cell_buf = []
                    rows.append(current)
                current = []
                cell_buf = [stripped[3:].strip()]
            elif stripped.startswith("- ") and current is not None:
                if cell_buf:
                    current.append(" ".join(cell_buf).strip())
                cell_buf = [stripped[2:].strip()]
            elif current is not None and stripped:
                cell_buf.append(stripped)
            if nl < 0:
                break
            idx = nl + 1
        if current is not None:
            if cell_buf:
                current.append(" ".join(cell_buf).strip())
            rows.append(current)
        if not rows:
            continue
        header = rows[0]
        body = rows[1:]
        yield (caption, header, body)


def _rst_list_table_port_columns(header: List[str]) -> Optional[Dict[str, int]]:
    """Identify column roles in a list-table header row. Returns
    a dict mapping role-key -> column index, or None when the
    header doesn't look like a port table (must have at least a
    name column AND a direction column)."""
    if not header:
        return None
    cols: Dict[str, int] = {}
    for i, raw in enumerate(header):
        cell = (raw or "").strip("` ").strip().lower()
        if cell in {"signal", "signals", "port", "ports", "pin",
                    "pins", "name"} and "name" not in cols:
            cols["name"] = i
        elif cell in {"direction", "dir", "mode", "i/o", "io"} \
                and "direction" not in cols:
            cols["direction"] = i
        elif cell in {"width", "bits", "size"} and "width" not in cols:
            cols["width"] = i
        elif cell in {"description", "desc", "function", "purpose",
                      "notes"} and "description" not in cols:
            cols["description"] = i
    if "name" not in cols or "direction" not in cols:
        return None
    return cols


# v1.6.255 — for #116 ORGANIC. Markdown / RST bullet-list-under-
# heading extractor. Several chip specs ship clean structured
# prose hierarchies under explicit headings like:
#
#   Top-level ports:
#     - clk_i        (input,  clock)
#     - rst_ni       (input,  active-low reset)
#     - inst_addr_o  (output, instruction-fetch address)
#
#   Key sub-blocks:
#     - fetch_unit   - instruction fetch and pre-decode
#     - decoder      - opcode decode + immediate gen
#
# Neither the Verilog port-decl nor the RST grid-table parser
# match this shape. The bullet extractor recognises a colon-
# terminated heading followed by a bullet list and emits each
# bullet as a candidate. Direction comes from parenthetical
# `(input, ...)` or trailing `(in/out/io)` text, else from a
# signal-name suffix. Chip-AGNOSTIC.
# v1.6.256 — for #116 field-agent round-2 feedback. Heading regex
# must allow a parenthetical qualifier between the prefix and the
# noun: e.g. `Top-level (FPGA bare-board) ports:`. The v1.6.255
# regex required prefix-then-noun adjacency and missed any
# heading with an interjection.
# 2026-08-26 — THE SAME OPTIONAL PREFIX ITS SIBLING ALREADY CARRIES.
# `_RE_DIRECTIONAL_PORT_HEADING` (below, same file) opens on `## Inputs` and
# `**Outputs**` because it allows a bullet or ATX-heading prefix and paired
# emphasis. This one did not, so two regexes in ONE file disagreed about what a
# heading is: a spec writing `Pins:` had its ports read, and the same spec
# writing `## Pins` — the commonest markdown form there is — had none.
#
# Measured on identical bullet text under each heading form:
#     'Pins:'   -> _l1_bullet_port_extract = 7 ports
#     '## Pins' -> _l1_bullet_port_extract = 0 ports
# and directly on the old regex: `Pins:` True, `Top-level ports:` True,
# `## Pins` False, `## Ports` False, `## Signals` False, `## Interface` False.
#
# The consequence is not a missing field. An empty L1.pin_table empties
# L9.top_ports, and every downstream producer then reports a PASS over nothing:
# `sdc_gen` emitted an SDC with the note "no I/O ports classified — the emitted
# SDC constrains NO input or output path" and still returned PASS.
#
# The prefix is COPIED VERBATIM from the sibling rather than re-invented,
# because a second dialect is the defect, not the cure.
_RE_L1_BULLET_PORT_HEADING = re.compile(
    r"(?im)^\s*(?:[-*+]\s+|#{1,6}\s+)?\*{0,2}_{0,2}"
    r"(?:top[-_ ]?level\s+|external\s+|chip[-_ ]?level\s+|module\s+)?"
    r"(?:\([^)\n]{0,80}\)\s+)?"
    r"(?:ports?|signals?|pins?|i/?o\s+ports?|interface)"
    r"\*{0,2}_{0,2}\s*[:.]?\s*$"
)
_RE_L1_BULLET_ITEM = re.compile(
    r"(?m)^\s*[-*+]\s+`?(?P<name>[a-zA-Z_][a-zA-Z0-9_]{0,40})`?"
    r"(?P<rest>(?:[ \t\(:,\-—–][^\n]{0,200})?)\s*$"
)

# v1.6.314 — for #213 P2 ORGANIC. `_RE_L1_BULLET_ITEM` requires the
# first non-list-marker character of the bullet body to be an ASCII
# letter or underscore. The canonical Markdown TOC bullet shape
# `- [LinkText](#anchor)` starts with `[` and is rejected by the
# very first regex check. Every downstream walker that consumes
# the output of `_RE_L1_BULLET_ITEM` — including the L1 bullet-
# submodule pipeline and the L9 enumeration fallback — never sees
# the link-text payload. Pre-pass rewrites
# `- [LinkText](url)` into `- LinkText` so the existing regex
# matches LinkText as the name. Substitution only affects bullet
# lines whose payload is a bracketed link; all other bullet
# shapes pass through unchanged. Chip-AGNOSTIC: Markdown TOC link
# shape, not anything chip-specific.
_RE_L1_BULLET_BRACKETED_LINK_v1_6_314 = re.compile(
    r"^(\s*)([-*+])\s+\[([^\]]+)\]\([^)]*\)",
    re.MULTILINE,
)


def _preprocess_md_bracketed_link_bullets_v1_6_314(text: str) -> str:
    """v1.6.314 — for #213 P2 ORGANIC. Normalise Markdown TOC link
    bullets `- [LinkText](url)` into plain-text bullets `- LinkText`
    so the existing `_RE_L1_BULLET_ITEM` regex can match LinkText
    as the bullet's name token.

    Chip-AGNOSTIC: pure Markdown link-bullet shape; no chip-class
    literal participates.
    """
    if not isinstance(text, str) or not text:
        return text
    return _RE_L1_BULLET_BRACKETED_LINK_v1_6_314.sub(
        r"\1\2 \3", text)


# v1.6.315 — for #214 P2 ORGANIC. `_RE_V1_6_299_FPGA_BENCHMARK_DENY`
# was added to filter FPGA platform tokens from the L2
# clock_domains.fmax walker (in `gen_l8_timing_waveform`). The
# deny-list was only consulted at that single emit site. Other L2
# emitters — `_extract_bullet_kv_specs` callers, the FRS-section
# scanner, the platform-perf walker, the doc-prose timing emitter —
# never consulted the deny list, so any FPGA family token they
# picked up flowed straight through into L2 as a structured field.
# Result: L2.timing_parameters ends up with entries whose `name` is
# an FPGA platform identifier, which is structurally wrong because
# an FPGA family is not a timing parameter.
#
# Separately, there was no equivalent install-verb deny list. The
# FRS-section scanner reads h2/h3 headings from each input document
# and emits any heading that looks like a top-level capability into
# L2.frs_sections. Open-source IC trees commonly intersperse build
# / install / dev-env sections; their headings (the imperative verb
# shape `Make`, the tool name `Icarus Verilog`, the full sudo
# install line, the conditional builder shape `For 64 bit`) were
# picked up verbatim and emitted as L2.frs_sections, again
# structurally wrong because they are not functional-requirements
# sections.
#
# Fix: share a small set of deny helpers across all L2 emitters.
# Chip-AGNOSTIC: FPGA-platform vocabulary + install-verb vocabulary
# are open-standard; no chip-class literal participates.
_RE_FPGA_PLATFORM_DENY_v1_6_315 = re.compile(
    r"(?i)\b("
    r"speed[\s\-]?grade|"
    r"LUT[\s\-]?occupation|LUTs?[\s\-]?used|FFs?[\s\-]?used|"
    r"BRAM(?:s)?[\s\-]?used|DSPs?[\s\-]?used|slice(?:s)?[\s\-]?used|"
    r"synthesis[\s\-]?only|synthesis[\s\-]?target|"
    r"Kintex|Spartan|Artix|Cyclone|Stratix|Virtex|Zynq|"
    r"MachXO|ECP5|iCE40|PolarFire|SmartFusion|"
    r"achievable[\s\-]?fmax|target[\s\-]?frequency|"
    r"achievable[\s\-]?frequency"
    r")\b"
)


def _is_fpga_platform_token_v1_6_315(name) -> bool:
    """v1.6.315 — for #214 P2 ORGANIC. Return True when `name`
    matches the open-standard FPGA-platform vocabulary
    (speed grade / LUT-occupation / family names / synthesis-only
    target). L2 emitters call this to reject FPGA platform tokens
    that would otherwise be misclassified as timing parameters /
    clock domains.

    Chip-AGNOSTIC: open-standard FPGA vendor / family vocabulary.

    v1.6.317 — for #216 P3 ORGANIC follow-on. The wrapper is
    extended to ALSO consult `_RE_FPGA_PLATFORM_DENY_v1_6_317`,
    which is a narrower regex that only carries family names with
    a broadened suffix shape (covers the no-hyphen concatenated
    form `Artix7` / `Cyclone10LP` that the v1.6.315 `\\b` boundary
    misses). The original v1.6.315 regex is preserved verbatim so
    the speed-grade / LUT-usage / synthesis-only vocabulary it
    uniquely covers is NOT lost; the v1.6.317 regex is OR-ed in
    so every existing call site automatically picks up the
    no-hyphen family form without touching call sites.
    """
    if not isinstance(name, str) or not name:
        return False
    # v1.6.317: OR-in the broadened family regex so no-hyphen
    # concatenated forms (`Artix7` / `Cyclone10LP`) are also caught.
    # The original v1.6.315 regex remains the source of truth for
    # the non-family vocabulary it covers (speed-grade, LUT/FF/BRAM
    # usage, synthesis-target, achievable-fmax, …).
    if _RE_FPGA_PLATFORM_DENY_v1_6_315.search(name):
        return True
    return bool(_RE_FPGA_PLATFORM_DENY_v1_6_317.search(name))


# v1.6.317 — for #216 P3 ORGANIC follow-on. The v1.6.315 deny regex
# uses a `\b` word boundary after each family name. `\b` requires a
# non-word ↔ word transition, but `Artix7` has `x` (word) followed
# by `7` (word) so the boundary does NOT trigger and the token slips
# through. Same gap for `Cyclone10LP` (`e` ↔ `1`). The fix is to
# replace the post-family `\b` with an alternation that explicitly
# covers (a) the no-hyphen concatenated digit form, (b) the hyphen-
# separated digit form, and (c) the bare family-name form.
#
# Coverage matrix (all True under the new regex):
#   Spartan         — bare family               (regression preserve)
#   Spartan-6       — hyphen-separated digit    (regression preserve)
#   Artix-7         — hyphen-separated digit    (regression preserve)
#   Artix7          — no-hyphen concatenated    (NEW v1.6.317)
#   Cyclone10LP     — no-hyphen concat + alpha  (NEW v1.6.317)
#
# Chip-AGNOSTIC: vendor family vocabulary lifted from the v1.6.315
# regex without modification; the only change is the suffix shape.
_RE_FPGA_PLATFORM_DENY_v1_6_317 = re.compile(
    r"\b(?:Spartan|Artix|Kintex|Virtex|Zynq|"
    r"Cyclone|Stratix|MachXO|ECP5|iCE40|"
    r"PolarFire|SmartFusion)"
    r"(?:[\s\-]?\d+[A-Z]*|\b)",
    re.IGNORECASE,
)


def _is_fpga_platform_token_v1_6_317(name) -> bool:
    """v1.6.317 — for #216 P3 ORGANIC follow-on. Return True when
    `name` matches the broadened FPGA-platform vocabulary that
    additionally covers the no-hyphen concatenated digit / alpha
    suffix shape (`Artix7`, `Cyclone10LP`). Used by both the
    v1.6.315 wrapper (delegated to from this function) AND by the
    `rst_list_table_transposed` emitter gate (newly added in
    v1.6.317).

    Chip-AGNOSTIC: open-standard FPGA vendor / family vocabulary.
    """
    if not isinstance(name, str) or not name:
        return False
    return bool(_RE_FPGA_PLATFORM_DENY_v1_6_317.search(name))


# v1.6.380 — for #273 P3 ORGANIC. FPGA-deny prose-fmax rescue.
#
# `_RE_FPGA_PLATFORM_DENY_v1_6_315` / `_v1_6_317` over-reject rows
# that legitimately carry an Fmax frequency literal alongside an
# FPGA-family / synthesis-target token. Real benchmarks ship a
# README bullet like
#
#     - Spartan-6 LX9 synthesis-only: 100 MHz Fmax
#
# where the row text contains both `Spartan-6` (FPGA family — must
# be denied as a platform identifier) and `100 MHz Fmax` (a real
# operating-frequency value that L2 should keep). Pre-v1.6.380 the
# deny path `continue`s out of the loop and the entire row is lost.
#
# v1.6.380 adds a small rescue path: when a row gets denied AND the
# row text carries a clean prose-frequency literal (`<N>` followed
# by `MHz`/`GHz`/`kHz`), emit ONE typed `operating_frequency` row
# carrying the literal value, normalised to MHz, with
# `low_confidence=True` so downstream gates can audit the
# provenance. Chip-AGNOSTIC: pure unit-suffix detection.
_V1_6_380_RE_PROSE_FREQ_LITERAL = re.compile(
    r"(?P<val>\d+(?:\.\d+)?)\s*(?P<unit>MHz|GHz|kHz)\b",
    re.IGNORECASE,
)


def _v1_6_380_rescue_prose_fmax_from_fpga_row(
        row_text: str, evidence_path: str):
    """v1.6.380 — for #273 P3. If the row text carries a clean prose
    frequency literal, return a single L2.timing_parameters[] entry
    normalised to MHz. Returns ``None`` when no literal is present.

    The emitted entry is stamped:
      * ``extraction_strategy = "prose_freq_promotion_fpga_filtered_v1_6_380"``
      * ``low_confidence = True``      (audit anchor for downstream)
      * ``name              = "operating_frequency"``
      * ``unit              = "MHz"``  (always normalised)

    Chip-AGNOSTIC: structural frequency-unit detection only.
    """
    m = _V1_6_380_RE_PROSE_FREQ_LITERAL.search(row_text or "")
    if not m:
        return None
    val = float(m.group("val"))
    unit = m.group("unit").upper()
    if unit == "GHZ":
        val *= 1000.0
    elif unit == "KHZ":
        val /= 1000.0
    return {
        "name": "operating_frequency",
        "value": str(val) if val != int(val) else str(int(val)),
        "unit": "MHz",
        "evidence": evidence_path,
        "extraction_strategy":
            "prose_freq_promotion_fpga_filtered_v1_6_380",
        "low_confidence": True,
    }


# v1.6.570 — for #388 P3 ORGANIC. Verb-form prose-fmax matcher.
# Pre-v1.6.570 the existing `prose_freq_promotion_fpga_filtered_
# v1_6_380` matcher only fires on FPGA-bullet rows
# (`Artix-7: <N> MHz`). The dominant free-prose forms
#   - "synthesized at <N> MHz"
#   - "runs at <N> MHz"
#   - "operates at <N> MHz"
#   - "clocked at <N> MHz"
#   - "clock speed <N> MHz"
#   - "up to <N> MHz"
#   - "achieves <N> MHz"
# are never matched, even when L2 already has many
# `operating_frequency` entries from the FPGA matcher. The new
# regex captures any of the verb / verb-phrase forms plus the
# nominal-keyword forms (`clock speed`, `maximum`, `peak`).
#
# Chip-AGNOSTIC: pure English verb / prepositional vocabulary;
# no chip-class literal participates.
_V1_6_570_PROSE_FMAX_VERB_RE = re.compile(
    r"\b(?:synthesi[sz]ed|synthetized|runs?|operates?|"
    r"clocked?|works?|clock\s+speed|target(?:s|ing)?|"
    r"achieves?|reaches?|up\s+to|maximum|peak|nominal)\s+"
    r"(?:at|of|to|=|:)?\s*"
    r"(?P<freq>\d+(?:\.\d+)?)\s*"
    r"(?P<unit>[MGk]Hz)\b",
    re.IGNORECASE,
)


def _v1_6_570_iter_prose_fmax_matches(text: str):
    """v1.6.570 — for #388 P3 ORGANIC. Yield (freq_mhz, unit_raw,
    match_obj) tuples for each verb-form fmax announcement in
    `text`. Caller (gen_l2_frs / gen_l8_*) wires each into the
    target list as a typed `operating_frequency` row.

    The unit is normalised to MHz internally (GHz × 1000, kHz
    / 1000). Chip-AGNOSTIC.
    """
    if not isinstance(text, str) or not text:
        return
    for m in _V1_6_570_PROSE_FMAX_VERB_RE.finditer(text):
        try:
            v = float(m.group("freq"))
        except (TypeError, ValueError):
            continue
        unit = (m.group("unit") or "").upper()
        if unit == "GHZ":
            v_mhz = v * 1000.0
        elif unit == "KHZ":
            v_mhz = v / 1000.0
        else:
            v_mhz = v
        if v_mhz <= 0:
            continue
        yield v_mhz, unit, m


def _v1_6_570_promote_l2_fmax_scalar(l2: Dict[str, Any]) -> None:
    """v1.6.570 — for #388 P3 ORGANIC. Mirror of
    `_v1_6_561_promote_l8_fmax_scalar` for the L2 doc. When L2's
    top-level `fmax_mhz` slot is None and `timing_parameters[]`
    carries one or more `operating_frequency` entries, set the
    scalar to the max numeric value and stamp the strategy.

    Idempotent: returns early when the scalar is already set to
    a non-None numeric value (no overwrite).

    Chip-AGNOSTIC: pure numeric aggregation."""
    if not isinstance(l2, dict):
        return
    if l2.get("fmax_mhz") is not None:
        return
    params = l2.get("timing_parameters") or []
    if not isinstance(params, list):
        return
    candidates = []
    for p in params:
        if not isinstance(p, dict):
            continue
        nm = (p.get("name") or p.get("parameter") or "").lower()
        if nm != "operating_frequency":
            continue
        v = p.get("value")
        if isinstance(v, bool):
            continue
        if isinstance(v, (int, float)) and v > 0:
            candidates.append(float(v))
        elif isinstance(v, str):
            try:
                f = float(v)
                if f > 0:
                    candidates.append(f)
            except (TypeError, ValueError):
                continue
    if not candidates:
        return
    l2["fmax_mhz"] = max(candidates)
    l2["fmax_mhz_extraction_strategy"] = (
        "max_of_operating_frequency_v1_6_570"
    )


# v1.6.579 — for #395 P3 ORGANIC. fmax-vocabulary anchor regex
# used by the evidence-window check. A numeric fmax candidate
# must have one of these tokens within ±30 chars to be considered
# a real fmax claim; otherwise it is dropped as noise (DMIPS
# table cell, figure number, paragraph counter, etc.).
# Chip-AGNOSTIC: open-standard English vocabulary for clock
# / frequency / synthesis claims.
_V1_6_579_FMAX_LEX_RE = re.compile(
    r"\b(?:f[_\-]?max|f[_\-]?clk|fmax[_\-]?mhz|"
    r"frequency|freq|"
    r"clock\s*(?:speed|rate|frequency)?|"
    r"MHz|GHz|kHz|"
    r"synthesi[sz]ed|operates?|runs?|clocked?|implement(?:ed)?|"
    r"up\s+to|peak|maximum|nominal|target)\b",
    re.IGNORECASE,
)

# v1.6.579 — for #395 P3. Deny-context tokens: DMIPS / CoreMark /
# MIPS/MHz are RATIO units, not fmax claims. A numeric near these
# tokens (or any `/MHz` ratio suffix) is rejected even if the
# fmax-vocab regex would otherwise accept.
_V1_6_579_FMAX_DENY_CONTEXT_RE = re.compile(
    r"\b(?:DMIPS(?:/MHz)?|CoreMark(?:/MHz)?|MIPS/MHz)\b",
    re.IGNORECASE,
)


def _v1_6_579_window_has_fmax_anchor(
        text: str, pos: int, radius: int = 30) -> bool:
    """v1.6.579 — for #395 P3 ORGANIC. Return True iff a fmax-
    related lexical token exists within `radius` chars on either
    side of `pos`. Chip-AGNOSTIC."""
    if not isinstance(text, str) or not text:
        return False
    if not isinstance(pos, int) or pos < 0:
        return False
    lo = max(0, pos - radius)
    hi = min(len(text), pos + radius)
    if lo >= hi:
        return False
    return bool(_V1_6_579_FMAX_LEX_RE.search(text[lo:hi]))


def _v1_6_579_window_has_deny_context(
        text: str, pos: int, radius: int = 40) -> bool:
    """v1.6.579 — for #395 P3 ORGANIC. Return True iff a
    deny-context token (DMIPS / CoreMark / */MHz ratio) exists
    within `radius` chars on either side of `pos`. When True,
    the numeric is a ratio operand, not a fmax claim, and the
    candidate must be rejected. Chip-AGNOSTIC."""
    if not isinstance(text, str) or not text:
        return False
    if not isinstance(pos, int) or pos < 0:
        return False
    lo = max(0, pos - radius)
    hi = min(len(text), pos + radius)
    if lo >= hi:
        return False
    return bool(_V1_6_579_FMAX_DENY_CONTEXT_RE.search(text[lo:hi]))


def _v1_6_579_fmax_candidate_is_valid(
        text: str, pos: int) -> bool:
    """v1.6.579 — for #395 P3 ORGANIC. Composite predicate: True
    when the numeric at `pos` should be accepted as a fmax
    candidate. Rules:
      (a) Must have an fmax-vocabulary token within ±30 chars.
      (b) Must NOT have a deny-context token (DMIPS/CoreMark/
          */MHz) within ±40 chars.
    Returns False on either failure. Chip-AGNOSTIC."""
    if _v1_6_579_window_has_deny_context(text, pos):
        return False
    return _v1_6_579_window_has_fmax_anchor(text, pos)


def _v1_6_579_audit_l2_fmax_scalar(
        l2: Dict[str, Any], extracted: Optional[Dict[str, str]]
        = None) -> bool:
    """v1.6.579 — for #395 P3 ORGANIC. Audit `L2.fmax_mhz` after
    all walkers have emitted. Schema contract:

      * `fmax_mhz` is None  → no `extraction_strategy` / `evidence`
                              expected.
      * `fmax_mhz` is non-None → MUST carry an explicit
                                 `fmax_mhz_extraction_strategy`
                                 AND either a non-empty
                                 `fmax_mhz_evidence` substring OR
                                 a known-strategy stamp.

    When the scalar is non-None but lacks BOTH strategy AND
    evidence (the leak shape reported in the field), reset to
    None and stamp `no_fmax_mhz_in_input=True` so downstream
    consumers see the honest signal.

    Returns True when the scalar was reset to None; False
    otherwise. Idempotent + chip-AGNOSTIC."""
    if not isinstance(l2, dict):
        return False
    val = l2.get("fmax_mhz")
    if val is None:
        # Schema-clean already; just stamp the sentinel if absent.
        l2.setdefault("no_fmax_mhz_in_input", True)
        return False
    strategy = l2.get("fmax_mhz_extraction_strategy")
    evidence = l2.get("fmax_mhz_evidence")
    has_strategy = (
        isinstance(strategy, str) and strategy
        and strategy.lower() not in {"none", "null"})
    has_evidence = (
        isinstance(evidence, str) and evidence
        and evidence.lower() not in {"none", "null"})
    if has_strategy and has_evidence:
        # Honest claim; leave untouched. Also ensure the sentinel
        # flag is False so downstream consumers know the value
        # comes from real source-doc evidence.
        l2["no_fmax_mhz_in_input"] = False
        return False
    if has_strategy and not has_evidence:
        # The `_v1_6_570_promote_l2_fmax_scalar` aggregation path
        # legitimately stamps a strategy without an inline evidence
        # substring (the evidence lives in `timing_parameters[]`).
        # Permit this canonical aggregator strategy without
        # requiring an inline evidence field.
        if "max_of_operating_frequency" in strategy:
            l2["no_fmax_mhz_in_input"] = False
            return False
    # No strategy stamp at all: this is the leak shape reported
    # in the field. Reset to None so downstream sees the honest
    # signal.
    l2["fmax_mhz"] = None
    l2["fmax_mhz_extraction_strategy"] = None
    l2["fmax_mhz_evidence"] = None
    l2["no_fmax_mhz_in_input"] = True
    l2["fmax_mhz_reset_reason_v1_6_579"] = (
        "scalar_lacked_strategy_and_evidence")
    return True


_RE_INSTALL_VERB_v1_6_315 = re.compile(
    r"\b(make|icarus|verilator|sudo\s+make\s+install|"
    r"for\s+\d+\s+bit|cmake|autotools|configure|gcc|clang)\b",
    re.IGNORECASE,
)


def _is_install_verb_v1_6_315(title) -> bool:
    """v1.6.315 — for #214 P2 ORGANIC. Return True when `title`
    matches the install / build / dev-env verb vocabulary. The
    FRS-section scanner calls this to reject install-step
    headings that would otherwise be misclassified as
    functional-requirement sections.

    Chip-AGNOSTIC: open-standard install / build / toolchain
    verb vocabulary.
    """
    if not isinstance(title, str) or not title:
        return False
    return bool(_RE_INSTALL_VERB_v1_6_315.search(title))
_RE_BULLET_DIR_PAREN = re.compile(
    r"(?i)\b(?P<dir>input|output|inout|in|out|io)\b"
)

# v1.6.257 — for #116 field-agent round-3 feedback. Real-shape
# bullet lines under a port heading carry multiple comma-separated
# identifiers, bracket-suffixed widths, and / or a parenthetical
# direction annotation:
#   - `uart_tx`, `uart_rx` — RS-232 to host
#   - `led[N-1:0]` — board LEDs
#   - `clk_i` (input, clock)
# Strategy: pull the bullet line stripped of its bullet prefix,
# find a *prose separator* (em-dash / en-dash / ` - ` / first
# `(`); everything before the separator is the name-region,
# everything after is the rest (description / direction). The
# name-region is then scanned for backticked identifiers (or, when
# no backticks, a single bare identifier). Each identifier is
# parsed for an optional `[...]` width suffix.
_RE_L1_BULLET_LINE = re.compile(r"(?m)^\s*[-*+]\s+(?P<line>[^\n]+)$")
_RE_L1_BULLET_SEPARATOR = re.compile(
    r"(?:\s+[—–]\s+|\s+-\s+|\s*\()"
)
_RE_L1_BULLET_NAME_BACKTICKED = re.compile(
    r"`(?P<name>[a-zA-Z_][a-zA-Z0-9_]{0,40})"
    r"(?P<bracket>\[[^\]\n]{1,40}\])?`"
)
_RE_L1_BULLET_NAME_BARE = re.compile(
    r"^(?P<name>[a-zA-Z_][a-zA-Z0-9_]{0,40})"
    r"(?P<bracket>\[[^\]\n]{1,40}\])?"
)

# v1.6.258 — for #118 ORGANIC. Common column-header tokens that
# leak when the L1 bullet picker is mis-applied to RST list-table
# header rows (`* - Signal\n  - Width\n  - Direction\n  ...`).
# These are NEVER real port names; reject them at the L1 bullet
# emit gate. Lower-case match against the captured name.
# Chip-AGNOSTIC: pure doc-table vocabulary.
# Issue #500 — the bullet-port header deny-list draws its column-role
# vocabulary from the ONE shared bilingual lexicon (name / direction /
# width / description / address / access / default / value / parameter /
# field / range / units) UNION a few bullet-list-specific structure
# tokens (synchronous / async / enables / out / in / inout / column /
# row). CJK header words (寬度 / 方向 / 描述 …) leaked from a CJK list-
# table header row are now denied as standalone bullet-port names too.
#
# Deliberately NOT denying: `data`, `addr`, `clock`, `clk`, `io` — those
# ARE common legitimate port-name stems (`data[7:0]`, `clk_i`, `clock`,
# `io`); only the list-table *header-row* shape would emit them as
# standalone tokens, and the `.. list-table::` directive-skip handles
# that case. Hence the lexicon `address` role's `addr` token would
# over-deny, so we draw the address role-tokens MINUS `addr`.
_BULLET_PORT_STRUCTURE_TOKENS = frozenset({
    "synchronous", "async", "enables", "out", "in", "inout",
    "column", "row", "type", "size",
})
_BULLET_PORT_COMMON_HEADER_TOKENS = (
    _hlex.tokens_for(
        "name", "direction", "width", "description", "access",
        "default", "value", "parameter", "field", "range", "units",
    )
    # `addr`, `data`, `io` are legitimate port-name stems; exclude them so
    # a bullet port literally named `data` / `addr` / `io` is not swallowed
    # (lexicon `value` role carries `data`, `address` carries `addr`,
    # `direction` carries `io`). The original bullet-port deny-list
    # deliberately omitted these stems.
    - {"addr", "data", "io"}
    | _BULLET_PORT_STRUCTURE_TOKENS
)

# v1.6.258 — for #118 ORGANIC. RST `.. list-table::` directive
# regex. Used to identify ranges where `* -` items are list-table
# rows (not free-form bullet ports). The bullet picker skips
# bullets that fall inside such a directive range.
_RE_RST_LIST_TABLE_DIRECTIVE = re.compile(
    r"(?m)^\s*\.\.\s+list-table::"
)


def _l1_bullet_port_extract(text: str) -> List[Dict[str, Any]]:
    """Return list of {name, mode, description} from any
    `<heading>:` + bullet-list block under recognised L1 port-
    related headings."""
    out: List[Dict[str, Any]] = []
    if not text:
        return out
    # v1.6.258 — for #118 ORGANIC. Compute byte-ranges covered by
    # any RST `.. list-table::` directive (heading + ~40 lines of
    # body). The bullet picker rejects any heading whose match
    # falls inside a list-table range — those bullets are RST
    # list-table rows (header + data), not free-form port bullets.
    list_table_ranges: List[Tuple[int, int]] = []
    for lm in _RE_RST_LIST_TABLE_DIRECTIVE.finditer(text):
        # End range = next non-blank line at zero indent (RST
        # directive scope) OR EOF, whichever comes first.
        body_start = text.find("\n", lm.end())
        if body_start < 0:
            list_table_ranges.append((lm.start(), len(text)))
            continue
        idx = body_start + 1
        end = len(text)
        while idx < len(text):
            nl = text.find("\n", idx)
            line = text[idx:nl if nl >= 0 else len(text)]
            if line.strip() and not (line.startswith(" ")
                                       or line.startswith("\t")
                                       or line.startswith("*")):
                end = idx
                break
            if nl < 0:
                break
            idx = nl + 1
        list_table_ranges.append((lm.start(), end))

    def _in_list_table(pos: int) -> bool:
        for s, e in list_table_ranges:
            if s <= pos < e:
                return True
        return False

    for hm in _RE_L1_BULLET_PORT_HEADING.finditer(text):
        # v1.6.258 — for #118 ORGANIC. Skip headings that sit
        # inside a `.. list-table::` directive body — those `* -`
        # rows are list-table cells, not port bullets.
        if _in_list_table(hm.start()):
            continue
        # Take up to 60 lines / 4000 chars after the heading, stopping
        # at the next blank-line+non-bullet boundary.
        tail = text[hm.end():hm.end() + 4000]
        # Stop at next heading or blank-line followed by non-bullet
        # narrative.
        bullet_lines: List[str] = []
        in_bullets = False
        for ln in tail.splitlines():
            if re.match(r"\s*[-*+]\s+", ln):
                bullet_lines.append(ln)
                in_bullets = True
                continue
            if not ln.strip():
                if in_bullets:
                    # blank line — peek; if followed by another bullet
                    # we continue, else break. We'll break unconditionally
                    # here for simplicity; bullet groups are usually
                    # contiguous.
                    break
                continue
            if in_bullets:
                # non-bullet line after bullets started — end of block.
                break
        body = "\n".join(bullet_lines)
        # v1.6.257 — for #116 field-agent round-3 feedback. Real-
        # shape bullet processing: split each line on a prose
        # separator into name-region + rest, scan for backticked
        # identifiers (or fallback bare-ident), preserve `[...]`
        # width per identifier.
        for hm2 in _RE_L1_BULLET_LINE.finditer(body):
            line_text = hm2.group("line")
            # Split on first prose separator.
            sep_m = _RE_L1_BULLET_SEPARATOR.search(line_text)
            if sep_m:
                name_region = line_text[:sep_m.start()].strip()
                rest = line_text[sep_m.end():].strip()
                if sep_m.group().endswith("("):
                    # `(` consumed; close at matching `)`.
                    close = rest.find(")")
                    if close >= 0:
                        rest = rest[:close]
            else:
                name_region = line_text.strip()
                rest = ""
            # Collect identifiers from the name-region. Prefer
            # backticked tokens (canonical RST/markdown convention);
            # fall back to a single bare ident at the start.
            id_hits = list(
                _RE_L1_BULLET_NAME_BACKTICKED.finditer(name_region))
            if not id_hits:
                bm = _RE_L1_BULLET_NAME_BARE.match(name_region)
                if not bm:
                    continue
                names_and_brackets = [(bm.group("name"),
                                       bm.group("bracket") or "")]
            else:
                names_and_brackets = [(m.group("name"),
                                        m.group("bracket") or "")
                                      for m in id_hits]
            for (name, bracket) in names_and_brackets:
                if len(name) < 3:
                    continue
                # v1.6.258 — for #118 ORGANIC. Reject common
                # column-header tokens that surface when the bullet
                # picker is mis-applied to RST list-table or
                # markdown grid-table header rows.
                if name.lower() in _BULLET_PORT_COMMON_HEADER_TOKENS:
                    continue
                # Direction precedence: explicit prose word > suffix
                # > heading-anchored default `input`.
                mode = None
                md = _RE_BULLET_DIR_PAREN.search(rest)
                if md:
                    raw = md.group("dir").lower()
                    mode = _DIR_ABBR_TO_FULL.get(raw, raw)
                if mode is None:
                    if _RE_DIR_SUFFIX_OUTPUT.search(name):
                        mode = "output"
                    elif _RE_DIR_SUFFIX_INOUT.search(name):
                        mode = "inout"
                    elif _RE_DIR_SUFFIX_INPUT.search(name):
                        mode = "input"
                if mode not in {"input", "output", "inout"}:
                    # v1.6.257 — heading-anchored default. Drop
                    # nothing under a recognised port heading; emit
                    # with conservative `input` direction.
                    mode = "input"
                # Parse bracketed width like `[N-1:0]` / `[7:0]`.
                width = None
                if bracket:
                    bw = re.match(r"\[(?P<msb>[^:]+):(?P<lsb>[^]]+)\]",
                                  bracket)
                    if bw:
                        try:
                            msb = int(bw.group("msb").strip())
                            lsb = int(bw.group("lsb").strip())
                            width = str(abs(msb - lsb) + 1)
                        except ValueError:
                            width = None
                out.append({
                    "name": name,
                    "mode": mode,
                    "width": width,
                    "bracket": bracket if bracket else None,
                    "description": rest[:160] if rest else None,
                })
    return out


# ── directional-prose port extractor (Inputs:/Outputs: headings) ─────────────
# Convergence 2026-06-21: a large class of CVDP specs state their ports as a
# bullet list under a DIRECTION heading rather than a "Ports:" heading, in two
# forms the `markdown_bullet_under_heading` walker above does not catch:
#   - Inputs:                          #### Inputs (1-bit width each):
#       - [7:0] in:  An 8-bit ...      - **i_S**: Set signal
#       - [2:0] out: A 3-bit ...       - **i_clk**: Clock signal
# i.e. (1) a `[msb:lsb]` WIDTH PREFIX before the name, and (2) a MARKDOWN-BOLD
# `**name**` identifier — both under an `Inputs:`/`Output(s):`/`Inout:` heading
# (bulleted `- Inputs:`, `#### Inputs ...:`, `**Inputs:**`, or a plain line).
# Direction comes from the HEADING (not a default). When the deterministic
# extractor leaves these ports out, a blind RTL author guesses the port
# name/case and the cocotb harness fails to bind ("contains no child object
# named X"). Emitted via _add_pin, whose width-aware dedup keeps the richer of
# any name collision — so this NEW source can only ADD or ENRICH, never drop a
# port another extractor already found (zero-regression by construction).
# chip-AGNOSTIC: direction-heading + bullet-definition shape only.
_RE_DIRECTIONAL_PORT_HEADING = re.compile(
    r"(?im)^\s*(?:[-*+]\s+|#{1,6}\s+)?\*{0,2}_{0,2}"
    r"(?P<dir>input|output|inout)s?"
    # Step-2.7: ONLY a port-list synonym (`ports`/`signals`/`pins`/`interface`/
    # `list`) and/or a `(width)` parenthetical may follow the direction word. A
    # heading with OTHER trailing words — "Output format:", "Input validation:",
    # "Input requirements:", "Output stage description:" — is a documentation
    # section, NOT a port list, and must NOT open a port block (its bullets are
    # features/options, not pins). The old `[^:\n]{0,40}?` arm accepted any
    # words and harvested those feature lists as phantom ports.
    r"(?:\s+(?:ports?|signals?|pins?|interface|list))?"
    r"(?:\s*\([^)\n]*\))?"
    # the colon may sit on EITHER side of the closing emphasis wrapper, so both
    # `**Inputs:**` (colon inside) and `**Inputs**:` (colon outside) match.
    r"\s*[:：]?\s*\*{0,2}_{0,2}\s*[:：]?\s*$"
)
# a bullet that DEFINES a port: optional [w] prefix, optional **/` wrappers,
# the identifier, optional [w] suffix, then a COLON (definition, not prose).
_RE_DIRECTIONAL_PORT_BULLET = re.compile(
    r"^\s*[-*+]\s+"
    r"(?:\[(?P<wpre>[^\]\n]{1,24})\]\s*)?"
    r"(?:\*{1,2}|__|`)?\s*"
    r"(?P<name>[A-Za-z_]\w{1,40})"
    r"(?:\*{1,2}|__|`)?\s*"
    r"(?:\[(?P<wpost>[^\]\n]{1,24})\]\s*)?"
    r"\s*[:：]"
    r"(?P<desc>[^\n]{0,200})?$"
)
# #czl9prompt — MOVED to `phase1_port_extract`, which the PROMPT front door
# already calls, so both doors now run this ONE implementation. The names below
# are aliases, not copies: there is exactly one definition of each, in that
# module. See the "ONE interface recovery core" section there for why.
_DIRECTIONAL_PORT_STOP = _ppx.DIRECTIONAL_PORT_STOP
_l1_inline_direction_bullet_port_extract = (
    _ppx.extract_inline_direction_bullet_ports)


def _l1_directional_prose_port_extract(text: str) -> List[Dict[str, Any]]:
    """Ports stated as bullets under an `Inputs:`/`Output(s):`/`Inout:`
    heading, with a `[msb:lsb]` width prefix or a `**bold**` name. Returns
    [{name, mode, width, description}]. Precision: a bullet contributes ONLY
    when it is a COLON definition (name immediately followed by `:`); a prose
    sentence and a stop-word token never qualify."""
    out: List[Dict[str, Any]] = []
    if not text:
        return out
    lines = text.splitlines()
    i = 0
    while i < len(lines):
        hm = _RE_DIRECTIONAL_PORT_HEADING.match(lines[i])
        if not hm:
            i += 1
            continue
        mode = {"input": "input", "output": "output",
                "inout": "inout"}[hm.group("dir").lower()]
        # a heading parenthetical width default, e.g. "(1-bit width each)"
        head_w = None
        hw = re.search(r"(\d{1,5})\s*[- ]?bit", lines[i], re.I)
        if hw:
            head_w = hw.group(1)
        # consume the bullet block that follows (any indent), stop at the
        # next directional heading or a non-bullet, non-blank narrative line.
        j = i + 1
        while j < len(lines):
            ln = lines[j]
            if not ln.strip():
                j += 1
                continue
            if _RE_DIRECTIONAL_PORT_HEADING.match(ln):
                break
            if not re.match(r"\s*[-*+]\s+", ln):
                # a non-bullet line ends the block UNLESS it is an indented
                # continuation of the previous bullet's description.
                if ln[:1] in (" ", "\t"):
                    j += 1
                    continue
                break
            bm = _RE_DIRECTIONAL_PORT_BULLET.match(ln)
            j += 1
            if not bm:
                continue
            name = bm.group("name")
            if not name or name.lower() in _DIRECTIONAL_PORT_STOP \
                    or len(name) < 2:
                continue
            desc = (bm.group("desc") or "").strip() or None
            # Step-2.7: a colon-bullet whose description is a short REGISTER /
            # memory-map LABEL is an internal addressable register, not a
            # top-level I/O port (`- CTRL: control register`). The label form is
            # `[adj] register(s)` (≤2 words then "register") — NOT a port whose
            # description merely mentions a register in a sentence (`- data_out:
            # drives the shift register`), which must still extract as a port.
            if desc and (
                    re.search(r"(?i)^\W*(?:\w+\W+){0,2}registers?\W*$", desc)
                    or re.search(r"(?i)\b(?:memory[\s-]?map|address\s+map)\b", desc)):
                continue
            wpre, wpost = bm.group("wpre"), bm.group("wpost")
            wraw = wpre or wpost
            width = None
            if wraw and ":" in wraw:                 # [msb:lsb]
                bw = re.match(r"\s*([^:]+):([^\]]+)\s*$", wraw)
                if bw:
                    try:
                        width = str(abs(int(bw.group(1).strip())
                                        - int(bw.group(2).strip())) + 1)
                    except ValueError:
                        # Step-2.7: a parameterized range ("[WIDTH-1:0]") is NOT
                        # a numeric Verilog width — emit None (unknown) so the
                        # author derives it from the parameter, not a junk string.
                        width = None
            elif wraw and wraw.strip().isdigit():     # [8]
                width = wraw.strip()
            if width is None and head_w:
                width = head_w
            out.append({"name": name, "mode": mode,
                        "width": width, "description": desc})
        i = j
    return out


# v1.6.256 — for #116 field-agent round-2 feedback. Same
# parenthetical-relaxation as the L1 port heading above.
_RE_L9_BULLET_SUBMOD_HEADING = re.compile(
    r"(?im)^\s*"
    r"(?:key\s+|main\s+|primary\s+)?"
    r"(?:\([^)\n]{0,80}\)\s+)?"
    r"(?:sub[-_]?modules?|sub[-_]?blocks?|"
    r"components?|building\s+blocks?|module\s+list)\s*[:.]?\s*$"
)

# v1.6.313 — for #212 P2 ORGANIC. The v1.6.256 heading vocab above
# accepts only `Submodules` / `Modules` / `Components` (plus
# singular). Open-source IC trees commonly use architectural
# synonyms: `Plugins`, `Subsystems`, `Cores`, `Units`, `Stages`,
# `Pipelines`. Broadened vocab + lifted from prefix-relaxed
# legacy variant to a pure `#{1,3}` Markdown heading + synonym
# alternation. Chip-AGNOSTIC: vocabulary is the conventional
# Markdown / RST section vocabulary, not chip-class.
_RE_L9_BULLET_SUBMOD_HEADING_v1_6_313 = re.compile(
    r"^#{1,3}\s+(?:Submodules?|Modules?|Components?|Cores?|"
    r"Plugins?|Subsystems?|Units?|Stages?|Pipelines?|"
    # v1.0.38 — for #648. Hierarchy / instantiation-tree /
    # integration / port-mapping headings are equally-conventional
    # SoC-documentation anchors for a submodule inventory and were
    # missing from the vocab, so bullet/tree blocks under them were
    # dropped. chip-AGNOSTIC documentation vocabulary.
    r"Hierarchy|Instantiation(?:\s+(?:Tree|Hierarchy))?|"
    r"(?:Submodule\s+)?Integration|Port[\s\-]?mapping)\b",
    re.IGNORECASE | re.MULTILINE,
)

# v1.6.313 — RST h3-subsection style: a snake_case title line
# followed by a row of caret OR tilde characters of matching
# length (canonical RST level-3 underline). Many RST-flavoured
# IC documents enumerate submodules via this shape instead of a
# bullet list. Chip-AGNOSTIC: the regex is the conventional RST
# level-3 underline pattern, no chip literal participates.
_RE_RST_H3_SUBMODULE_v1_6_313 = re.compile(
    r"^([a-z][a-z0-9_]{3,40})\n[\^~]+$",
    re.MULTILINE,
)


def _l9_strategy_a0b_rst_h3_subsections_v1_6_313(
        text: str, mod_h2_pos: int):
    """v1.6.313 — for #212 P2 ORGANIC. Strategy A0b — scan a
    ±4000-char window around the Modules/Architecture h2 for
    canonical RST level-3 subsection titles. Each match is a
    snake_case submodule name. Emits low_confidence: True so a
    later quality gate can down-weight RST h3 hits if needed.

    Chip-AGNOSTIC: window + regex shape only; no chip literal
    participates.
    """
    if not text:
        return
    window_lo = max(0, mod_h2_pos - 4000)
    window_hi = min(len(text), mod_h2_pos + 4000)
    window = text[window_lo:window_hi]
    for m in _RE_RST_H3_SUBMODULE_v1_6_313.finditer(window):
        name = m.group(1)
        if _is_real_submodule_name(name):
            yield {
                "name": name,
                "extraction_strategy":
                    "rst_h3_subsection_under_modules_h2",
                "low_confidence": True,
            }


# v0.1.82 — for the digital benchmark l_doc loop (subservient SoC). SoC
# integration specs list required sub-modules as NUMBERED sub-headings
# (`### 8.2.1 SERV core(必含)`, `### 8.2.4 GPIO peripheral`) rather than a
# bullet list under one heading, so the bullet extractor missed them and L9
# carried submodules=[]. This heading extractor parses numbered sub-headings
# in a submodule-integration-context doc. Chip-AGNOSTIC + input-docs only.
_RE_L9_SUBMOD_NUM_HEADING = re.compile(
    r'^#{2,4}\s*\d+(?:\.\d+)+\s+([^\n(（]+?)\s*(?:[\(（]|$)', re.M)
_RE_L9_SUBMOD_DOC_CTX = re.compile(
    r'(?i)sub[\s_-]?module|submodule|對外契約|module\s+integration|階層')


# v0.2.62 — ORGANIC-20260606-l9-ports-empty-submodule-pollution (#431).
# A verification-plan / test-plan layer doc routinely SAYS "submodule-level
# verification" in its prose, which armed _RE_L9_SUBMOD_DOC_CTX and turned
# every numbered stage heading ("## 1.1 Smoke Test Stage", …) into a phantom
# L9 submodule. Two deny layers: (1) doc-TYPE — a doc whose opening
# identifies itself as a verification/test plan is never a submodule
# inventory source; (2) entry — a heading whose name reads as a
# verification-activity title (…Stage / …Test / …Phase / …Scenario / …Plan)
# is a section title, not a module. chip-AGNOSTIC: doc-genre vocabulary.
_RE_L9_SUBMOD_DOC_DENY = re.compile(
    r'(?i)verification\s+plan|test\s+plan|verification\s+strategy'
    r'|驗證計畫|測試計畫|驗證策略')
_RE_L9_SUBMOD_ENTRY_DENY = re.compile(
    r'(?i)\b(?:stage|test|tests|phase|step|case|cases|scenario|plan'
    r'|coverage|regression|checklist)\s*$')


def _l9_heading_submodule_extract(text: str) -> List[str]:
    """Parse numbered sub-headings (`### N.N[.N] <name>`) of a submodule-
    integration-context doc into submodule names. Skips section titles that
    are themselves about the integration spec (not a concrete submodule)."""
    if not text or not _RE_L9_SUBMOD_DOC_CTX.search(text):
        return []
    # (#431 deny layer 1) verification/test-plan docs are not module sources
    if _RE_L9_SUBMOD_DOC_DENY.search(text[:1200]):
        return []
    out: List[str] = []
    # Section-title words (not concrete submodule names) to drop.
    _skip = ('integration', 'spec', 'overview', 'sub-module', 'submodule',
             '契約', '適用', '總覽', '概述', 'option', '選擇', '必要',
             '層級', '不在', '約束', '範圍', '概覽', 'level', 'scope')
    for m in _RE_L9_SUBMOD_NUM_HEADING.finditer(text):
        nm = m.group(1).strip().strip('`*').strip()
        if not nm or len(nm) > 48:
            continue
        low = nm.lower()
        if any(w in low for w in _skip):
            continue
        # (#431 deny layer 2) verification-activity titles are not modules
        if _RE_L9_SUBMOD_ENTRY_DENY.search(nm):
            continue
        if nm not in out:
            out.append(nm)
    return out


def _l9_bullet_submodule_extract(text: str) -> List[str]:
    """Return list of submodule names from a `<heading>:` + bullet-
    list block under recognised L9 submodule-related headings.

    v1.6.313 — for #212 P2 ORGANIC. Heading-scan now runs over the
    UNION of the legacy `_RE_L9_BULLET_SUBMOD_HEADING` (prefix-
    relaxed colon-terminated form: `Key sub-blocks:`,
    `Submodules:`) AND the broadened
    `_RE_L9_BULLET_SUBMOD_HEADING_v1_6_313` (Markdown `#{1,3}` form
    with vocab Plugins / Subsystems / Cores / Units / Stages /
    Pipelines / Submodules / Modules / Components). Both shapes are
    common in open-source IC trees; running the union catches both
    without regressing the legacy fixture set.
    """
    out: List[str] = []
    if not text:
        return out
    # v1.6.314 — for #213 P2 ORGANIC. Pre-pass: normalise
    # bracketed-link bullets `- [LinkText](url)` into plain-text
    # bullets `- LinkText` so the existing `_RE_L1_BULLET_ITEM`
    # regex (which requires the first non-list-marker char to be
    # `[a-zA-Z_]`) matches the canonical Markdown TOC shape.
    text = _preprocess_md_bracketed_link_bullets_v1_6_314(text)
    seen_pos: Set[int] = set()
    heading_starts: List[int] = []
    for hm in _RE_L9_BULLET_SUBMOD_HEADING.finditer(text):
        if hm.end() in seen_pos:
            continue
        seen_pos.add(hm.end())
        heading_starts.append(hm.end())
    for hm in _RE_L9_BULLET_SUBMOD_HEADING_v1_6_313.finditer(text):
        # The v2 regex matches only the heading line; jump to end
        # of that line so the bullet-scan starts on the next line.
        line_end = text.find("\n", hm.end())
        end_pos = line_end if line_end >= 0 else hm.end()
        if end_pos in seen_pos:
            continue
        seen_pos.add(end_pos)
        heading_starts.append(end_pos)
    for start in sorted(heading_starts):
        tail = text[start:start + 4000]
        bullet_lines: List[str] = []
        in_bullets = False
        for ln in tail.splitlines():
            if re.match(r"\s*[-*+]\s+", ln):
                bullet_lines.append(ln)
                in_bullets = True
                continue
            if not ln.strip():
                if in_bullets:
                    break
                continue
            if in_bullets:
                break
        body = "\n".join(bullet_lines)
        for ml in body.splitlines():
            # v1.0.38 — for #648. When the bullet body is an
            # "X instantiates `Y`" sentence, the CHILD is harvested by the
            # dedicated `_v1_0_38_prose_instantiates_children` parser; skip the
            # whole bullet here so broadening the heading vocab to include
            # `Integration` / `Hierarchy` does not leak the parent/prose words.
            if _V1_0_38_PROSE_INSTANTIATES_RE.search(ml):
                continue
            # ORGANIC #648 round-2 — a submodule name must carry trustworthy
            # provenance (§4.05 no-leak): it appears INSIDE a backtick
            # code-span (accepted via the relaxed legal-id gate, so short
            # children like `counter` survive), OR — for a BARE leading bullet
            # word — it passes the STRICT `_is_real_submodule_name` RTL-shape
            # gate. A bare prose word under a broadened heading (`Clock` /
            # `Single` / `The`) is neither code-spanned nor RTL-shaped, so it
            # is excluded.
            # The code-span must be in the bullet's NAME position — see
            # `_l9_bullet_declares_codespan_name`. A span buried in a
            # sentence is a reference, not a declaration, so only the
            # LEADING span is a candidate.
            cs = []
            if _l9_bullet_declares_codespan_name(ml):
                cs = [c for c in _v648r2_codespan_idents(ml)[:1]
                      if _is_codespan_submodule_name(c)]
            if cs:
                out.extend(cs)
                continue
            m = _RE_L1_BULLET_ITEM.match(ml)
            if not m:
                continue
            name = m.group("name")
            if len(name) < 3 or not _is_real_submodule_name(name):
                continue
            out.append(name)
    return out


# v1.0.38 — for #648. Prose "instantiation" sentence parser. Plain
# integration / hierarchy docs routinely declare the parent→child
# instantiation relation in a single prose sentence rather than a
# bullet list or an ASCII tree, e.g.
#
#     - `top_wrapper` (top) instantiates exactly one `child_a`
#     - `child_a #(.BITS(32))` instantiates one `child_b #(.BITS(32))`
#
# Neither the bullet-heading walker nor the ASCII-tree walker
# detects this shape, so the declared CHILDREN were dropped and L9
# emitted `submodules: []` → stub-module risk. The parser captures
# the right-hand `instantiates [exactly] one|<N>|a|an <child>`
# child identifier (the parent on the left is the module being
# described, not a submodule of itself, so only the child is
# emitted). A trailing `#(...)` parameter-override block is
# tolerated and stripped. Each captured child still passes the
# shared `_is_real_submodule_name` gate at the call-site.
#
# chip-AGNOSTIC: the `X instantiates [N] Y` relation is a universal
# hierarchical-SoC documentation convention — no chip-class string
# literal participates.
# ORGANIC #648 round-2 — backtick-code-span provenance helpers. A submodule
# name harvested from prose/bullets MUST appear inside a backtick code-span
# (the author's explicit "this is an identifier" marker) — a BARE prose word
# (`Clock` / `Single` / `The` / `everything`) is NEVER code-spanned and must
# not leak into L9.submodules (§4.05 no-leak). A code-spanned LEGAL identifier
# is accepted even when the strict RTL-shape gate would reject it (the backtick
# is the evidence), so short / vowel-sparse real children like `counter` are
# kept. chip-AGNOSTIC: pure backtick grammar + identifier legality.
_V648R2_LEGAL_ID_RE = re.compile(r"^[A-Za-z_][A-Za-z0-9_$]*$")
_RE_V648R2_CODESPAN = re.compile(r"`\s*([A-Za-z_][A-Za-z0-9_$]*)\b[^`]*`")


def _v648r2_codespan_idents(text_fragment: str) -> List[str]:
    """ORGANIC #648 round-2 — ordered, de-duplicated leading identifiers of the
    backtick code-spans in ``text_fragment`` (a trailing `#(.PARAM(...))`
    override inside the span is ignored). chip-AGNOSTIC."""
    if not isinstance(text_fragment, str):
        return []
    out: List[str] = []
    for m in _RE_V648R2_CODESPAN.finditer(text_fragment):
        tok = m.group(1)
        if tok not in out:
            out.append(tok)
    return out


# A backtick says "this token is CODE". It does NOT say "this token is a
# MODULE". IC prose backticks parameters, config keys, signals, filenames and
# language keywords constantly, and always for the same reason: to mark an
# identifier inside a sentence ABOUT something else --
#
#     - the minimum pad spacing is `min_distance = 0.1` um
#     - Checks if `priority_override` is non-zero.
#     - all ports are unsigned (do not use the `signed` keyword)
#
# Every one of those was harvested into `L9.submodules` on the published
# corpus. What separates them from a declaration is not the token, it is the
# POSITION: a bullet that DECLARES a submodule puts the identifier in its NAME
# field -- the bullet leads with it and the rest describes it --
#
#     - `rx_phy` — recovers the line clock
#     - **`ctrl_fsm`**: main sequencer
#     - 2x `sram_bank` (dual-ported)
#
# whereas a bullet that MENTIONS one puts words in front of it. So the rule is
# "the identifier must open the bullet", which is decidable from the bullet's
# own structure and needs no vocabulary to maintain. Note this is what makes
# the pre-existing reserved-keyword deny list unnecessary for the `signed`
# case rather than merely lucky: `signed` is rejected because of WHERE it sits,
# not because it is on a list -- and an unusual-but-legal name in the same
# position is admitted for the same reason. That list is left in place; it is
# not this change's to remove.
#
# chip-AGNOSTIC and language-AGNOSTIC: Markdown list/emphasis punctuation and
# a numeric multiplicity prefix only. The corpus bullets this rejects are
# written in English and in Chinese and are rejected identically, because the
# rule never reads the words -- only whether any word precedes the span.
_RE_L9_BULLET_NAME_POSITION = re.compile(
    r"^\s*[-*+]\s+"          # the list marker
    r"(?:\d+\s*[x×]\s*)?"   # optional multiplicity prefix: `2x` / `4 × `
    r"[*_~#\s]*"             # optional emphasis / heading markup
    r"`"                     # ...and then the code-span must open
)


def _l9_bullet_declares_codespan_name(bullet_line: str) -> bool:
    """True iff ``bullet_line`` puts a backtick code-span in its NAME
    position -- i.e. no WORD precedes the span.

    False for a bullet that merely mentions a code-spanned identifier inside a
    sentence. chip-AGNOSTIC: list/emphasis punctuation only."""
    if not isinstance(bullet_line, str):
        return False
    return bool(_RE_L9_BULLET_NAME_POSITION.match(bullet_line))


def _is_codespan_submodule_name(name: str) -> bool:
    """ORGANIC #648 round-2 — relaxed acceptance for a name carrying backtick
    code-span provenance: any legal Verilog identifier (len>=2) that is not a
    doc-table header or a common English verb. The strict RTL-shape gate is NOT
    applied (the backtick is the evidence), so short / vowel-sparse real
    modules (`counter`, `alu`) are admitted; bare prose words are already
    excluded at the extraction site by the backtick requirement. chip-AGNOSTIC."""
    if not isinstance(name, str):
        return False
    nm = name.strip()
    if len(nm) < 2 or not _V648R2_LEGAL_ID_RE.match(nm):
        return False
    low = nm.lower()
    return (low not in _DOC_TABLE_HEADER_TOKENS
            and low not in _COMMON_ENGLISH_VERB_TOKENS)


_V1_0_38_PROSE_INSTANTIATES_RE = re.compile(
    r"instantiat(?:es?|ed|ing)\b"
    # optional count qualifier: exactly / one / two / a / an / digits
    r"(?:\s+(?:exactly|at\s+least|up\s+to|a|an|one|two|three|four|"
    r"five|six|seven|eight|nine|ten|\d+))*"
    r"\s+"
    # ORGANIC #648 round-2 — the child identifier MUST be backtick-fenced (a
    # bare object like "instantiates everything" is prose, not a submodule),
    # with an optional `#(...)` parameter-override block inside the span.
    r"`\s*(?P<child>[A-Za-z_]\w*)"
    r"(?:\s*#\s*\([^()]*(?:\([^()]*\)[^()]*)*\))?\s*`",
    re.IGNORECASE,
)


def _v1_0_38_prose_instantiates_children(text: str) -> List[str]:
    """v1.0.38 — for #648. Return the ordered, de-duplicated list of
    child module identifiers declared by prose `X instantiates
    [exactly] one|N `Y`` sentences in ``text``. Only the right-hand
    child is emitted; the left-hand parent is the subject of the
    sentence (not a submodule of itself). Empty list when no such
    sentence is present. chip-AGNOSTIC."""
    out: List[str] = []
    if not isinstance(text, str) or not text:
        return out
    seen: Set[str] = set()
    for m in _V1_0_38_PROSE_INSTANTIATES_RE.finditer(text):
        child = (m.group("child") or "").strip()
        if not child or child in seen:
            continue
        seen.add(child)
        out.append(child)
    return out


# v1.0.38 — for #648. Wrapper→child markdown port-map table router.
# An integration doc commonly pins a parent→child connectivity table
# whose header row names the child module, e.g.
#
#     | top_wrapper port | child_a port | width |
#     | ---------------- | ------------ | ----- |
#     | clk              | clk          | 1     |
#
# The child-module name living in a header cell of a wrapper→child
# port-map table is itself evidence of an instantiated submodule.
# This router parses such a table and returns the child name + the
# (parent_port -> child_port) pairs so the L9 builder can attach a
# `port_map` to the corresponding submodule. chip-AGNOSTIC: GitHub-
# flavoured-Markdown grid-table grammar — no chip-class literal.
_V1_0_38_PORTMAP_HEADER_RE = re.compile(
    r"^\s*\|\s*(?P<parent>[A-Za-z_]\w*)\s+port\s*\|\s*"
    r"(?P<child>[A-Za-z_]\w*)\s+port\s*\|",
    re.IGNORECASE,
)


def _v1_0_38_wrapper_child_port_maps(text: str) -> List[Dict[str, Any]]:
    """v1.0.38 — for #648. Parse every wrapper→child markdown
    port-map table in ``text``. Returns a list of
        {child: <name>, port_map: [{parent_port, child_port}, ...]}
    one per table. The child name is taken from the second
    `<name> port` header cell; the parent name from the first.
    Empty list when no such table is present. chip-AGNOSTIC."""
    out: List[Dict[str, Any]] = []
    if not isinstance(text, str) or not text:
        return out
    lines = text.splitlines()
    i = 0
    while i < len(lines):
        hm = _V1_0_38_PORTMAP_HEADER_RE.match(lines[i])
        if hm is None:
            i += 1
            continue
        child = hm.group("child")
        pairs: List[Dict[str, str]] = []
        j = i + 1
        # Skip the GFM separator row (`| --- | --- |`) if present.
        if (j < len(lines)
                and re.match(r"^\s*\|[\s:\-|]+\|\s*$", lines[j])):
            j += 1
        # Collect body rows until a non-table line.
        while j < len(lines):
            row = lines[j]
            cells = [c.strip() for c in row.strip().strip("|").split("|")]
            if not row.strip().startswith("|") or len(cells) < 2:
                break
            p_port, c_port = cells[0], cells[1]
            if re.fullmatch(r"[A-Za-z_]\w*", p_port) and \
                    re.fullmatch(r"[A-Za-z_]\w*", c_port):
                pairs.append({"parent_port": p_port,
                              "child_port": c_port})
            j += 1
        out.append({"child": child, "port_map": pairs})
        i = j
    return out


# v1.6.415 — for #297 P2 ORGANIC. DSL plugin-class submodule filter.
# `markdown_bullet_under_heading` walker collects CamelCase identifiers
# under "Modules" / "Components" / "Plugins" headings without
# distinguishing real Verilog modules from SpinalHDL / Chisel / Migen
# DSL class names. Field-agent observed 22/23 entries on SpinalHDL CPU
# (≈96%) are DSL classes — `FetcherPlugin`, `BranchPlugin`,
# `DBusCachedPlugin` and similar. They share a stable suffix vocabulary
# (`Plugin`, `Service`, `Component`, `Bundle`, `Stage`, `Phase`) that
# Verilog modules essentially never use, so suffix + companion-file
# evidence is a high-precision filter.
#
# Chip-AGNOSTIC: shapes only (CamelCase suffix vocab + file existence
# probe under arbitrary project root). No chip-class literal participates.
_V1_6_415_DSL_CLASS_SUFFIXES = (
    "Plugin", "Service", "Component", "Bundle",
    "Stage", "Phase",
)


def _v1_6_415_is_likely_rtl_module(
        name: str, text_window: str, project_root) -> bool:
    """Decide if a CamelCase name is likely a real Verilog/SV/VHDL
    module vs. SpinalHDL/Chisel/Migen DSL class. True if:
      - text_window mentions `<name>.{v,sv,vh,svh,vhd,vhdl}`, OR
      - project tree has a matching file, OR
      - name doesn't end in known DSL suffix (default-include).
    Else False (drop). Chip-AGNOSTIC."""
    import re as _re
    from pathlib import Path as _Path
    if not name:
        return False
    ext_pattern = _re.compile(
        rf"\b{_re.escape(name)}\.(v|sv|svh|vh|vhd|vhdl)\b",
        _re.IGNORECASE,
    )
    if ext_pattern.search(text_window or ""):
        return True
    try:
        proot = _Path(str(project_root)) if project_root else None
        if proot and proot.exists():
            for ext in (".v", ".sv", ".svh", ".vh", ".vhd", ".vhdl"):
                if list(proot.rglob(f"{name}{ext}")):
                    return True
    except Exception:
        pass
    if any(name.endswith(s) for s in _V1_6_415_DSL_CLASS_SUFFIXES):
        return False
    return True


def _infer_direction_from_suffix(signal: str) -> str:
    if _RE_DIR_SUFFIX_OUTPUT.search(signal):
        return "output"
    if _RE_DIR_SUFFIX_INOUT.search(signal):
        return "inout"
    if _RE_DIR_SUFFIX_INPUT.search(signal):
        return "input"
    return "input"

# v1.6.248 — for #109. Verilog/SystemVerilog port-declaration
# extractor. Two shapes:
#   (a) `input [31:0] mem_addr,` — bare port decl
#   (b) `.clk_i ( clk_i )`        — instantiation port-binding
# Both shapes are common inside markdown ```verilog ``` fences and
# RST `.. code-block:: verilog` literal blocks. The extractor is
# GATED on being inside such a block — running on prose freely
# would flood the pin table.
_RE_VERILOG_PORT_DECL = re.compile(
    r"(?m)^\s*"
    r"(?P<dir>input|output|inout)"
    r"(?:\s+(?P<kind>wire|reg|logic))?"
    r"\s*(?:\[\s*(?P<msb>\d+)\s*:\s*(?P<lsb>\d+)\s*\])?"
    r"\s+(?P<name>[a-zA-Z_][\w]*)"
    r"\s*,?\s*$"
)
# v1.6.320 — for #219 ORGANIC P2. Verilog/SystemVerilog implicit
# 1-bit port-decl shape. The IEEE-1800 language standard mandates
# that any `(input|output|inout) <name>` declaration WITHOUT a
# preceding packed-dimension `[N:0]` is implicitly 1-bit. The
# pre-v1.6.320 extractors emitted these as `width=null/?` because
# the explicit-width capture group was the only width source.
#
# This regex is the same shape as `_RE_VERILOG_PORT_DECL` but with
# a negative lookahead `(?!\[)` after the direction keyword, so it
# matches ONLY the implicit-1-bit case. The explicit-width branch
# still goes through `_RE_VERILOG_PORT_DECL` and takes precedence
# at the call site (we only consult this regex when the explicit
# branch did not parse a width).
#
# Chip-AGNOSTIC: pure Verilog/SV grammar pattern; no chip-class
# string literal participates.
_RE_VERILOG_PORT_IMPLICIT_1BIT_v1_6_320 = re.compile(
    r"\b(output|input|inout)\s+(?!\[)([a-z_][a-z0-9_]+)\b",
    re.IGNORECASE,
)


# v1.6.321 — for #220 ORGANIC P2. Heading-style and RST field-list
# parameter documentation extractors. Open-source HDL projects
# commonly document Verilog/SV `parameter` defaults under H3/H4
# headings (`#### ENABLE_COUNTERS (default = 1)`) or RST field-list
# directives (`:Parameter: ENABLE_COUNTERS`). Pre-v1.6.321 the
# Phase 1 (doc-extraction) extractors only consumed table-style parameter rows so
# the heading-style and RST forms dropped silently.
#
# `_RE_MD_PARAM_H4_HEADING_v1_6_321` — H3 or H4 heading whose body
# is an UPPERCASE token (optionally backtick-quoted), with an
# optional `(default = N)` / `(reset: N)` clause. The default
# capture group is permissive (digit + alphanumeric + underscore)
# to handle integer, hex, binary, and enumeration defaults.
#
# `_RE_RST_PARAM_DIRECTIVE_v1_6_321` — RST field-list directive
# `:Parameter: NAME`. Default is not captured (RST field-list
# values usually live in the following paragraph; we record the
# name + tag and let downstream consult the surrounding text).
#
# Chip-AGNOSTIC: pure GFM / RST grammar patterns; no chip-class
# string literal participates.
_RE_MD_PARAM_H4_HEADING_v1_6_321 = re.compile(
    r"^#{3,4}\s+`?([A-Z][A-Z0-9_]{2,30})`?\s*"
    r"(?:\(?\s*(?:default|reset)\s*[=:]\s*([\dA-Za-z_]+)\s*\)?)?",
    re.MULTILINE,
)

# v1.6.335 — for #233 P2 ORGANIC. STRICT variant of the v1.6.321
# H4 regex. The default clause is now MANDATORY (not optional), so
# plain H3 / H4 section headings like `#### README`, `####
# ARCHITECTURE`, `#### LATCHED_MEM_RDATA` (the canonical false-
# positive shapes observed on the benchmark) NO LONGER emit a
# fake design-parameter row with default=None. Only headings
# carrying an explicit `(default = N)` / `(reset: N)` clause are
# treated as parameter definitions.
#
# Chip-AGNOSTIC: pure structural grammar; no chip-class literal.
_RE_MD_PARAM_H4_HEADING_v1_6_335 = re.compile(
    r"^#{3,4}\s+`?([A-Z][A-Z0-9_]{2,30})`?\s*"
    r"\(?\s*(?:default|reset)\s*[=:]\s*([\dA-Za-z_]+)\s*\)?",
    re.MULTILINE,
)

# v1.6.390 — for #281 P3 ORGANIC. The v1.6.335 H4 regex used a narrow
# value-capture `([\dA-Za-z_]+)` that truncates Verilog sized literals
# at the apostrophe: `#### NAME (default = 32'h0000_0000)` captured
# only `"32"` because `'` was not in the character class. Real-world
# RTL/CSR documentation routinely uses Verilog sized literals for
# reset-value clauses, so this silently corrupted every such default.
#
# Fix: replace the narrow group with a named `(?P<val>...)` alternation
# covering the canonical literal shapes:
#   * Verilog sized literal `<N>'[hHbBdDoO]<digits-with-_-xX-zZ>`
#   * `0x...` hexadecimal (with `_` digit separators)
#   * `0b...` binary    (with `_` digit separators)
#   * decimal           (with `_` digit separators, optional sign)
#   * boolean `true` / `false`
#   * parametric reference (UPPER_SNAKE identifier)
#
# The v1.6.335 constant is kept defined above for backward compat
# (any external pinned test still imports it). Call sites switch to
# the v1.6.390 regex via `_RE_MD_PARAM_H4_HEADING_v1_6_390`.
#
# Companion helper `_v1_6_390_normalize_verilog_literal` strips
# internal whitespace inside a sized literal so `"32'h 0000_0000"`
# (space after the base-specifier — observed in the wild) normalises
# to `"32'h0000_0000"`.
#
# Chip-AGNOSTIC: pure Verilog / numeric grammar; no chip-class
# string literal participates.
_RE_MD_PARAM_H4_HEADING_v1_6_390 = re.compile(
    r"^#{3,4}\s+`?([A-Z][A-Z0-9_]{2,30})`?\s*\(?\s*"
    r"(?:default|reset)\s*[=:]\s*"
    r"(?P<val>"
    r"\d+'[hHbBdDoO]\s*[\dA-Fa-f_xXzZ]+"     # Verilog sized literal
    r"|0[xX][\dA-Fa-f_]+"                    # 0x hex
    r"|0[bB][01_]+"                          # 0b binary
    r"|[+-]?\d[\d_]*"                        # decimal
    r"|true|false"                           # boolean
    r"|[A-Z][A-Z0-9_]*"                      # parametric ref
    r")\s*\)?",
    re.MULTILINE | re.IGNORECASE,
)


def _v1_6_390_normalize_verilog_literal(val: str) -> str:
    """v1.6.390 — for #281 P3 ORGANIC. Strip internal whitespace
    inside a Verilog sized literal so `"32'h 0000_0000"` normalises
    to `"32'h0000_0000"`. Non-Verilog literals pass through with
    only outer whitespace stripped.

    Chip-AGNOSTIC: pure structural Verilog grammar; no chip-class
    string literal participates.
    """
    import re as _re
    m = _re.match(r"^(\d+'[hHbBdDoO])\s*(.+)$", val or "")
    if m:
        return m.group(1) + m.group(2).strip()
    return (val or "").strip()


def _v1_6_335_dedup_against_section_titles(
        params: List[Dict[str, Any]],
        section_titles: Optional[List[str]] = None,
) -> List[Dict[str, Any]]:
    """v1.6.335 — for #233 P2 ORGANIC. Post-filter that drops
    design-parameter entries whose `name` (case-insensitive) appears
    in `section_titles` (typically L2.frs_sections titles). Used as
    secondary defense alongside the strict v1.6.335 H4 regex.

    `params` is a list of `{name, default, ...}` dicts. `section_titles`
    is the list of frs_sections titles already extracted at the L2
    stage; pass `None` to skip the dedup pass entirely.

    Returns a NEW list. Chip-AGNOSTIC: pure structural set membership.
    """
    if not section_titles:
        return list(params or [])
    forbidden = {
        str(t).strip().upper()
        for t in section_titles
        if isinstance(t, str)
    }
    out: List[Dict[str, Any]] = []
    for p in params or []:
        if not isinstance(p, dict):
            out.append(p)
            continue
        name = (p.get("name") or p.get("parameter") or "")
        if isinstance(name, str) and name.strip().upper() in forbidden:
            # Drop — `name` is also a section title.
            continue
        out.append(p)
    return out

_RE_RST_PARAM_DIRECTIVE_v1_6_321 = re.compile(
    r"^:Parameter:\s*`?([A-Z][A-Z0-9_]{2,30})`?",
    re.MULTILINE,
)


# v1.6.322 — for #221 ORGANIC P3. Sphinx `.. wavedrom::` directive
# extractor. The directive embeds a WaveDrom JSON-like payload
# rendered by the sphinxcontrib-wavedrom extension; payload lines
# are indented relative to the directive marker. Pre-v1.6.322
# `gen_l8_timing_waveform_doc` only scanned ASCII-table and inline
# `<NAME> = <NUM> <UNIT>` shapes, so every wavedrom block in a
# Sphinx tree dropped silently.
#
# Regex shape:
#   ^\.\. wavedrom::\s*$\n((?:^[ \t]+.*$\n?)+)
# matches `.. wavedrom::` on its own line followed by one or more
# indented (tab/space) payload lines until the first dedent.
#
# Chip-AGNOSTIC: pure Sphinx grammar pattern; no chip-class string
# literal participates.
_RE_WAVEDROM_DIRECTIVE_v1_6_322 = re.compile(
    r"^\.\.\s+wavedrom::\s*$\n((?:^[ \t]+.*$\n?)+)",
    re.MULTILINE,
)


# v1.6.429 — for #306 P2 ORGANIC. Sphinx directive grammar lets the
# options block end with a blank line and then continue with the
# directive body (indented at the same level). The v1.6.322 regex
# stopped at the first blank line so the WaveJSON signal payload
# was completely dropped — every `.. wavedrom::` block with an
# options block emitted `raw_payload` containing only `:name: ...`
# and `:caption: ...` while the actual signal definitions were
# silently truncated.
#
# Fix: a structural directive-body parser that handles the canonical
# two-pass Sphinx grammar (options → blank → body), tolerates blank
# lines INSIDE the body, and stops on dedent or next directive.
# Chip-AGNOSTIC: pure Sphinx grammar; no chip-class string literal.
_RE_V1_6_429_WAVEDROM_HEADER = re.compile(
    r"^\.\.\s+wavedrom::\s*$",
    re.MULTILINE,
)


def _v1_6_429_parse_wavedrom_directive(text: str, header_match):
    """v1.6.429 — for #306 P2. Parse the full body of a single
    `.. wavedrom::` directive, returning (options_dict, body_str,
    end_offset_in_text).

    Two-pass walker:
      1. Options pass: lines starting with `:key: value` until first
         blank line.
      2. Body pass: skip blanks, then collect every indented line
         (at >= base_indent) including INTERNAL blank lines until a
         non-blank line dedents below base_indent or EOF.

    `end_offset_in_text` is the offset one past the last consumed
    line so the call site can advance its scan cursor.

    Chip-AGNOSTIC: pure Sphinx-directive grammar.
    """
    if not text or header_match is None:
        return {}, "", 0
    start = header_match.end()
    # The header regex matches `.. wavedrom::` up to (but not
    # including) the trailing newline. Skip past that newline so
    # the first line we read is the FIRST line under the directive.
    if start < len(text) and text[start] == "\n":
        start += 1
    elif (start + 1 < len(text)
          and text[start] == "\r" and text[start + 1] == "\n"):
        start += 2
    # Newlines split — keep `splitlines(keepends=True)` so we can
    # reconstruct character offsets exactly.
    lines_with_ends = []
    pos = start
    while pos < len(text):
        nl = text.find("\n", pos)
        if nl < 0:
            lines_with_ends.append((pos, len(text), text[pos:]))
            break
        lines_with_ends.append((pos, nl + 1, text[pos:nl + 1]))
        pos = nl + 1
    if not lines_with_ends:
        return {}, "", start
    # Skip the trailing newline of the header line itself if the
    # match consumed up to "::" not the newline.
    options: Dict[str, str] = {}
    body_lines: List[str] = []
    base_indent = None
    saw_blank_between = False
    end_offset = start
    i = 0
    while i < len(lines_with_ends):
        a, b, raw = lines_with_ends[i]
        line = raw.rstrip("\n").rstrip("\r")
        stripped = line.strip()
        if not stripped:
            # Blank line: in options-pass it terminates options. In
            # body-pass it stays inside the body unless followed by
            # a dedent.
            if base_indent is None:
                # In options pass — blank ends options, transition.
                saw_blank_between = True
                end_offset = b
                i += 1
                continue
            # In body pass — keep as part of body for fidelity.
            body_lines.append("")
            end_offset = b
            i += 1
            continue
        # Non-blank line. Compute its leading indent.
        indent = len(line) - len(line.lstrip())
        if base_indent is None:
            # First non-blank line under directive: this is the
            # base_indent — applies to BOTH options and body. Per
            # Sphinx grammar the directive body MUST be indented;
            # an indent==0 line is sibling prose, not directive
            # content — terminate the parse so callers see this as
            # a header-only directive with no body / no options.
            if indent == 0:
                break
            base_indent = indent
        if indent < base_indent:
            # Dedent → directive body ended.
            break
        # Decide options vs body based on whether we saw a blank.
        if not saw_blank_between and stripped.startswith(":"):
            # Options shape `:key: value` (only inside the options
            # pass — once `saw_blank_between` is set we treat
            # `:`-starting lines as body content like `{ signal: …}`
            # which can sometimes start with `:` after dedent).
            m_opt = re.match(r"^:([A-Za-z_][A-Za-z0-9_-]*):\s*(.*)$",
                             stripped)
            if m_opt:
                options[m_opt.group(1)] = m_opt.group(2)
                end_offset = b
                i += 1
                continue
        # Body line.
        body_lines.append(line[base_indent:] if len(line) >= base_indent
                          else line.lstrip())
        end_offset = b
        i += 1
    # Trim trailing blank lines off the body.
    while body_lines and not body_lines[-1].strip():
        body_lines.pop()
    body = "\n".join(body_lines)
    return options, body, end_offset


def _v1_6_322_extract_wavedrom_blocks(text: str, fname: str):
    """v1.6.322 — for #221 ORGANIC P3. Yield wavedrom-directive
    entries from RST text.

    Each yielded entry carries:
      * `file_ref`: the source filename (for downstream evidence)
      * `raw_payload`: dedented directive body, capped at 2000
        chars (matches the suggested_fix's audit-cap)
      * `extraction_strategy`: stamp `rst_wavedrom_directive` for
        provenance auditing.

    Dedupe across paths must happen at the call site on
    `(file_ref, hash(raw_payload))` — yielded entries are not
    deduplicated here so the call site retains visibility of every
    raw match.

    v1.6.429 — for #306 P2. Replaced the strict no-blank-line regex
    with a two-pass parser that handles `options + blank + body`
    Sphinx grammar, so the WaveJSON signal payload (after the blank
    line that ends the options block) is no longer dropped. Each
    yielded entry now also carries `options` (dict) and `wavejson`
    (the body text isolated from options) alongside the legacy
    `raw_payload`, which now contains options + body concatenated
    for backward compatibility with existing downstream consumers.

    Chip-AGNOSTIC: pure structural Sphinx grammar match; no
    chip-class string literal participates.
    """
    if not text or not isinstance(text, str):
        return
    for m_hdr in _RE_V1_6_429_WAVEDROM_HEADER.finditer(text):
        options, body, _end = _v1_6_429_parse_wavedrom_directive(
            text, m_hdr)
        # Construct the legacy raw_payload as `options + blank + body`
        # so any downstream consumer that grepped on `:name:` etc.
        # still finds them.
        legacy_parts = []
        for k, v in options.items():
            legacy_parts.append(f":{k}: {v}")
        if legacy_parts and body:
            legacy_parts.append("")  # blank line separator
        if body:
            legacy_parts.append(body)
        raw_payload = "\n".join(legacy_parts).strip()
        if not raw_payload and not options and not body:
            continue
        # v1.6.473 — for #340 P3 ORGANIC. Lift the parsed
        # `options.name` / `options.caption` to the entry-level
        # `name` field so Phase 2 TB-gen + cross-doc reference
        # resolution (`:numref:` / `:ref:`) can anchor on it.
        # Pre-v1.6.473 entry["name"] was always None even when
        # the Sphinx directive declared `:name:` or `:caption:`.
        opts = options if isinstance(options, dict) else {}
        derived_name = (
            opts.get("name")
            or opts.get("caption")
            or None
        )
        name_lifted_v1_6_473 = bool(opts.get("name") or opts.get("caption"))
        yield {
            "file_ref": fname,
            "raw_payload": raw_payload[:2000],
            "options": options,
            "wavejson": body[:2000] if body else "",
            "extraction_strategy": "rst_wavedrom_directive",
            # v1.6.473 lifted name (None if neither :name: nor
            # :caption: was set; caller may stamp an auto-id).
            "name": derived_name,
            "name_lifted_v1_6_473": name_lifted_v1_6_473,
        }


# v1.6.325 — for #224 ORGANIC P2. AsciiDoc `[wavedrom, ...]` fenced-
# block extractor. The v1.6.322 RST `.. wavedrom::` extractor cannot
# see AsciiDoc waveform blocks emitted by Sphinx-AsciiDoc /
# asciidoctor-diagram toolchains: those use bracket-attribute opener
# `[wavedrom, format="svg"]` followed by a four-or-more-dash fenced
# block. Pre-v1.6.325 every such block on `.adoc` / `.asciidoc`
# sources dropped silently.
#
# Regex shape — DOTALL so the body capture can span newlines, lazy
# `.*?` so the first closing `----` terminates the body. MULTILINE
# anchors the opener to a line start.
#
# Chip-AGNOSTIC: pure AsciiDoc grammar match; no chip-class string
# literal participates.
_RE_ADOC_WAVEDROM_BLOCK_v1_6_325 = re.compile(
    r"^\[wavedrom[^\]]*\]\s*\n-{4,}\s*\n(?P<body>.*?)\n-{4,}",
    re.DOTALL | re.MULTILINE,
)


def _v1_6_325_extract_adoc_wavedrom(text: str, fname: str):
    """v1.6.325 — for #224 ORGANIC P2. Yield AsciiDoc wavedrom
    bracket-attribute-fenced entries `{file_ref, raw_payload,
    extraction_strategy}`. Payload capped at 2000 chars to match the
    v1.6.322 RST extractor's audit-cap.
    Chip-AGNOSTIC: pure AsciiDoc grammar match; no chip-class string
    literal participates.

    v1.6.473 — for #340 P3 ORGANIC. Also parse the bracket-attribute
    header for `id=` / `title=` so the top-level entry `name` is
    populated when the AsciiDoc author declared one. Restores
    `:numref:` / cross-reference resolution.
    """
    if not text or not isinstance(text, str):
        return
    for m in _RE_ADOC_WAVEDROM_BLOCK_v1_6_325.finditer(text):
        body = m.group("body") or ""
        if not body.strip():
            continue
        # v1.6.473 — extract opener line attributes for name lift.
        # Header shape: `[wavedrom, format="svg", id="myid", title="..."]`
        header_text = m.group(0).split("\n", 1)[0]
        derived_name = None
        for attr_re in (
                r'\bid\s*=\s*"([^"]+)"',
                r"\bid\s*=\s*'([^']+)'",
                r'\btitle\s*=\s*"([^"]+)"',
                r"\btitle\s*=\s*'([^']+)'",
                r'\bname\s*=\s*"([^"]+)"',
                r"\bname\s*=\s*'([^']+)'",
                r'\bcaption\s*=\s*"([^"]+)"',
                r"\bcaption\s*=\s*'([^']+)'",
        ):
            attr_m = re.search(attr_re, header_text)
            if attr_m:
                derived_name = attr_m.group(1)
                break
        yield {
            "file_ref": fname,
            "raw_payload": body[:2000],
            "extraction_strategy":
                "adoc_wavedrom_fenced_block_v1_6_325",
            # v1.6.473 — for #340 P3 ORGANIC. Top-level name lifted
            # from AsciiDoc bracket-attribute `id` / `title` / `name`
            # / `caption`. None when no such attribute is present.
            "name": derived_name,
            "name_lifted_v1_6_473": derived_name is not None,
        }


def _v1_6_321_extract_design_parameters(text: str):
    """v1.6.321 — for #220 ORGANIC P2. Yield design-parameter
    entries `{name, default, extraction_strategy}` from heading-
    style and RST field-list parameter documentation.

    Two extraction strategies:
      * `md_h4_uppercase_default` — Markdown H3/H4 heading whose
        body is an UPPERCASE token, optionally followed by
        `(default = N)` / `(reset: N)`.
      * `rst_parameter_directive` — RST `:Parameter: NAME` field-
        list directive. Default left None (RST puts the value in
        the following paragraph; downstream may layer it in
        separately).

    Chip-AGNOSTIC: pure structural regex match; no chip-class
    string literal participates.
    """
    if not text:
        return
    # v1.6.335 — for #233 P2 ORGANIC. Switched to the STRICT
    # `_RE_MD_PARAM_H4_HEADING_v1_6_335` regex, which makes the
    # `(default = N)` / `(reset: N)` clause MANDATORY. The legacy
    # v1.6.321 regex had the clause optional, causing plain section
    # headings (`#### README`, `#### ARCHITECTURE`,
    # `#### LATCHED_MEM_RDATA`) to surface as fake parameter rows
    # with default=None.
    # Chip-AGNOSTIC: pure structural grammar tightening.
    #
    # v1.6.390 — for #281 P3 ORGANIC. Replaced the narrow
    # `_RE_MD_PARAM_H4_HEADING_v1_6_335` value-capture (which
    # truncated Verilog sized literals at the apostrophe) with the
    # `_RE_MD_PARAM_H4_HEADING_v1_6_390` named-alternation form that
    # also matches `32'h0000_0000`, `0xDEAD`, `0b1010`, decimals,
    # boolean, and parametric refs. Captured value passes through
    # `_v1_6_390_normalize_verilog_literal` to strip internal
    # whitespace inside the sized-literal form.
    for m in _RE_MD_PARAM_H4_HEADING_v1_6_390.finditer(text):
        name = m.group(1)
        default = _v1_6_390_normalize_verilog_literal(m.group("val"))
        if not name:
            continue
        yield {
            "name": name,
            "default": default,
            "extraction_strategy": "md_param_h4_heading_v1_6_390",
        }
    for m in _RE_RST_PARAM_DIRECTIVE_v1_6_321.finditer(text):
        name = m.group(1)
        if not name:
            continue
        yield {
            "name": name,
            "default": None,
            "extraction_strategy": "rst_parameter_directive",
        }


# v1.6.324 — for #223 ORGANIC P2. Section-anchored grid-table /
# pipe-table parameter extractor. The v1.6.321 H4-heading + RST
# field-list extractor missed the third common shape: a `Parameters`
# heading followed by a Markdown pipe-table or RST grid-table whose
# columns are `| Name | Type | Default | Description |`. Pre-v1.6.324
# dozens of parameter rows in this canonical form dropped silently.
#
# `_RE_PARAM_SECTION_ANCHOR_v1_6_324` — anchors the search window
# at a `Parameters` heading underlined by `===` / `---` / `~~~` /
# `^^^` (Sphinx-RST heading conventions).
#
# `_RE_RST_PARAM_GRID_ROW_v1_6_324` — captures one pipe-table row
# with four cells `| name | type | default | description |`. The
# name cell may be backtick-quoted (Markdown literal) and must start
# with a letter so separator rows like `|----------|---|---|---|`
# are not captured. The header row (name == "Name") and obvious
# separator rows are filtered at the consumer.
#
# Chip-AGNOSTIC: pure GFM / RST grammar pattern; no chip-class
# string literal participates.
_RE_PARAM_SECTION_ANCHOR_v1_6_324 = re.compile(
    r"^Parameters\s*\n[-=^~]{3,}",
    re.MULTILINE,
)

_RE_RST_PARAM_GRID_ROW_v1_6_324 = re.compile(
    r"^\|\s*`?(?P<name>[A-Za-z][\w]{2,40})`?\s*\|"
    r"\s*(?P<typ>[^|]{0,40})\|"
    r"\s*(?P<dflt>[^|]{0,40})\|"
    r"\s*(?P<desc>[^|]+)\|",
    re.MULTILINE,
)


def _v1_6_324_extract_param_grid_table(text: str):
    """v1.6.324 — for #223 ORGANIC P2. Yield parameter entries
    `{name, default, type, description, extraction_strategy}` from
    a pipe-table block under a `Parameters` heading.

    v1.6.447 — for #316 R2 ORGANIC. Body now passes through
    `_v1_6_447_collapse_continuation_lines_in_text` so multi-row
    cell continuations merge onto their parent row's description
    column (symmetric with v1.6.329 walker). Description cap raised
    from 200 to 500 chars to fit merged text.

    Skips header/separator rows whose name (lowercased) is one of
    `{"name", "parameter", "default", "type"}`.

    Chip-AGNOSTIC: pure GFM / RST grammar match; no chip-class
    string literal participates.
    """
    if not text or not isinstance(text, str):
        return
    for m_anchor in _RE_PARAM_SECTION_ANCHOR_v1_6_324.finditer(text):
        body_start = m_anchor.end()
        body_end = body_start + 8000
        body = text[body_start:body_end]
        # v1.6.447 — collapse continuation rows before regex sweep.
        body = _v1_6_447_collapse_continuation_lines_in_text(body)
        for row in _RE_RST_PARAM_GRID_ROW_v1_6_324.finditer(body):
            name = (row.group("name") or "").strip()
            if not name:
                continue
            # Skip header / column-label rows. Lowercase the
            # captured name so case-insensitive comparison wins.
            if name.lower() in {"name", "parameter",
                                 "default", "type"}:
                continue
            yield {
                "name": name,
                "default": (row.group("dflt") or "").strip(),
                "type": (row.group("typ") or "").strip(),
                # v1.6.447 — raise description cap from 200 to 500.
                "description": (row.group("desc") or "").strip()[:500],
                "extraction_strategy":
                    "rst_param_grid_table_v1_6_324",
            }


# v1.6.329 — for #223 Round-2. Three grammar gaps were observed after
# v1.6.324 shipped on the 8-IC benchmark rotation:
#   1. RST literal form `` ``Name`` `` (double backtick) was not
#      covered by `_RE_RST_PARAM_GRID_ROW_v1_6_324` whose name cell
#      quantifier was `` `? `` (0 or 1 backtick). Concrete example:
#      `ibex/doc/02_user/integration.rst:183` lists every parameter
#      row as `` | ``PMPEnable`` | ... ``.
#   2. Sphinx documentation often wraps parameter pipe-tables inside
#      `.. table::` or `.. list-table::` directive blocks. The
#      v1.6.324 walker just sliced the raw body, so pipe rows inside
#      a directive (whose lines are uniformly indented) were never
#      reached.
#   3. The v1.6.324 unit-test fixtures used single-backtick rows,
#      which masked grammar gap (1) at unit-test time.
#
# Fix:
#   * `_RE_RST_PARAM_GRID_ROW_v1_6_329` widens the name-cell backtick
#     quantifier to `` `{0,2} `` so 0, 1, or 2 backticks on either
#     side of the name all match.
#   * `_v1_6_329_walk_param_section_with_directives(text, anchor)`
#     dedents `.. table::` and `.. list-table::` directive bodies
#     found inside the Parameters window and appends them to the
#     raw body, then runs the v1.6.329 row regex over the
#     concatenated text.
#   * `_v1_6_329_extract_param_grid_table(text)` is the new
#     generator that uses the wider regex + the directive-walking
#     section helper. Call sites are switched from the v1.6.324
#     generator to this one; the v1.6.324 symbols remain exported
#     for back-compat with any external pinned test.
#
# Chip-AGNOSTIC: pure GFM / RST grammar pattern; no chip-class
# string literal participates.
_RE_RST_PARAM_GRID_ROW_v1_6_329 = re.compile(
    r"^\|\s*`{0,2}(?P<name>[A-Za-z][\w]{2,40})`{0,2}\s*\|"
    r"\s*(?P<typ>[^|]{0,40})\|"
    r"\s*(?P<dflt>[^|]{0,40})\|"
    r"\s*(?P<desc>[^|]+)\|",
    re.MULTILINE,
)


# Section terminator: a non-blank line followed by a `===`/`---`/
# `~~~`/`^^^` underline of length >= 3 marks the next heading.
_RE_SECTION_NEXT_HEADING_v1_6_329 = re.compile(
    r"\n[^\n]+\n[-=^~]{3,}\s*\n", re.MULTILINE,
)


# Sphinx directive opening: `.. table::` or `.. list-table::`.
_RE_SPHINX_TABLE_DIRECTIVE_v1_6_329 = re.compile(
    r"(?m)^(?P<indent>[ \t]*)\.\.\s+(?:table|list-table)::"
)


def _v1_6_329_dedent_directive_body(text: str, start: int,
                                     base_indent: int) -> str:
    """Walk forward from `start` collecting lines that are either
    blank OR indented deeper than `base_indent`. Stop at the first
    non-blank line whose indent is <= `base_indent`. Return the
    dedented body (each line stripped of `base_indent + 1` leading
    spaces — but we conservatively just `lstrip` so a pipe-row
    starting at any deeper indent reaches column 0)."""
    out_lines: list[str] = []
    i = start
    n = len(text)
    while i < n:
        # Locate end of current line.
        j = text.find("\n", i)
        if j == -1:
            j = n
        line = text[i:j]
        stripped = line.strip()
        if stripped == "":
            # Blank line — keep, may be inside or after block.
            out_lines.append("")
            i = j + 1
            continue
        # Indent count = leading spaces (Sphinx directives use spaces).
        k = 0
        while k < len(line) and line[k] == " ":
            k += 1
        if k <= base_indent:
            # Outdented — directive body ended before this line.
            break
        # Inside directive body. Strip ALL leading whitespace so
        # any pipe row starts at column 0 for the row regex.
        out_lines.append(line.lstrip())
        i = j + 1
    return "\n".join(out_lines)


def _v1_6_329_walk_param_section_with_directives(
        text: str, anchor_end: int) -> str:
    """Return a body string for parameter-row scanning that
    concatenates:
      (a) the raw section body from `anchor_end` to the next h1/h2
          heading (or `anchor_end + 8000`, whichever comes first); and
      (b) the dedented bodies of any `.. table::` / `.. list-table::`
          Sphinx directive blocks found inside that window.

    The concatenation lets a single regex sweep over both raw rows
    and rows that lived inside a Sphinx directive."""
    if not text or anchor_end < 0 or anchor_end >= len(text):
        return ""
    # Default cap at 8000 chars.
    body_end = min(anchor_end + 8000, len(text))
    # Tighten body_end to the next section heading underline if any.
    m_next = _RE_SECTION_NEXT_HEADING_v1_6_329.search(
        text, anchor_end, body_end,
    )
    if m_next is not None:
        body_end = m_next.start()
    raw_body = text[anchor_end:body_end]
    # Find directive openings inside the raw body.
    chunks: list[str] = [raw_body]
    for m_dir in _RE_SPHINX_TABLE_DIRECTIVE_v1_6_329.finditer(raw_body):
        indent = len(m_dir.group("indent"))
        # Body starts at the line after the directive opening.
        opening_end = raw_body.find("\n", m_dir.end())
        if opening_end == -1:
            continue
        dedented = _v1_6_329_dedent_directive_body(
            raw_body, opening_end + 1, indent,
        )
        if dedented:
            chunks.append("\n" + dedented)
    return "\n".join(chunks)


# v1.6.456 — for #328 P2 ORGANIC. RST grid-table port walker reads
# name / width / direction / description from a single matched row,
# but when the description column has cell continuations across
# multiple physical lines (RST grid `+----+...+----+` separator
# every row OR pipe-table style with empty Name|Width|Direction
# rows whose Description column is non-empty), the per-row regex
# only sees the FIRST line and silently drops the continuation
# text. 5/6 benchmark ICs with multi-port RST grid tables emit
# 47/31/48/48/45 ports each with 0 descriptions because of this.
#
# Fix: scan the doc text up-front, identify each 4-col port-table
# row, and harvest the FULL description (joined across continuation
# rows). Return a `{port_name: full_description}` dict that the
# `gen_l1_datasheet` post-pass uses to enrich existing pins entries
# that lack a description.
#
# Chip-AGNOSTIC: pure RST / GFM grid-table grammar; uses the
# canonical RTL direction-suffix set (`_o`/`_i`/`_ni`/`_io`) to
# anchor the port-name cell. No chip-class string literal.
_V1_6_456_RE_PORT_ROW = re.compile(
    # Match a 4-col port-table data row (the canonical Interface
    # table shape `| name | width | direction | description |`).
    # Identical name / width / direction patterns to
    # `_RE_L1_L9_RST_IFACE_4COL`; description cell allowed to be
    # any non-pipe text up to 500 chars (raised from 200).
    r"^[ \t]*\|\s*[`]{0,2}(?P<signal>[a-zA-Z_][\w]{0,40}(?:\[[^\]\n]{1,40}\])?)[`]{0,2}\s*\|"
    r"\s*[`]{0,2}"
    r"(?P<width>\d{1,4}|\*|[A-Za-z][A-Za-z0-9_]*(?:\s*[+\-*/]\s*\d+)?|\(?\s*variable\s*\)?|-|)"
    r"[`]{0,2}\s*\|"
    r"\s*(?P<dir>input|output|inout|in|out|io)\s*\|"
    r"\s*(?P<desc>[^|\n]{0,500}?)\s*\|",
    re.MULTILINE,
)
# Continuation row: leading cells (everything before the last `|`)
# all empty, only the LAST cell has non-empty text. We match any
# row with a leading empty-cell sequence followed by a non-empty
# trailing cell.
_V1_6_456_RE_CONT_ROW = re.compile(
    r"^[ \t]*\|(?P<lead>(?:\s*\|){1,5})\s*(?P<cont>[^|\n]{1,500}?)\s*\|",
    re.MULTILINE,
)


def _v1_6_456_extract_port_descriptions_with_continuation(
        text: str) -> Dict[str, str]:
    """v1.6.456 — for #328 P2 ORGANIC. Walk `text` line-by-line and
    return a `{port_name: full_description}` mapping that includes
    continuation-row content. The map is consumed by the post-pass
    in `gen_l1_datasheet` to fill in `pin.description` slots that
    the row-anchored `_RE_L1_L9_RST_IFACE_4COL` finditer dropped.

    Algorithm:
      1. Iterate lines; track the most recently matched port row
         (its captured signal + description).
      2. When the next line matches the empty-leading-cell
         continuation shape, append its trailing cell text to the
         tracked port row's description.
      3. RST grid separator lines (`+---+`, `+===+`) and blank /
         non-pipe lines reset the tracker so continuations never
         cross logical-row boundaries.

    Chip-AGNOSTIC: pure structural grammar; no chip-class literal.
    """
    if not text:
        return {}
    out: Dict[str, str] = {}
    pending_name: Optional[str] = None
    pending_desc_parts: List[str] = []
    # RST grid separator pattern (e.g. `+----+----+----+`).
    sep_re = re.compile(r"^\s*\+[-=+\s]+\+\s*$")

    def _flush() -> None:
        nonlocal pending_name, pending_desc_parts
        if pending_name is not None:
            joined = " ".join(p for p in pending_desc_parts if p).strip()
            if joined:
                prev = out.get(pending_name, "")
                # Prefer the longest description seen for the same
                # signal name. Multiple tables describing the same
                # port (e.g. brief in `signals.rst` + detailed in
                # `integration.rst`) collapse to the richer text.
                if len(joined) > len(prev):
                    out[pending_name] = joined
        pending_name = None
        pending_desc_parts = []

    for line in (text or "").splitlines():
        # Separator line resets the tracker.
        if sep_re.match(line):
            _flush()
            continue
        m_port = _V1_6_456_RE_PORT_ROW.match(line)
        if m_port:
            # Reject column-header rows by name.
            sig = m_port.group("signal").strip()
            sig_low = sig.lower()
            if sig_low in {"signal", "name", "port", "direction",
                           "type", "dir", "description", "width"}:
                _flush()
                continue
            _flush()
            pending_name = sig
            first_desc = (m_port.group("desc") or "").strip()
            if first_desc:
                pending_desc_parts.append(first_desc)
            continue
        # Continuation? Only valid when we already have a pending
        # port-row anchor. The leading cells must all be empty AND
        # the trailing cell non-empty.
        if pending_name is not None:
            m_cont = _V1_6_456_RE_CONT_ROW.match(line)
            if m_cont:
                lead = m_cont.group("lead") or ""
                # `lead` is one-or-more `|` separators with only
                # whitespace between them — verify by structural
                # split.
                lead_cells = [c.strip() for c in lead.split("|")
                              if c is not None]
                # Reject if any leading cell carries non-whitespace
                # content (would mean this is a new port row, not
                # a continuation).
                if all(not c for c in lead_cells):
                    cont_text = m_cont.group("cont").strip()
                    if cont_text:
                        pending_desc_parts.append(cont_text)
                    continue
            # Pipe-table row that doesn't fit continuation shape →
            # flush and treat as a non-pipe line (no anchor).
            if line.lstrip().startswith("|"):
                _flush()
                continue
        # Blank or non-pipe line — flush.
        if not line.strip() or not line.lstrip().startswith("|"):
            _flush()
            continue
    _flush()
    return out


# v1.6.572 — for #390 P3 ORGANIC. Promote the continuation walker
# to a SEED mode when the primary 4COL / 2COL / NCOL walker found
# 0 pins but the continuation parser DID identify walkable rows.
# Pre-v1.6.572 `_v1_6_456_extract_port_descriptions_with_continuation`
# was an enrichment-only pass: it iterates existing `pins[]`, looks
# up each name in the input doc, and folds continuation rows into
# the description. When `pins[]` is empty (because the primary seed
# walker had a blind spot — e.g. the 3-col grid before v1.6.565)
# the enrichment pass had nothing to enrich and exited with
# `pins[]` still empty, dropping the structurally-valid rows the
# continuation parser saw.
#
# Fix: a sibling function that reuses the SAME row-anchored regex
# (`_V1_6_456_RE_PORT_ROW`) the v1.6.456 walker uses, but emits a
# full record per match (name + direction + width + description)
# so the caller can route to `_add_pin` as a seed source. Wired
# into `gen_l1_datasheet` AFTER the primary seed walkers run; the
# v1.6.572 seed pass only fires when `pins[]` is still empty AND
# the row regex identifies ≥1 structurally-valid row.
#
# Chip-AGNOSTIC: pure RST/GFM grid grammar; no chip-class literal.
def _v1_6_572_extract_port_rows_in_seed_mode(text: str):
    """v1.6.572 — for #390 P3 ORGANIC. Walk `text` and yield port
    records `{name, direction, width, description, source_row}` for
    every row matched by `_V1_6_456_RE_PORT_ROW`. The width / dir
    capture groups are taken verbatim; the caller routes through
    `_add_pin` for canonical record shape.

    Used in seed mode ONLY when the primary 4COL/2COL/NCOL seed
    walker emitted 0 pins. Idempotent: yielding the same row twice
    is filtered by `_add_pin`'s name-dedup.

    Chip-AGNOSTIC.
    """
    if not isinstance(text, str) or not text:
        return
    for m in _V1_6_456_RE_PORT_ROW.finditer(text):
        sig = (m.group("signal") or "").strip()
        sig_low = sig.lower()
        if sig_low in {"signal", "name", "port", "direction",
                       "type", "dir", "description", "width"}:
            continue
        raw_dir = (m.group("dir") or "").lower()
        # Normalise abbreviated direction to canonical full form.
        dir_full = _DIR_ABBR_TO_FULL.get(raw_dir, raw_dir)
        if dir_full not in {"input", "output", "inout"}:
            continue
        width_raw = (m.group("width") or "").strip()
        desc_raw = (m.group("desc") or "").strip() or None
        yield {
            "name": sig,
            "direction": dir_full,
            "width": width_raw or None,
            "description": desc_raw,
            "source_row": m.group(0).strip()[:120],
        }


# v0.3.2 — ORGANIC-20260606 #491 R2. Universal multi-table header-role
# pin walker. The per-row regex family above (_RE_L1_L9_RST_IFACE_4COL /
# _DIR2 / _2COL / _3COL / _NCOL_SUFFIX) hard-codes the COLUMN ORDER and
# requires both a leading `^|` AND a closing `|` per row. Two
# real-document pipe-table shapes slip through ALL of them:
#
#   (a) BORDERLESS GFM pipe tables — the canonical Markdown form that
#       omits the outer `|` borders entirely:
#           Signal | Direction | Width | Description
#           ------ | --------- | ----- | -----------
#           clk    | input     | 1     | system clock
#       Every per-row regex anchors on `^[ \t]*\|`, so a borderless row
#       (`clk | input | 1 | ...`) matches NONE of them → 0 pins.
#
#   (b) An interface doc that carries TWO pipe tables (a main Port-group
#       table with clk/reset/GPIO rows + a memory-block sub-port table).
#       When the two tables use DIFFERENT column orders, the order-locked
#       regexes each only catch the table whose order they happen to
#       match — so a document can surface with the SECOND table's rows
#       only and the whole first table dropped, or vice-versa.
#
# This walker fixes both classes the GENERAL way: it scans EVERY pipe-
# table block in the document (bordered or borderless), reads the column
# ROLES from each table's OWN header row, and emits one record per data
# row with the direction resolved from that table's direction column.
# Because the role mapping is recomputed PER TABLE, the second table's
# direction is never `None` just because the first table had a different
# layout, and NO table is dropped in favour of another (no latch).
# Because each block is bounded by its own separator + the first non-pipe
# line, SDC / stdcell-library lines elsewhere in the doc can never leak
# into a table's rows.
#
# Chip-AGNOSTIC: pure GFM/RST pipe-table grammar + universal port-table
# header vocabulary + RTL direction keywords; no chip-class literal.
# Issue #500 — the pin family's per-role header token sets now derive
# from the ONE shared bilingual lexicon. The #491 round-3 CJK vocabulary
# is folded into `_header_lexicon.ROLE_TOKENS` (reused, not duplicated),
# so these constants keep the exact #491 behaviour while every sibling
# family (register-map / opcode / field / parameter) draws from the same
# source pin. Chip-AGNOSTIC.
_V0_3_2_HEADER_NAME_TOKENS = _hlex.tokens_for("name")
_V0_3_2_HEADER_DIR_TOKENS = _hlex.tokens_for("direction")
_V0_3_2_HEADER_WIDTH_TOKENS = _hlex.tokens_for("width")
_V0_3_2_HEADER_DESC_TOKENS = _hlex.tokens_for("description")
# A pipe-table separator row: every cell is `:?---:?` (GFM) or `:?===:?`
# (RST/AsciiDoc), with or without outer `|` borders.
_V0_3_2_RE_SEP_CELL = re.compile(r"^:?[-=]{1,}:?$")


def _v0_3_2_split_pipe_cells(line: str) -> List[str]:
    """Split one pipe-table row into trimmed cell strings, tolerating
    BORDERLESS rows (no leading / trailing `|`). The leading/trailing
    empty cells produced by outer borders are dropped so a bordered
    `| a | b |` and a borderless `a | b` yield the SAME `['a', 'b']`.
    Chip-AGNOSTIC."""
    parts = [c.strip() for c in line.split("|")]
    if parts and parts[0] == "":
        parts = parts[1:]
    if parts and parts and parts[-1] == "":
        parts = parts[:-1]
    return parts


def _v0_3_2_is_pipe_row(line: str) -> bool:
    """True iff `line` is a pipe-table data/header row — bordered OR
    borderless. Requires ≥1 internal `|` separating ≥2 non-empty
    cells. Chip-AGNOSTIC structural shape."""
    if "|" not in line:
        return False
    cells = _v0_3_2_split_pipe_cells(line)
    return len(cells) >= 2


def _v0_3_2_is_sep_row(line: str) -> bool:
    """True iff `line` is a pipe-table alignment / separator row,
    bordered or borderless (`---|---`, `:--|--:`, `===|===`)."""
    if "|" not in line:
        return False
    cells = _v0_3_2_split_pipe_cells(line)
    if len(cells) < 2:
        return False
    return all(bool(c) and _V0_3_2_RE_SEP_CELL.match(c) for c in cells)


def _v0_3_2_classify_pin_header(cells: List[str]) -> Optional[Dict[str, int]]:
    """Map a header row's cells to column roles. Returns a dict with at
    least `name` + `direction` indices (the two roles required for a
    port table), plus optional `width` / `description`, or None when
    the row does not look like a port table. Chip-AGNOSTIC."""
    if not cells:
        return None
    roles: Dict[str, int] = {}
    for i, raw in enumerate(cells):
        cell = (raw or "").strip(" *`").strip().lower()
        if not cell:
            continue
        if cell in _V0_3_2_HEADER_NAME_TOKENS and "name" not in roles:
            roles["name"] = i
        elif cell in _V0_3_2_HEADER_DIR_TOKENS and "direction" not in roles:
            roles["direction"] = i
        elif cell in _V0_3_2_HEADER_WIDTH_TOKENS and "width" not in roles:
            roles["width"] = i
        elif cell in _V0_3_2_HEADER_DESC_TOKENS and "description" not in roles:
            roles["description"] = i
    if "name" not in roles or "direction" not in roles:
        return None
    return roles


def _v0_3_2_iter_gfm_pin_tables(text: str):
    """v0.3.2 — for #491 R2. Yield `(roles, rows)` for EVERY pipe-table
    block in `text` whose header row carries both a name column and a
    direction column. `rows` is a list of cell-lists (one per data
    row), bounded to that table's block. Bordered AND borderless tables
    are recognised. Multiple tables in the SAME document are ALL yielded
    — no table is latched / dropped in favour of another.

    Block detection: a header row (pipe row) immediately followed by a
    separator row opens a block; the block's data rows run until the
    first blank line, the first non-pipe line, or the start of the next
    header+separator pair. Each table's column roles are computed from
    its OWN header, so per-table direction parsing is independent.

    Chip-AGNOSTIC: pure pipe-table grammar + universal port vocabulary.
    """
    if not isinstance(text, str) or not text:
        return
    lines = text.split("\n")
    n = len(lines)
    i = 0
    while i < n:
        line = lines[i]
        # A table opens with: pipe header row, then a separator row.
        if (_v0_3_2_is_pipe_row(line)
                and not _v0_3_2_is_sep_row(line)
                and i + 1 < n
                and _v0_3_2_is_sep_row(lines[i + 1])):
            header_cells = _v0_3_2_split_pipe_cells(line)
            roles = _v0_3_2_classify_pin_header(header_cells)
            ncols = len(header_cells)
            # Walk the data rows after the separator.
            rows: List[List[str]] = []
            j = i + 2
            while j < n:
                rl = lines[j]
                if not rl.strip():
                    break
                if not _v0_3_2_is_pipe_row(rl):
                    break
                # A new header+separator pair ends this block (and the
                # outer while re-enters it as a fresh table).
                if (j + 1 < n and _v0_3_2_is_sep_row(lines[j + 1])
                        and not _v0_3_2_is_sep_row(rl)):
                    break
                if _v0_3_2_is_sep_row(rl):
                    j += 1
                    continue
                cells = _v0_3_2_split_pipe_cells(rl)
                rows.append(cells)
                j += 1
                if len(rows) >= 256:
                    break
            if roles is not None and rows:
                yield (roles, rows, ncols)
            # Advance past the consumed block (at least past header +
            # separator so we never loop on the same header).
            i = max(j, i + 2)
            continue
        i += 1


# v0.3.4 — ORGANIC #491 ROUND-4. Generic table-annotation optionality
# vocabulary. A real port-table row may carry an OPTIONALITY annotation
# either as a parenthesised prefix on the name cell — `(optional)
# `i_gpio`` — or as the entire width cell (`optional`). These are
# GENERIC documentation words (EN + CJK), never chip-class literals.
_V0_3_4_OPTIONALITY_TOKENS = frozenset({
    "optional", "option", "reserved",
    "可選", "可选", "選用", "选用", "選配", "选配", "保留",
})

# Parenthesised annotation groups (ASCII + fullwidth parens).
_V0_3_4_RE_PAREN = re.compile(r"[(（]([^()（）]*)[)）]")


def _v0_3_4_sanitize_pin_name_cell(raw: str):
    """v0.3.4 — ORGANIC #491 ROUND-4. Sanitise a port-table NAME cell.

    Real vendor tables annotate the identifier in-cell:
      * ``(optional) `i_gpio```      → annotation prefix + backticks;
      * ```o_data` (or `o_wdata`)``  → alternative-name annotation.

    Returns ``(clean_name, optional, aliases)``:
      * parenthesised groups are STRIPPED from the name; a group whose
        text contains a generic optionality token (EN/CJK,
        `_V0_3_4_OPTIONALITY_TOKENS`) sets ``optional=True``; a group
        of the shape ``or <ident>`` / ``或 <ident>`` contributes the
        identifier to ``aliases``;
      * emphasis (`*`), backticks and surrounding whitespace are
        removed from what remains.

    Chip-AGNOSTIC: only generic annotation vocabulary participates; the
    identifier itself is never pattern-matched against chip names."""
    optional = False
    aliases: List[str] = []
    def _eat(m):
        nonlocal optional
        body = (m.group(1) or "").strip().strip("`* ").lower()
        if any(tok in body for tok in _V0_3_4_OPTIONALITY_TOKENS):
            optional = True
        alias_m = re.match(r"^(?:or|或)\s+(.+)$", body)
        if alias_m:
            cand = alias_m.group(1).strip().strip("`* ")
            if cand and re.fullmatch(r"[A-Za-z_][A-Za-z0-9_\[\]:]*", cand):
                aliases.append(cand)
        return " "
    no_paren = _V0_3_4_RE_PAREN.sub(_eat, raw or "")
    clean = no_paren.replace("`", " ").replace("*", " ").strip()
    clean = re.sub(r"\s+", " ", clean).strip()
    return clean, optional, aliases


_V644_LEGAL_ID_RE = re.compile(r"^[A-Za-z_][A-Za-z0-9_$]*$")


def _v644_split_pair_names(name: str) -> List[str]:
    """ORGANIC #644 — split a power/supply NAME cell that PAIRS two rails in a
    single cell (`vccd1 / vssd1`, `VDD/VSS`, `AVDD / AGND`) into the list of
    individual LEGAL Verilog identifiers it carries.

    A power/supply table routinely groups a rail pair in one cell; the GFM
    walker otherwise emits a single port whose name contains a literal `/` — an
    ILLEGAL Verilog identifier that corrupts L9 (the integration contract) and
    every downstream consumer (TB gen #643, chip_top wrapper, LEF pin list). A
    later legality guard then DROPS it (losing the power ports entirely). Split
    on `/` so each rail becomes its OWN legal port instead.

    Returns: [name] for a single already-legal name; the split legal tokens for
    an `A / B` pair; [] when nothing legal remains (never emit an illegal id).

    NEGATIVE no-leak: the SPLIT branch applies a >=2-char floor per part (the
    same 1-char floor `_is_real_port_token` enforces) so a junk grouping cell
    like `N/A` / `TBD/—` does NOT manufacture phantom 1-char ports (`N`, `A`);
    real supply-rail pairs (`vccd1`, `VSS`, `AVDD` — all >=3 chars) are
    unaffected. The single-name passthrough is NOT floored, so a legitimate
    1-char datapath port (`x` / `p`, no `/`) still survives.

    chip-AGNOSTIC: pure `/`-split + identifier-legality + length floor, no
    chip/vendor/SKU literal."""
    name = (name or "").strip()
    if not name:
        return []
    if "/" not in name:
        return [name] if _V644_LEGAL_ID_RE.match(name) else []
    out: List[str] = []
    seen: set = set()
    for part in name.split("/"):
        p = part.strip().strip("`* ").strip()
        if (p and len(p) >= 2 and _V644_LEGAL_ID_RE.match(p)
                and p not in seen):
            seen.add(p)
            out.append(p)
    return out


def _v0_3_2_emit_pins_from_gfm_tables(text: str):
    """v0.3.2 — for #491 R2. Resolve `_v0_3_2_iter_gfm_pin_tables` blocks
    into canonical port records `{name, direction, width, description,
    source_row}` (direction normalised to input/output/inout). Header /
    separator-leak rows are rejected; rows whose direction cell is not a
    recognised direction keyword are skipped (NOT emitted with a null
    direction).

    v0.3.4 — ORGANIC #491 ROUND-4: the NAME cell is sanitised via
    `_v0_3_4_sanitize_pin_name_cell` (parenthesised annotations + backticks
    stripped) and rows annotated optional — `(optional)` name prefix or an
    `optional`-class width cell — carry ``optional: True``. Chip-AGNOSTIC."""
    for roles, rows, ncols in _v0_3_2_iter_gfm_pin_tables(text):
        name_i = roles["name"]
        dir_i = roles["direction"]
        width_i = roles.get("width")
        desc_i = roles.get("description")
        for cells in rows:
            if name_i >= len(cells) or dir_i >= len(cells):
                continue
            # v0.3.4 — #491 R4: sanitise annotations/backticks out of the
            # name cell and pick up the row's optionality marker.
            name, row_optional, _name_aliases = (
                _v0_3_4_sanitize_pin_name_cell(cells[name_i] or ""))
            raw_dir = (cells[dir_i] or "").strip(" *`").strip().lower()
            raw_dir = raw_dir.replace("/", "")  # `i/o` → `io`
            if not name:
                continue
            # Reject any leaked header row.
            if name.lower() in (
                _V0_3_2_HEADER_NAME_TOKENS | _V0_3_2_HEADER_DIR_TOKENS
                | _V0_3_2_HEADER_WIDTH_TOKENS | _V0_3_2_HEADER_DESC_TOKENS
            ):
                continue
            dir_full = _DIR_ABBR_TO_FULL.get(raw_dir)
            if dir_full not in {"input", "output", "inout"}:
                # The direction cell is not a real direction keyword
                # (e.g. the "Type"-column header matched but its body
                # holds `Clock` / `Data`). Skip — never emit a row with
                # a null / fabricated direction.
                continue
            width_arg = None
            if width_i is not None and width_i < len(cells):
                wraw = (cells[width_i] or "").strip(" *`").strip()
                # v0.3.4 — #491 R4: an optionality word as the ENTIRE
                # width cell ('optional' / '可選' / 'reserved' …) marks
                # the row optional; it is not a width.
                if wraw.lower() in _V0_3_4_OPTIONALITY_TOKENS:
                    row_optional = True
                else:
                    try:
                        w_int, _w_sym = _v1_6_420_parse_width_cell(wraw)
                    except NameError:
                        w_int = int(wraw) if wraw.isdigit() else None
                    if w_int is not None:
                        width_arg = str(w_int)
            desc_arg = None
            if desc_i is not None and desc_i < len(cells):
                desc_arg = (cells[desc_i] or "").strip() or None
            # ORGANIC #644 — a power/supply NAME cell that PAIRS two rails
            # (`vccd1 / vssd1`) must SPLIT into two separate legal-identifier
            # ports, never collapse into one illegal name carrying a '/'. The
            # row's direction / width / description apply to each split rail.
            # A single legal name yields one rec unchanged.
            for _split_nm in _v644_split_pair_names(name):
                rec = {
                    "name": _split_nm,
                    "direction": dir_full,
                    "width": width_arg,
                    "description": desc_arg,
                    "source_row": " | ".join(cells)[:120],
                }
                if row_optional:
                    rec["optional"] = True
                yield rec


# ===========================================================================
# Comportable-style interface harvester (#638)
# ---------------------------------------------------------------------------
# The auto-generated "Comportable" register-tool interface convention (used
# by the OpenTitan-style REUSED-IP register-mapped accelerator class, and any
# IP whose interface doc is emitted by `regtool --interfaces`) declares the
# canonical top-level interface as a bullet block:
#
#     the module `<name>` has the following hardware interfaces defined
#     - Primary Clock: `clk_i`
#     - Other Clocks: `clk_edn_i`
#     - Bus Device Interfaces (TL-UL): `tl`
#     - Bus Host Interfaces (TL-UL): *none*
#     - Peripheral Pins for Chip IO: *none*
#     - Interrupts: *none*
#
# plus an "Inter-Module Signals" pipe-table whose DIRECTION is carried by an
# `Act` (req / rcv / rsp / uni) role column rather than an input/output cell:
#
#     | Port Name | Package::Struct | Type    | Act | Width | Description |
#     | tl        | tlul_pkg::tl    | req_rsp | rsp | 1     |             |
#
# Before #638 NONE of these were harvested into L1.pin_table / L9.top_ports:
#   (a) no positive harvester existed for the clock/bus bullet block, so the
#       primary clock(s) and the primary device bus were dropped entirely;
#   (b) the GFM walker requires a name+direction header, but the Inter-Module
#       table has no input/output column, so its `req_rsp`/`rsp` bus row was
#       dropped (only the secondary "Other Signals" input/output table was
#       picked up); and
#   (c) the `<name>` token in the narrative intro sentence could leak as a
#       phantom input port.
#
# This harvester closes (a)+(b) with a POSITIVE structural parse, and exposes
# the intro module-name token so the caller can deny (c). Chip-AGNOSTIC: pure
# Comportable doc-convention vocabulary (Primary/Other Clock(s), Bus
# Device/Host Interfaces, Peripheral Pins, Interrupts, Act-role keywords); no
# chip-class / SKU literal participates.
# ===========================================================================

# Comportable intro sentence: `the module `<name>` has the following hardware
# interface(s)`. The name token (bold-or-plain backticked) is captured so the
# narrative line-scan can deny promoting it as a phantom port.
_RE_V638_COMPORTABLE_INTRO = re.compile(
    r"the\s+module\s+\*{0,2}`(?P<name>[A-Za-z_][A-Za-z0-9_]{0,40})`\*{0,2}"
    r"\s+has\s+the\s+following\s+hardware\s+interface",
    re.IGNORECASE,
)

# One bullet line of the comportable interface block. The label classifies
# the role (clock vs bus vs other); the value region carries one or more
# backticked tokens (bold-or-plain) OR the sentinel `*none*`.
_RE_V638_COMPORTABLE_BULLET = re.compile(
    r"(?im)^\s*[-*+]\s+"
    r"(?P<label>Primary\s+Clock|Other\s+Clocks?|"
    r"Bus\s+(?:Device|Host)\s+Interfaces?|"
    r"Peripheral\s+Pins(?:\s+for\s+Chip\s+IO)?|Interrupts?|"
    r"Inter-?Module\s+Signals?)"
    r"\s*(?:\([^)\n]{0,40}\))?\s*:\s*(?P<value>[^\n]*)$"
)

# A backticked identifier token inside a bullet value region (bold markup
# tolerated on either side). Reused for the clock/bus bullets.
_RE_V638_BACKTICK_TOKEN = re.compile(
    r"\*{0,2}`(?P<tok>[A-Za-z_][A-Za-z0-9_]{0,40})`\*{0,2}"
)

# Inter-Module-Signals `Act` role column keywords. `req`/`rsp` denote a
# bidirectional request/response (struct) bus port; `rcv` is an inbound
# (received) signal; `uni` is a unidirectional signal whose direction the
# `Act` value alone does not pin down. The `Type` column distinguishes a
# `req_rsp` struct bus from a `uni` simple signal. Chip-AGNOSTIC: these are
# the Comportable inter-signal-handling role keywords, not chip literals.
_V638_ACT_TO_DIRECTION = {
    "req": "inout",   # this module drives a request (struct bus master/dev)
    "rsp": "inout",   # this module answers a request (struct bus device)
    "rcv": "input",   # received (inbound)
}


def _v638_comportable_module_name(text: str):
    """#638 — return the backticked module-name token from the Comportable
    intro sentence (`the module `<name>` has the following hardware
    interface...`), or None. Chip-AGNOSTIC: matched purely on the convention
    sentence shape; the captured token is whatever the doc names."""
    if not isinstance(text, str) or not text:
        return None
    m = _RE_V638_COMPORTABLE_INTRO.search(text)
    return m.group("name") if m else None


def _v638_comportable_interface_harvest(text: str):
    """#638 — POSITIVE harvester for the Comportable interface bullet block
    and the Inter-Module-Signals Act-role table. Yields canonical port
    records ``{name, direction, width, description, source_row,
    extraction_strategy}``.

    Facet (a): the `Primary Clock` / `Other Clocks` bullets emit each
    backticked token as an input clock port; the `Bus Device/Host
    Interfaces (<proto>)` bullets emit each backticked token as an inout
    (struct) bus port. The sentinel `*none*` and empty values emit nothing.
    `Peripheral Pins` / `Interrupts` bullet tokens emit with suffix-inferred
    direction (default input).

    Facet (b): the `Inter-Module Signals` pipe-table — header carrying a
    `Port Name` (name) column plus an `Act` (req/rcv/rsp/uni) role column —
    emits the `req_rsp`/`rsp`/`req` bus row(s) (e.g. `tl`) as inout struct
    ports. Rows whose `Act` role does not map to a direction are skipped
    (never emitted with a null/fabricated direction).

    Chip-AGNOSTIC: pure Comportable doc-convention vocabulary + pipe-table
    grammar; no chip-class literal participates.
    """
    if not isinstance(text, str) or not text:
        return

    # ---- Facet (a): the clock / bus bullet block -----------------------
    for bm in _RE_V638_COMPORTABLE_BULLET.finditer(text):
        label = re.sub(r"\s+", " ", bm.group("label").strip().lower())
        value = bm.group("value") or ""
        # The `*none*` sentinel (and any empty value) means the interface
        # is absent — emit nothing.
        if not value.strip() or re.search(r"\*\s*none\s*\*", value, re.I):
            continue
        if label.startswith("inter") or label.startswith("inter-module"):
            # Heading-only bullet; the table walker handles its rows.
            continue
        is_clock = "clock" in label
        is_bus = label.startswith("bus ")
        for tm in _RE_V638_BACKTICK_TOKEN.finditer(value):
            tok = tm.group("tok")
            if len(tok) < 2:
                continue
            if is_clock:
                direction = "input"
                strat = "comportable_clock_bullet_v638"
            elif is_bus:
                direction = "inout"
                strat = "comportable_bus_bullet_v638"
            else:
                # Peripheral pins / interrupts — infer from RTL suffix,
                # default input.
                if _RE_DIR_SUFFIX_OUTPUT.search(tok):
                    direction = "output"
                elif _RE_DIR_SUFFIX_INOUT.search(tok):
                    direction = "inout"
                else:
                    direction = "input"
                strat = "comportable_iface_bullet_v638"
            yield {
                "name": tok,
                "direction": direction,
                "width": None,
                "description": None,
                "source_row": bm.group(0).strip()[:120],
                "extraction_strategy": strat,
            }

    # ---- Facet (b): the Inter-Module-Signals Act-role table ------------
    for roles, rows, _ncols in _v0_3_2_iter_gfm_act_tables(text):
        name_i = roles["name"]
        act_i = roles["act"]
        type_i = roles.get("type")
        width_i = roles.get("width")
        desc_i = roles.get("description")
        for cells in rows:
            if name_i >= len(cells) or act_i >= len(cells):
                continue
            name, _opt, _al = _v0_3_4_sanitize_pin_name_cell(
                cells[name_i] or "")
            act = (cells[act_i] or "").strip(" *`").strip().lower()
            if not name:
                continue
            if name.lower() in (
                _V0_3_2_HEADER_NAME_TOKENS | {"port name", "port", "act",
                                              "type", "package::struct"}
            ):
                continue
            # The req_rsp struct bus rows (e.g. the `tl` TL-UL device port)
            # are the load-bearing addition: they carry NO direction-suffix
            # twin in the secondary "Other Signals" input/output table, so
            # without this harvester the primary device bus is dropped
            # entirely. `uni`-Type inter-signals, by contrast, are ALSO
            # surfaced (direction-suffixed) by the Other-Signals table, so
            # emitting their bare base name here would only create a
            # duplicate base/suffixed pair. Restrict to the `req_rsp` struct
            # bus rows. Chip-AGNOSTIC: the `req_rsp` Type keyword is the
            # Comportable struct-bus convention, not a chip literal.
            type_cell = ""
            if type_i is not None and type_i < len(cells):
                type_cell = (cells[type_i] or "").strip(" *`").strip().lower()
            if type_cell != "req_rsp":
                continue
            direction = _V638_ACT_TO_DIRECTION.get(act)
            if direction is None:
                # An unrecognised Act value does not by itself pin a
                # direction — skip rather than fabricate one.
                continue
            width_arg = None
            if width_i is not None and width_i < len(cells):
                wraw = (cells[width_i] or "").strip(" *`").strip()
                if wraw.isdigit():
                    width_arg = wraw
            desc_arg = None
            if desc_i is not None and desc_i < len(cells):
                desc_arg = (cells[desc_i] or "").strip() or None
            yield {
                "name": name,
                "direction": direction,
                "width": width_arg,
                "description": desc_arg,
                "source_row": " | ".join(cells)[:120],
                "extraction_strategy": "comportable_intermodule_act_v638",
            }


def _v638_classify_act_header(cells):
    """#638 — map an Inter-Module-Signals header row to column roles.
    Returns a dict with at least `name` + `act` indices (plus optional
    `type` / `width` / `description`) or None. Requires BOTH a name column
    (`Port Name`/`Name`/`Signal`/…) and an `Act` role column — this is what
    distinguishes the Comportable inter-signal table from an ordinary
    input/output port table. Chip-AGNOSTIC."""
    if not cells:
        return None
    roles = {}
    for i, raw in enumerate(cells):
        cell = (raw or "").strip(" *`").strip().lower()
        if not cell:
            continue
        if cell in _V0_3_2_HEADER_NAME_TOKENS and "name" not in roles:
            roles["name"] = i
        elif cell in {"port name", "port"} and "name" not in roles:
            roles["name"] = i
        elif cell == "act" and "act" not in roles:
            roles["act"] = i
        elif cell == "type" and "type" not in roles:
            roles["type"] = i
        elif cell in _V0_3_2_HEADER_WIDTH_TOKENS and "width" not in roles:
            roles["width"] = i
        elif cell in _V0_3_2_HEADER_DESC_TOKENS and "description" not in roles:
            roles["description"] = i
    if "name" not in roles or "act" not in roles:
        return None
    return roles


def _v0_3_2_iter_gfm_act_tables(text: str):
    """#638 — sibling of `_v0_3_2_iter_gfm_pin_tables` that yields the
    Inter-Module-Signals tables (header with a name column + an `Act` role
    column). Reuses the same block-detection grammar. Chip-AGNOSTIC."""
    if not isinstance(text, str) or not text:
        return
    lines = text.split("\n")
    n = len(lines)
    i = 0
    while i < n:
        line = lines[i]
        if (_v0_3_2_is_pipe_row(line)
                and not _v0_3_2_is_sep_row(line)
                and i + 1 < n
                and _v0_3_2_is_sep_row(lines[i + 1])):
            header_cells = _v0_3_2_split_pipe_cells(line)
            roles = _v638_classify_act_header(header_cells)
            ncols = len(header_cells)
            rows = []
            j = i + 2
            while j < n:
                rl = lines[j]
                if not rl.strip():
                    break
                if not _v0_3_2_is_pipe_row(rl):
                    break
                if (j + 1 < n and _v0_3_2_is_sep_row(lines[j + 1])
                        and not _v0_3_2_is_sep_row(rl)):
                    break
                if _v0_3_2_is_sep_row(rl):
                    j += 1
                    continue
                rows.append(_v0_3_2_split_pipe_cells(rl))
                j += 1
                if len(rows) >= 256:
                    break
            if roles is not None and rows:
                yield (roles, rows, ncols)
            i = max(j, i + 2)
            continue
        i += 1


# v1.6.463 — for #328 R2 ORGANIC. Cascade L1.pin_table[].description
# into L9.top_ports[].description by exact name match. The v1.6.456
# enricher fills L1.pin_table descriptions correctly (81 / 100 / 50 %
# on 3 RV-CPU ICs), but `gen_l9_integration_spec`'s
# `top_module_pins` builder reads directly from the RST grid via the
# row-anchored regex, not from L1.pin_table — so the v1.6.456 gains
# never propagate to L9 and `L9.top_ports.description` stays 0 %.
#
# This helper closes the gap with a structural cascade: walk L1
# pins, build a `{name: description}` map, then fill in any L9 port
# whose description is empty. When both L1 and L9 already carry a
# description for the same port, prefer the longer one (no benchmark
# IC currently has BOTH, but it costs nothing to add — same
# convention as `_v1_6_456_extract_port_descriptions_with_continuation`
# already uses). Chip-AGNOSTIC: pure structural cascade by name
# match; no chip-class vocabulary participates.
def _v1_6_463_cascade_l1_descriptions_to_l9(l1_pins, l9_ports) -> list:
    """v1.6.463 — for #328 R2. Returns the `l9_ports` list with
    `description` cascaded from L1 pin_table entries by exact name
    match. Empty / missing descriptions on the L9 side are filled
    in; non-empty L9 descriptions are preserved unless the L1 side
    has a longer string. Stamps `+desc_cascade_v1_6_463` on
    `extraction_strategy` for every entry that received a new
    description so downstream evidence audits can trace which L9
    ports were enriched.

    Idempotent: calling twice produces the same suffix exactly once
    (the substring check in the strategy stamp guards against
    double-application).
    """
    # Empty / missing inputs: return whatever the caller had (or
    # `[]` to keep the schema slot populated).
    if not l1_pins or not l9_ports:
        return l9_ports or []
    # Build the {name: description} map. Pick the LONGEST
    # description when multiple L1 pin entries share the same
    # `name` (defence-in-depth — a 4-col RST grid may have a brief
    # version + a continuation-rich version of the same port).
    pin_desc_map: Dict[str, str] = {}
    for p in l1_pins:
        if not isinstance(p, dict):
            continue
        name = p.get("name")
        desc = p.get("description")
        if (name
                and isinstance(desc, str)
                and desc.strip()):
            existing = pin_desc_map.get(name) or ""
            if len(desc) > len(existing):
                pin_desc_map[name] = desc
    if not pin_desc_map:
        return l9_ports
    # Apply the cascade. Stamp `+desc_cascade_v1_6_463` on the
    # strategy of every L9 port that received a new description.
    for port in l9_ports:
        if not isinstance(port, dict):
            continue
        name = port.get("name")
        if not name:
            continue
        existing_desc = port.get("description")
        if (isinstance(existing_desc, str)
                and existing_desc.strip()):
            # L9 already has a description — keep the existing
            # value unless the L1 side carries a strictly longer
            # one (longer-wins convention).
            cascaded = pin_desc_map.get(name)
            if (cascaded
                    and len(cascaded) > len(existing_desc.strip())):
                port["description"] = cascaded
                _es = str(port.get("extraction_strategy", "") or "")
                if "+desc_cascade_v1_6_463" not in _es:
                    port["extraction_strategy"] = (
                        _es + "+desc_cascade_v1_6_463"
                    ).lstrip("+")
            continue
        # L9 description empty — cascade from L1.
        cascaded = pin_desc_map.get(name)
        if cascaded:
            port["description"] = cascaded
            _es = str(port.get("extraction_strategy", "") or "")
            if "+desc_cascade_v1_6_463" not in _es:
                port["extraction_strategy"] = (
                    _es + "+desc_cascade_v1_6_463"
                ).lstrip("+")
    return l9_ports


def _v1_6_447_collapse_continuation_lines_in_text(body: str) -> str:
    """v1.6.447 — for #316 R2 ORGANIC. Collapse RST / GFM grid-table
    cell continuation rows BEFORE the
    `_RE_RST_PARAM_GRID_ROW_v1_6_329.finditer(body)` regex sweep runs.

    The v1.6.440 fix introduced
    `_v1_6_440_join_grid_continuation_rows(rows)` but wired it only
    into `_v1_6_400_iter_pipe_tables` (the GFM walker). The real
    `_v1_6_329_extract_param_grid_table` / `_v1_6_324_extract_param_grid_table`
    use a raw-text per-row `finditer` and never reach a row-list
    merger, so multi-row continuations (a row with an empty first
    cell whose trailing cell continues the previous row's
    description) were dropped.

    Strategy — scan the body line-by-line. For each pipe row, if the
    leading cell is empty AND at least one trailing cell has text,
    treat the row as a continuation: lift its trailing-cell text
    onto the previous data row's last column, then DROP the
    continuation row from the output so the downstream regex sweep
    sees only collapsed parent rows.

    Separator lines (`+---+`, `+===+`, or `|---|`) reset the
    "last data row" pointer because RST grid separators terminate
    a logical row's run.

    Chip-AGNOSTIC: pure RST / GFM grid grammar; no chip-class
    literal participates.
    """
    if not body:
        return body
    lines = body.split("\n")
    out_lines: list[str] = []
    sep_re = re.compile(r"^\s*[+|][\-=+|\s]+$")
    row_re = re.compile(r"^\s*\|(.*)\|\s*$")
    last_data_row_idx: int = -1
    for line in lines:
        if sep_re.match(line):
            # RST grid separator — keep, reset continuation pointer.
            out_lines.append(line)
            last_data_row_idx = -1
            continue
        m = row_re.match(line)
        if not m:
            # Non-pipe-row text; pass through, reset pointer so a
            # blank line / prose interleave doesn't merge across it.
            out_lines.append(line)
            last_data_row_idx = -1
            continue
        cells_raw = m.group(1)
        cells = [c.strip() for c in cells_raw.split("|")]
        # Continuation rule: first cell empty + at least one of the
        # other cells non-empty.
        if cells and not cells[0] and any(c for c in cells[1:]):
            if last_data_row_idx >= 0 and last_data_row_idx < len(out_lines):
                prev_m = row_re.match(out_lines[last_data_row_idx])
                if prev_m:
                    prev_cells = [c.rstrip() for c in
                                  prev_m.group(1).split("|")]
                    cont_text = " ".join(c for c in cells[1:]
                                          if c).strip()
                    if cont_text and prev_cells:
                        prev_cells[-1] = (
                            prev_cells[-1] + " " + cont_text).strip()
                    out_lines[last_data_row_idx] = (
                        "|" + "|".join(prev_cells) + "|")
                # Either way drop the continuation row itself.
                continue
            # Orphan continuation (no parent yet) — keep as-is.
        out_lines.append(line)
        last_data_row_idx = len(out_lines) - 1
    return "\n".join(out_lines)


def _v1_6_329_extract_param_grid_table(text: str):
    """v1.6.329 — for #223 Round-2. Yield parameter entries
    `{name, default, type, description, extraction_strategy}` from
    pipe-table rows under a `Parameters` heading.

    Improvements over `_v1_6_324_extract_param_grid_table`:
      * Name cell accepts 0, 1, or 2 backticks (RST `` ``literal`` ``
        form, which was the dominant shape on benchmark RST docs).
      * Section body now also includes dedented bodies of
        `.. table::` and `.. list-table::` Sphinx directives that
        live inside the Parameters window — pre-v1.6.329 those
        indented rows were invisible to the raw-pipe-row regex.

    v1.6.447 — for #316 R2 ORGANIC. The body now passes through
    `_v1_6_447_collapse_continuation_lines_in_text` BEFORE the
    per-row `_RE_RST_PARAM_GRID_ROW_v1_6_329.finditer` sweep, so
    multi-row continuations are merged into their parent row's
    description column. The 200-char description cap is also raised
    to 500 to accommodate merged continuation text (ic-A `ZFINX`
    spans ~250 chars across 4 continuation rows).

    Skips header/separator rows whose name (lowercased) is one of
    `{"name", "parameter", "default", "type"}`.

    Chip-AGNOSTIC: pure GFM / RST grammar match; no chip-class
    string literal participates.
    """
    if not text or not isinstance(text, str):
        return
    for m_anchor in _RE_PARAM_SECTION_ANCHOR_v1_6_324.finditer(text):
        body = _v1_6_329_walk_param_section_with_directives(
            text, m_anchor.end(),
        )
        if not body:
            continue
        # v1.6.447 — collapse continuation rows before the per-row
        # regex sweep so multi-row descriptions land on one row.
        body = _v1_6_447_collapse_continuation_lines_in_text(body)
        for row in _RE_RST_PARAM_GRID_ROW_v1_6_329.finditer(body):
            name = (row.group("name") or "").strip()
            if not name:
                continue
            # Skip header / column-label rows. Lowercase the
            # captured name so case-insensitive comparison wins.
            if name.lower() in {"name", "parameter",
                                 "default", "type"}:
                continue
            yield {
                "name": name,
                "default": (row.group("dflt") or "").strip(),
                "type": (row.group("typ") or "").strip(),
                # v1.6.447 — raise description cap from 200 to 500 so
                # merged continuation text isn't re-truncated.
                "description": (row.group("desc") or "").strip()[:500],
                "extraction_strategy":
                    "rst_param_grid_table_v1_6_329",
            }


# v1.6.399 — for #289 P3: RST list-table parameters walker.
# Sibling of v1.6.329 .. table:: walker; reuses existing
# `_rst_list_table_iter_blocks` (yields `(caption, header, body)`
# tuples). Title regex covers canonical Parameters/Generics
# vocabulary. Chip-AGNOSTIC: pure RST list-table grammar; no
# chip-class string literal participates.
_V1_6_399_RE_LIST_TABLE_PARAMETERS_TITLE = re.compile(
    r"^(?P<title>(?:Parameter|Parameters|Configuration\s+Generics|"
    r"Generics|Module\s+Parameters|Design\s+Parameters))",
    re.IGNORECASE,
)


def _v1_6_399_extract_param_list_table(text: str, fname: str) -> list:
    """Extract L8.parameters[] rows from RST list-table whose
    caption matches parameter vocabulary. Mirrors v1.6.329 emit
    shape. Header row (first body row from `_rst_list_table_iter_blocks`)
    is the rendered header; subsequent body rows produce one
    parameter entry each.

    `_rst_list_table_iter_blocks` yields ``(caption, header, body)``
    where ``caption`` is the text directly after ``.. list-table::``
    and ``header`` is the first row, ``body`` the remaining rows.
    Each row is ``List[str]`` of trimmed cell text.

    Chip-AGNOSTIC: pure RST list-table grammar.
    """
    out: list = []
    if not text or not isinstance(text, str):
        return out
    try:
        blocks_iter = _rst_list_table_iter_blocks(text)
    except Exception:
        return out
    for triple in blocks_iter:
        try:
            caption, _header, body_rows = triple
        except (TypeError, ValueError):
            continue
        if not _V1_6_399_RE_LIST_TABLE_PARAMETERS_TITLE.match(
                (caption or "").strip()):
            continue
        if not body_rows:
            continue
        for row in body_rows:
            if not row:
                continue
            name = (row[0] or "").strip().strip("`")
            if not name:
                continue
            # Skip rows whose name cell is a header-label leftover.
            if name.lower() in {"name", "parameter", "default",
                                "type", "generic"}:
                continue
            default_raw = (row[1] or "").strip() if len(row) > 1 else ""
            desc = (row[2] or "").strip() if len(row) > 2 else ""
            # Extract first token from default cell, strip
            # `(default)` annotation tail.
            m_def = re.search(
                r"^([^\s,(]+)(?:\s*\(default\))?",
                default_raw, re.IGNORECASE,
            )
            default_val = m_def.group(1) if m_def else None
            if default_val in (None, ""):
                default_val = None
            # Try to extract type from description via v1.6.379 helper.
            try:
                _, type_val = _v1_6_379_extract_default_type(desc)
            except (NameError, Exception):
                type_val = None
            out.append({
                "name": name,
                "default": default_val,
                "type": type_val,
                "description": desc[:200],
                "source": fname,
                "extraction_strategy":
                    "rst_list_table_parameters_v1_6_399",
            })
    return out


# v1.6.400 — for #290 P3: anchorless parameter table fallback.
# `_RE_PARAM_SECTION_ANCHOR_v1_6_324` requires a section anchor
# `^Parameters\n[-=^~]{3,}` before the pipe-table walker fires.
# Tables under non-canonical section headings (e.g. `## Plugin
# Settings` or `## Configuration`) drop. This fallback scans all
# pipe-tables in the document; if the first header cell matches
# a parameter-vocabulary token (Parameters / Generics / Config /
# Constants / Macros), route the rows through the parameter
# pipeline regardless of section heading. Pure structural —
# header-cell check uses a frozenset of grammar tokens, no
# chip-class vocabulary participates.
# Issue #500 — parameter-table header vocabulary now derives from the
# ONE shared bilingual lexicon (`parameter` role), so a CJK-headed
# `參數 | 型別 | 預設值 | 描述` parameter table is recognised the same
# as the English `Parameter | Type | Default | Description`. The original
# English vocabulary is the English subset of the `parameter` role.
# Chip-AGNOSTIC.
_V1_6_400_PARAMETER_HEADER_TOKENS = _hlex.tokens_for("parameter")


def _v1_6_400_is_parameter_table_header(
        header_cells: list,
        preceding_lines: list = None) -> bool:
    """True iff the first cell of the header row matches
    parameter-table vocabulary. Case-insensitive; strips
    surrounding backticks/whitespace. Chip-AGNOSTIC.

    v1.6.425 — for #298 R4 ORGANIC. The original check accepts only
    Tier (a): first cell ∈ ``_V1_6_400_PARAMETER_HEADER_TOKENS``
    (Parameter / Generic / Config / Constant / Macro). Real-world
    AsciiDoc grids put the parameter-vocabulary token in the
    SECTION HEADING (``=== Processor Top Entity - Generics``) or
    TABLE CAPTION (``.Processor Generic List``) and use a NAME-like
    column header (``Name | Type | Default | Description``). The
    Tier (a) gate rejects those rows even though they ARE parameter
    tables. v1.6.425 adds Tier (b) — accept when the first cell is
    NAME-LIKE AND any of the ≤10 preceding non-empty lines contain
    a parameter-context token.

    ``preceding_lines`` defaults to ``None`` so existing single-arg
    callers retain v1.6.400 behaviour (Tier (a) only).

    Chip-AGNOSTIC: NAME-like vocabulary + context vocabulary are
    pure grammar tokens; no chip identifier participates.
    """
    if not header_cells:
        return False
    first = (header_cells[0] or "").strip().strip("`").strip().lower()
    # Tier (a) — v1.6.400 vocab path (unchanged).
    if first in _V1_6_400_PARAMETER_HEADER_TOKENS:
        return True
    # Tier (b) — v1.6.425 anchor-context path.
    if _v1_6_425_first_cell_is_name_like(header_cells[0]) and \
            _v1_6_425_preceding_has_param_vocab(preceding_lines):
        return True
    return False


# v1.6.425 — for #298 R4 ORGANIC. Anchor-context path for parameter
# tables whose header first cell is NAME-LIKE (Name / Symbol /
# Identifier / Signal / etc.) rather than parameter vocab. The
# parameter-vocabulary token sits in the surrounding AsciiDoc /
# Markdown / RST context — section heading (``=== ... - Generics``)
# or table caption (``.<X> Generic List``). Tier (b) of the 2-tier
# accept in ``_v1_6_400_is_parameter_table_header``.
#
# Chip-AGNOSTIC: NAME-like first-cell vocabulary and context vocab
# are pure structural tokens; no chip identifier participates.
_V1_6_425_NAME_LIKE_FIRST_CELL = frozenset({
    "name", "symbol", "identifier", "ident", "signal",
    "generic name", "parameter name", "constant name",
})


_V1_6_425_RE_PARAM_CONTEXT_TOKEN = re.compile(
    r"\b(generic|parameter|config|constant|macro|setting)s?\b",
    re.IGNORECASE,
)


def _v1_6_425_first_cell_is_name_like(first: str) -> bool:
    """v1.6.425 — for #298 R4. True iff ``first`` (raw header cell)
    normalises to a NAME-like identifier token. Strips surrounding
    backticks, asterisks, quotes, whitespace.

    Chip-AGNOSTIC."""
    if not first:
        return False
    norm = first.strip().lower().strip("`*\"' ").strip()
    return norm in _V1_6_425_NAME_LIKE_FIRST_CELL


def _v1_6_425_preceding_has_param_vocab(preceding_lines) -> bool:
    """v1.6.425 — for #298 R4. True iff any of the ``preceding_lines``
    contains a parameter-context token (generic / parameter / config /
    constant / macro / setting, with optional ``s`` suffix). Used
    against ≤10 lines immediately preceding a candidate parameter
    table to detect AsciiDoc section heading
    (``=== Processor Top Entity - Generics``) or table caption
    (``.Processor Generic List``).

    Chip-AGNOSTIC: vocabulary is pure structural grammar."""
    if not preceding_lines:
        return False
    context = "\n".join(preceding_lines)
    return bool(_V1_6_425_RE_PARAM_CONTEXT_TOKEN.search(context))


def _v1_6_425_get_preceding_lines(
        text: str, table_start_offset: int, n: int = 10) -> list:
    """v1.6.425 — for #298 R4. Return up to ``n`` non-empty lines in
    source order that immediately precede ``table_start_offset`` (a
    character offset into ``text``). AsciiDoc section headings
    (``=== ...``) and table captions (``.<X> ...``) typically sit
    within 1-5 lines of the table they describe; ``n=10`` gives slack
    for blank-line separators / attribute lines.

    Chip-AGNOSTIC."""
    if not text or table_start_offset <= 0:
        return []
    head = text[:table_start_offset]
    lines = head.split("\n")
    out: list = []
    for ln in reversed(lines):
        if not ln.strip():
            continue
        out.append(ln)
        if len(out) >= n:
            break
    return list(reversed(out))


# Pipe-table block split: blank line or any non-pipe non-blank line.
# Each block is a contiguous run of lines starting with `|`.
_V1_6_400_RE_PIPE_TABLE_LINE = re.compile(r"^\s*\|")


# v1.6.424 — for #298 R3 ORGANIC. AsciiDoc table-block delimiter
# `|====...====` (with or without trailing `|`) brackets the table
# body in AsciiDoc grids. These rows match `^\s*\|` so the original
# walker added them as `block_rows[0]` with a single cell
# (`["======..."]`); the downstream `_is_sep` predicate only knew
# Markdown `:?-{3,}:?` form so it failed to strip them, and
# `_v1_6_400_is_parameter_table_header` then rejected the row's first
# cell `"======..."` as not parameter vocab → the entire 105-row
# master Generics block was dropped (80 params lost).
#
# Fix: detect the delimiter line and soft-skip it inside the iterator
# (sibling of the v1.6.421 col-span skip — same SOFT-CONTINUATOR shape:
# don't add to ``block_rows``, don't break the block).
#
# Chip-AGNOSTIC: pure AsciiDoc table grammar.
_V1_6_424_RE_ADOC_TABLE_DELIMITER = re.compile(
    r"^\s*\|\s*={3,}\s*\|?\s*$"
)


def _v1_6_440_join_grid_continuation_rows(rows):
    """v1.6.440 — for #316 P2 ORGANIC. Merge RST/AsciiDoc grid-table
    cell-continuation rows. The RST grid-table grammar permits a
    long cell to wrap across multiple physical row-lines: subsequent
    row-lines whose leading column cells are all empty are
    continuation of the previous row's wrapped cell. Pre-v1.6.440
    consumers iterated row-by-row and treated each continuation row
    as either a new entry (with empty name) or dropped it; the
    description field ended up truncated to the first physical line.
    Real-world: a parameter row whose source spans 4 continuation
    lines emitted only the first ~40 chars before truncation.

    A row is a continuation iff:
      * all cells except the LAST are empty/whitespace;
      * the last cell has content.
    On continuation, append `" " + last_cell.strip()` to the
    previous row's last non-empty cell.

    Pure structural grammar; chip-AGNOSTIC.

    Returns a new list of rows; never mutates the input list.
    """
    if not rows:
        return list(rows or [])
    merged = []
    for row in rows:
        if not isinstance(row, list):
            merged.append(row)
            continue
        if not merged:
            merged.append(list(row))
            continue
        # Determine if `row` is a continuation: every cell BEFORE the
        # last is empty/whitespace, and the last cell is non-empty.
        if len(row) == 0:
            merged.append(list(row))
            continue
        leading_empty = all(
            (str(c).strip() == "") for c in row[:-1]
        ) if len(row) > 1 else True
        last_cell = (str(row[-1] or "")).strip() if row else ""
        if leading_empty and last_cell:
            # Append last_cell to the previous row's last non-empty
            # cell. Walk previous row right-to-left to find first
            # non-empty cell.
            prev = merged[-1]
            if isinstance(prev, list):
                for ci in range(len(prev) - 1, -1, -1):
                    if str(prev[ci] or "").strip():
                        prev[ci] = (str(prev[ci]).rstrip()
                                    + " " + last_cell)
                        break
                else:
                    # All previous cells empty too — just append last.
                    if prev:
                        prev[-1] = (str(prev[-1] or "").rstrip()
                                    + " " + last_cell)
                continue
            # Previous row not a list — fall through to append as
            # standalone row.
        merged.append(list(row))
    return merged


def _v1_6_400_iter_pipe_tables(text: str):
    """Yield ``(start_line, end_line, rows)`` triples for every
    contiguous pipe-table block in ``text``. Each row is a list
    of trimmed cell-text strings (the leading/trailing empty
    cells from the outer pipes are removed). Pure GFM pipe-table
    grammar; chip-AGNOSTIC.

    v1.6.421 — for #298 R2 ORGANIC. AsciiDoc col-span group-separator
    rows (e.g. ``4+^| **General**``) are soft continuators: they start
    with a digit (NOT ``|``), so the original block-terminator logic
    would shatter an ``[options="header"]`` AsciiDoc grid into
    headerless fragments at each group-separator row. The fix detects
    col-span rows via the shared ``_v1_6_416_is_colspan_group_separator``
    helper and SKIPS them without breaking the block; the row itself
    is not added to ``block_rows`` (downstream parsing only needs the
    real data rows).

    v1.6.424 — for #298 R3 ORGANIC. AsciiDoc table-block delimiter
    rows ``|====...====`` are also soft continuators: they DO start
    with ``|`` so the line matches ``_V1_6_400_RE_PIPE_TABLE_LINE`` and
    used to be added as a 1-cell data row ``["======..."]`` — causing
    ``_v1_6_400_is_parameter_table_header`` to reject the block. The
    fix detects the delimiter via ``_V1_6_424_RE_ADOC_TABLE_DELIMITER``
    BEFORE the generic pipe-line branch and skips it without breaking
    the block.

    Chip-AGNOSTIC: pure AsciiDoc / GFM grammar; no chip-class literal.
    """
    if not text:
        return
    lines = text.split("\n")
    i = 0
    n = len(lines)
    while i < n:
        if not _V1_6_400_RE_PIPE_TABLE_LINE.match(lines[i]):
            i += 1
            continue
        start = i
        block_rows: list = []
        end = i  # tracks the last line that participated in this block
        while i < n:
            line_raw = lines[i]
            if _V1_6_424_RE_ADOC_TABLE_DELIMITER.match(line_raw):
                # v1.6.424 — for #298 R3. AsciiDoc table-block
                # delimiter ``|====...====`` is a SOFT continuator
                # (sibling of the v1.6.421 col-span skip below):
                # don't add to ``block_rows`` and don't break the
                # block. Must precede the generic pipe-line branch
                # because the delimiter also begins with ``|``.
                end = i
                i += 1
            elif _V1_6_400_RE_PIPE_TABLE_LINE.match(line_raw):
                line = line_raw.rstrip()
                # Split on `|`; trim cells; drop leading/trailing empties.
                cells = [c.strip() for c in line.split("|")]
                if cells and cells[0] == "":
                    cells = cells[1:]
                if cells and cells[-1] == "":
                    cells = cells[:-1]
                block_rows.append(cells)
                end = i
                i += 1
            elif _v1_6_416_is_colspan_group_separator(line_raw):
                # v1.6.421 — for #298 R2. AsciiDoc col-span row is a
                # SOFT continuator: skip the row without adding it to
                # the block and without breaking the block. Real
                # ``[options="header"]`` AsciiDoc grids place
                # ``N+^| **Group**`` rows between data rows.
                end = i
                i += 1
            else:
                break
        if block_rows:
            # v1.6.440 — for #316 P2 ORGANIC. Merge cell-continuation
            # rows. RST/AsciiDoc grid-tables permit a long cell to
            # wrap across multiple physical row-lines: subsequent
            # row-lines whose leading columns are blank are
            # continuations. Pre-v1.6.440, consumers iterated each
            # physical row as a separate entry, truncating the
            # description column to the first physical line.
            block_rows = _v1_6_440_join_grid_continuation_rows(
                block_rows)
            yield (start, end, block_rows)


# v1.6.420 — for #302 P3 ORGANIC. Parametric / placeholder width cell
# parser. Signal-table parsers previously dropped rows whose width
# column contained anything other than `\d{1,4}` (e.g. `*`, `N`,
# `WIDTH`, `DATA_WIDTH-1`, `(variable)`, `var`). 2/50 ports dropped
# on a typical SoC reference. The helper splits cells into:
#   - numeric  → returns (int, raw_str)
#   - parametric / placeholder / empty → returns (None, raw_str)
# The row caller checks: numeric → set `width=str(int)`; else
# preserve `width_raw_symbolic` so the row survives.
#
# Chip-AGNOSTIC: structural shape, no chip-class literal.
_V1_6_420_RE_WIDTH_NUMERIC = re.compile(r"^\s*(\d{1,4})\s*$")
_V1_6_420_RE_WIDTH_PARAMETRIC = re.compile(
    r"^\s*([A-Z][A-Z0-9_]*(?:[+\-*/]\s*\d+)?|\*|"
    r"\(?\s*variable\s*\)?|var|[\w\s+\-*/]+)\s*$",
    re.IGNORECASE,
)


def _v1_6_420_parse_width_cell(raw: str) -> tuple:
    """v1.6.420 — for #302 P3. Return ``(width_int_or_None,
    width_raw_str)``. Numeric → (int, raw). Parametric / placeholder
    → (None, raw). Empty → (None, ""). Never drops a row.

    v1.0.78 — for #731 ORGANIC. A row that falls through to the GFM
    multitable walker (`gfm_multitable_header_role_v0_3_2`) used to lose its
    `8-bit` / `1-bit` / `~10-bit` / `[31:0]` width here, because only a PURE
    numeric cell resolved to an int. Route a non-numeric cell through the
    shared `_parse_port_width` so the `N-bit` idiom (incl. an optional
    approximation marker) and a bracketed `[M:L]` cell resolve to their
    concrete integer width; a symbolic / placeholder cell still yields
    (None, raw) so the row survives unchanged.

    Chip-AGNOSTIC: pure structural shape; no chip identifier."""
    raw = (raw or "").strip()
    if not raw:
        return (None, "")
    m_num = _V1_6_420_RE_WIDTH_NUMERIC.match(raw)
    if m_num:
        return (int(m_num.group(1)), raw)
    # v1.0.78 — for #731: recognise the `N-bit` / `~N-bit` / bracketed-width
    # idioms via the canonical parser so the multitable fallback carries the
    # concrete width. Only a resolved INTEGER is promoted; symbolic widths
    # (e.g. `[WIDTH-1:0]`) stay (None, raw) to preserve prior behaviour.
    w_int, _msb, _lsb, _wsym = _parse_port_width(raw)
    if w_int is not None:
        return (w_int, raw)
    return (None, raw)


# v1.6.418 — for #300 P2 ORGANIC. Env-var context deny-list. The
# anchorless walker (v1.6.400) accepts any pipe-table whose first
# header cell matches parameter vocab ("Parameter", "Parameters",
# "Generic", "Generics", etc.). README CI/shell tables also use
# "Parameter" as a header cell to document shell env vars + their
# meaning, and those tables leak as RTL parameters (~15% L8
# pollution rate reported in the field).
#
# The fix: gather a +-10-line text window around each candidate
# table. If the window contains canonical env-var / CI / shell /
# regression hints (export NAME=, environment variable, CI flag,
# Makefile var, etc.), reject the whole table.
#
# Chip-AGNOSTIC: open shell / CI vocabulary; no chip identifier.
_V1_6_418_ENV_VAR_CONTEXT_DENYLIST = re.compile(
    r"\b("
    r"environment\s*variable|env\s*var|"
    r"export\s+\w+|"
    r"shell\s+(?:script|variable|env)|"
    r"command[\s\-]line\s+(?:flag|option|arg)|"
    r"makefile\s+(?:variable|flag)|"
    r"\bCI\b|continuous\s+integration|"
    r"regression\s+(?:test|script|seed|config)"
    r")\b",
    re.IGNORECASE,
)


def _v1_6_418_is_env_var_context(text_window: str) -> bool:
    """v1.6.418 — for #300 P2 ORGANIC. True iff ``text_window``
    contains canonical env-var / CI / shell / regression hints.
    Chip-AGNOSTIC."""
    if not text_window:
        return False
    return bool(_V1_6_418_ENV_VAR_CONTEXT_DENYLIST.search(text_window))


def _v1_6_400_extract_anchorless_param_table(text: str) -> list:
    """Anchorless parameter-table fallback. Scan every pipe-table
    in ``text``; for each, if its first header-cell matches
    parameter vocabulary AND the table does NOT sit inside a
    canonical ``Parameters`` section anchor window (which is
    already covered by v1.6.329 / v1.6.399), emit one parameter
    entry per body row with strategy
    ``rst_param_grid_table_anchorless_v1_6_400``.

    Returns a list of dicts (same shape as the v1.6.329 emit).

    v1.6.418 — for #300 P2. After the header semantic check passes,
    gather ±10 lines of surrounding text and call
    `_v1_6_418_is_env_var_context`. If it returns True, skip the
    table; counts feed `env_var_table_rejected_v1_6_418`.

    Chip-AGNOSTIC: vocabulary frozenset has no chip-class
    literal; pipe-table grammar is pure GFM.
    """
    out: list = []
    if not text or not isinstance(text, str):
        return out
    # Pre-compute byte-offset ranges of canonical Parameters
    # section anchor windows so we can skip tables that fall
    # inside one (already covered by v1.6.329).
    canonical_windows: list = []
    for m in _RE_PARAM_SECTION_ANCHOR_v1_6_324.finditer(text):
        # The anchor + ~8000 chars of body — matches the window
        # cap used in `_v1_6_329_walk_param_section_with_directives`.
        canonical_windows.append((m.start(), m.end() + 8000))
    # Byte offset of each line for the in-window check.
    lines = text.split("\n")
    line_offsets: list = []
    off = 0
    for ln in lines:
        line_offsets.append(off)
        off += len(ln) + 1  # +1 for \n
    for start_line, end_line, rows in _v1_6_400_iter_pipe_tables(text):
        if len(rows) < 2:
            continue
        # Filter out pure-separator-only blocks: row is a separator
        # if every cell looks like Markdown ``:?---+:?`` OR AsciiDoc
        # ``={3,}`` (v1.6.424 — for #298 R3 defensive complement to
        # the table-block-delimiter skip in
        # ``_v1_6_400_iter_pipe_tables``: if any other code path
        # constructs cells from a delimiter row, this predicate still
        # strips them before the header semantic check). Chip-AGNOSTIC.
        def _is_sep(cells: list) -> bool:
            if not cells:
                return False
            for c in cells:
                if not re.match(r"^(?::?-{3,}:?|={3,})$", c.strip()):
                    return False
            return True
        # Skip the separator row when present (after header).
        data_rows = [r for r in rows if not _is_sep(r)]
        if len(data_rows) < 2:
            continue
        header = data_rows[0]
        # Header semantic check: first cell must be a parameter
        # vocabulary token (Tier (a) v1.6.400) OR NAME-LIKE +
        # preceding ≤10 lines contain parameter-context vocab
        # (Tier (b) v1.6.425 — for #298 R4). The preceding-context
        # window catches AsciiDoc section heading
        # (``=== ... - Generics``) and table caption
        # (``.<X> Generic List``) shape where the vocab sits
        # OUTSIDE the table itself.
        block_off_for_anchor = line_offsets[start_line] \
            if start_line < len(line_offsets) else 0
        preceding = _v1_6_425_get_preceding_lines(
            text, block_off_for_anchor, 10)
        if not _v1_6_400_is_parameter_table_header(header, preceding):
            continue
        # Is this table already inside a canonical anchor window?
        block_off = line_offsets[start_line] if start_line < len(
            line_offsets) else 0
        in_canonical = any(
            lo <= block_off <= hi for (lo, hi) in canonical_windows)
        if in_canonical:
            continue
        # v1.6.418 — for #300 P2. Context-aware env-var deny: gather
        # ±10 lines of surrounding text and reject the entire table
        # when shell / env / CI / regression keywords appear nearby.
        win_lo_line = max(0, start_line - 10)
        win_hi_line = min(len(lines) - 1, end_line + 10)
        text_window = "\n".join(lines[win_lo_line:win_hi_line + 1])
        if _v1_6_418_is_env_var_context(text_window):
            continue
        # Header-driven column role mapping. Column 0 is always the
        # name. For cols 1..N look at header label and bucket into
        # default / type / description.
        col_role: dict = {}
        for ci, hc in enumerate(header):
            if ci == 0:
                continue
            hclow = (hc or "").strip().strip("`").lower()
            if hclow in ("default", "value", "dflt"):
                col_role.setdefault("default", ci)
            elif hclow in ("type", "kind", "datatype", "dtype"):
                col_role.setdefault("type", ci)
            elif hclow in ("description", "desc", "notes",
                           "purpose", "comment"):
                col_role.setdefault("description", ci)
        # Emit one entry per body row.
        for row in data_rows[1:]:
            if not row:
                continue
            name = (row[0] or "").strip().strip("`")
            if not name:
                continue
            if name.lower() in {"name", "parameter", "default",
                                "type", "generic"}:
                continue

            def _col(role_name: str) -> str:
                ci = col_role.get(role_name, -1)
                if 0 <= ci < len(row):
                    return (row[ci] or "").strip()
                return ""

            default_val = _col("default")
            type_val = _col("type")
            desc = _col("description")
            # Fallback for headers that lacked any of the standard
            # role labels: assume col1=default, col2=type, col3=desc.
            if not default_val and not type_val and not desc:
                default_val = (row[1] or "").strip() \
                    if len(row) > 1 else ""
                type_val = (row[2] or "").strip() \
                    if len(row) > 2 else ""
                desc = (row[3] or "").strip() \
                    if len(row) > 3 else ""
            out.append({
                "name": name,
                "default": default_val or None,
                "type": type_val or None,
                "description": desc[:200],
                "extraction_strategy":
                    "rst_param_grid_table_anchorless_v1_6_400",
            })
    return out


_RE_VERILOG_PORT_BIND = re.compile(
    r"(?m)^\s*\.(?P<name>[a-zA-Z_][\w]*)\s*\(\s*"
    r"(?P<connection>[^)]*?)\s*\)\s*,?\s*$"
)
# Code-fence / literal-block delimiters that gate the extractor.
_RE_VERILOG_FENCE_OPEN = re.compile(
    r"(?im)^\s*```(?:verilog|systemverilog|sv)\b")
_RE_FENCE_CLOSE = re.compile(r"(?m)^\s*```\s*$")
_RE_RST_VERILOG_DIRECTIVE = re.compile(
    r"(?im)^\s*\.\.\s+code-block::\s*(?:verilog|systemverilog|sv)\b")

# v1.6.249 — #109 round-2. CommonMark-traditional 4-space-indented
# code block. Trigger = a non-empty line ending in ':' followed by a
# blank line and one or more 4-space-indented lines.
#
# v1.6.250 — #109 round-3. The v1.6.249 single-regex implementation
# stopped at the first internal blank line; real RV README blocks
# split port groups (request / response / etc.) by blank lines but
# remain ONE CommonMark indented code block (spec: blank lines
# inside an indented block belong to the block as long as the next
# non-blank line is still 4-space-indented). Replaced with a
# line-by-line scanner in `_extract_markdown_indented_verilog_blocks`.
_RE_VERILOG_TOKEN_HINT = re.compile(r"\b(?:input|output|inout)\b")


def _extract_markdown_indented_verilog_blocks(text: str) -> List[str]:
    """Return list of dedented bodies for CommonMark 4-space-indented
    code blocks that follow a colon-terminated paragraph and contain
    Verilog port keywords. Blank lines INSIDE the block are kept as
    long as the next non-blank line is still 4-space-indented (per
    CommonMark spec). Prose-only indented blocks (shell snippets,
    quoted logs) are filtered by `_RE_VERILOG_TOKEN_HINT`."""
    out: List[str] = []
    if not text:
        return out
    lines = text.split("\n")
    n = len(lines)
    i = 0
    while i < n:
        # Trigger: a non-empty line ending in `:` + blank line + 4-sp line.
        line = lines[i]
        if line.strip().endswith(":") and i + 2 < n \
                and not lines[i + 1].strip() \
                and lines[i + 2].startswith("    "):
            body_lines: List[str] = []
            j = i + 2
            while j < n:
                ln = lines[j]
                if ln.startswith("    "):
                    body_lines.append(ln[4:])
                    j += 1
                    continue
                if not ln.strip():
                    # Peek past any run of blank lines.
                    k = j
                    while k < n and not lines[k].strip():
                        k += 1
                    if k < n and lines[k].startswith("    "):
                        # Block continues; keep the blanks.
                        body_lines.extend([""] * (k - j))
                        j = k
                        continue
                    break
                break
            body = "\n".join(body_lines)
            if body and _RE_VERILOG_TOKEN_HINT.search(body):
                out.append(body)
            i = j
            continue
        i += 1
    return out


# v1.6.406 — for #295 P3: relax markdown indented Verilog block
# trigger. CommonMark allows ANY block boundary (blank line +
# 4-space indent); colon-terminated lead-in is just one common
# shape. Period/exclam/question-terminated prose lead-ins are also
# valid CommonMark separators. The Verilog-content gate
# (_RE_VERILOG_TOKEN_HINT on the body's FIRST non-blank line)
# prevents shell-log / quoted-output false positives.
#
# Return shape matches the v1.6.0 helper (List[str] of dedented
# bodies) so existing callers receive identical contracts. The
# v1.6.0 helper itself is kept defined above for backward compat.
def _v1_6_406_extract_markdown_indented_verilog_blocks(
        text: str) -> List[str]:
    """Relaxed CommonMark indented-Verilog block extractor.

    Trigger: any non-empty prose line (lead-in) that is NOT itself a
    Verilog port declaration, followed by one or more blank lines,
    followed by a 4-space-indented line whose dedented form passes
    `_RE_VERILOG_TOKEN_HINT`. Internal blank lines inside the body
    are preserved as long as the next non-blank line is still
    4-space-indented (per CommonMark).
    """
    out: List[str] = []
    if not text:
        return out
    lines = text.split("\n")
    n = len(lines)
    i = 0
    while i < n:
        line = lines[i]
        stripped = line.strip()
        if not stripped:
            i += 1
            continue
        # The lead-in must be PROSE (no Verilog port-decl token).
        if _RE_VERILOG_TOKEN_HINT.search(line):
            i += 1
            continue
        # The lead-in itself must NOT be indented 4 spaces (that
        # would put it inside an existing code block).
        if line.startswith("    "):
            i += 1
            continue
        # Peek for blank-line separator(s).
        j = i + 1
        while j < n and not lines[j].strip():
            j += 1
        if j == i + 1 or j >= n:
            # No blank-line separator OR ran off the end.
            i = max(i + 1, j)
            continue
        # The next non-blank line must be 4-space-indented AND its
        # dedented form must contain a Verilog port-decl token.
        if not lines[j].startswith("    "):
            i = j
            continue
        if not _RE_VERILOG_TOKEN_HINT.search(lines[j]):
            i = j
            continue
        # Walk the indented body; keep internal blank lines as long
        # as the next non-blank line is still 4-space-indented.
        body_lines: List[str] = []
        k = j
        while k < n:
            ln = lines[k]
            if ln.startswith("    "):
                body_lines.append(ln[4:])
                k += 1
                continue
            if not ln.strip():
                p = k
                while p < n and not lines[p].strip():
                    p += 1
                if p < n and lines[p].startswith("    "):
                    body_lines.extend([""] * (p - k))
                    k = p
                    continue
                break
            break
        body = "\n".join(body_lines)
        if body and _RE_VERILOG_TOKEN_HINT.search(body):
            out.append(body)
        i = max(k, j + 1)
    return out


# v1.6.256 — for #115 field-agent round-2 feedback. SystemVerilog
# instantiation parameter block: `<module> #( ... )`. Returns a
# list of (start, end) char-spans covering every `#( ... )` block
# in the body so downstream port-bind extraction can skip them.
# Uses bracket-balanced scanning (regex alone cannot match balanced
# parens). Chip-AGNOSTIC.
def _find_param_block_spans(body: str) -> "List[Tuple[int, int]]":
    spans: List[Tuple[int, int]] = []
    if not body:
        return spans
    i = 0
    n = len(body)
    while i < n - 1:
        if body[i] == "#":
            # Skip whitespace between `#` and `(`.
            j = i + 1
            while j < n and body[j] in " \t":
                j += 1
            if j < n and body[j] == "(":
                # Bracket-balanced scan for the matching `)`.
                depth = 1
                k = j + 1
                while k < n and depth > 0:
                    c = body[k]
                    if c == "(":
                        depth += 1
                    elif c == ")":
                        depth -= 1
                    k += 1
                spans.append((i, k))
                i = k
                continue
        i += 1
    return spans


def _extract_verilog_blocks(text: str) -> List[str]:
    """Return the bodies of every markdown ```verilog``` fence
    and `.. code-block:: verilog` RST directive in `text`. Other
    prose is excluded so the port-decl regex cannot match prose
    sentences like `input data and output results`.
    """
    blocks: List[str] = []
    if not text:
        return blocks
    # Markdown fences.
    pos = 0
    while True:
        m = _RE_VERILOG_FENCE_OPEN.search(text, pos)
        if not m:
            break
        body_start = m.end()
        c = _RE_FENCE_CLOSE.search(text, body_start)
        body_end = c.start() if c else len(text)
        blocks.append(text[body_start:body_end])
        pos = body_end + 3
    # RST `.. code-block:: verilog` directive. Body = the
    # indented block immediately below. Use a simple indentation
    # detector that stops at the first non-blank line that has no
    # leading whitespace.
    for d in _RE_RST_VERILOG_DIRECTIVE.finditer(text):
        body_start = text.find("\n", d.end())
        if body_start < 0:
            continue
        body_start += 1
        lines = text[body_start:].splitlines(keepends=True)
        body_buf: List[str] = []
        seen_indented = False
        for ln in lines:
            if not ln.strip():
                body_buf.append(ln)
                continue
            if ln[0] in (" ", "\t"):
                body_buf.append(ln)
                seen_indented = True
            else:
                break
        if seen_indented:
            blocks.append("".join(body_buf))
    # v1.6.250 — #109 round-3. Markdown-indented blocks are now
    # extracted by `_extract_markdown_indented_verilog_blocks` and
    # emitted separately at the L1 callsite so they can be tagged
    # with a distinct extraction_strategy. Keep this function focused
    # on fenced + RST-directive shapes.
    return blocks

# v1.7.80 — for #514. The sibling of `_RE_BULLET_KV_SPEC`, carrying
# two instances of the same defect class that issue names. `([\d.]+)`
# accepted a number ending in a full stop, so a sentence boundary
# could be read into the value exactly as it was in the bullet-KV
# path; and `\s*` spans NEWLINES, so a symbol at the end of one
# paragraph and an unrelated quantity at the start of the next could
# be joined into one specification. Neither fires anywhere in the
# current corpus (measured: 8 matches, 0 affected), but a rule that
# is wrong only on documents nobody has fed it yet is still wrong —
# and the whole point of #514 is that these read as confident output.
# A number begins and ends with a digit; a specification does not
# span a line break.
_ELECTRICAL_SPEC_RE = re.compile(
    r"\b(VDD|VDDA|VSS|VOH|VOL|VIH|VIL|IDD|TJ|VBG|VREF)\b[ \t]*[:=]?[ \t]*"
    r"(\d+(?:\.\d+)?)[ \t]*(V|mV|mA|μA|uA|°C|MHz|kHz)",
    re.IGNORECASE,
)
_FREQUENCY_RE = re.compile(
    r"\b(\d+(?:\.\d+)?)\s*(MHz|kHz|Hz)\b",
    re.IGNORECASE,
)
_VOLTAGE_RE = re.compile(
    r"\b(\d+(?:\.\d+)?)\s*V\b"
)

# v1.6.234 — closes #101. Bullet KV-pair spec parser. Matches lines
# shaped `[bullet] <Param phrase>: <value>[ <unit>][ @ <cond>]`
# anywhere the parameter NAME is meaningful (canonical markdown /
# RST / AsciiDoc bullet form). Chip-AGNOSTIC: structural pattern
# (cap-letter start, optional unit-with-known-vocabulary suffix);
# no chip-class literal in detection.
#
# Layer routing is unit-driven (see _route_bullet_kv_spec):
#   electrical units → L1 + L5 electrical_specs
#   frequency/time   → L2 timing_parameters
#   unitless         → L5 design_parameters
_RE_BULLET_KV_SPEC = re.compile(
    # v1.6.236 — accept `~` (AsciiDoc subscript marker like
    # `f~main~`). Sample-rate units added. Trailing prose tolerated.
    # v1.6.238 — for #101 field-agent round-2 feedback. Param charset
    # now allows `[A-Za-z]` first char so AsciiDoc identifiers like
    # `f_main` / `f~main~` / `t_clk` (lowercase canonical names for
    # frequency / time constants) are captured. Pre-processing in
    # `_extract_bullet_kv_specs` strips italic / subscript markers
    # AND a stopword-words filter in the helper rejects prose phrases
    # whose param tokens carry English connectives — kills the
    # `"SRET instruction is executed when V"` false-positive that
    # relaxing lowercase capitalisation would otherwise enable.
    #
    # v1.7.80 — for #514. A KV match may not span a sentence boundary.
    # Three of this pattern's properties combined to read the English
    # indefinite article as an ampere: the value charset ended in
    # `[\d.,_]*`, so a sentence-ending full stop was absorbed into the
    # NUMBER; the unit alternation offers bare single letters; and the
    # trailing-prose tolerance swallowed the remainder so nothing
    # downstream could object. On `TSTRB = 1. A normal content byte`
    # that yields value `1.` unit `A` — a one-ampere specification
    # minted from a byte-qualifier sentence. Three general repairs,
    # none of which names a unit:
    #
    #   (1) A number begins AND ends with a digit. Trailing `.` `,`
    #       `_` are punctuation of the surrounding text, never part of
    #       the literal.
    #   (2) A unit may not abut an alphanumeric. `1Ampere` does not
    #       carry the unit `A`, and `204A` in an enumeration is an
    #       identifier, not a current.
    #   (3) The tolerated remainder must start at a boundary: either
    #       whitespace (the pre-existing tolerance — `3.3 V nominal`)
    #       or a clause terminator that the NUMBER ITSELF runs into.
    #       The `(?<=[0-9])` lookbehind is what makes that second form
    #       safe: it can only fire when no unit was matched, so a
    #       sentence boundary can never be the thing that promotes a
    #       prose word into a unit. `(?=[ \t]|$)` keeps a decimal
    #       point (`2.5V`) and a range dot (`0..7`) from being read as
    #       a clause end and truncating the number.
    #
    # Net effect on the sentence above: value `1`, NO unit, remainder
    # `. A normal content byte` tolerated as prose. The byte-qualifier
    # value survives — as the unitless design parameter it always was
    # — and the fabricated ampere is gone.
    r"^[ \t]*[\-\*\+]?[ \t]*"
    r"(?P<param>[A-Za-z][\w ~\-/()²³µΩ°.]{1,60}?)"
    r"[ \t]*[:=][ \t]*"
    r"(?P<value>[<>≈±]?[ \t]*[+-]?\d(?:[\d.,_]*[\d])?)"
    r"[ \t]*"
    r"(?P<unit>dBFS/Hz|dBFS|dBc|dB|Vpp|mV|µV|uV|kV|V|"
    r"mA|µA|uA|nA|A|"
    r"GHz|MHz|kHz|Hz|"
    r"GS/s|MS/s|kS/s|S/s|"
    r"ns|µs|us|ms|s|"
    r"ppm/°C|ppm|°C|"
    r"pF|nF|µF|uF|"
    r"µm|nm|um|"
    r"Ω|ohm|"
    r"%|x)?(?![A-Za-z0-9])"
    r"(?:[ \t]*(?:@|at)[ \t]*"
    r"(?P<cond>[\d.]+[ \t]*"
    r"(?:Hz|kHz|MHz|GHz|°C|V|ns|µs|us|ms)))?"
    r"(?:[ \t]+[^\n]*|(?<=[0-9])[.,;!?](?=[ \t]|$)[^\n]*)?[ \t]*$",
    re.MULTILINE,
)

# Stopword params that look like KV but are header / table-of-contents
# noise. Detection-only filter; not a chip-class literal.
_BULLET_KV_PARAM_STOPWORDS = {
    "table", "figure", "section", "note", "page", "version",
    "date", "revision", "author", "copyright", "license",
    "see", "ref", "ref.", "p.",
}

# v1.6.238 — for #101 field-agent round-2 feedback. Words that almost
# never appear in real spec parameter phrases (`Target SNR`, `PSRR
# target`, `Sampling capacitor`, `Voltage tolerance`, ...) but DO
# appear in prose ("V is the input voltage when X = '0'"). Rejecting
# any param that contains one of these connective tokens lets us
# safely relax the first-char to `[A-Za-z]` without flooding the
# spec list with prose false-positives.
_BULLET_KV_PARAM_CONNECTIVES = {
    "is", "are", "was", "were", "be", "been", "being",
    "the", "of", "and", "or", "but", "for", "to", "from", "with",
    "by", "in", "on", "at", "as", "if", "then", "when", "where",
    "which", "while", "until", "since", "during", "after", "before",
    "executed", "executes", "follows", "following", "shall",
    "should", "must", "may", "can", "could", "would", "will",
    "this", "that", "these", "those",
}

# v1.6.238 — for #101 field-agent round-2 feedback. Split-anchor for
# multi-KV-on-single-line bullets like
# `- Vin: 3.6 V, Vout: 3.3 V, Iload: 2 mA quiescent + 5 mA peak`.
# Splits on `,\s+` only when the next fragment starts with a
# capital-letter param phrase + KV separator — otherwise it would
# fragment normal English commas inside a value/cond phrase.
_BULLET_KV_FRAGMENT_SPLIT = re.compile(
    r",\s+(?=[A-Za-z][\w ~\-/()²³µΩ°.]*?[:=])")

# v1.6.238 — for #101 field-agent round-2 feedback. AsciiDoc italic
# wrapper `_text_` / `*text*` and subscript `name~sub~` strip-pass.
# Applied before regex so AsciiDoc lines like `* _f~main~_ = 100 MHz`
# become `* f_main = 100 MHz` (single token, captured normally).
_RE_ADOC_ITALIC_UNDER = re.compile(r"(?<!\w)_([^_\s\n][^_\n]{0,40})_(?!\w)")
_RE_ADOC_ITALIC_STAR  = re.compile(r"(?<!\w)\*([^\*\s\n][^\*\n]{0,40})\*(?!\w)")
_RE_ADOC_SUBSCRIPT    = re.compile(r"(\w+)~([\w.]+)~")

_ELECTRICAL_UNITS = {
    "V", "mV", "µV", "uV", "kV", "Vpp",
    "mA", "µA", "uA", "nA", "A",
    "dB", "dBc", "dBFS", "dBFS/Hz",
    "ppm", "ppm/°C", "°C",
    "pF", "nF", "µF", "uF",
    "Ω", "ohm",
    "µm", "nm", "um",
    "%", "x",
}
_TIMING_UNITS = {"GHz", "MHz", "kHz", "Hz", "ns", "µs", "us", "ms", "s"}
# v1.6.236 — for #101 field-agent feedback. Sample-rate units belong
# in BOTH the timing band (they are a frequency) AND the L5 analog/
# mixed-signal electrical band (they are an analog signal-path spec).
# Membership in both classes powers the L5-mirror rule below.
_SAMPLE_RATE_UNITS = {"GS/s", "MS/s", "kS/s", "S/s"}


def _preprocess_bullet_line(line: str) -> str:
    """v1.6.238 — for #101 field-agent round-2 feedback. Strip
    AsciiDoc italic markers and collapse `name~sub~` subscript form
    so the bullet KV regex sees a single-token canonical param.
    `* _f~main~_ = 100 MHz`  →  `* f_main = 100 MHz`.
    """
    # Order matters: strip italic FIRST (so the inner `f~main~` is
    # exposed), then collapse subscript.
    line = _RE_ADOC_ITALIC_UNDER.sub(r"\1", line)
    line = _RE_ADOC_ITALIC_STAR.sub(r"\1", line)
    line = _RE_ADOC_SUBSCRIPT.sub(r"\1_\2", line)
    return line


def _param_passes_connective_filter(param: str) -> bool:
    """v1.6.238 — reject param phrases whose tokens include English
    connectives. Real spec params (`Target SNR`, `PSRR target`,
    `Sampling capacitor`) never carry such words; prose lines do
    (`SRET instruction is executed when V`). Filter required because
    relaxing first-char to `[A-Za-z]` widens the false-positive
    surface."""
    for tok in param.split():
        if tok.lower() in _BULLET_KV_PARAM_CONNECTIVES:
            return False
    return True


# v1.6.289 — for #161 ORGANIC. FPGA platform-performance table
# extractor. Multi-vendor IP cores routinely tabulate performance on
# open-source FPGA platforms with multi-column tables shaped like:
#
#     +-----------+--------+-------+-----+
#     | Platform  | Fmax   | LUTs  | FFs |
#     +-----------+--------+-------+-----+
#     | Artix-7   | 162    | 1850  | 920 |
#     +-----------+--------+-------+-----+
#
# Pre-v1.6.289 the inline-token regex (`tFOO = N us`) never matched
# these rows. The helper detects RST grid, Markdown pipe, and
# AsciiDoc cell-block forms, identifies the platform token in column
# one and the Fmax / LUT / FF / ALM / BRAM / DSP value in subsequent
# columns. Each row yields one entry per recognised performance
# column with `extraction_strategy = "platform_perf_table"`.
#
# Chip-AGNOSTIC: pure open-standard FPGA platform vocabulary.
_FPGA_PLATFORM_TOKENS_RE = re.compile(
    r"\b(?P<plat>Artix|Cyclone|ECP5|iCE40|Kintex|Spartan|Stratix|"
    r"Virtex|Zynq)(?:[-\s][0-9A-Za-z]+)?\b",
    re.IGNORECASE,
)
_PERF_CELL_TOKENS_RE = re.compile(
    r"\b(?:Fmax|LUT|LUTs|FF|FFs|ALM|ALMs|LC|LCs|LE|LEs|BRAM|DSP)\b",
    re.IGNORECASE,
)
_PIPE_TABLE_ROW_RE = re.compile(
    r"^[ \t]*\|(?P<cells>[^|\n]+(?:\|[^|\n]+)+)\|[ \t]*$",
    re.MULTILINE,
)

# v1.6.293 — for #171 ORGANIC. Wider FPGA-platform vocabulary used to
# detect the TRANSPOSED list-table / AsciiDoc shape where row 1 is
# the platform axis (one column per platform) instead of the canonical
# row-major shape (one platform per body row). Matches multi-word
# vendor-prefixed forms like "Altera Cyclone10LP" or "AMD Artix-7"
# where the vendor name appears immediately before the platform token.
#
# Chip-AGNOSTIC: only open-standard FPGA / silicon platform vocabulary
# (no chip-class literal).
_RE_FPGA_PLATFORM_TOKEN = re.compile(
    r"\b("
    r"iCE40|ECP5|MachXO|"
    r"Cyclone\s*(?:II|III|IV|V|10\s*LP)?|"
    r"Stratix\s*(?:II|III|IV|V|10)?|"
    r"Spartan(?:-?6|-?7)?|Artix(?:-?7)?|Kintex(?:-?7|-?UltraScale)?|"
    r"Virtex(?:-?[567]|-?UltraScale\+?)?|"
    r"Zynq(?:-?7|-?UltraScale\+?)?|"
    r"PolarFire|Igloo|ProASIC|"
    r"CMOS|FinFET"
    r")\b",
    re.IGNORECASE,
)

# v1.6.293 — for #171 ORGANIC. Value+unit cell extractor for the
# transposed-shape emit path. Matches the leading numeric (with
# optional comma thousands separator and decimal fraction) plus
# the trailing unit token. Cells in the transposed shape look like
# `198 LUT`, `164 FF`, `23,000 transistors`, `200 MHz`. The numeric
# part is captured as group 1, the unit as group 2.
_PERF_VALUE_RE = re.compile(
    r"\b(\d[\d,]*(?:\.\d+)?)\s*"
    r"([A-Za-zµμ][A-Za-z]*)?",
)


def _normalise_perf_column_name(col: str) -> Optional[str]:
    """Return the canonical performance-column slug, or None."""
    c = col.strip().lower()
    if c in ("fmax", "f_max", "frequency"):
        return "fmax"
    if c in ("lut", "luts"):
        return "lut"
    if c in ("ff", "ffs"):
        return "ff"
    if c in ("alm", "alms"):
        return "alm"
    if c in ("lc", "lcs"):
        return "lc"
    if c in ("le", "les"):
        return "le"
    if c == "bram":
        return "bram"
    if c == "dsp":
        return "dsp"
    return None


def _emit_perf_table_rows(
        rows_cells: List[List[str]],
        raw_blob: str) -> List[Dict[str, Any]]:
    """v1.6.291 — for #161 round-2 ORGANIC. Common emitter for any
    table-shape that has been pre-tokenised into a list of rows,
    each row being a list of stripped cell strings. First row is
    the header. Returns the list of typed perf entries.

    Chip-AGNOSTIC: pure structural emission — caller is responsible
    for shape-specific parsing (Markdown pipe / RST list-table /
    AsciiDoc 4-column)."""
    out: List[Dict[str, Any]] = []
    if not rows_cells or len(rows_cells) < 2:
        return out
    header_cells = rows_cells[0]
    perf_cols: List[Tuple[int, str]] = []
    has_perf = False
    for idx, cell in enumerate(header_cells):
        if _PERF_CELL_TOKENS_RE.search(cell):
            slug = _normalise_perf_column_name(cell)
            if slug is not None:
                perf_cols.append((idx, slug))
                has_perf = True
    if not has_perf:
        return out
    for body_cells in rows_cells[1:]:
        if not body_cells:
            continue
        plat_match = None
        for cell in body_cells[: min(3, len(body_cells))]:
            pm = _FPGA_PLATFORM_TOKENS_RE.search(cell)
            if pm:
                plat_match = pm
                break
        if plat_match is None:
            continue
        plat_cell_idx = None
        for i, cell in enumerate(body_cells[: min(3, len(body_cells))]):
            if _FPGA_PLATFORM_TOKENS_RE.search(cell):
                plat_cell_idx = i
                break
        plat_label = (body_cells[plat_cell_idx]
                      if plat_cell_idx is not None
                      else plat_match.group(0))
        plat_label = plat_label.strip(" `*")
        for col_idx, slug in perf_cols:
            if col_idx >= len(body_cells):
                continue
            cell_val = body_cells[col_idx]
            num_match = re.search(r"\d+(?:\.\d+)?", cell_val)
            if not num_match:
                continue
            try:
                num: Any = float(num_match.group(0))
                if num.is_integer():
                    num = int(num)
            except ValueError:
                continue
            unit = "MHz" if slug == "fmax" else "count"
            out.append({
                "name": f"{slug}_{plat_label}",
                "parameter": f"{slug}_{plat_label}",
                "value": num,
                "unit": unit,
                "platform": plat_label,
                "raw": raw_blob.strip()[:160],
            })
    return out


# v1.6.293 — for #171 ORGANIC. Transposed-shape emitter. When the
# header row of a `.. list-table::` directive or AsciiDoc `|===`
# block contains FPGA platform vocabulary (and NO perf-metric vocab),
# the table is arranged column-per-platform: row 1 IS the platform
# axis, and each subsequent row carries one metric cell per platform.
#
# This helper emits one typed perf entry per (header_col, body_cell)
# pair where the body cell carries a numeric value. The caller chooses
# the `extraction_strategy` stamp ("rst_list_table_transposed" or
# "asciidoc_table_transposed") so provenance distinguishes the
# table-shape recogniser that fired.
#
# Chip-AGNOSTIC: purely structural — vocab lives in module-level
# constants, no chip-class literal in this body.
def _emit_perf_table_rows_transposed(
        header_cells: List[str],
        body_rows: List[List[str]],
        raw_blob: str,
        extraction_strategy: str) -> List[Dict[str, Any]]:
    """v1.6.293 — for #171 ORGANIC. Transposed-shape emitter."""
    out: List[Dict[str, Any]] = []
    if not header_cells or not body_rows:
        return out
    n_cols = len(header_cells)
    for row in body_rows:
        if not row:
            continue
        for c_idx, cell in enumerate(row):
            if c_idx >= n_cols:
                continue
            m = _PERF_VALUE_RE.search(cell or "")
            if not m:
                continue
            num_raw = m.group(1) or ""
            unit_tok = (m.group(2) or "").strip()
            try:
                num: Any = float(num_raw.replace(",", ""))
                if num.is_integer():
                    num = int(num)
            except ValueError:
                continue
            plat_label = header_cells[c_idx].strip(" `*")
            # Pick a slug from the unit token when recognisable;
            # otherwise fall back to the raw unit token / "count".
            unit_lower = unit_tok.lower()
            if unit_lower in ("mhz", "khz", "ghz", "hz"):
                # Frequency: canonicalise the unit casing.
                unit_canon = {
                    "mhz": "MHz",
                    "khz": "kHz",
                    "ghz": "GHz",
                    "hz":  "Hz",
                }[unit_lower]
                slug = "fmax"
            elif unit_lower in ("lut", "luts"):
                unit_canon = "count"
                slug = "lut"
            elif unit_lower in ("ff", "ffs"):
                unit_canon = "count"
                slug = "ff"
            elif unit_lower in ("alm", "alms"):
                unit_canon = "count"
                slug = "alm"
            elif unit_lower in ("le", "les"):
                unit_canon = "count"
                slug = "le"
            elif unit_lower in ("lc", "lcs"):
                unit_canon = "count"
                slug = "lc"
            elif unit_lower == "bram":
                unit_canon = "count"
                slug = "bram"
            elif unit_lower == "dsp":
                unit_canon = "count"
                slug = "dsp"
            elif unit_lower in ("transistor", "transistors"):
                unit_canon = "count"
                slug = "transistors"
            elif unit_lower in ("ns", "us", "µs", "μs", "ms", "s"):
                unit_canon = unit_tok  # keep original casing
                slug = "delay"
            else:
                # No recognisable unit token — keep the raw unit
                # (if any) and slug by row index for traceability.
                unit_canon = unit_tok or "count"
                slug = f"metric{c_idx}"
            out.append({
                "name": f"{slug}_{plat_label}",
                "parameter": f"{slug}_{plat_label}",
                "value": num,
                "unit": unit_canon,
                "platform": plat_label,
                "raw": raw_blob.strip()[:160],
                "extraction_strategy": extraction_strategy,
            })
    return out


# v1.6.291 — for #161 round-2 ORGANIC. RST `.. list-table::` directive
# shape recogniser. Match block is the directive header line, optional
# option lines (e.g. `:header-rows: 1`, `:widths: ...`), a blank line,
# then a bullet-tree where each bullet `* - <cell>` opens a row and
# each continuation `  - <cell>` adds a cell. The block ends when an
# outdented non-bullet line / new section heading / new directive is
# seen.
_RE_RST_LIST_TABLE_HEADER = re.compile(
    r"(?m)^[ \t]*\.\.\s+list-table::"
)


def _parse_rst_list_table_perf(text: str) -> List[Dict[str, Any]]:
    """v1.6.291 — for #161 round-2 ORGANIC. Walk RST `.. list-table::`
    directives. Yields one perf entry per detected row × perf column.

    Each list-table is parsed by:
      1. Locate the directive header line.
      2. Consume option lines (`:option: value`) and the blank line.
      3. Then consume bullet rows: each row starts with `   * - <c1>`
         and continuation cells are `     - <cN>`. Lines that begin
         with `* -` open a new row; lines with bare `- ` (at the
         deeper indent) are continuation cells of the current row.
      4. Stop on outdent / non-bullet content / new directive.

    Chip-AGNOSTIC: pure RST grammar — no chip-class literal."""
    out: List[Dict[str, Any]] = []
    if not text:
        return out
    lines = text.split("\n")
    n = len(lines)
    i = 0
    while i < n:
        if not _RE_RST_LIST_TABLE_HEADER.match(lines[i]):
            i += 1
            continue
        start = i
        i += 1
        # Consume option lines: `   :option: value`
        while i < n:
            ln = lines[i]
            if re.match(r"^[ \t]+:\w[\w-]*:", ln):
                i += 1
                continue
            break
        # Consume the (optional) blank line.
        while i < n and not lines[i].strip():
            i += 1
        # Now parse rows. Each row opens with `   * - <cell>` and is
        # followed by zero or more continuation cells `     - <cell>`.
        rows_cells: List[List[str]] = []
        current_row: Optional[List[str]] = None
        while i < n:
            ln = lines[i]
            # Empty line — allow inside a row (RST allows blank
            # between cells); do NOT terminate the table.
            if not ln.strip():
                i += 1
                continue
            # Detect outdent: a non-indented line breaks the block.
            if not ln.startswith((" ", "\t")):
                break
            # Detect a new directive: `.. <name>::`
            if re.match(r"^\s*\.\.\s+\w[\w-]*::", ln):
                break
            # Match row-open: `   * - <cell>`
            m_open = re.match(r"^(\s*)\*\s+-\s*(.*)$", ln)
            if m_open:
                if current_row is not None:
                    rows_cells.append(current_row)
                current_row = [m_open.group(2).strip()]
                i += 1
                continue
            # Match continuation cell: bare `   - <cell>` (deeper indent)
            m_cont = re.match(r"^(\s+)-\s+(.*)$", ln)
            if m_cont and current_row is not None:
                current_row.append(m_cont.group(2).strip())
                i += 1
                continue
            # Match a wrapped-line continuation of the previous cell.
            # Append text to the last cell of the current row.
            if current_row and current_row and ln.strip():
                # Treat as wrapped text only if it's a deeply-indented
                # narrative line (no leading bullet sigils).
                current_row[-1] = (current_row[-1] + " " + ln.strip()).strip()
                i += 1
                continue
            # Unrecognised inside the block — break.
            break
        if current_row is not None:
            rows_cells.append(current_row)
        raw_blob = "\n".join(lines[start: i])

        # v1.6.293 — for #171 ORGANIC. Detect TRANSPOSED shape: the
        # header row carries FPGA platform vocabulary (one column per
        # platform) instead of the canonical perf-metric vocabulary.
        # When platform_hits >= 2 AND perf_metric_hits == 0 in the
        # header, treat row 1 as the platform axis and subsequent
        # rows as per-platform metric cells. Otherwise fall through
        # to the existing row-major emit path (v1.6.291 contract).
        if rows_cells and len(rows_cells) >= 2:
            header_cells = rows_cells[0]
            header_platform_hits = sum(
                1 for c in header_cells
                if _RE_FPGA_PLATFORM_TOKEN.search(c)
            )
            header_perf_metric_hits = sum(
                1 for c in header_cells
                if _PERF_CELL_TOKENS_RE.search(c)
            )
            if (header_platform_hits >= 2
                    and header_perf_metric_hits == 0):
                out.extend(_emit_perf_table_rows_transposed(
                    header_cells,
                    rows_cells[1:],
                    raw_blob,
                    "rst_list_table_transposed",
                ))
                continue  # skip row-major emit for this block

        out.extend(_emit_perf_table_rows(rows_cells, raw_blob))
    return out


def _parse_asciidoc_4col_table_perf(text: str) -> List[Dict[str, Any]]:
    """v1.6.291 — for #161 round-2 ORGANIC. AsciiDoc table block
    recogniser. AsciiDoc tables are delimited by `|===` and cells
    begin with `|` at the line head. A typical 4-column shape:

        |===
        | Platform | Fmax | LUTs | FFs

        | Artix-7 | 200 MHz | 1500 | 600
        | Cyclone | 100 MHz |  900 | 400
        |===

    Cells may be on one line (`| a | b | c | d`) or split across
    lines (one cell per line, each starting with `|`). The header
    is the FIRST non-blank row after the opening delimiter.

    Chip-AGNOSTIC."""
    out: List[Dict[str, Any]] = []
    if not text:
        return out
    lines = text.split("\n")
    n = len(lines)
    i = 0
    while i < n:
        ln = lines[i].strip()
        if ln != "|===":
            i += 1
            continue
        start = i
        i += 1
        # Collect table body until the matching `|===`.
        body_lines: List[str] = []
        while i < n:
            inner = lines[i].rstrip()
            if inner.strip() == "|===":
                break
            body_lines.append(inner)
            i += 1
        if i < n:
            i += 1  # consume closing delimiter
        # Group body_lines into rows. Each row contains one or more
        # cells. A new row starts when we see a `|` cell after a
        # blank line OR when a fully-tokenised single-line row has
        # multiple `|` separators. Approach: split on blank-line
        # groups; within each group, parse cells.
        rows_cells: List[List[str]] = []
        current_group: List[str] = []
        groups: List[List[str]] = []
        for bl in body_lines:
            if not bl.strip():
                if current_group:
                    groups.append(current_group)
                    current_group = []
                continue
            current_group.append(bl)
        if current_group:
            groups.append(current_group)
        for g in groups:
            # If any single line in the group has multiple `|`
            # separators (`| a | b | c | d`), treat each such line as
            # its own row. Otherwise the group of N lines each
            # starting with `|` is ONE row of N cells.
            multi_pipe_rows = [
                ln_ for ln_ in g
                if ln_.count("|") >= 3 and ln_.lstrip().startswith("|")
            ]
            if multi_pipe_rows:
                # Each multi-pipe line is its own row.
                for ln_ in g:
                    if not ln_.lstrip().startswith("|"):
                        continue
                    cells = [c.strip()
                             for c in ln_.lstrip()[1:].split("|")]
                    # Strip trailing empty cell from a trailing `|`.
                    while cells and cells[-1] == "":
                        cells.pop()
                    if cells:
                        rows_cells.append(cells)
            else:
                # One row, cells split across lines.
                row: List[str] = []
                for ln_ in g:
                    s = ln_.lstrip()
                    if not s.startswith("|"):
                        continue
                    cell = s[1:].strip()
                    row.append(cell)
                if row:
                    rows_cells.append(row)
        raw_blob = "\n".join(lines[start: i])

        # v1.6.293 — for #171 ORGANIC. Detect TRANSPOSED AsciiDoc
        # shape: the header row carries FPGA platform vocabulary
        # (one column per platform) instead of the canonical
        # perf-metric vocabulary. Mirrors the RST transpose detector.
        if rows_cells and len(rows_cells) >= 2:
            header_cells = rows_cells[0]
            header_platform_hits = sum(
                1 for c in header_cells
                if _RE_FPGA_PLATFORM_TOKEN.search(c)
            )
            header_perf_metric_hits = sum(
                1 for c in header_cells
                if _PERF_CELL_TOKENS_RE.search(c)
            )
            if (header_platform_hits >= 2
                    and header_perf_metric_hits == 0):
                out.extend(_emit_perf_table_rows_transposed(
                    header_cells,
                    rows_cells[1:],
                    raw_blob,
                    "asciidoc_table_transposed",
                ))
                continue  # skip row-major emit for this block

        out.extend(_emit_perf_table_rows(rows_cells, raw_blob))
    return out


def _extract_platform_perf_table(text: str) -> List[Dict[str, Any]]:
    """v1.6.289 — for #161 ORGANIC. Walk `text` for FPGA-platform
    perf tables. Returns a list of typed entries:

        {name, parameter, value, unit, platform, raw}

    The unit is `MHz` for Fmax columns and `count` for LUT/FF/ALM/etc.
    Chip-AGNOSTIC: open-standard FPGA platform + perf-cell vocabulary.

    v1.6.291 — for #161 round-2 ORGANIC. Extended to recognise two
    additional table shapes that the field-agent flagged on real
    benchmark documents:

      * RST `.. list-table::` directive (with `:header-rows: 1`)
      * AsciiDoc `|===` 4-column table

    Each row of any shape emits one entry per perf column.
    """
    out: List[Dict[str, Any]] = []
    if not isinstance(text, str) or not text:
        return out

    # Shape 1 — Markdown pipe-table (original v1.6.289 path).
    rows = list(_PIPE_TABLE_ROW_RE.finditer(text))
    if rows:
        # Group consecutive rows into table blocks. Two rows belong
        # to the same block iff they are separated by at most a single
        # blank line OR a grid separator line (`+---+---+`).
        blocks: List[List[re.Match]] = []
        current: List[re.Match] = []
        last_end_line = -10
        for m in rows:
            line_no = text[: m.start()].count("\n")
            if line_no - last_end_line > 2 and current:
                blocks.append(current)
                current = []
            current.append(m)
            last_end_line = line_no
        if current:
            blocks.append(current)

        for block in blocks:
            rows_cells: List[List[str]] = []
            for row in block:
                cells = [c.strip()
                         for c in row.group("cells").split("|")]
                rows_cells.append(cells)
            raw_blob = "\n".join(b.group(0) for b in block)
            out.extend(_emit_perf_table_rows(rows_cells, raw_blob))

    # Shape 2 — RST list-table directive.
    out.extend(_parse_rst_list_table_perf(text))

    # Shape 3 — AsciiDoc `|===` 4-column table.
    out.extend(_parse_asciidoc_4col_table_perf(text))

    return out


def _extract_bullet_kv_specs(text: str) -> List[Dict[str, Any]]:
    """Yield normalised bullet-KV spec entries from `text`.

    Each entry: {parameter, value, unit, condition, raw}. Parameter
    is preserved as the original prose phrase (issue #101: NEVER
    drop the parameter name). Empty `unit` is allowed — caller
    routes those to L5.design_parameters.

    v1.6.238 (#101 field-agent round-2): line-level preprocessing
    strips AsciiDoc italic / subscript markers, and the line is
    additionally split on `, ` boundaries that introduce a new
    `param[:=]` pair so multi-KV-on-single-bullet shapes
    (`- Vin: 3.6 V, Vout: 3.3 V, Iload: 2 mA`) emit one entry per
    KV instead of one.
    """
    out: List[Dict[str, Any]] = []
    seen: Set[Tuple[str, str, str]] = set()
    for raw_line in (text or "").splitlines():
        if not raw_line.strip():
            continue
        line = _preprocess_bullet_line(raw_line)
        # Split on multi-KV boundaries. First fragment keeps the
        # leading bullet prefix; later fragments have an implicit
        # bullet (start-of-line) so prepend a `- ` to satisfy the
        # regex anchor.
        fragments = _BULLET_KV_FRAGMENT_SPLIT.split(line)
        for i, frag in enumerate(fragments):
            if not frag:
                continue
            probe = frag if i == 0 else "- " + frag
            m = _RE_BULLET_KV_SPEC.match(probe)
            if not m:
                continue
            param = (m.group("param") or "").strip().rstrip(":=")
            if not param:
                continue
            if param.lower() in _BULLET_KV_PARAM_STOPWORDS:
                continue
            if param.split()[0].lower() in _BULLET_KV_PARAM_STOPWORDS:
                continue
            # v1.6.238 — anti-false-positive: drop param phrases that
            # carry English connectives (kills the SRET-instruction
            # false-positive when first char is lowercase-relaxed).
            if not _param_passes_connective_filter(param):
                continue
            value = (m.group("value") or "").strip()
            unit = (m.group("unit") or "").strip()
            cond = (m.group("cond") or "").strip() or None
            dedup_key = (param, value, unit)
            if dedup_key in seen:
                continue
            seen.add(dedup_key)
            out.append({
                "parameter": param,
                "value": value,
                "unit": unit,
                "condition": cond,
                "raw": probe.strip()[:120],
            })
    return out


def _collect_electrical_specs_for_doc(
        fname: str,
        text: str,
        e_seen: Set[Tuple[str, str, str]],
) -> List[Tuple[Dict[str, Any], Dict[str, str]]]:
    """Yield L1 ``electrical_specs[]`` entries found in ONE input doc.

    Returns ``[(spec_entry, evidence_item), ...]`` in emission order.
    `e_seen` is the caller's cross-document dedup set and is mutated
    in place, exactly as when this loop lived inline in
    ``gen_l1_datasheet``.

    v1.7.80 — for #514. Lifted out of ``gen_l1_datasheet`` so the
    corpus re-derivation and the regression tests can call the real
    emission path instead of re-implementing it. Re-implementing it
    was how the four fabricated ampere entries stayed invisible: the
    only way to see what the emitter produces was to read what it had
    already published.
    """
    out: List[Tuple[Dict[str, Any], Dict[str, str]]] = []
    for m in _ELECTRICAL_SPEC_RE.finditer(text):
        param, val, unit = m.group(1), m.group(2), m.group(3)
        try:
            num = float(val)
        except ValueError:
            continue
        key = (param.upper(), str(num), unit)
        if key in e_seen:
            continue
        e_seen.add(key)
        out.append((
            {
                "name": param.upper(),
                "parameter": param,
                "min_typ_max": {"typ": num},
                "unit": unit,
                "conditions": "VDD=nominal, T=25C unless otherwise stated",
                "evidence": f"input/docs/{fname}",
            },
            {"literal": f"{param}={val}{unit}",
             "label": "electrical spec"},
        ))
    # v1.6.234 — closes #101. Bullet KV-pair spec parser. Captures
    # `<Phrase>: <value> <unit>` lines that the hardcoded VDD/VOH/...
    # list above never matched. Routes only electrical-unit entries
    # to L1.electrical_specs; timing-unit entries go to L2,
    # unitless ones go to L5.design_parameters via gen_l5_adi_spec.
    for entry in _extract_bullet_kv_specs(text):
        unit = entry["unit"]
        # v1.6.236 — for #101 field-agent feedback. L1 now also
        # accepts _SAMPLE_RATE_UNITS (kS/s, MS/s, GS/s) since
        # ADC/DAC sample-rate is an electrical spec, and the
        # `condition` field (singular) is now emitted alongside
        # `conditions` (plural, pre-existing) so layer-mirror
        # consistency check between L1 and L5 passes.
        if (unit not in _ELECTRICAL_UNITS
                and unit not in _SAMPLE_RATE_UNITS):
            continue
        param = entry["parameter"]
        value = entry["value"]
        key = (param.upper(), value, unit)
        if key in e_seen:
            continue
        e_seen.add(key)
        try:
            num: Any = float(value.replace(",", ""))
        except ValueError:
            num = value
        out.append((
            {
                "name": param,
                "parameter": param,
                "min_typ_max": ({"typ": num}
                                if isinstance(num, float) else None),
                "value": value,
                "unit": unit,
                "condition": entry["condition"],
                "conditions": (entry["condition"] or
                               "VDD=nominal, T=25C unless otherwise stated"),
                "evidence": f"input/docs/{fname}",
                "extraction_strategy": "bullet_kv_pair_spec",
            },
            {"literal": entry["raw"],
             "label": "electrical spec (bullet KV)"},
        ))
    return out


# v1.6.9 Fix 4 — schema-level alias normalization map (chip-AGNOSTIC).
#
# Each entry maps a *canonical* token (the name typically emitted into the
# typed L*.json fields by the deterministic generator) to a list of *alias*
# tokens that vendor docs may use interchangeably. When the runner finishes
# all generators it walks every L*.json and, for every typed field whose
# string value contains a canonical token, attaches an `aliases[]` sub-key
# carrying the matching alias literals. This means a hands-on grep for the
# alias literal (e.g. ``RD5K``) finds the alias verbatim inside a typed
# field — counted by ``extraction_coverage_check`` and visible to humans.
#
# This map is INTENTIONALLY EMPTY-EXTENSIBLE: it does not encode any
# specific IC's vocabulary. Entries below are common AID-class /
# half-duplex single-wire / OTP-IP synonyms that recur across multiple
# vendor docs in the open-source IC corpus. Adding a new entry is safe
# because aliases are only attached when the canonical token is already
# present in a typed field — no false positives on chips that don't use
# the same vocabulary.
# v1.6.359 — for #254 P3 ORGANIC. The legacy single global
# `_ALIAS_MAP` injected protocol-class-specific vocabulary onto every
# chip regardless of structural class (the emit gate only checked
# canonical / alias word-boundary presence in extracted text). On
# CPU / DSP / non-bus IPs whose READMEs / docs incidentally use the
# canonical short token + any long-form fragment, the alias is
# emitted as if the chip used the half-duplex protocol vocabulary.
#
# Split into TWO maps:
#
#   * `_ALIAS_MAP_ARCHITECTURAL_V1_6_359` — cross-vendor / open-
#     standard tokens (JTAG, AXI, AHB, APB, AMBA, IIC, I2C, SPI).
#     These are universal architectural primitives that apply to
#     every chip and never need a class predicate. (Initially seeded
#     empty unless a follow-up wave populates them; keeping the
#     constant declared makes the split explicit for future writers.)
#
#   * `_ALIAS_MAP_CLASS_GATED_V1_6_359` — protocol-class / vendor-
#     specific aliases keyed by canonical token, with each entry
#     carrying ``(long_forms_list, required_class_pattern_regex)``.
#     The emit gate compiles the regex once and rejects when the
#     project's L1.class_path does NOT match.
#
# Conservative split rule: every existing `_ALIAS_MAP` entry is moved
# to the class-gated map. The field-agent's #254 specifically flagged
# the half-duplex-protocol class entries (AID-class single-wire OTP
# vocabulary), so those entries get a tightened
# ``half[_-]?duplex[_-]?(protocol|bus|interface)`` regex. Cross-
# vendor entries (DPLUS / DMINUS — USB; LOCK_BIT — generic NVM) get
# permissive ``.*`` to preserve pre-v1.6.359 behaviour.
#
# Class-path resolution: re-use `_v1_6_295_resolve_class_path(project)`
# inside the emit gate. When no class_path is determined, class-gated
# aliases are SAFE-DEFAULT REJECTED (don't emit). Architectural
# aliases always emit regardless of class_path.
#
# Backward compatibility: `_ALIAS_MAP` is preserved as a unified flat
# view (architectural ∪ flat-form of class-gated). Other code that
# iterates `_ALIAS_MAP.keys()` / `_ALIAS_MAP[canon]` (e.g. the inner
# `_walk` typed-field attachment at the per-doc loop) keeps working.
#
# Chip-AGNOSTIC: detection logic uses `class_path` regex match only.
# Class path values are taken from `class_kb/templates` slug
# conventions; no chip-class string literal participates.

_ALIAS_MAP_ARCHITECTURAL_V1_6_359: Dict[str, List[str]] = {
    # Reserved for cross-vendor / open-standard architectural tokens
    # (JTAG / AXI / AHB / APB / AMBA / IIC / I2C / SPI). Empty by
    # default — populate via follow-up backlog when an actual
    # alias-divergence is observed. Keeping the declaration ensures
    # the split is obvious to future maintainers.
}

# Half-duplex single-wire protocol predicate. Matches canonical
# `class_path` strings like:
#   protocol/half_duplex_bus/aid
#   protocol/half-duplex-interface/...
#   protocol/halfduplex_protocol/...
# Chip-AGNOSTIC: structural class-vocabulary regex only.
_V1_6_359_CLASS_PATTERN_HALF_DUPLEX = (
    r"half[_-]?duplex[_-]?(?:protocol|bus|interface)"
)

# Permissive predicate that preserves pre-v1.6.359 behaviour for
# entries that the field-agent did NOT flag as protocol-class-leaky.
_V1_6_359_CLASS_PATTERN_PERMISSIVE = r".*"

_ALIAS_MAP_CLASS_GATED_V1_6_359: Dict[str,
                                       Tuple[List[str], str]] = {
    # 70 / RX-event vocabulary — half-duplex single-wire class.
    "RD_EN":         (["RD5K", "RD_ENB", "CC_RD5K", "CC_5K"],
                      _V1_6_359_CLASS_PATTERN_HALF_DUPLEX),
    "RD5K":          (["RD_EN", "CC_5K"],
                      _V1_6_359_CLASS_PATTERN_HALF_DUPLEX),
    "CC_EN":         (["CC_OUT", "CC_IN", "CC_I", "CC_O"],
                      _V1_6_359_CLASS_PATTERN_HALF_DUPLEX),
    # Test / engineer mode vocabulary — half-duplex class
    "CLK5M":         (["5M_CLK", "5MHz_CLK", "5MHz CLK"],
                      _V1_6_359_CLASS_PATTERN_HALF_DUPLEX),
    "5M_CLK":        (["CLK5M"],
                      _V1_6_359_CLASS_PATTERN_HALF_DUPLEX),
    # EngineerMode pulse / payload literals — half-duplex class
    "WAKE_PULSE":    (["WakePulse", "wake_pulse"],
                      _V1_6_359_CLASS_PATTERN_HALF_DUPLEX),
    "WakePulse":     (["WAKE_PULSE", "wake_pulse"],
                      _V1_6_359_CLASS_PATTERN_HALF_DUPLEX),
    # USB differential pair — cross-vendor; permissive (USB chips
    # may carry any class_path)
    "DPLUS":         (["Dp", "D+"],
                      _V1_6_359_CLASS_PATTERN_PERMISSIVE),
    "DMINUS":        (["Dn", "D-"],
                      _V1_6_359_CLASS_PATTERN_PERMISSIVE),
    # Common bit / percent literals — half-duplex single-wire OTP
    "BIT7":          (["7Bit", "Bit7"],
                      _V1_6_359_CLASS_PATTERN_HALF_DUPLEX),
    "BR_FLAG":       (["BR_Flag"],
                      _V1_6_359_CLASS_PATTERN_HALF_DUPLEX),
    # Datasheet vocabulary (Apple Identification class)
    "AID":           (["Apple ID Bus", "Apple Identification",
                       "AID-class"],
                      _V1_6_359_CLASS_PATTERN_HALF_DUPLEX),
    # OTP / EEPROM lock vocabulary — generic NVM; permissive
    "LOCK_BIT":      (["LockBit", "Lockbit", "lock_bit"],
                      _V1_6_359_CLASS_PATTERN_PERMISSIVE),
    # OTP-program timing parameter vocabulary — half-duplex class
    "VREAD":         (["Vread", "Tvr", "tvr"],
                      _V1_6_359_CLASS_PATTERN_HALF_DUPLEX),
}


def _v1_6_359_alias_map_class_gate(canonical: str,
                                     class_path: Optional[str]) -> bool:
    """v1.6.359 — for #254 P3 ORGANIC. Return True iff the
    class-gated alias entry for ``canonical`` should be emitted given
    the project's ``class_path``.

    Decision matrix:
      * canonical not in class-gated map → True (legacy permissive)
      * class_path is None → False (safe-default reject — without
        class evidence we cannot tell whether the chip carries the
        protocol vocabulary)
      * class_path regex matches → True
      * otherwise → False

    Chip-AGNOSTIC: regex match on canonical class-path slug
    convention only; no chip-class literal participates.
    """
    entry = _ALIAS_MAP_CLASS_GATED_V1_6_359.get(canonical)
    if entry is None:
        return True
    _aliases, pattern_re = entry
    if pattern_re == _V1_6_359_CLASS_PATTERN_PERMISSIVE:
        return True
    if not isinstance(class_path, str) or not class_path.strip():
        # Safe-default reject: no class evidence, do not inject
        # protocol-class-specific vocabulary.
        return False
    try:
        return re.search(pattern_re, class_path,
                          re.IGNORECASE) is not None
    except re.error:
        return False


# v1.6.359 — backward-compatibility unified view. Existing callsites
# iterate `_ALIAS_MAP.keys()` and read `_ALIAS_MAP[canon]` directly
# (per-doc typed-field attachment at the inner `_walk` + the
# `aliases_index` emit loop). Preserve a Dict[str, List[str]] shape
# that flattens the class-gated tuple to its alias list, unioned
# with the architectural map.
_ALIAS_MAP: Dict[str, List[str]] = {
    **_ALIAS_MAP_ARCHITECTURAL_V1_6_359,
    **{canon: list(aliases)
        for canon, (aliases, _pat)
        in _ALIAS_MAP_CLASS_GATED_V1_6_359.items()},
}


# ---------------------------------------------------------------------------
# 1. extract_text_pipeline
# ---------------------------------------------------------------------------
def extract_text_pipeline(project: Path,
                          force: bool = False) -> Dict[str, str]:
    """Convert every doc in input/docs/ (RECURSIVELY) to plain UTF-8
    text under input_doc/. Returns map {filename → extracted_text}.

    v1.6.55 — closes ORGANIC-20260509-phase1-input-format-coverage-gap
    (GitHub issue #3):
      * BUG 1 fix: walk input/docs/ recursively (rglob) instead of
        depth-only (iterdir). Files in subdirectories are no longer
        silently dropped.
      * BUG 2 fix: extract_one() now handles .odt / .rst / .adoc /
        .html / extension-less plain text in addition to the prior
        .pdf / .doc / .docx / .xlsx / .pptx / .txt / .md.
      * Filename collision: subdir paths are encoded into the output
        filename (`spec/foo.pdf` -> `spec__foo.txt`) so two files
        with the same basename in different subdirs do not clobber
        each other.
      * Visibility: emits phase1/extraction_skipped.json listing
        every input file that was visited but produced no text, with
        a reason code, so the agent + downstream gates can audit
        silent drops.
    """
    src_dir = project / "input" / "docs"
    dst_dir = _pl.input_doc_dir(project)
    dst_dir.mkdir(parents=True, exist_ok=True)
    if not src_dir.is_dir():
        return {}

    # Binary / archive extensions we deliberately do not attempt.
    #
    # v1.6.93 — closes GitHub issue #26. Removed `.svg` and `.dia` from
    # this list because both are XML text whose <text>/<title> /
    # <dia:string> labels populate L9.submodules. They are now routed to
    # _extract_svg / _extract_dia in extract_one(). Raster image
    # extensions remain here, but a per-file WARN is now emitted to
    # stderr (and recorded in extraction_skipped.json with a distinct
    # `raster_image_no_ocr` reason code) so silent drops are visible.
    # v1.6.143 (#56) — raster image extensions REMOVED from _SKIP_EXT.
    # `.png` / `.jpg` / etc. are now routed through `_extract_image_ocr`
    # in `extract_one()`. When OCR is unavailable the converter returns
    # empty string and the (already-existing) "empty converter output"
    # path appends to `skipped` with a specific reason from
    # `_image_ocr_skip_reason()` — preserves the visibility v1.6.93
    # introduced for issue #26.
    _SKIP_EXT = (".rar", ".zip", ".tar", ".gz", ".7z",
                 ".exe", ".sof", ".dat", ".dsl",
                 ".gds", ".oas", ".lib")
    _RASTER_EXT = (".jpg", ".jpeg", ".png", ".gif", ".bmp", ".tiff", ".tif")

    out: Dict[str, str] = {}
    skipped: List[Dict[str, str]] = []

    for f in sorted(src_dir.rglob("*")):
        if not f.is_file():
            continue
        suf = f.suffix.lower()
        if suf in _SKIP_EXT:
            # v1.6.93 — issue #26: distinguish raster images (which
            # carry visible information that *could* be OCRed in a
            # future Tier-2 release) from pure binary archives. Raster
            # files emit a WARN to stderr so the user is not surprised
            # by a silent drop; archives stay quiet because nothing in
            # them is human-readable.
            if suf in _RASTER_EXT:
                reason = (
                    f"raster_image_no_ocr — {suf!r} not OCRed by "
                    "phase1 Tier-1; visible labels may be lost")
                print(
                    f"[WARN] phase1 skipped raster image without OCR: "
                    f"{f.relative_to(project)} (Tier 2 OCR deferred)",
                    file=sys.stderr,
                )
            else:
                reason = (f"binary/archive extension {suf!r} — not "
                          "ingested by phase1")
            skipped.append({
                "path": str(f.relative_to(project)),
                "reason": reason,
            })
            continue
        # Encode subdir relative to src_dir into the output filename to
        # avoid collisions between same-basename files in different
        # subdirs. `__` is the separator (POSIX-safe + visible).
        rel = f.relative_to(src_dir)
        if rel.parent == Path("."):
            stem_out = f.stem
        else:
            stem_out = (str(rel.parent).replace("/", "__")
                        + "__" + f.stem)
        # Defensive: cap output filename length so deep nested trees
        # don't hit OS path-length limits.
        if len(stem_out) > 200:
            stem_out = stem_out[:200]
        target = dst_dir / (stem_out + ".txt")
        # Cache short-circuit (unchanged from prior behaviour).
        if not force and target.exists() and target.stat().st_size > 0:
            try:
                out[stem_out + (suf or "")] = target.read_text(
                    encoding="utf-8", errors="ignore")
            except Exception:
                pass
            continue
        text = extract_one(f)
        if not text.strip():
            # v1.6.143 (#56) — raster images carry a specific OCR
            # reason so field-agents can distinguish
            # tesseract-not-installed vs feature-flag-off vs
            # pipeline-empty without re-running. Other extensions
            # keep the generic "converter returned empty" reason.
            if suf in _RASTER_EXT:
                reason = _image_ocr_skip_reason()
                print(
                    f"[WARN] phase1 skipped raster image: "
                    f"{f.relative_to(project)} — {reason}",
                    file=sys.stderr,
                )
            elif suf == ".doc":
                # ORGANIC-20260531-legacy-binary-office-doc-ingestion-depth
                reason = ("legacy binary .doc could not be decoded "
                          "(antiword/catdoc/libreoffice unavailable) — "
                          "raw OLE bytes deliberately NOT ingested")
            elif suf == ".xls":
                # ORGANIC-20260531-legacy-binary-office-doc-ingestion-depth
                reason = ("legacy binary .xls (BIFF) could not be decoded "
                          "(xlrd/libreoffice unavailable) — raw BIFF "
                          "bytes deliberately NOT ingested")
            elif suf:
                reason = f"converter for extension {suf!r} returned empty"
            else:
                reason = ("extension-less file did not look like "
                          "plain text")
            skipped.append({
                "path": str(f.relative_to(project)),
                "reason": reason,
            })
            continue
        try:
            target.write_text(text, encoding="utf-8")
        except Exception as e:
            print(f"[WARN] failed to write {target}: {e}", file=sys.stderr)
            skipped.append({
                "path": str(f.relative_to(project)),
                "reason": f"write_text failed: {e}",
            })
            continue
        # Use the encoded stem + original suffix as the map key so
        # downstream provenance citations are unambiguous.
        out[stem_out + (suf or "")] = text

    # v1.6.446 — for #315 R2 ORGANIC. Physical-distinct, byte-identical
    # README files (common multi-IP / open-source layout: chip-root
    # `README.md` plus a near-identical copy under `input/docs/README.md`)
    # bypass the v1.6.439 canonical-path dedup because `Path.resolve()`
    # returns 2 distinct canonical paths. Add a SHA256 content-hash
    # dedup pool shared by all 3 chip-root ingestion sites
    # (the `__chip_root__/` walker, the `__chip_root_docs__/` doc-tree
    # walker, and the v1.6.343 sub-folder README rglob fallback).
    #
    # Seed the pool from any existing `out` entries (the head-of-function
    # `input/docs/` walker already populated them) so a chip-root README
    # whose content is byte-identical to the input/docs README is also
    # rejected. Empty-content texts are not seeded (defensive: skip
    # empty so two distinct empty files do not collide).
    #
    # Chip-AGNOSTIC: pure SHA256 of UTF-8 text; no chip-class literal
    # participates.
    _v1_6_446_seen_sha256: Set[str] = set()
    for _existing_key in list(out.keys()):
        _txt = out.get(_existing_key) or ""
        if isinstance(_txt, str) and _txt.strip():
            _v1_6_446_seen_sha256.add(
                hashlib.sha256(
                    _txt.encode("utf-8", "ignore")).hexdigest())

    # v1.6.274 — for #140 ORGANIC. Widen README discovery to include
    # chip-root README files (the canonical open-source layout). The
    # phase1 runner previously only scanned `input/docs/`, so any
    # repository whose README sits at the project root was invisible
    # to `find_readme_text` (readme_deep_parser) → class detector →
    # downstream `class_path = None` cascade.
    #
    # Fix — scan a small priority chain of fallback paths AFTER the
    # main input/docs walk. Any README we find here is added to the
    # `out` dict with a `__chip_root__/` prefix so:
    #   * downstream `find_readme_text` sees it as just-another-entry
    #     and matches `readme` in its filename token
    #   * provenance citations (`input/docs/{fname}`) on the legacy
    #     path continue to work unchanged
    #   * the `__chip_root__/` prefix is visible in evidence chains so
    #     gates can audit which README drove classification
    #
    # Chip-AGNOSTIC: pure filesystem-convention paths, no chip-class
    # literal in the lookup.
    _ROOT_README_FALLBACK_DIRS = [
        project,
        project / "doc",
        project / "docs",
        project / "input",
    ]
    _ROOT_README_EXTS = {"", ".md", ".rst", ".adoc", ".txt"}
    # Track lowercase basenames already present in the extracted dict so
    # we don't shadow a real input/docs/README.* with a chip-root one.
    _have_readme = any("readme" in k.lower() for k in out.keys())
    if not _have_readme:
        for d in _ROOT_README_FALLBACK_DIRS:
            if not d.is_dir():
                continue
            for cand in sorted(d.iterdir()):
                if not cand.is_file():
                    continue
                if "readme" not in cand.name.lower():
                    continue
                if cand.suffix.lower() not in _ROOT_README_EXTS:
                    continue
                try:
                    text = cand.read_text(encoding="utf-8", errors="ignore")
                except Exception:
                    continue
                if not text or not text.strip():
                    continue
                # v1.6.446 — for #315 R2: content-hash dedup. Two
                # physically distinct files with byte-identical
                # content collapse to a single ingestion.
                _h = hashlib.sha256(
                    text.encode("utf-8", "ignore")).hexdigest()
                if _h in _v1_6_446_seen_sha256:
                    continue
                _v1_6_446_seen_sha256.add(_h)
                # Marker prefix so evidence chains can audit chip-root
                # provenance separately from input/docs/ provenance.
                key = "__chip_root__/" + cand.name
                out[key] = text
                _have_readme = True
                break
            if _have_readme:
                break

    # v1.6.289 — for #157 ORGANIC. Recursive doc-tree walk. The
    # README-only fallback above misses chips whose authoritative
    # documentation lives in a Sphinx tree (the canonical open-source
    # convention). When `len(out) < 2`, walk the conventional doc-tree
    # directories under the project root and ingest every text-shaped
    # file. Tag with `__chip_root_docs__/` prefix so evidence chains
    # see chip-root-docs provenance separately from input/docs/.
    #
    # Chip-AGNOSTIC: pure filesystem-convention paths.
    _DOC_TREE_DIRS = ["doc", "docs", "doc/source", "docs/source",
                      "Documentation", "documentation"]
    _DOC_TREE_EXTS = {".rst", ".md", ".adoc", ".txt"}
    _DOC_TREE_SKIP_BASENAMES = {
        "LICENSE", "LICENSE.md", "LICENSE.rst", "LICENSE.txt",
        "CONTRIBUTING", "CONTRIBUTING.md", "CONTRIBUTING.rst",
        "CHANGELOG", "CHANGELOG.md", "CHANGELOG.rst",
        "AUTHORS", "AUTHORS.md", "COPYING",
    }
    if len(out) < 2:
        for rel in _DOC_TREE_DIRS:
            d = project / rel
            if not d.is_dir():
                continue
            for cand in sorted(d.rglob("*")):
                if not cand.is_file():
                    continue
                if cand.suffix.lower() not in _DOC_TREE_EXTS:
                    continue
                # Skip obvious legal / contributing / changelog noise.
                stem = cand.stem
                base = cand.name
                if (stem in _DOC_TREE_SKIP_BASENAMES
                        or base in _DOC_TREE_SKIP_BASENAMES):
                    continue
                try:
                    text = cand.read_text(
                        encoding="utf-8", errors="ignore")
                except Exception:
                    continue
                if not text or not text.strip():
                    continue
                # v1.6.446 — for #315 R2: content-hash dedup. Two
                # physically distinct files with byte-identical
                # content collapse to a single ingestion.
                _h = hashlib.sha256(
                    text.encode("utf-8", "ignore")).hexdigest()
                if _h in _v1_6_446_seen_sha256:
                    continue
                _v1_6_446_seen_sha256.add(_h)
                # Use relative path under the doc-tree root so a tree
                # like doc/source/chapter1.rst keeps the structure.
                rel_path = cand.relative_to(project).as_posix()
                key = "__chip_root_docs__/" + rel_path
                out[key] = text

        # v1.6.343 — for #240 P2. Sub-folder README rglob fallback.
        # Many open-source HDL repos organise docs by feature
        # sub-folder (rtl/README.md, sim/README.md,
        # boards/<board>/README.md) rather than under a central doc/
        # tree. If NONE of the whitelisted _DOC_TREE_DIRS exist OR all
        # enumerated dirs were empty (out still <2 after the loop),
        # do a bounded rglob("README*") scan from the project root to
        # pick up sub-folder READMEs. Depth-capped at 4 segments and
        # file-capped at 30 entries to avoid pathological repos /
        # vendored trees. Tag each entry with extraction_strategy
        # "rglob_readme_fallback_v1_6_343" via key prefix so post-pass
        # gates can trace provenance. Chip-AGNOSTIC: pure
        # filesystem-convention paths; no chip-class literal.
        #
        # v1.6.439 — for #315 P2 ORGANIC. Dedup by canonical resolved
        # path. Pre-v1.6.439 the same physical README could land in
        # `out` under both `input/docs/README.md` (head-of-function
        # walker) AND `__chip_root_docs__/input/docs/README.md`
        # (this rglob fallback) AND, on a re-run,
        # `__chip_root_docs__/phase1/input_doc/README.txt`
        # (the runner's own previous extraction output ingested as
        # input). Each alias path emitted its own evidence row,
        # yielding ~3x duplicate L doc rows. The fix walks each
        # candidate's `.resolve()` against a `seen_canonical` set so
        # the same disk file gets ingested at most once.
        _v1_6_439_seen_canonical: Set[Path] = set()
        # Seed with the canonical paths of every file already ingested
        # at the head of the function (these are real input/docs paths).
        for _existing_key in list(out.keys()):
            if _existing_key.startswith("__chip_root_docs__/"):
                _rel = _existing_key[len("__chip_root_docs__/"):]
            elif _existing_key.startswith("__chip_root__/"):
                _rel = _existing_key[len("__chip_root__/"):]
            else:
                _rel = _existing_key
            try:
                _v1_6_439_seen_canonical.add(
                    (project / _rel).resolve())
            except Exception:
                pass
        _v1_6_343_did_fallback = False
        if len(out) < 2:
            _v1_6_343_any_doc_dir = any(
                (project / d).is_dir() for d in _DOC_TREE_DIRS
            )
            _v1_6_343_skip_segments = (set(_DOC_TREE_SKIP_BASENAMES)
                                       | {"node_modules", "build",
                                          "dist", ".git", "vendor",
                                          ".github", ".vscode",
                                          "__pycache__",
                                          # v1.6.439 — for #315 P2 ORGANIC.
                                          # Never re-ingest the runner's own
                                          # output. Pre-v1.6.439 the rglob
                                          # fallback walked
                                          # `phase1/input_doc/__chip_root_*.txt`
                                          # (its own previous pass output)
                                          # as input, yielding ~3x duplicate
                                          # L doc entries per README.
                                          "phase1",
                                          # v0.2.14 — never scoop DOWNSTREAM
                                          # build output back into phase1. A
                                          # full doc->GDS run leaves
                                          # phase3/stage4/foundry_handoff/README
                                          # (+ phase2 RTL/report trees); the
                                          # README rglob below (depth<=4) was
                                          # ingesting them and citing them in
                                          # L1, which the RTL-as-oracle leak
                                          # guard then correctly FAILed at
                                          # [14b/15] — halting phase1 before the
                                          # [14e2b] auto-dispatch on any project
                                          # previously taken to GDS. phase1
                                          # reads INPUT docs only.
                                          "phase2", "phase3", "reports",
                                          "extracted_docs"})
            # ORGANIC — the ingester must never read its OWN documentation as
            # the design's specification. The skip set above excludes the
            # runner's own OUTPUT (phase1/phase2/phase3/reports); nothing
            # excluded the runner's own SOURCE. When the plugin is checked out
            # INSIDE the run root (run root holds `input/` and a plugin
            # checkout side by side — a normal deployment) this rglob walked
            # the plugin tree and ingested 9 plugin READMEs as design input:
            # 97.2% of the corpus by bytes on a run whose real input was ONE
            # natural-language request. L1 then described the TOOL (a pin named
            # `Verb` from a docs table of verbs; the plugin README's vendor and
            # process node), and ic_class was decided from that text — the
            # crypto detector matched the literal `SHA` in the plugin's
            # artifact-ATTESTATION section, classifying the design
            # `crypto_accelerator`, whose registry declares rtl_gen=null, so
            # RTL was WAIVED and Phase-2 FAILed with `rtl/ missing`.
            # Identified by STRUCTURE (plugin manifest / programs+flow+skills
            # triple), never by directory name. See _input_corpus_scope.py.
            _tooling_roots = []
            _tooling_excluded: List[str] = []
            _staged_pdk_excluded: List[str] = []
            try:
                if str(Path(__file__).resolve().parent) not in sys.path:
                    sys.path.insert(
                        0, str(Path(__file__).resolve().parent))
                import _input_corpus_scope as _ics
                _tooling_roots = _ics.find_tooling_roots(project)
            except Exception:
                # DEGRADE LOUDLY: recorded as NOT_RUN below, never silently
                # treated as "no tooling present".
                _ics = None  # type: ignore[assignment]
            if not _v1_6_343_any_doc_dir:
                _v1_6_343_cap = 30
                _v1_6_343_count = 0
                try:
                    _v1_6_343_iter = sorted(
                        project.rglob("README*"))
                except Exception:
                    _v1_6_343_iter = []
                for readme in _v1_6_343_iter:
                    if _v1_6_343_count >= _v1_6_343_cap:
                        break
                    if not readme.is_file():
                        continue
                    try:
                        rel = readme.relative_to(project)
                    except ValueError:
                        continue
                    # Depth cap: README at <root>/<sub>/README.md
                    # has 2 parts, <root>/<sub>/<board>/README.md
                    # has 3 — accept up to 4 to permit one extra
                    # nested layer (boards/<board>/<rev>/README.md).
                    if len(rel.parts) > 4:
                        continue
                    if any(seg in _v1_6_343_skip_segments
                           for seg in rel.parts):
                        continue
                    # Issue #1996 — `input/pdk*` is a declared process-kit
                    # input, not a design-document tree.  Dedicated Phase-1
                    # readers consume its enablement and labelled declaration;
                    # the generic README fallback must not reinterpret the
                    # PDK's own manual as the chip specification.
                    if _ics is not None:
                        _pdk_root = _ics.staged_pdk_root(rel.as_posix())
                        if _pdk_root is not None:
                            _staged_pdk_excluded.append(rel.as_posix())
                            continue
                    # ORGANIC — tooling subtree: the plugin's own checkout is
                    # not design input. Recorded, never dropped silently.
                    if _tooling_roots and _ics is not None:
                        _hit = _ics.path_is_tooling(rel.as_posix(),
                                                    _tooling_roots)
                        if _hit is not None:
                            _tooling_excluded.append(rel.as_posix())
                            continue
                    if readme.suffix.lower() not in {
                            ".md", ".rst", ".txt", ".adoc",
                            ".asciidoc"}:
                        continue
                    # Skip the project-root README — the
                    # __chip_root__/ fallback at the head of this
                    # function already collects it.
                    if len(rel.parts) == 1:
                        continue
                    if (readme.stem in _DOC_TREE_SKIP_BASENAMES
                            or readme.name
                            in _DOC_TREE_SKIP_BASENAMES):
                        continue
                    # v1.6.439 — for #315 P2 ORGANIC. Skip
                    # phase1/input_doc/ subtree (the runner's
                    # own output, would re-ingest 3rd time).
                    if any(seg == "phase1"
                           for seg in rel.parts):
                        continue
                    # v1.6.439 — for #315 P2 ORGANIC. Canonical-path
                    # dedup: skip if this same disk file was already
                    # ingested under a different alias key.
                    try:
                        _canonical = readme.resolve()
                    except Exception:
                        _canonical = None
                    if _canonical is not None and (
                            _canonical in _v1_6_439_seen_canonical):
                        continue
                    try:
                        text = readme.read_text(
                            encoding="utf-8", errors="replace")
                    except OSError:
                        continue
                    if not text or not text.strip():
                        continue
                    # v1.6.446 — for #315 R2: content-hash dedup. Two
                    # physically distinct files with byte-identical
                    # content collapse to a single ingestion. Closes
                    # the canonical-path gap when two real files have
                    # identical bytes (common in multi-IP / chip-root
                    # vs input/docs/ layouts).
                    _h = hashlib.sha256(
                        text.encode("utf-8", "ignore")).hexdigest()
                    if _h in _v1_6_446_seen_sha256:
                        continue
                    _v1_6_446_seen_sha256.add(_h)
                    key = ("__chip_root_docs__/"
                           + rel.as_posix())
                    if key in out:
                        continue
                    out[key] = text
                    if _canonical is not None:
                        _v1_6_439_seen_canonical.add(_canonical)
                    _v1_6_343_count += 1
                    _v1_6_343_did_fallback = True
        # Trace surface: if the fallback fired, leave a sentinel
        # __chip_root_docs__/__rglob_readme_fallback_v1_6_343__.tag
        # entry so any post-pass diagnostic can see the strategy
        # ("rglob_readme_fallback_v1_6_343") was taken on this run.
        if _v1_6_343_did_fallback:
            out["__chip_root_docs__/"
                "__rglob_readme_fallback_v1_6_343__.tag"] = (
                "extraction_strategy: "
                "rglob_readme_fallback_v1_6_343\n"
            )
        # ORGANIC — DEGRADE LOUDLY (flow-change-acceptance §6). Excluding input
        # is an action with consequences, so it is never silent. `status=RAN`
        # with an empty excluded_roots positively means "no tooling subtree
        # present"; `NOT_RUN` means the rule never applied. The two are never
        # conflated into "nothing was excluded".
        try:
            if _ics is not None:
                _scope = _ics.scope_record(
                    project, _tooling_roots, _tooling_excluded, status="RAN",
                    excluded_staged_pdk_files=_staged_pdk_excluded)
            else:
                _scope = {"_schema_version": "1", "status": "NOT_RUN",
                          "rule": "programs/_input_corpus_scope.py",
                          "_comment": ("the input-corpus scope rule could not "
                                       "be loaded; tooling and staged-PDK "
                                       "subtrees were NOT excluded on this "
                                       "run"),
                          "excluded_roots": [], "excluded_files": [],
                          "excluded_file_count": 0,
                          "excluded_staged_pdk_roots": [],
                          "excluded_staged_pdk_files": [],
                          "excluded_staged_pdk_file_count": 0}
            _scope_p = project / "phase1" / "input_corpus_scope.json"
            _scope_p.parent.mkdir(parents=True, exist_ok=True)
            _scope_p.write_text(json.dumps(_scope, indent=2) + "\n",
                                encoding="utf-8")
            if _tooling_excluded:
                print(f"      input_corpus_scope: excluded "
                      f"{len(_tooling_excluded)} tooling document(s) from "
                      f"{len(_tooling_roots)} tooling subtree(s) — the "
                      f"plugin's own checkout is not design input "
                      f"(→ phase1/input_corpus_scope.json)")
            if _staged_pdk_excluded:
                print(f"      input_corpus_scope: excluded "
                      f"{len(_staged_pdk_excluded)} staged-PDK document(s) "
                      f"from the design-input walk — input/pdk* has its own "
                      f"typed readers (→ phase1/input_corpus_scope.json)")
        except Exception:
            pass

    # v1.6.291 — for #166 + #168 round-2 ORGANIC (Option A).
    # Persist every `__chip_root_docs__/<rel_path>` in-memory entry
    # to disk under `input_doc/__chip_root_<sanitized>.txt` so
    # downstream post-emit consumers that re-read from disk
    # (`_load_extracted_docs_for_post_pass`,
    # `_post_emit_secondary_clock_domains_from_docs`, etc.) and the
    # README-text + chip-root-doc concat path used by
    # `_post_emit_ic_class_into_L9_L1` for L9.interface_types
    # automatically see chip-root doc content.
    #
    # The on-disk filename uses a clear sentinel prefix
    # (`__chip_root_`) so filename heuristics that ignore chip-root
    # content can still filter them out. Path separators (`/`, `\`)
    # in the original `rel_path` are replaced with `__` to keep the
    # filename POSIX-safe.
    #
    # Chip-AGNOSTIC: pure filesystem-convention.
    #
    # v1.6.295 — for #187 ORGANIC. Extend the walk to ALSO include the
    # `__chip_root__/` prefix (the project-root README files added by
    # the v1.6.274 fallback walker at the head of this function).
    # Pre-v1.6.295 the persistence loop walked only the
    # `__chip_root_docs__/` prefix, so the chip-root README content
    # stayed in-memory only and any downstream pass that re-reads
    # input_doc/ from disk (the post-pass gates, L doc
    # completeness reviewers, re-runs of L emitters after partial
    # runs) was blind to the chip-root README. Now both prefixes
    # land on disk under the canonical `__chip_root_<sanitised>.txt`
    # filename pattern so the v1.6.291 consumer
    # `_read_chip_root_docs_concat` automatically sees them.
    # Chip-AGNOSTIC: pure filesystem-convention.
    for chip_key, chip_text in list(out.items()):
        if not (chip_key.startswith("__chip_root_docs__/")
                or chip_key.startswith("__chip_root__/")):
            continue
        if chip_key.startswith("__chip_root_docs__/"):
            rel_inner = chip_key[len("__chip_root_docs__/"):]
        else:
            rel_inner = chip_key[len("__chip_root__/"):]
        sanitised = (rel_inner.replace("/", "__")
                     .replace("\\", "__"))
        # Cap filename length defensively (filesystem limits).
        if len(sanitised) > 200:
            sanitised = sanitised[:200]
        # Strip the original extension off `sanitised` so the on-disk
        # file uniformly carries `.txt` (consistent with the rest of
        # input_doc/). Use Path.stem to drop the last suffix.
        sanitised_stem = Path(sanitised).stem
        if len(sanitised_stem) > 200:
            sanitised_stem = sanitised_stem[:200]
        disk_name = "__chip_root_" + sanitised_stem + ".txt"
        target = dst_dir / disk_name
        try:
            target.write_text(chip_text, encoding="utf-8")
        except Exception as e:
            print(f"[WARN] failed to persist chip-root doc "
                  f"{chip_key!r} → {target}: {e}",
                  file=sys.stderr)
            continue

    # Emit the skip log. Empty list = clean run; non-empty = audit
    # surface for what was visited but not extracted.
    # #497: stamp the per-design identity so an honestly-empty skip log
    # (the common clean-run shape) DIFFERS per design and is not flagged
    # as a canned cross-design report. At Step 1 only the project name is
    # known (L docs are generated later); that already differs per design.
    skip_log_payload = json.dumps({
        "_schema_version": "1",
        "_comment": (
            "Files under input/docs/ that the phase1 ingestor visited "
            "but produced no text. Empty list means every input "
            "rendered. Non-empty entries indicate either deliberate "
            "skip (binary/archive/raster) or converter gap — investigate."),
        "design_identity": _design_identity_fields(project),
        "skipped": skipped,
        "total_visited": len(out) + len(skipped),
        "total_extracted": len(out),
    }, indent=2, ensure_ascii=False) + "\n"
    # Legacy path (kept for backward compatibility with existing gates).
    skip_log_dir = project / "phase1"
    skip_log_dir.mkdir(parents=True, exist_ok=True)
    (skip_log_dir / "extraction_skipped.json").write_text(skip_log_payload)
    # v1.6.93 — issue #26: also emit under reports/phase1/ so the
    # raster-image WARN surface lives next to the other phase1 reports.
    reports_dir = project / "reports" / "phase1"
    reports_dir.mkdir(parents=True, exist_ok=True)
    (reports_dir / "extraction_skipped.json").write_text(skip_log_payload)
    # v1.6.600 — for #402 R2. The v1.6.594 fix applied the badge strip
    # only inside `_extract_markdown_pipe_tables`. Real-benchmark
    # verification (v3 caravel pilot, 3 shields.io badges in index.md
    # line 3) showed phase1 still hung in a post-emit hook AFTER all
    # 14 L*.json were emitted — i.e. a different downstream walker that
    # also reads `extracted[fname]` and back-tracks on the same nested
    # bracket structure. Applying the strip once at the extraction-
    # pipeline RETURN site makes every downstream consumer (the 30+
    # post-emit hooks between [14b/15] and [15/15]) see pre-stripped
    # text, so no individual walker has to defend against badge URLs.
    # Chip-AGNOSTIC: pure surface-Markdown grammar; deny-list contains
    # no chip-class literal.
    for _k, _v in list(out.items()):
        if isinstance(_v, str) and _v:
            out[_k] = _v1_6_594_strip_markdown_badges(_v)
    return out


def _scan(extracted: Dict[str, str], pattern: re.Pattern,
          file_filter: Optional[re.Pattern] = None) -> List[Tuple[str, re.Match]]:
    """Run `pattern` across all extracted texts; return list of (fname, match)."""
    hits: List[Tuple[str, re.Match]] = []
    for fname, text in extracted.items():
        if file_filter and not file_filter.search(fname):
            continue
        for m in pattern.finditer(text):
            hits.append((fname, m))
    return hits


# ---------------------------------------------------------------------------
# v1.6.78 — closes GitHub issue #11. FLAG-EVIDENCE CONSISTENCY RULE.
#
# Each layer's `no_X_in_input` flag should be True only when there is
# NO source-document evidence of X-topic content. The flag must NOT be
# set just because the structured extractor produced an empty list —
# the input may carry the content in a form the extractor cannot parse
# (free-form prose, narrative, scanned PDF), and the flag would then
# disagree with the same layer's `extraction_evidence` map.
#
# The L7 contradiction reported in #11 ("test_modes: [] +
# no_test_modes_in_input: true while extraction_evidence still lists
# EngineerMode.txt / TestMode<docname>.txt as sources") is the
# canonical anti-pattern; the same shape exists across L1..L13.
# Helper falls back to the v1.6.77 length-based check when the
# evidence map is empty/None — preserves prior behaviour on projects
# with no evidence bookkeeping.
# ---------------------------------------------------------------------------
_TOPIC_FILENAME_PATTERNS = {
    "pin_table":          re.compile(r"(?i)pin[\s_-]?(?:list|out|table|map|assignment)|pinmux"),
    "protocol_overview":  re.compile(r"(?i)protocol|interface|bus|signaling|frame|wake|cmd[\s_-]?protocol"),
    "crc_parameters":     re.compile(r"(?i)crc|checksum|parity|frame[\s_-]?check"),
    "registers":          re.compile(r"(?i)register|reg[\s_-]?map|reg[\s_-]?table|memory[\s_-]?map|\bcsr\b"),
    "analog":             re.compile(r"(?i)analog|\badi\b|\badc\b|\bdac\b|\bldo\b|bandgap|\bpll\b|\bvco\b|\bref\b|comparator|opamp|bias|amp"),
    "fsm":                re.compile(r"(?i)\bfsm\b|state[\s_-]?machine|state[\s_-]?diagram|control[\s_-]?logic"),
    "test_modes":         re.compile(r"(?i)test[\s_-]?mode|engineer[\s_-]?mode|debug[\s_-]?mode|production[\s_-]?test|functional[\s_-]?mode"),
    "timing_constants":   re.compile(r"(?i)timing|signal[\s_-]?format|tx[\s_-]?rx|waveform|signal[\s_-]?spec"),
    "integration":        re.compile(r"(?i)integration|top[\s_-]?level|hierarchy|block[\s_-]?diagram"),
    "test_cases":         re.compile(r"(?i)test[\s_-]?case|test[\s_-]?plan|\batpg\b|coverage"),
    "otp_layout":         re.compile(r"(?i)otp|fuse|\bemem\b|one[\s_-]?time[\s_-]?programmable|efuse"),
    "behavioral_sequences": re.compile(r"(?i)sequence|flow|behavior|scenario|use[\s_-]?case"),
    "lab_calibration":    re.compile(r"(?i)calibration|trim|lab[\s_-]?cal|cal[\s_-]?procedure|adjust"),
    # v1.6.79 — closes issue #12. New topic regexes for the 17 sibling
    # sub-fields previously emitting hardcoded AID-class scaffolds.
    "verdict_byte":       re.compile(r"(?i)verdict|status[\s_-]?byte"),
    "payload_semantics":  re.compile(r"(?i)payload|response[\s_-]?(?:format|template)"),
    "debug_observability": re.compile(r"(?i)debug[\s_-]?(?:pin|signal|port)|observability"),
    "verification_strategy": re.compile(r"(?i)verification|validation|qualification"),
    "engineer_mode_unlock": re.compile(r"(?i)engineer[\s_-]?mode|unlock[\s_-]?seq"),
    "rx_classifier_ticks": re.compile(r"(?i)rx[\s_-]?classifier|bit[\s_-]?cell|tick"),
    "clock_mhz":          re.compile(r"(?i)clock|frequency|freq|mhz"),
    "clock_domains":      re.compile(r"(?i)clock|domain|cdc"),
    "top_module":         re.compile(r"(?i)integration|hierarchy|top[\s_-]?level"),
    "submodules":         re.compile(r"(?i)integration|hierarchy|top[\s_-]?level|submodule|module[\s_-]?list"),
    "internal_wires":     re.compile(r"(?i)integration|hierarchy|top[\s_-]?level|wire|netlist"),
    "calibration_steps":  re.compile(r"(?i)calibration|lab|rig|trim"),
    "lab_equipment":      re.compile(r"(?i)calibration|lab|rig|trim|equipment"),
    "rig_pin_assignments": re.compile(r"(?i)calibration|lab|rig|trim|pin[\s_-]?assignment"),
    "l13_test_cases":     re.compile(r"(?i)calibration|lab|rig|trim|test[\s_-]?case"),
}


def _flag_no_X_in_input(structured_list_or_dict: Any,
                         evidence_map: Optional[Dict[str, Any]],
                         topic_key: str) -> bool:
    """Issue #11 consistency rule. Returns True only when:
      (a) the structured field is empty/None/missing, AND
      (b) the evidence_map contains NO source whose filename matches
          the topic regex.
    Either condition broken → returns False.

    Falls back to the simple len()-style check when evidence_map is
    None/empty or the topic_key is unknown — preserves v1.6.77
    behaviour on projects with no evidence bookkeeping.

    v1.6.81 — closes issue #12 follow-up. Defensive guarantee: returns
    a hard `bool` even on weird input. Field-agent reported
    `L8.no_timing_constants_in_input` showing as `null` instead of
    `True`/`False` on rich-input projects. Ensure the helper never
    leaks a non-bool sentinel.
    """
    has_structured = bool(structured_list_or_dict)
    if has_structured:
        return False
    pat = _TOPIC_FILENAME_PATTERNS.get(topic_key)
    if pat and evidence_map:
        for src_path in evidence_map:
            if pat.search(str(src_path)):
                return False
    return True


def _ensure_bool_flags(content: Dict[str, Any]) -> Dict[str, Any]:
    """v1.6.81 — closes issue #12 follow-up.

    Walks every key in ``content`` whose name starts with ``no_`` and
    ends with ``_in_input`` and coerces the value to a hard ``bool``
    (True/False). Catches every code path that may inadvertently leave
    a flag as ``None``, missing, or a truthy/falsy non-bool.

    Coercion rules (chip-AGNOSTIC):
      * already-bool → unchanged
      * None / missing → True (no-evidence fallback; matches the
                                 ``_flag_no_X_in_input`` empty-input path)
      * any other → ``bool(value)``

    Field agent's v1.6.79 verification observed
    ``L8.no_timing_constants_in_input: null`` on both thin- AND rich-input
    projects — that's a process bug regardless of which path produced it.
    This helper makes the bool guarantee structural so future regressions
    can never re-introduce ``null``.
    """
    if not isinstance(content, dict):
        return content
    for k in list(content.keys()):
        if k.startswith("no_") and k.endswith("_in_input"):
            v = content[k]
            if v is None:
                content[k] = True
            elif not isinstance(v, bool):
                content[k] = bool(v)
    return content


# ---------------------------------------------------------------------------
# 2-14. L1-L23 generators (each emits a JSON file with extraction_evidence)
# ---------------------------------------------------------------------------
@dataclass
class LDocResult:
    name: str
    path: Path
    todo_count: int = 0
    evidence_count: int = 0


def _sanitize_evidence_skip_null_literals(
    evidence: Dict[str, List[Dict[str, Any]]]
) -> Dict[str, List[Dict[str, Any]]]:
    """v1.6.96 (issue #28 Bug 2) — skip evidence entries whose
    ``literal`` is None.

    The extraction_evidence_schema_check requires
    ``isinstance(entry["literal"], str)``. Some emitter paths
    occasionally produced ``literal: None`` (regex group(0) returning
    None on no match, f-string consuming a None upstream value, etc.),
    which then FAILed the schema gate. Skipping the entry — rather
    than coercing to "" — is preferred: an entry with no literal
    isn't actually evidence. Chip-AGNOSTIC.
    """
    if not isinstance(evidence, dict):
        return evidence
    cleaned: Dict[str, List[Dict[str, Any]]] = {}
    for k, entries in evidence.items():
        if not isinstance(entries, list):
            cleaned[k] = entries
            continue
        kept: List[Dict[str, Any]] = []
        for e in entries:
            if isinstance(e, dict):
                if "literal" in e and not isinstance(e.get("literal"), str):
                    # literal is present but non-string (None, int, list,
                    # etc.) — skip the entry entirely.
                    continue
            kept.append(e)
        cleaned[k] = kept
    return cleaned


def _v1_6_367_strip_sentinel_keys(
    evidence: Dict[str, List[Dict[str, str]]]
) -> Tuple[Dict[str, List[Dict[str, str]]], int]:
    """v1.6.367 — for #262 P3 ORGANIC (follow-on to #256).

    v1.6.361 filtered runner-internal sentinel tag filenames (e.g.
    `__rglob_readme_fallback_v1_6_343__.tag`) only at the L1
    description picker. Other L*-level emitters still routed
    sentinel-tag entries into `extraction_evidence`, so the leak
    surfaced in L1/L2/L3/L5/L6/L8 alike. Apply the v1.6.361 filter
    at the `_write_l_doc` chokepoint so every L generator benefits.

    Returns ``(filtered_dict, count_skipped)``.

    Chip-AGNOSTIC: pattern is `__<name>_v\\d+_\\d+_\\d+__.*\\.tag`,
    a runner-internal convention.
    """
    if not isinstance(evidence, dict):
        return evidence, 0
    filtered: Dict[str, List[Dict[str, str]]] = {}
    skipped = 0
    for k, v in evidence.items():
        base = str(k).rsplit("/", 1)[-1]
        if _v1_6_361_is_sentinel_tag_filename(base):
            skipped += 1
            continue
        filtered[k] = v
    return filtered, skipped


def _source_documents_from_extracted(
        project: Path, extracted: Dict[str, str]) -> List[str]:
    """Project-relative source paths scanned by one Phase-1 emitter.

    The five L9-L13 emitters can legitimately emit an absence declaration,
    leaving their match-only ``extraction_evidence`` empty even though they
    scanned the complete input corpus to reach that conclusion.  Preserve that
    scan provenance without fabricating a match.  Internal fallback sentinels
    are not documents and are excluded at the same structural boundary used by
    the extraction-evidence writer.
    """
    # The extractor encodes a recursive input path into its dictionary key
    # (``subdir/spec.md`` -> ``subdir__spec.md``) so its scratch filenames
    # cannot collide.  Rebuild that deterministic key map here and cite the
    # real source path rather than the encoded scratch name.
    encoded_input_paths: Dict[str, Set[str]] = {}
    input_docs = project / "input" / "docs"
    if input_docs.is_dir():
        try:
            input_files = sorted(input_docs.rglob("*"))
        except OSError:
            input_files = []
        for path in input_files:
            if not path.is_file():
                continue
            try:
                input_rel = path.relative_to(input_docs)
            except ValueError:
                continue
            if input_rel.parent == Path("."):
                encoded_stem = path.stem
            else:
                encoded_stem = (input_rel.parent.as_posix().replace("/", "__")
                                + "__" + path.stem)
            encoded_stem = encoded_stem[:200]
            key = encoded_stem + path.suffix.lower()
            encoded_input_paths.setdefault(key, set()).add(
                f"input/docs/{input_rel.as_posix()}")

    out: Set[str] = set()
    for raw_name, text in (extracted or {}).items():
        if not isinstance(raw_name, str):
            continue
        if not isinstance(text, str) or not text.strip():
            continue
        base = raw_name.rsplit("/", 1)[-1]
        if _v1_6_361_is_sentinel_tag_filename(base):
            continue
        if raw_name.startswith("__chip_root_docs__/"):
            rel = raw_name[len("__chip_root_docs__/"):]
        elif raw_name.startswith("__chip_root__/"):
            rel = raw_name[len("__chip_root__/"):]
        elif raw_name.startswith("input/docs/"):
            rel = raw_name
        else:
            mapped = encoded_input_paths.get(raw_name)
            if mapped:
                out.update(mapped)
                continue
            rel = f"input/docs/{raw_name}"
        if rel:
            out.add(rel)
    return sorted(out)


def _write_l_doc(project: Path, name: str, content: dict,
                 evidence: Dict[str, List[Dict[str, str]]],
                 source_documents: Optional[List[str]] = None,
                 ) -> LDocResult:
    """Write content + extraction_evidence to generated_docs/{name}.json."""
    # v1.6.96 (issue #28 Bug 2) — defensive sanitiser for null-literal
    # entries. Runs as a single chokepoint so every L emitter benefits.
    evidence = _sanitize_evidence_skip_null_literals(evidence)
    # v1.6.367 — for #262 P3 ORGANIC (follow-on to #256). Structural
    # sentinel-tag strip at the extraction_evidence chokepoint. The
    # v1.6.361 filter only applied to the L1 description picker;
    # other L*-level emitters still leaked sentinel-tag filenames.
    # Apply the strip here so every L generator benefits.
    evidence, _v1_6_367_sentinel_skipped = _v1_6_367_strip_sentinel_keys(
        evidence)
    content["extraction_evidence"] = evidence
    # v1.12.65 — RECORD WHERE THE LAYER CAME FROM, AT THE ONE PLACE EVERY
    # LAYER PASSES THROUGH.
    #
    # `phase1_provenance_presence_check` asks all fourteen layers for a
    # top-level `provenance` or `source_documents`. Exactly ONE emitter wrote
    # one — the L5 no-analog builder hardcodes `source_documents` in its own
    # content dict — so the gate returned 1/14 on EVERY design. Measured on two
    # independent designs on two hosts: 1 of 28 generated docs, both times, and
    # the one was L5 both times. That is not a design's docs being thin; it is
    # the writer recording provenance at one of fourteen sites.
    #
    # The data was already here. `extraction_evidence` is KEYED BY SOURCE:
    #     {"input/docs/L1_product_metadata.md": [{"literal": "100 MHz", ...}],
    #      "derived_from_L3": []}
    # so the layer's provenance is its own evidence's keys, split by whether the
    # key names an input path or names a derivation. Nothing is invented.
    #
    # THREE THINGS THIS DELIBERATELY DOES NOT DO:
    #   - it never overwrites a `source_documents` an emitter set itself (L5);
    #   - a layer whose evidence is EMPTY gets `[]`, which the gate still counts
    #     as absent, and that is the honest answer — a document with no evidence
    #     has no provenance, and manufacturing one would be the fabrication this
    #     whole gate exists to catch;
    #   - a derivation key ("derived_from_L3") is NOT written into
    #     source_documents, because it is not a source document. It is recorded
    #     separately so the trail is still readable.
    # Issue #1997: L9-L13 scan the input even when their typed content is an
    # honest absence declaration.  Match-only evidence is then empty, which
    # made all five emit `source_documents: []` and held the acceptance gate at
    # 9/14.  Their callers now pass the scanned corpus separately: it records
    # which documents were examined without claiming that a field matched.
    if "source_documents" not in content and "provenance" not in content:
        _ev_keys = [k for k in evidence if isinstance(k, str)] \
            if isinstance(evidence, dict) else []
        _src = sorted({k for k in _ev_keys if "/" in k})
        _derived = sorted({k for k in _ev_keys if "/" not in k})
        if not _src and source_documents:
            _src = sorted({str(p) for p in source_documents if str(p)})
        content["source_documents"] = _src
        if _derived:
            content["source_documents_derivation"] = _derived
    if _v1_6_367_sentinel_skipped:
        content.setdefault("extraction_strategy", {})[
            "extraction_evidence_sentinel_stripped_v1_6_367"
        ] = _v1_6_367_sentinel_skipped
    # v1.6.81 — closes issue #12 follow-up. Coerce every `no_<X>_in_input`
    # flag to hard bool before serialise. Field agent's verification of
    # v1.6.79 found `L8.no_timing_constants_in_input: null` in both
    # thin-input and rich-input runs; this defensive pass guarantees the
    # flag is always True/False regardless of which code path produced it.
    _ensure_bool_flags(content)
    # CLOCK CONTRACT — one clock name, one period. Applied at the same write
    # chokepoint as the sanitisers above so no L emitter, present or future,
    # can put a self-contradictory clock contract into a document. Borrowed-
    # name records are folded onto the record that owns the name (their
    # numbers survive under `alternate_frequency_mentions[]`); a genuine
    # two-owner disagreement is NOT resolved here — it is stamped on the
    # document as `clock_contract_conflicts[]` and blocks the run in
    # `_post_emit_enforce_clock_contract`. Fail-closed beats guessing.
    _cc.enforce(content)
    # v0.1.60 capture (R11): wire phase1_post_process.scrub_l_doc into the
    # write chokepoint so every L doc emission gets the HALLUC_PATTERNS scan
    # (ic_name lifted from "SUCH ARM TECHNOLOGY" license clause, opcode_hex
    # cribbed from 2-digit page numbers, etc.). The scrubber existed since
    # v0.1.51 but was never invoked from the doc-mode runner pipeline; the
    # AMBA AXI parity run on v0.1.57 reproduced the hallucination across all
    # 14 L docs. Now caught at emission time, with an audit entry attached.
    try:
        from phase1_post_process import scrub_l_doc as _scrub_l_doc
        _scrub_log = _scrub_l_doc(content, name)
        if _scrub_log:
            content.setdefault("extraction_strategy", {})[
                "hallucination_scrub_v0_1_60"
            ] = [entry.as_dict() for entry in _scrub_log]
    except Exception as _e:
        # Fail-open: scrubber missing or broken shouldn't block emission.
        content.setdefault("extraction_strategy", {})[
            "hallucination_scrub_error_v0_1_60"
        ] = str(_e)[:200]
    # v0.1.62 capture (R13): consult l_doc_taxonomy.is_applicable. When the
    # detected ic_class declares this L doc not-applicable (e.g.
    # bus_interconnect_protocol legitimately has no L4 regmap / L5 analog /
    # L11 OTP / L13 lab calibration), replace the over-filled content with
    # the canonical na_stub. Preserves any R11 scrub audit so the trail
    # stays complete. Fail-open: missing taxonomy → emit as before.
    try:
        from l_doc_taxonomy import is_applicable as _is_applicable
        from l_doc_taxonomy import na_stub as _na_stub
        from l_doc_taxonomy import l_doc_spec as _l_doc_spec
        from ic_class_profile import detect_ic_class as _detect_ic_class
        _profile = _detect_ic_class(project)
        _ic_class = _profile.get("ic_class", "unknown") if isinstance(_profile, dict) else "unknown"
        _spec_code = _l_doc_spec(name).code
        # is_applicable returns True for unknown ic_class (legacy-compat
        # default emit-everything). It only flips to False when the registry
        # entry explicitly excludes this L doc for this class.
        if _ic_class != "unknown" and not _is_applicable(_ic_class, _spec_code):
            _scrub = (content.get("extraction_strategy") or {}).get(
                "hallucination_scrub_v0_1_60")
            content = _na_stub(_ic_class, name)
            if _scrub:
                content.setdefault("extraction_strategy", {})[
                    "hallucination_scrub_v0_1_60"] = _scrub
            content.setdefault("extraction_strategy", {})[
                "ic_class_applicability_gate_v0_1_62"] = (
                f"ic_class={_ic_class!r} declares L{_spec_code} not "
                "applicable; emitted as N/A stub (l_doc_taxonomy.na_stub)")
    except Exception as _e:
        # Fail-open: gate missing / partial → emission proceeds.
        content.setdefault("extraction_strategy", {})[
            "ic_class_applicability_gate_error_v0_1_62"
        ] = str(_e)[:200]
    out = _pl.generated_docs_dir(project) / f"{name}.json"
    out.parent.mkdir(parents=True, exist_ok=True)
    _stamp.dump(out, content)
    todo = json.dumps(content).count("__TODO__")
    n_ev = sum(len(v) for v in evidence.values())
    return LDocResult(name=name, path=out,
                      todo_count=todo, evidence_count=n_ev)


def _try_load_l_doc(project: Path, name: str) -> Optional[dict]:
    """v1.6.58 — load a previously-emitted L doc by name (e.g.
    "L2_FRS"). Used by L6 generator to consult L2.protocol_overview
    when deciding whether to emit the AID 5-state FSM scaffold."""
    try:
        path = _pl.generated_docs_dir(project) / f"{name}.json"
        if path.is_file():
            return json.loads(path.read_text(errors="ignore"))
    except Exception:
        pass
    return None


