# ORGANIC-20260606 #475 — token-class guard for the L1.pin_table → L9
# ports promoter. Two non-port token families were observed leaking into
# L9.top_ports (each emitted as `mode=input`, evidence='promoted from
# L1.pin_table'), while the real direction-prefixed top ports were
# dropped:
#
#   (a) SDC constraint-directive families. An `.sdc` / constraints file
#       mistakenly fed into the pin extractor surfaced directive tokens
#       (`set_input_delay`, `set_output_delay`, `create_clock`, …) — the
#       `*_delay` / `set_*` tokens carry the word `input`/`output` in
#       their name, so the legacy direction heuristic mislabelled them as
#       ports. This is a PATTERN class (a directive-keyword family), not
#       a single literal. Chip-AGNOSTIC: SDC is an industry-standard
#       constraint language; none of these are chip/vendor names.
#
#   (b) Standard-cell library / cell-name prefix SHAPE. A library token
#       (e.g. `<process>_fd_sc_<variant>` style names, or tokens ending
#       in a cell-library suffix shape) leaked from a synth/PDK file.
#       The guard matches the SHAPE of a stdcell-library identifier, NOT
#       any one vendor literal — `\w+_fd_sc_\w+` is a structural pattern;
#       no vendor string (e.g. a specific PDK name) participates. This
#       keeps the rule chip-AGNOSTIC per the project deny-list policy.
#
# Both are PATTERN-on-SHAPE guards, applied inside `_is_real_port_token`
# so EVERY caller (gen_l1_datasheet line-scan, the L9 promoter, the
# verilog-port harvester) gets the same protection — defence in depth.
_SDC_DIRECTIVE_RE = re.compile(
    r"(?i)^(?:"
    # `set_*_delay` family (set_input_delay / set_output_delay /
    # set_max_delay / set_min_delay / set_clock_latency …) — the
    # specific shape that masquerades as a direction-bearing port.
    r"set_[a-z0-9_]*_delay"
    r"|"
    # generic SDC `set_*` constraint setters
    r"(?:set_(?:input_transition|output_load|load|driving_cell|"
    r"clock_groups|clock_latency|clock_transition|clock_uncertainty|"
    r"false_path|multicycle_path|propagated_clock|case_analysis|"
    r"disable_timing|max_transition|max_fanout|max_capacitance|"
    r"min_capacitance|units|operating_conditions|wire_load_model|"
    r"timing_derate|ideal_network|dont_touch|dont_use|size_only))"
    r"|"
    # SDC object-creation / collection directives
    r"(?:create_(?:clock|generated_clock|voltage_area)"
    r"|get_(?:ports|pins|clocks|cells|nets)"
    r"|all_(?:inputs|outputs|registers|clocks)"
    r"|current_design|read_sdc|write_sdc)"
    r")$"
)

# Standard-cell library / cell identifier SHAPE. Two structural anchors:
#   - the `_fd_sc_` infix that names a stdcell library family
#     (`<foo>_fd_sc_<bar>` — pattern, not a vendor literal), or
#   - a token that *ends* in a recognised stdcell-library suffix shape
#     (`__1`, `_2`, drive-strength tails on a `*_sc_*` body, etc.).
# These appear in synth / PDK / Liberty files, never as a chip's own
# top-level port name. Chip-AGNOSTIC: matches the SHAPE only.
_STDCELL_LIB_SHAPE_RE = re.compile(
    r"(?i)(?:"
    r"^\w*_fd_sc_\w+"        # <process>_fd_sc_<variant>[...]  (infix)
    r"|"
    r"^\w+_sc_(?:hd|hs|hdll|ls|ms|lp|hvl)\b"  # generic *_sc_<lib-tier>
    r")"
)


def _is_sdc_directive_token(tok) -> bool:
    """ORGANIC #475 (a) — True iff `tok` matches an SDC constraint
    directive family (PATTERN class, not a single literal)."""
    return bool(isinstance(tok, str) and _SDC_DIRECTIVE_RE.match(tok.strip()))


def _is_stdcell_lib_shape_token(tok) -> bool:
    """ORGANIC #475 (b) — True iff `tok` matches a standard-cell library
    / cell-name prefix SHAPE (pattern on shape, never one vendor
    literal)."""
    return bool(isinstance(tok, str)
                and _STDCELL_LIB_SHAPE_RE.match(tok.strip()))


# ORGANIC #475 (c) — positive port-like-evidence corroboration for the
# L1.pin_table → L9 promoter. A pin entry promotes ONLY when it carries
# real port-like evidence, mirroring the existing pin-extraction
# corroboration patterns (the `extraction_strategy` provenance markers
# set by the structured extractors, the `_v455_*` direction-convention
# helpers, and the `_is_pipe_table_row` structured-row anchor). Three
# accepted forms of evidence:
#   1. a direction-affix naming convention (i_/o_/io_ prefix, or an
#      _i/_o/_n/_in/_out/_oe direction suffix) — the same convention the
#      `_v455_*` helpers already trust;
#   2. a structured port-table-row source — the source pin's
#      `extraction_strategy` is one of the known port-table extractors
#      (pipe table / RST grid interface table / verilog port decl /
#      markdown bullet / backticked interface), or its evidence string
#      names a structured row source;
#   3. a recognisable port-name stem (clk / rst / data / bus / addr /
#      cs / we / oe / en / dq / irq / valid / ready / …) — the
#      conventional functional-pin vocabulary the corpus already emits.
# This is the safety net behind guards (a)/(b): it rejects NOVEL
# non-port token classes (tool directives, namespaced commands) that the
# enumerated deny-patterns have not yet captured, without pruning the
# legitimate functional pins the corpus already produces.
_PORT_DIR_PREFIX_RE = re.compile(r"(?i)^(?:i|o|io|in|out)_[a-z0-9]")
_PORT_DIR_SUFFIX_RE = re.compile(
    r"(?i)[a-z0-9]_(?:i|o|io|n|in|out|oe|en|p|m|b)$")
# Structured port-table extraction strategies (a token sourced from one
# of these is, by construction, a real port-table cell).
_PORT_TABLE_STRATEGIES = frozenset({
    "markdown_pipe_table",
    "rst_grid_interface_table", "rst_grid_interface_table_2col",
    "rst_grid_interface_table_ncol",
    "rst_grid_interface_table_dir2col_v0262",
    "gfm_multitable_header_role_v0_3_2",
    "rst_list_table_signals", "rst_iface_3col_v1_6_565",
    "interfaces_section_v1_6_524",
    "markdown_bullet_under_heading",
    "md_inline_backtick_port_bullet_v1_6_381",
    "verilog_port_decl", "verilog_port_bind",
    "backticked_interface_v455",
    "peripheral_clock_pin", "l9_port_reset_shape_v1_6_369",
    "spice_netlist_v1", "aid_class_canonical_pin_augment",
})
# Conventional functional-pin name stems. Matched SEGMENT-WISE (the
# name is split on `_`, each segment compared) rather than as a raw
# substring, so a 2-char stem like `id` does not spuriously fire inside
# an unrelated word ("wIDget"). A segment qualifies when it equals a
# stem, or equals a stem followed only by digits (`clk0`, `data3`), or
# a stem followed by digits is a prefix of the segment. Deliberately
# broad — the corpus emits these as real ports across IC classes — yet
# none coincide with the SDC-directive / stdcell-library shapes already
# rejected by (a)/(b).
_PORT_NAME_STEMS = frozenset({
    "clk", "clock", "rst", "reset", "data", "bus", "addr", "address",
    "cs", "we", "oe", "en", "ena", "irq", "int", "dq", "dqs", "cke",
    "req", "ack", "valid", "ready", "sda", "scl", "tx", "rx", "wake",
    "ovp", "vbg", "vref", "gpio", "sel", "wr", "rd", "id", "din", "dout",
    "miso", "mosi", "sck", "ss", "byte", "word", "strobe", "stb", "cyc",
    "mem", "pwm", "adc", "dac", "vin", "vout", "vdd", "vss", "gnd",
    "scan", "test", "mode", "ctrl", "stat", "flag", "busy", "done",
    "err", "trig", "sync", "frame", "lane", "phy", "io", "pad", "pin",
    "precharge", "activate",
})


def _segment_is_port_stem(seg: str) -> bool:
    """True iff a single `_`-delimited name segment is a functional-pin
    stem (exact, or stem+trailing-digits)."""
    if not seg:
        return False
    if seg in _PORT_NAME_STEMS:
        return True
    # stem followed by trailing digits (clk0 / data3 / addr12)
    base = seg.rstrip("0123456789")
    if base != seg and base in _PORT_NAME_STEMS:
        return True
    return False


def _pin_has_port_like_evidence(pin) -> bool:
    """ORGANIC #475 (c) — positive corroboration gate. Return True iff
    `pin` (a dict from L1.pin_table) carries port-like evidence per the
    three accepted forms above. Chip-AGNOSTIC: name-convention shapes,
    structured-source provenance, and a generic functional-pin stem
    vocabulary — no chip/vendor literal participates."""
    if not isinstance(pin, dict):
        return False
    name = str(pin.get("name") or "").strip()
    if not name:
        return False
    low = name.lower()
    # Form 1 — direction-affix naming convention.
    if _PORT_DIR_PREFIX_RE.match(name) or _PORT_DIR_SUFFIX_RE.search(name):
        return True
    # Form 2 — structured port-table-row source.
    es = str(pin.get("extraction_strategy") or "").strip()
    if es in _PORT_TABLE_STRATEGIES:
        return True
    ex = str(pin.get("_extraction") or "").strip()
    if ex in _PORT_TABLE_STRATEGIES:
        return True
    ev = str(pin.get("evidence") or "").strip().lower()
    # A structural evidence string (names a real row source). The bare
    # placeholder 'promoted from l1.pin_table' is NOT structural — it is
    # exactly the marker the issue's junk tokens carried.
    if ev and ev != "promoted from l1.pin_table" and any(
            k in ev for k in (
                "pipe", "table row", "grid", "port decl", "port-decl",
                "interface", "signal", "bullet", "backtick", "netlist",
                "verilog", "pinout", "column",
            )):
        return True
    # Form 3 — recognisable functional-pin stem (segment-wise, so a
    # short stem like `id` never fires inside an unrelated word).
    for seg in re.split(r"[^a-z0-9]+", low):
        if _segment_is_port_stem(seg):
            return True
    return False


def _is_real_port_token(tok, l1_chip_name=None, pin=None):
    """v1.6.85 (#17 Bug A2) — chip-AGNOSTIC reject filter for harvested
    all-caps tokens proposed as top-level ports.

    Rejects: power rails (VDD/VSS/GND/VIN/V_OUT/VCC*), narrative tokens
    (HOST/ATE/GPIO/POR), the chip's own name (so `IC-A` mentioned in
    a pinout caption doesn't promote to a port), version codes (E4 /
    A1101 / IC-A), and tokens shorter than 3 chars (defensive — real
    multi-bit pin names are at least 3 chars). Returns True iff the
    token is plausibly a real chip port name.

    v1.6.152 (#60 P0-1) — also rejects Verilog/SystemVerilog reserved
    keywords (`new`, `module`, `wire`, `class`, `bit`, ...) and a
    short list of mass-prose nouns (`org`, `the`, `page`, ...). Field
    agent observed `new` and `org` leaking from datasheet prose,
    producing `wire new;` in chip_top.sv which iverilog rejects
    with a syntax error and cascades into fpga_compile FAIL →
    fpga_burn SKIP → STALE-board PASS chain. chip-AGNOSTIC: the
    deny-set is a language-keyword list applicable to any chip.
    """
    if not isinstance(tok, str):
        return False
    # ORGANIC-20260606 #475 (a)(b) — token-class guards (PATTERN on
    # SHAPE, chip-AGNOSTIC). SDC constraint-directive families and
    # standard-cell library-prefix shapes are never chip top-level
    # ports; reject them before any direction/length heuristic so they
    # can't masquerade as `mode=input` ports via their embedded
    # `input`/`output` substrings.
    if _is_sdc_directive_token(tok):
        return False
    if _is_stdcell_lib_shape_token(tok):
        return False
    up = tok.upper()
    # #611 — provenance-aware exemptions (chip-AGNOSTIC). A pin the L1 stage
    # deliberately enumerated from a banked range / structured port table
    # (provenance ∈ _PORT_TABLE_STRATEGIES, e.g. backticked_interface_v455) is
    # corroborated as a real port and must NOT be re-screened by the
    # version-code SHAPE rejector as a part-number (IN1..IN6 / OUT1..OUT6 /
    # CK4..CK6 were being dropped). A pin carrying an explicit FUNCTIONAL
    # direction (input/output) is a signal port, never a supply rail (a VREF
    # reference INPUT is not a VDD/VSS supply). Other callsites pass pin=None
    # → both guards behave exactly as before (no behaviour change).
    _pin = pin if isinstance(pin, dict) else {}
    _strat = _pin.get("_extraction") or _pin.get("extraction_strategy")
    # v1.0.44 — for #664 ORGANIC. A structured walker may ANNOTATE its
    # base strategy with a `+<annotation>` suffix (the canonical
    # `rst_grid_interface_table+width_parametric_v1_6_423` form a 4COL
    # row takes when its width cell is parametric / `<N>-bit` / bracketed).
    # The bare `in _PORT_TABLE_STRATEGIES` membership test missed the
    # suffixed form, so a legitimate short datapath port (x/y/p/q) coming
    # out of a parametric-width port-table row was dropped by the 1-char
    # floor below — the very buses #664 is about. Test the BASE strategy
    # (everything before the first `+`) so the provenance survives the
    # annotation. Chip-AGNOSTIC: pure strategy-name convention.
    _strat_base = (str(_strat).split("+", 1)[0] if _strat else _strat)
    _has_port_table_provenance = (
        _strat in _PORT_TABLE_STRATEGIES
        or _strat_base in _PORT_TABLE_STRATEGIES)
    _dir = str(_pin.get("mode") or _pin.get("direction") or "").strip().lower()
    _has_functional_dir = _dir in ("input", "output", "inout", "in", "out")
    if up in _POWER_RAIL_TOKENS and not _has_functional_dir:
        return False
    if up in _NON_PORT_NARRATIVE_TOKENS:
        return False
    if l1_chip_name and up == str(l1_chip_name).upper():
        return False
    # #17 Bug A2 — `EXAMPLE_*` placeholder/sentinel names (EXAMPLE_CHIP,
    # EXAMPLE_TESTER, EXAMPLE_IC, …) are documentation scaffolds, never
    # real chip ports. chip-AGNOSTIC: the `EXAMPLE_` prefix is the
    # platform-wide placeholder convention used across all spec docs.
    if up.startswith("EXAMPLE_"):
        return False
    # v1.6.152 (#60 P0-1) — Verilog/SystemVerilog reserved keywords +
    # mass-prose nouns. Lowercase compare because the deny set is
    # stored lowercase; tokens may come in any case.
    if tok.lower() in _VERILOG_RESERVED_KEYWORDS:
        return False
    # Pure chip-version codes: leading letters + digits only (E4, IC-A, A1101).
    # #611 — but NOT when the pin was deliberately enumerated from a banked
    # range / structured port table: that provenance corroborates a real
    # port (IN1 / OUT6 / CK4) and overrides the part-number shape heuristic.
    if _CHIP_VERSION_CODE_RE.match(up) and not _has_port_table_provenance:
        return False
    # v1.6.86 (#18 Bug 3) — board-pin labels (PIN_N5 / PIN_N14 / PIN_AB12)
    # are FPGA-package ball assignments, never chip top-level ports.
    if _PIN_NUMBERED_RE.match(up):
        return False
    # v1.6.87 (#19 Bug 2) — DE10-Lite-class board-pin patterns
    # (ADC_CLK_<N>, MAX10_CLK<X>_<N>, GPIO_<N>, HEX_<N>, KEY_<N>,
    # LEDR_<N>, SW_<N>, DRAM_*). Chip-AGNOSTIC: chip top-level ports
    # never match these dev-kit-board hardware-pin shapes.
    if _matches_dev_kit_pattern(tok):
        return False
    # v0.1.86 — 1-char tokens only. The prior ≥3 floor dropped legitimate
    # 2-char control ports (cs / we / oe / rd / wr / en / ce / hs), e.g.
    # sha256's `cs` (chip-select) + `we` (write-enable), which then broke
    # l9_rtl_pin_consistency (RTL had cs/we, L9 didn't). The other reject
    # filters above (power rails, Verilog reserved words, version codes like
    # `E4`, power/narrative tokens) already screen the common 2-char noise, so
    # the length floor only needs to reject 1-char tokens. Chip-AGNOSTIC.
    # ORGANIC #627 round-2 — port-table-PROVENANCE exemption (mirrors the
    # #611 version-code exemption above at the `_CHIP_VERSION_CODE_RE` line).
    # The v455 walker (#627 round-1) correctly recovers single-letter datapath
    # ports (x / y / p / a / b / q) into L1.pin_table, but on the L1→L9
    # promotion path this 1-char floor dropped them AGAIN — so
    # l9_rtl_pin_consistency_check FAILed "RTL top has ports not in L9:
    # [p,x,y]". A 1-char token deliberately enumerated from a port TABLE
    # (provenance ∈ _PORT_TABLE_STRATEGIES, e.g. backticked_interface_v455)
    # IS a real port; only drop a 1-char token WITHOUT that provenance (a bare
    # prose glyph). chip-AGNOSTIC: provenance flag, no chip/vendor literal.
    if len(tok) < 2 and not _has_port_table_provenance:
        return False
    return True


_PIN_ANCHOR_RE = re.compile(
    r"\b(?:pin|port|signal|wire|bus|input|output|inout|"
    r"i/o|i\.o|type|description|name)\b",
    re.IGNORECASE,
)


# v1.6.263 — for #121 ORGANIC. ALL-CAPS prose abbreviation
# (`FFT` / `PLL` / `ADC` / `DAC` / `CRC` / `FIFO` / `DMA` / `AHB` /
# `AXI` / `SPI` / `I2C` / `UART` / `JTAG` / `OTP` / …) appearing
# in narrative paragraphs MUST NOT promote to L1.pin_table /
# L9.top_ports without port-context corroboration. The narrative-
# fallback line-scan in `gen_l1_datasheet` (the path with NO
# `extraction_strategy`) is the leak surface. Same family as
# closed #114 (corroborating-prose for L9.submodules) on the L1
# port-side.
#
# Port-context heading scope: section whose heading matches the
# usual pin / port / signal / interface vocabulary. Three anchor
# shapes are recognised:
#   1. Markdown heading: `# Pinout`, `## I/O`, `### Top-level Ports`
#   2. Plain-text colon-terminated heading: `Pin table:`,
#      `Pinout:`, `Top-level ports:`, `Signals:`, `Interface:`
#   3. Plain-text column-header line: `PIN  NAME  I/O  DESCRIPTION`
_RE_PORT_HEADING_SCOPE = re.compile(
    r"(?im)(?:^|\n)"
    r"(?:"
    # case 1b (ORGANIC-20260606 #455): markdown heading that CONTAINS
    # the pin/port/interface vocabulary anywhere in its first 60 chars
    # ("## Externally-observable interface (per the chip's top pins)").
    # Still heading-anchored — prose paragraphs never match.
    r"#{1,6}[^\n]{0,60}?\b(?:pin(?:s|out)?|i/?o|ports?|interface|signals?)\b[^\n]*"
    r"|"
    r"#{1,6}\s+"  # case 1: markdown heading
    r"(?:pin(?:out|s|\s+(?:list|table|map))?|i/?o|"
    r"top[-\s]*level\s+ports?|external\s+ports?|"
    r"interface(?:\s+ports?)?|"
    r"port\s+(?:list|table|map|description)|"
    r"ports?|signals?)\b"
    r"|"
    r"(?:pin[\s_-]?(?:list|out|table|map|assignment)|pinmux|"  # case 2
    r"top[-\s]*level\s+ports?|external\s+ports?|"
    r"port\s+(?:list|table|map|description)|"
    r"i/?o|signals?|interface)\s*:\s*$"
    r"|"
    # case 3: bare column-header line. Requires PIN/NAME/SIGNAL
    # column AND a direction-or-IO column to qualify.
    r"\s*(?:PIN|NAME|SIGNAL)\s+(?:NUM(?:BER)?\s+)?"
    r"(?:NAME\s+|SIGNAL\s+)?"
    r"(?:I/?O|DIR(?:ECTION)?|TYPE|MODE)\b"
    r")"
)
_RE_NEXT_MARKDOWN_HEADING = re.compile(r"(?m)^#{1,6}\s+\S")


def _port_context_heading_ranges(text: str) -> List[Tuple[int, int]]:
    """Return byte-offset ranges covered by port-context section
    headings. Each range runs from the heading line to the next
    heading or 4000 chars further down, whichever comes first."""
    if not text:
        return []
    ranges: List[Tuple[int, int]] = []
    for m in _RE_PORT_HEADING_SCOPE.finditer(text):
        start = m.start()
        nm = _RE_NEXT_MARKDOWN_HEADING.search(text, m.end())
        end = nm.start() if nm else min(len(text), m.end() + 4000)
        ranges.append((start, end))
    return ranges


def _is_pipe_table_row(line: str) -> bool:
    """Detect a Markdown pipe-table cell row (`| ... | ... | ...`).

    Real port tables in Markdown always carry this shape; prose
    paragraphs that happen to contain a direction keyword never
    do. This is the structural anchor for narrative-fallback
    line-scan emission."""
    s = (line or "").lstrip()
    return s.startswith("|") and s.count("|") >= 2


# ORGANIC #376 — GFM makes a pipe table's OUTER pipes OPTIONAL, so a
# perfectly legal port table can be written with no leading `|` on any
# row. `_is_pipe_table_row` anchors on that leading `|`, so for such a
# table it answers False on EVERY row, and any caller that uses it to
# recognise a port-table row loses the row's cell structure entirely.
#
# Widening `_is_pipe_table_row` itself is the wrong repair, and the
# direction of the error is why: of its three call sites, two use it
# PERMISSIVELY (a row shape is treated as corroboration that a token is
# a real port) and only one uses it RESTRICTIVELY (in a port-table row,
# only the leading name cell holds the port). Relaxing the shared
# predicate would admit more tokens at the first two and reject more at
# the third — one edit moving the result in both directions at once.
#
# So the relaxed form is a SEPARATE, block-scoped predicate, anchored on
# the one construct GFM actually requires: the DELIMITER row. A bare
# "line contains two pipes" test would match prose and a bitwise-or
# expression; a delimiter row (`---|---`, `:--|--:`) has no other
# meaning. Membership is computed over a whole chunk because that anchor
# lives on a DIFFERENT line than the rows it qualifies, which is exactly
# what a single-line predicate cannot see.
#
# chip-AGNOSTIC: pure Markdown table structure — no design, vendor, PDK
# or IC-class literal.
_RE_GFM_DELIM_ROW = re.compile(
    r"^\s*\|?(?:\s*:?-{2,}:?\s*\|)+\s*:?-{2,}:?\s*\|?\s*$")


def _gfm_pipe_table_row_indices(chunk: str) -> frozenset:
    """0-based line indices of `chunk` that belong to a GFM pipe table.

    Anchored on the table's DELIMITER row rather than on a leading `|`,
    so it recognises the outer-pipe-omitted form that
    `_is_pipe_table_row` cannot see. From each delimiter row, claims the
    header line directly above and the contiguous run of pipe-carrying
    lines below, stopping at the first blank or pipe-less line — the
    block GFM itself terminates a table on.

    Returns indices only; the caller decides what a row membership
    means. Deliberately NOT a drop-in replacement for
    `_is_pipe_table_row` (see the note above it)."""
    lines = (chunk or "").splitlines()
    rows: set = set()
    for i, ln in enumerate(lines):
        if not _RE_GFM_DELIM_ROW.match(ln):
            continue
        rows.add(i)
        if i and lines[i - 1].strip() and "|" in lines[i - 1]:
            rows.add(i - 1)
        j = i + 1
        while j < len(lines) and lines[j].strip() and "|" in lines[j]:
            rows.add(j)
            j += 1
    return frozenset(rows)


# v1.6.264 — for #122 ORGANIC. RST grid-table cell values
# (e.g. parameter-default `AFTER` / `BEFORE` / `DEFAULT` / `NONE`)
# leaked into L1.pin_table via the narrative-fallback line-scan
# whenever the row happened to contain a direction keyword in
# any cell. Two complementary filters:
#   (a) RST grid-table source-line filter — lines between
#       `+---+...+---+` separator pairs are RST table cells, not
#       narrative; skip them entirely in line-scan emission.
#   (b) Common-English deny-list — ALL-CAPS English words that
#       are never legitimate port names; reject in narrative-
#       fallback path only (structural extractors carry
#       `extraction_strategy` and bypass).
_RE_RST_GRID_SEP_LINE = re.compile(r"^\s*\+[-+=]+\+\s*$")


# ORGANIC #553 — column-2 ID/position semantic guard.
# RST grid tables whose second column header names a position/ID field
# (e.g. "MIP bit", "interrupt ID", "index") must NOT have their second
# column parsed as the signal WIDTH.  Canonical case: CPU/SoC interrupt
# tables list (signal | MIP-bit-position | direction | description); the
# position column contains small integers (3, 7, 11, 31) that are NOT wire
# widths.  Chip-AGNOSTIC: matched by keyword content of the header cell
# (no IC brand names), not by position value.
_ID_COL_HDR_RE = re.compile(
    r"\b(?:id|position|pos|index|idx|number|num|mip)\b",
    re.IGNORECASE,
)
# Recognise the RST grid table header-separator row (uses = signs,
# distinct from the dashed row-separator).
_RST_EQ_SEP_LINE_RE = re.compile(r"^[ \t]*\+={2,}(?:\+={2,})*\+\s*$")


def _rst_col2_id_char_ranges(text: str) -> List[Tuple[int, int]]:
    """Return character [start, end) ranges where the enclosing RST grid
    table's SECOND column header is a position/ID column (not width).
    Rows inside these ranges should not use column 2 as a signal width.

    Algorithm: find RST header-separator rows (+=======+ lines). The
    row immediately above is the column-header row.  If cell[1] (the
    second pipe-delimited cell, index 1 after stripping the empty leading
    cell) matches _ID_COL_HDR_RE → record the range from the separator
    line to the end of that table block (next blank / non-table line).
    Chip-AGNOSTIC: keyword match only, no IC-specific literals.
    """
    if not text:
        return []
    lines = text.split("\n")
    # Build map: line index → character offset
    offsets: List[int] = []
    off = 0
    for ln in lines:
        offsets.append(off)
        off += len(ln) + 1
    ranges: List[Tuple[int, int]] = []
    for i, line in enumerate(lines):
        if not _RST_EQ_SEP_LINE_RE.match(line):
            continue
        # Header row is the line just above
        if i == 0:
            continue
        header_line = lines[i - 1]
        stripped_hdr = header_line.strip()
        if not (stripped_hdr.startswith("|") and stripped_hdr.endswith("|")):
            continue
        cells = header_line.split("|")
        # cells: ["", " col1 ", " col2 ", ..., ""]
        # col2 = cells[2] (0=pre-pipe empty, 1=first col, 2=second col)
        if len(cells) < 3:
            continue
        col2_header = cells[2].strip()
        if not _ID_COL_HDR_RE.search(col2_header):
            continue
        # Scan forward from the separator row to the end of the table block
        start_off = offsets[i]
        end_idx = i + 1
        while end_idx < len(lines):
            nl = lines[end_idx].strip()
            if nl.startswith("+") or (nl.startswith("|") and nl.endswith("|")):
                end_idx += 1
            else:
                break
        end_off = offsets[min(end_idx, len(lines) - 1)]
        ranges.append((start_off, end_off))
    return ranges


def _in_id_col2_zone(pos: int,
                     zones: List[Tuple[int, int]]) -> bool:
    """True when character offset `pos` falls inside an ID-column-2 zone."""
    return any(start <= pos < end for start, end in zones)


def _rst_grid_table_line_ranges(text: str) -> List[Tuple[int, int]]:
    """Return byte-offset ranges covered by RST grid-table blocks.

    An RST grid table is a contiguous region of `+---+` separator
    lines and `|...|` body lines. Markdown pipe-tables (which use
    `---` separators without `+`) do NOT match — they remain
    eligible for the v1.6.263 pipe-row anchor."""
    if not text:
        return []
    ranges: List[Tuple[int, int]] = []
    block_start: Optional[int] = None
    block_end: Optional[int] = None
    offset = 0
    for line in text.splitlines(keepends=False):
        line_end = offset + len(line)
        stripped = line.strip()
        is_sep = bool(_RE_RST_GRID_SEP_LINE.match(line))
        is_body = (stripped.startswith("|") and stripped.endswith("|")
                   and stripped.count("|") >= 2)
        if is_sep:
            if block_start is None:
                block_start = offset
            block_end = line_end
        elif is_body and block_start is not None:
            block_end = line_end
        else:
            if block_start is not None and block_end is not None:
                ranges.append((block_start, block_end))
            block_start = None
            block_end = None
        offset = line_end + 1
    if block_start is not None and block_end is not None:
        ranges.append((block_start, block_end))
    return ranges


# Common English-prose words that are NEVER legitimate port names.
# Chip-AGNOSTIC: deliberately excludes `data`/`addr`/`name`/`mode`/
# `state`/`status`/`config`/`count`/`index` — those ARE common
# port-name stems and would over-prune real pins. The list targets
# parameter-default values and prose connectives that have actually
# leaked in field reports.
_L1_PIN_NARRATIVE_DENY_LOWERCASE = frozenset({
    "after", "before", "default", "value", "values",
    "true", "false", "none", "null",
    "any", "all", "each", "every", "some",
    "first", "last", "next", "prev", "previous", "current",
    "select", "size", "placement",
    "yes", "no", "on", "off",
    "min", "max", "low", "high",
})


def _has_pin_table_anchor(line, surrounding_lines=None):
    """v1.6.85 (#17 Bug A2) — require structural context before
    promoting an all-caps token to a chip port. The token must sit
    in a line that ALSO carries pin-table column-headers (PIN / I/O /
    TYPE / DESCRIPTION) OR a sentence with pin/port/signal/wire/bus/
    input/output keywords. Without this, every all-caps mention in
    narrative gets promoted to a pin (the field-agent's #17 finding).
    """
    if not isinstance(line, str):
        return False
    if _PIN_ANCHOR_RE.search(line):
        return True
    if surrounding_lines:
        # ±2-line context window
        for nbr in list(surrounding_lines)[-2:]:
            if isinstance(nbr, str) and _PIN_ANCHOR_RE.search(nbr):
                return True
    return False


_PROTOCOL_ACRONYM_DENY = frozenset({
    # memory protocols / classes
    "DDR", "SDR", "QDR", "LPDDR", "HBM", "GDDR",
    # bus / interconnect protocol classes
    "PCIE", "PCI", "AXI", "AXIS", "AHB", "APB", "AVALON", "WISHBONE",
    "USB", "USB2", "USB3",  # bare class — pin names like USB_DM survive
                            # the substring check (deny-list compares the
                            # WHOLE token).
    # network / link protocol classes (acronyms — real pins are
    # specific signal names like `gmii_rxd`, `mdio_clk`, etc.)
    "ETH", "ETHERNET", "MII", "RMII", "GMII", "RGMII", "SGMII",
    "PHY",  # protocol-class shorthand; real pin names like PHY_TX
            # carry an underscore and survive the regex.
    # time-sync / packet-level protocol classes
    "PTP", "1588", "8B10B", "64B66B",
    # generic IP-class words that show up in prose but never as a
    # top-level pin
    "PCS", "MAC", "FIFO", "DMA", "NIC", "RSS", "MSI",
})


# v1.6.273 — for #138 ORGANIC. README / main-doc intro paragraph
# extractor for L1.description. Pre-v1.6.273 no extractor populated
# `L1.description`, so every chip emitted `description: ""` regardless
# of how rich the README intro was. Downstream Phase 2 uses
# L1.description to seed the chip-level RTL comment header and the
# human-readable summary at the top of `human_docs/L1_DATASHEET.md`.
#
# Strategy: walk extracted docs in priority order looking for the first
# non-empty prose paragraph after one of these intro anchors:
#   1. Markdown H1 matching the chip name (`# <name>\n`)
#   2. Markdown H2 / RST h2 with the word `Introduction` / `Overview` /
#      `About` / `Description`.
#   3. AsciiDoc level-2 heading with the same vocabulary.
#   4. Plain-prose first paragraph of the README (fallback).
#
# Cap at 500 chars. Skip markdown badges / citation lines. Returns
# (description, evidence_dict) where evidence carries the source path,
# line, and extraction_strategy. Returns (None, None) when no candidate
# extracted.
#
# Chip-AGNOSTIC: structural anchors only; no chip-class literal.
_RE_L1_DESC_BADGE = re.compile(
    r"!\[[^\]]*\]\([^)]*\)"  # markdown image / shield (inline url)
    r"|"
    r"\[!\[[^\]]*\]\([^)]*\)\]\([^)]*\)"  # nested image link (inline url)
    r"|"
    # v1.6.280 — for #142 ORGANIC. Reference-style badge variants:
    #   [![alt][LABEL_REF]][URL_REF]
    #   [![alt][LABEL_REF]](https://...)
    # Pre-v1.6.280 these slipped through and became L1.description.
    r"\[!\[[^\]]*\]\[[^\]]*\]\]\[[^\]]*\]"
    r"|"
    r"\[!\[[^\]]*\]\[[^\]]*\]\]\([^)]*\)"
    r"|"
    # v1.6.280 — for #142 ORGANIC. HTML embed lines (open / self-close /
    # close tag on its own line, optionally wrapped in <p>/<a>/<center>/<div>):
    #   <img align="right" src="..."/>
    #   <p align="center"><img src="..."/></p>
    #   </p>  </div>  </center>
    r"|"
    r"^\s*<[a-zA-Z][^>]*/?>\s*$"
    r"|"
    r"^\s*</[a-zA-Z]+>\s*$"
    r"|"
    # v1.6.280 — for #142 ORGANIC. Trailing reference definitions:
    #   [ref]: https://... "title"
    # These belong at the bottom of a README and should never become
    # description prose.
    r"^\s*\[[^\]]+\]:\s+\S+.*$"
    r"|"
    r"^>\s+"  # blockquote prefix
    r"|"
    r"^=+\s*$|^-+\s*$"  # RST underline-only lines
)
_RE_L1_DESC_INTRO_HEADING = re.compile(
    # v1.6.280 — for #141 ORGANIC. Switched the `\s+` separators to
    # `[ \t]+` so the regex stays on a single line. Pre-v1.6.280 the
    # multiline-friendly `\s+` would span a blank line and match
    # `==========\n\nIntroduction` (the RST title underline followed by
    # the RST Introduction heading word), causing the description to
    # become the literal word "Introduction".
    #
    # v1.6.284 — for #147 ORGANIC. Suffix-tolerant: the trailing
    # `[ \t]*$` clamp required the heading text to be the bare
    # vocabulary word. Canonical sphinx-doc / Markdown title shapes
    # carry a chip-name suffix on the same line:
    #     `# Introduction to MyChip`
    #     `## Overview of ExampleSoC`
    #     `### About SomeProject`
    # Relaxing to `\b[^\n]*$` accepts any trailing suffix on the same
    # line while still requiring a word-boundary match on the
    # vocabulary token (so `## Introductionary` does NOT match).
    # Mirrors the v1.6.281 (#143 round-2) Features regex relaxation.
    r"(?im)^[ \t]*(?:#{1,3}[ \t]+|==+[ \t]+)"
    r"(?:Introduction|Overview|About|Description|Summary|Abstract"
    r"|Architecture Overview)"
    r"\b[^\n]*$"
)
# v1.6.280 — for #141 ORGANIC. RST two-line (setext) intro heading:
#     Introduction
#     ============
# Pre-v1.6.280 the single-line anchor regex did not match this
# canonical sphinx-doc / RST form. Multiline flag is load-bearing —
# the heading word and the underline marker are on separate lines.
#
# v1.6.284 — for #147 ORGANIC. Suffix-tolerant: heading-word group
# now followed by `\b[^\n]*$` so canonical sphinx-doc titles like
#     Introduction to MyChip
#     ======================
# (the dominant RST form on real-world IC documentation trees) anchor
# the extractor instead of being rejected for not being the bare
# vocabulary word. Same relaxation as the ATX / AsciiDoc forms below.
#
# v1.6.284 — for #148 ORGANIC. Underline char-class restricted to
# `={3,}` ONLY (page-title level). Sub-section markers `-`, `~`, `^`,
# `*`, backtick are conventionally non-chapter — rejecting them
# removes ambiguity where a sub-section `Overview\n-----` block was
# previously promoted as a page-title intro anchor. The features RST
# regex `_RE_L1_FEATURES_RST_HEADING` keeps its broader underline
# char-class because Features sections are commonly section-level.
_RE_L1_DESC_RST_INTRO_HEADING = re.compile(
    r"(?im)^[ \t]*"
    r"(?:Introduction|Overview|About|Description|Summary|Abstract"
    r"|Architecture Overview)"
    r"\b[^\n]*$"
    r"\n"
    r"={3,}[ \t]*$",
    re.MULTILINE,
)
# v1.6.280 — for #143 ORGANIC. README/main-doc Features bullet
# extractor. Pre-v1.6.280 the `_rdp.parse_readme` LiteX-style features
# parser returned a Dict[subsection→bullets]; that dict shape is
# preserved separately for backwards compatibility (still consumed
# by phase2's RTL templater). The flat-list extractor below targets
# the dominant plain README convention:
#
#     ## Features
#     - Bullet one
#     - Bullet two
#
# Returns List[str] (cap 20) so downstream gates that do a substring
# match against the rendered fact-haystack can score each bullet
# independently. The flat list and the dict can coexist (different
# keys: `L1.features` for dict from #61, `L1.features_list` for the
# flat list this issue requests). Reading the issue body strictly:
# "Emit as L1.features: [str, ...]" — to honour both, the flat list
# is wired in next to the existing dict and the dict is preserved
# under `features_grouped` when both are present (back-compat).
_RE_L1_FEATURES_ATX_HEADING = re.compile(
    # v1.6.281 — for #143 round-2 ORGANIC. Pre-v1.6.281 the trailing
    # `\s*:?\s*$` clamp required the heading text to be the bare
    # vocabulary word. Real-world chips ship suffix variants:
    #
    #   `## Features and Typical Applications`   (suffix-on-same-line)
    #   `## Features :`                          (trailing colon-space)
    #   `# Key Features (Hardware)`              (parenthesised qualifier)
    #
    # Relaxing to `\b[^\n]*$` accepts any trailing suffix on the same
    # line while still requiring a word-boundary match on the
    # vocabulary token (so `## Featuredetection` does NOT match).
    #
    # v1.6.289 — for #158 ORGANIC. Add open-standard headline-capability
    # vocabulary: `Standards Compliance`, `Instruction Set Extensions`,
    # `Bus Interfaces`, `Supported Interfaces`, `Interfaces`. These
    # appear widely across CPU IPs, peripheral IPs, and any IC that
    # lists protocol compliance, ISA extensions, or interface options
    # as the headline capability summary.
    r"(?im)^\s*#{1,3}\s+"
    r"(?:Features|Key Features|Highlights|Capabilities"
    r"|Main Features|Feature Summary"
    r"|Standards Compliance|Instruction Set Extensions"
    r"|Bus Interfaces|Supported Interfaces|Interfaces)"
    r"\b[^\n]*$"
)
_RE_L1_FEATURES_RST_HEADING = re.compile(
    # v1.6.281 — for #143 round-2 ORGANIC. Same suffix relaxation as the
    # ATX form. RST setext requires the heading word + suffix on one
    # line, underline `===` on the next. The `\b[^\n]*` clause caps
    # at the newline before the underline marker.
    #
    # v1.6.289 — for #158 ORGANIC. Mirror new vocabulary added to ATX
    # form so RST setext docs (the canonical Sphinx convention) also
    # land headline-capability sections.
    r"(?im)^[ \t]*"
    r"(?:Features|Key Features|Highlights|Capabilities"
    r"|Main Features|Feature Summary"
    r"|Standards Compliance|Instruction Set Extensions"
    r"|Bus Interfaces|Supported Interfaces|Interfaces)"
    r"\b[^\n]*\n"
    r"[=\-~^*`]{3,}[ \t]*$",
    re.MULTILINE,
)
# v1.6.281 — for #143 round-2 ORGANIC. Overview/About fallback. When no
# Features section is found across any doc, harvest bullets from an
# Overview / About / Introduction / Summary section. Used as a degraded
# but better-than-None signal — annotated as `fallback_source =
# overview_bullets` so downstream consumers see provenance.
_RE_L1_FEATURES_OVERVIEW_ATX_HEADING = re.compile(
    r"(?im)^\s*#{1,3}\s+"
    r"(?:Overview|About|Introduction|Description|Summary|Abstract"
    r"|Architecture Overview)"
    r"\b[^\n]*$"
)
_RE_L1_FEATURES_OVERVIEW_RST_HEADING = re.compile(
    r"(?im)^[ \t]*"
    r"(?:Overview|About|Introduction|Description|Summary|Abstract"
    r"|Architecture Overview)"
    r"\b[^\n]*\n"
    r"[=\-~^*`]{3,}[ \t]*$",
    re.MULTILINE,
)
_RE_L1_FEATURES_BULLET = re.compile(
    r"^\s*(?:[-*+]|\d+\.)\s+(.+?)\s*$"
)
_RE_L1_FEATURES_BULLET_INLINE_CODE = re.compile(r"`([^`]+)`")
_RE_L1_FEATURES_BULLET_BOLD = re.compile(r"\*\*([^*]+)\*\*")
_RE_L1_FEATURES_BULLET_LINK = re.compile(r"\[([^\]]+)\]\([^)]*\)")
# v1.6.283 — for #145 ORGANIC. AsciiDoc prefix-heading anchor for
# `L1.features`. Pre-v1.6.283 the Features anchor chain handled ATX
# `##` and RST setext `Features\n========` but NOT the canonical
# AsciiDoc prefix shape (`== Features`, `=== Features`, `==== Project
# Key Features`, etc.). Chips whose docs are authored in AsciiDoc
# (several open-source SoC vendor datasheets + sphinx-doc-derived
# asciidoc trees) emitted empty `L1.features` despite rich heading +
# bullet content. The level-2..level-6 range covers every AsciiDoc
# heading depth (`== H2` .. `====== H6`).
#
# Suffix-tolerant via `\b[^\n]*$` for the same reason the ATX and
# RST forms became suffix-tolerant in v1.6.281 — real-world headings
# carry trailing qualifiers (`=== Features and Highlights`,
# `==== Project Key Features (Hardware)`).
#
# Chip-AGNOSTIC: structural vocabulary only.
_RE_L1_FEATURES_ASCIIDOC_HEADING = re.compile(
    # v1.6.289 — for #158 ORGANIC. Mirror open-standard headline-
    # capability vocabulary so AsciiDoc-source docs (`== Standards
    # Compliance`, `=== Bus Interfaces`, etc.) also anchor.
    r"(?im)^={2,6}[ \t]+"
    r"(?:Features|Key Features|Highlights|Capabilities"
    r"|Main Features|Feature Summary|Project Key Features"
    r"|Standards Compliance|Instruction Set Extensions"
    r"|Bus Interfaces|Supported Interfaces|Interfaces)"
    r"\b[^\n]*$"
)
# v1.6.283 — for #145 ORGANIC. AsciiDoc prefix-heading anchor for
# `L1.description`. Same `^==..==`..`======` range, intro vocabulary
# (Introduction / Overview / About / Description / Summary / Abstract
# / Architecture Overview) mirroring `_RE_L1_DESC_INTRO_HEADING` and
# `_RE_L1_DESC_RST_INTRO_HEADING`.
#
# v1.6.284 — for #147 ORGANIC. The `\b[^\n]*$` clause was already
# present from v1.6.283, so this AsciiDoc form is already
# suffix-tolerant (e.g. `== Introduction to MyChip` matches). No
# regex change needed here; preserved as the canonical reference
# shape that the sibling ATX + RST forms were aligned to in #147.
_RE_L1_DESC_ASCIIDOC_INTRO_HEADING = re.compile(
    r"(?im)^={2,6}[ \t]+"
    r"(?:Introduction|Overview|About|Description|Summary|Abstract"
    r"|Architecture Overview)"
    r"\b[^\n]*$"
)
# v1.6.283 — for #146 ORGANIC. Bold-pseudo-heading anchor for
# per-block sub-features. Pre-v1.6.283 the Features anchor chain
# required structural prefix characters (`#`, `=`) or RST setext.
# It did NOT recognise the bold-pseudo-heading shape
# `**Key Features**` / `**Features**` / `**Highlights**` on its own
# line, which is the canonical AsciiDoc / Markdown convention for
# per-block sub-feature lists when the parent already used a
# `#`-prefix or `==`-prefix heading.
#
# Per-block harvest target: `L1.features_grouped[<block_name>]` —
# the flat `L1.features` list added in v1.6.280 (#143) remains
# UNCHANGED by this pass (it stays sourced from the canonical
# chip-level Features anchor).
#
# Chip-AGNOSTIC: pure structural anchor on bold-formatted vocabulary.
_RE_L1_FEATURES_BOLD_PSEUDO_HEADING = re.compile(
    r"(?im)^[ \t]*\*\*"
    r"(?:Key |Main )?(?:Features|Highlights|Capabilities)"
    r"\*\*[ \t]*$"
)
# v1.6.283 — for #146 ORGANIC. Filename-stem prefix strip list for
# deriving per-block `<block_name>` from a source filename. Used by
# `_derive_block_name_from_stem`. Extend with care; never per-chip.
_BLOCK_FILENAME_STEM_STRIP_PREFIXES: Tuple[str, ...] = (
    "soc_",
    "block_",
    "module_",
    "ip_",
    "core_",
)


def _derive_block_name_from_stem(src: str) -> str:
    """v1.6.283 — for #146 ORGANIC. Derive a per-block name from a
    source filename. Deterministic transform:

      (a) Strip directory components — keep just the filename.
      (b) Drop the final extension only (so `soc_pwm.txt` → `soc_pwm`,
          `module_xbus.md` → `module_xbus`, `cfs` (no ext) → `cfs`).
      (c) Lowercase the stem.
      (d) Strip the first matching prefix from
          `_BLOCK_FILENAME_STEM_STRIP_PREFIXES` so common per-block
          filename prefixes (`soc_`, `block_`, `module_`, `ip_`,
          `core_`) collapse to the bare block name.

    Examples (chip-AGNOSTIC):
        `soc_pwm.txt`       → `pwm`
        `module_xbus.md`    → `xbus`
        `block_clint.asciidoc` → `clint`
        `ip_onewire.txt`    → `onewire`
        `core_bootrom.md`   → `bootrom`
        `cfs.txt`           → `cfs` (no stripped prefix)
        `xbus.md`           → `xbus`
        `nested/dir/pwm.md` → `pwm`
        `README.md`         → `readme` (no stripped prefix)

    Returns the empty string when the filename has no usable stem.
    Chip-AGNOSTIC: prefix list is a module-level constant.
    """
    if not src:
        return ""
    # Strip directory components.
    base = src.replace("\\", "/").rsplit("/", 1)[-1]
    # Drop the final extension only.
    if "." in base:
        base = base.rsplit(".", 1)[0]
    stem = base.lower().strip()
    if not stem:
        return ""
    for pref in _BLOCK_FILENAME_STEM_STRIP_PREFIXES:
        if stem.startswith(pref) and len(stem) > len(pref):
            stem = stem[len(pref):]
            break
    return stem


# v1.6.284 — for #148 ORGANIC. Filename ranking for the cross-file
# intro-anchor selector. Real benchmark directories ship dozens of
# `input_doc/NN_*.txt` files; the cross-file selector
# (introduced in v1.6.281 for #141 round-2) iterated in lexical order
# only, so files prefixed `03_reference__cosim.txt` could win over a
# canonical `01_overview__index.txt` simply because they happened to
# also carry an `Overview` sub-section heading. Lower score wins:
#
#   0  ^(intro|introduction)\b     — explicit Introduction filename
#   1  ^(overview)\b               — explicit Overview filename
#   2  ^(about|readme|index)\b     — generic About / README / index
#   3  ^0?1[_-]?(overview|intro|index)\b — `01_*` / `1_*` ordering prefix
#   9  (lexical fallback)          — everything else
#
# Chip-AGNOSTIC: pure structural filename vocabulary.
# Word-boundary surrogate: a vocabulary token is considered "complete"
# when followed by EOL, a separator (`_`, `-`, `.`), or a non-letter.
# Plain `\b` is broken here because `_` is a regex-word-char, so
# `^overview\b` does NOT match `overview__index` (the literal stem of
# canonical sphinx-doc page names like `01_overview__index.txt`).
# `(?=[^A-Za-z0-9]|$)` lets the vocabulary token end before any
# non-alphanumeric separator (including `_`) or at end of stem.
_RE_FILENAME_INTRO_RANK_0 = re.compile(
    r"^(?:intro|introduction)(?=[^A-Za-z0-9]|$)",
    re.IGNORECASE,
)
_RE_FILENAME_INTRO_RANK_1 = re.compile(
    r"^overview(?=[^A-Za-z0-9]|$)",
    re.IGNORECASE,
)
_RE_FILENAME_INTRO_RANK_2 = re.compile(
    r"^(?:about|readme|index)(?=[^A-Za-z0-9]|$)",
    re.IGNORECASE,
)
_RE_FILENAME_INTRO_RANK_3 = re.compile(
    r"^0?1[_\-]?(?:overview|intro|introduction|index)"
    r"(?=[^A-Za-z0-9]|$)",
    re.IGNORECASE,
)


def _score_intro_filename(basename: str) -> int:
    """v1.6.284 — for #148 ORGANIC. Score a basename's affinity for the
    canonical intro-paragraph role. Lower score = higher priority. The
    cross-file intro-anchor selector sorts intro-candidates by
    (score, lexical) so high-priority filename shapes (`intro.rst`,
    `overview.txt`, `01_overview__index.txt`) outrank arbitrary
    reference-tree files that happen to also carry an `Overview`
    sub-section heading.

    Args:
        basename: filename basename (caller is expected to strip any
            directory components and the trailing extension before
            calling, e.g. via `_derive_block_name_from_stem`). Empty
            input returns the lexical-fallback rank.

    Returns:
        int rank in [0, 9]. 0..3 are deliberate priority tiers; 9 is
        the catch-all lexical-fallback tier (everything else).

    Chip-AGNOSTIC: vocabulary is the same for every chip class.
    """
    if not basename:
        return 9
    stem = basename.strip().lower()
    # Rank 3 first — the numeric-prefix shape ('01_overview') so that
    # it doesn't accidentally fall through to the rank-1 'overview'
    # check (which only fires on a leading 'overview' token).
    if _RE_FILENAME_INTRO_RANK_3.match(stem):
        return 3
    if _RE_FILENAME_INTRO_RANK_0.match(stem):
        return 0
    if _RE_FILENAME_INTRO_RANK_1.match(stem):
        return 1
    if _RE_FILENAME_INTRO_RANK_2.match(stem):
        return 2
    return 9


# v1.6.284 — for #149 ORGANIC. Filename demotion regex for the
# cross-file intro-anchor selector. Real benchmark sphinx-doc trees
# ship LEGAL / LICENSE / authors files at top-level that the lexical
# sort would otherwise visit first. Demotion is structural — no
# chip-name vocabulary.
#
# Demotes when ANY of:
#   * `legal`, `license`, `licence`, `copyright`
#   * `author`, `authors`
#   * `contributing`
#   * `changelog`, `notice`, `history`
#   * any `*_data_readme`, `*_metadata`, `*_about` suffix
#
# Chip-AGNOSTIC: structural / common-document-name vocabulary only.
_DEMOTE_BASENAME_DESC = re.compile(
    r"^(?:legal|license|licence|copyright|author|authors|"
    r"contributing|changelog|notice|history|"
    r".*_data_readme|.*_metadata|.*_about)\b",
    re.IGNORECASE,
)


# v1.6.285 — for #153 ORGANIC. Shared filename-demotion vocabulary
# for the L1.description AND L1.features cross-file selectors.
# Pre-v1.6.285 only `_extract_l1_description` carried a demote regex
# (`_DEMOTE_BASENAME_DESC`). `_extract_l1_features` had no demotion
# layer, so a `coverage_plan.rst` / `verification_plan.adoc` /
# `developer_guide.md` Features heading could outrank the chip's real
# overview.rst Features bullets in the cross-file lexical race.
#
# `_DEMOTE_BASENAME_PATTERNS` extends the v1.6.284 vocabulary with
# two new clusters:
#   * verification / developer cluster — `coverage_plan`,
#     `verification_plan`, `verification_guide`, `test_plan`,
#     `debug_guide`, `developer_guide`, `developer_notes`,
#     `contributing_guide`, `release_notes`, `roadmap`, `todo`,
#     `change_log`, `release_history`.
#   * build / tooling cluster — `build_guide`, `install_guide`,
#     `tooling`, `build_setup`, `installation`.
# The legal cluster (already in v1.6.284 `_DEMOTE_BASENAME_DESC`)
# is reproduced here so `_basename_demoted` is the single source of
# truth and downstream description / features selectors converge on
# the same vocabulary.
#
# Chip-AGNOSTIC: structural common-document-name vocabulary only.
_DEMOTE_BASENAME_PATTERNS: Tuple[str, ...] = (
    # legal cluster — folded in from `_DEMOTE_BASENAME_DESC` so the
    # shared helper covers both v1.6.284 + v1.6.285 callers. Note:
    # bare `about` is INTENTIONALLY excluded (it's intro vocabulary
    # — README's "About" sections often carry chip prose). Only the
    # suffix shape `*_about` is demoted (mirrors v1.6.284).
    #
    # v1.6.287 — for #153 round-2 NOT VERIFIED. Switched from `^`
    # anchor to `(?:^|[/_.])` boundary class so the patterns also
    # match the `NN_section__filename.rst` flatten convention emitted
    # by `extract_text_pipeline` (mirrors L7 v1.6.242 fix).
    r"(?:^|[/_.])(legal|license|licence|copyright|authors?|contributing|"
    r"changelog|notice|history|.*_data_readme|.*_metadata|"
    r".*_about)",
    # verification / developer cluster (NEW for v1.6.285 #153)
    r"(?:^|[/_.])(coverage_plan|verification_plan|verification_guide|"
    r"test_plan|debug_guide|developer_guide|developer_notes|"
    r"contributing_guide|release_notes|roadmap|todo|"
    r"change_log|release_history)",
    # build / tooling cluster (NEW for v1.6.285 #153)
    r"(?:^|[/_.])(build_guide|install_guide|tooling|build_setup|"
    r"installation)",
)
_DEMOTE_BASENAME_COMPILED: Tuple["re.Pattern[str]", ...] = tuple(
    re.compile(pat, re.IGNORECASE) for pat in _DEMOTE_BASENAME_PATTERNS
)


def _basename_demoted(basename: str) -> bool:
    """v1.6.285 — for #153 ORGANIC. True iff the basename stem matches
    any demote-cluster pattern (legal / verification / build). Strips
    a known doc suffix (`.rst` / `.md` / `.adoc` / `.txt`) before
    matching so the pattern set works on common doc extensions.

    Args:
        basename: filename or path; caller may pass full path —
            directory components are stripped via `rsplit('/')`.

    Returns:
        True when the stem matches any `_DEMOTE_BASENAME_PATTERNS`
        entry; False otherwise. Empty / whitespace-only input → False.

    Chip-AGNOSTIC.
    """
    if not basename:
        return False
    stem = basename.replace("\\", "/").rsplit("/", 1)[-1]
    for tail_suffix in (".rst", ".md", ".adoc", ".txt"):
        if stem.lower().endswith(tail_suffix):
            stem = stem[: -len(tail_suffix)]
            break
    stem = stem.lower()
    if not stem:
        return False
    # v1.6.287 — for #153 round-2. `compiled.search` (was `.match`)
    # because patterns now use `(?:^|[/_.])` boundary class to match
    # the `NN_section__filename.rst` flatten convention; `re.match`
    # anchors at position 0 only, which prevents the boundary class
    # from finding mid-string `_` separators.
    for compiled in _DEMOTE_BASENAME_COMPILED:
        if compiled.search(stem):
            return True
    return False


# v1.6.285 — for #151 ORGANIC. Paragraph-quality reject regex for
# academic / institution / course attribution lines. Real benchmark
# academic-tapeout READMEs lead with
#     <CHIP NAME>
#     EE 628 (University of Hawaii)
#     https://github.com/lab/project
#
#     <Chip> is a delta-sigma modulator ...
# The v1.6.284 author-card / bullet-led / badge-only filters did NOT
# catch the attribution + bare-URL paragraph shape, so the walker
# promoted the attribution as L1.description and skipped the real
# chip prose two lines below.
#
# `_RE_PARA_ATTRIBUTION` matches a single line with a trailing
# parenthetical that contains a course / department / institution
# keyword. The leading 80-char text region keeps the regex bounded
# (real attributions are short).
#
# `_RE_PARA_BARE_URL_LINE` matches a line that is JUST a bare
# http(s) URL (no other text). Mirrors v1.6.284
# `_RE_L1_DESC_BARE_URL_LINE` but is reused here under a fresh name
# for #151 readability.
#
# Chip-AGNOSTIC: vocabulary is institution / course / department —
# never a chip-class literal.
_RE_PARA_ATTRIBUTION = re.compile(
    r"^[^.\n]{0,80}\("
    r"(?:[^)]*\b"
    r"(?:University|Institute|College|Lab(?:oratory)?|"
    r"School|Department|Course|EE\s?\d+|CS\s?\d+|"
    r"CSEE\s?\d+|ECE\s?\d+)\b[^)]*)"
    r"\)\s*$",
    re.IGNORECASE | re.MULTILINE,
)
_RE_PARA_BARE_URL_LINE = re.compile(
    r"^\s*https?://\S+\s*$",
    re.MULTILINE,
)


# v1.6.285 — for #150 ORGANIC. Setext-underline lookahead char-class
# regex. Mirrors the existing module-level `_RE_RST_UNDERLINE`
# defined later in the file (line ~15715 — module-level resolution
# at call time makes that name available everywhere) but exposed
# under a dedicated v1.6.285 alias so this fix's lookahead is
# explicit at the call-site. The pattern matches setext H1 (`={3,}`),
# H2 (`-{3,}`), and the looser ` ~ ^ * \` underline shapes that
# appear in some RST trees.
#
# Chip-AGNOSTIC: pure structural shape.
_RE_SETEXT_UNDERLINE_LOOKAHEAD = re.compile(
    r"^[=\-~`'\"^+\*#]{3,}\s*$"
)


# v1.6.285 — for #152 ORGANIC. Intra-page TOC anchor bullet shape.
# Markdown `[<DisplayName>](#anchor)` — distinct from `[Name](url)`
# external links because the href starts with `#` (intra-page
# fragment identifier). Markdown TOCs under a `### Plugins` /
# `## Modules` heading consist exclusively of these bullets; none
# are submodule declarations.
#
# MUST be `fullmatch` not `search` at the call site so external
# `[FooModule](https://...)` links and bare `FooModule` bullets are
# still promoted to submodules (only the exact `[text](#anchor)`
# shape is rejected).
#
# Chip-AGNOSTIC: pure Markdown link-syntax shape.
_RE_INTRA_PAGE_ANCHOR_BULLET = re.compile(
    r"^\[([^\]]+)\]\(#[^)]+\)\s*$"
)


# v1.6.285 — for #154 ORGANIC. List-introducer sentence shape.
# A single-sentence paragraph whose last non-blank character is `:`
# (or full-width `：`) AND whose next non-blank line is a bullet
# marker is structurally a header for the bullet list below — it
# carries little information on its own. The picker strips it and
# either leaves the prefix prose alone (when the prefix is ≥8
# chars) OR joins the first two bullets to recover content.
#
# Matches the trailing `:`/`：` sentence at end of paragraph, with
# the captured group covering the introducer sentence text so the
# call-site can slice `[: m.start(1)]` to keep only the prefix prose.
#
# Chip-AGNOSTIC.
_RE_LIST_INTRODUCER_SENTENCE = re.compile(
    r"(?:^|[.!?]\s+)([^.!?\n]{4,}[:：])\s*$"
)


# v1.6.285 — for #154 ORGANIC. Generic catalog-bullet detector for
# list-introducer handling. Mirrors `_RE_CATALOG_BULLET` (defined
# later in the module at ~15706 — module-level scope means this
# duplicate is safe; we keep a v1.6.285-scoped alias here for
# call-site clarity). Pattern: leading whitespace + `-` / `*` / `+`
# + whitespace + content.
#
# Chip-AGNOSTIC.
_RE_DESC_LIST_INTRODUCER_BULLET = re.compile(
    r"^[ \t>]*[-*+]\s+"
)


# v1.6.284 — for #149 ORGANIC. Post-anchor paragraph quality filter
# regexes. The `_next_paragraph` helper, on hitting a candidate
# paragraph, applies these structural rejection rules to skip
# author-cards / bullet-led structural lists / badge-only blocks and
# advance to the next paragraph (capped at 5 forward scans per anchor
# to prevent pathological docs from looping forever).
#
# Chip-AGNOSTIC: shape-only regex; no chip-class literals.
#
# Author-card shape — AsciiDoc hard-break (` +` at end of line),
# AsciiDoc inline image-link macro, or bare URL on its own line.
_RE_L1_DESC_AUTHOR_HARDBREAK_LINE = re.compile(r" \+\s*$")
_RE_L1_DESC_ASCIIDOC_IMAGE_MACRO = re.compile(
    r"image:[^\[]*\[[^\]]*\]"
)
_RE_L1_DESC_BARE_URL_LINE = re.compile(
    r"^\s*https?://\S+\s*$"
)
# Bullet-led shape — first non-blank line starts with `*` or `-`
# followed by space (Markdown / AsciiDoc bullet).
_RE_L1_DESC_BULLET_LED_LINE = re.compile(
    r"^[ \t]*[*\-][ \t]+\S"
)
# Badge-only line shape — Markdown image (`![alt](url)`), Markdown
# image-link (`[![alt](url)](href)`), AsciiDoc image-macro
# (`image:URL[caption]`), or bare URL.
_RE_L1_DESC_BADGE_LINE_MD = re.compile(
    r"^\s*!\[[^\]]*\]\([^)]*\)\s*$"
)
_RE_L1_DESC_BADGE_LINE_MD_LINKED = re.compile(
    r"^\s*\[!\[[^\]]*\]\([^)]*\)\]\([^)]*\)\s*$"
)
_RE_L1_DESC_BADGE_LINE_ASCIIDOC = re.compile(
    r"^\s*image:[^\[]*\[[^\]]*\]\s*$"
)

_PARAGRAPH_QUALITY_MAX_FORWARD_SCANS = 5


def _is_authorcard_paragraph(para_lines: List[str]) -> bool:
    """v1.6.284 — for #149 ORGANIC. Reject AsciiDoc author-card
    paragraph. Author-card shapes carry ≥2 of:
      (a) line ending with ` +` (AsciiDoc hard-break),
      (b) `image:URL[caption]` AsciiDoc inline-link macro,
      (c) bare `https?://...` URL on its own line.

    Chip-AGNOSTIC: pure structural detection.
    """
    if not para_lines:
        return False
    hits = 0
    has_hardbreak = any(
        _RE_L1_DESC_AUTHOR_HARDBREAK_LINE.search(ln) for ln in para_lines
    )
    if has_hardbreak:
        hits += 1
    has_adoc_image = any(
        _RE_L1_DESC_ASCIIDOC_IMAGE_MACRO.search(ln) for ln in para_lines
    )
    if has_adoc_image:
        hits += 1
    has_bare_url = any(
        _RE_L1_DESC_BARE_URL_LINE.match(ln) for ln in para_lines
    )
    if has_bare_url:
        hits += 1
    return hits >= 2


def _is_bullet_led_paragraph(para_lines: List[str]) -> bool:
    """v1.6.284 — for #149 ORGANIC. Reject paragraph whose first
    non-blank line starts with `*` or `-` followed by space (Markdown
    / AsciiDoc bullet shape). These are structural list paragraphs,
    not prose intros.

    Chip-AGNOSTIC.
    """
    for ln in para_lines:
        if ln.strip():
            return bool(_RE_L1_DESC_BULLET_LED_LINE.match(ln))
    return False


def _is_badge_only_paragraph(para_lines: List[str]) -> bool:
    """v1.6.284 — for #149 ORGANIC. Reject paragraph where every
    non-blank line is a badge: `![alt](url)` (Markdown image),
    `[![alt](url)](href)` (Markdown image-link), `image:URL[caption]`
    (AsciiDoc image-macro), or bare URL. Empty paragraph (no
    non-blank lines) is NOT badge-only.

    Chip-AGNOSTIC: pure structural shape.
    """
    has_content = False
    for ln in para_lines:
        s = ln.strip()
        if not s:
            continue
        has_content = True
        # Accept if ANY of the badge shapes match the line; reject
        # the whole paragraph only when EVERY line is a badge.
        if (_RE_L1_DESC_BADGE_LINE_MD.match(s)
                or _RE_L1_DESC_BADGE_LINE_MD_LINKED.match(s)
                or _RE_L1_DESC_BADGE_LINE_ASCIIDOC.match(s)
                or _RE_L1_DESC_BARE_URL_LINE.match(ln)):
            continue
        return False  # non-badge content line → not badge-only
    return has_content


def _is_attribution_url_paragraph(para_lines: List[str]) -> bool:
    """v1.6.285 — for #151 ORGANIC. Reject paragraph whose first
    non-blank line is an academic / institution / course
    attribution (`<DEPT> <NUM> (<University>)`-shape) — common in
    open-source academic / reference IC READMEs. Two patterns fire:

      (1) First non-blank line matches `_RE_PARA_ATTRIBUTION`
          (institution / department parenthetical at end).
      (2) The paragraph has EXACTLY one prose line + a bare-URL
          continuation line (a two-line attribution-style paragraph
          with no real prose body).

    Chip-AGNOSTIC: vocabulary is University / Institute / EE 628
    style — never a chip-class literal.
    """
    if not para_lines:
        return False
    # Predicate (1) — first non-blank line shape.
    first: Optional[str] = None
    for ln in para_lines:
        if ln.strip():
            first = ln.strip()
            break
    if first is not None and _RE_PARA_ATTRIBUTION.match(first):
        return True
    # Predicate (2) — exactly two non-blank lines AND the second is a
    # bare URL. The first line is treated as attribution-style prose
    # only because of its short / URL-pairing context.
    non_blank: List[str] = [ln for ln in para_lines if ln.strip()]
    if len(non_blank) == 2 and _RE_PARA_BARE_URL_LINE.match(non_blank[1]):
        return True
    return False


# v1.6.361 — for #256 P3 ORGANIC. Sentinel-tag filename deny.
# The v1.6.291 persist step writes runner-internal trace markers
# (e.g. `__rglob_readme_fallback_v1_6_343__*.tag`) into
# `phase1/input_doc/`. Their body is the literal string
# `extraction_strategy: <NAME>\n` so any picker that scans
# `input_doc/` for prose can accidentally promote that body as
# L1.description on chips with sparse top-level docs.
# Chip-AGNOSTIC: filename shape regex on the runner's own sentinel
# convention; no chip-class literal participates.
_RE_SENTINEL_TAG_FNAME_V1_6_361 = re.compile(
    r"^__[a-z_0-9]+_v\d+_\d+_\d+__.*\.tag$",
    re.IGNORECASE,
)


def _v1_6_361_is_sentinel_tag_filename(fname: str) -> bool:
    """v1.6.361 — for #256 P3 ORGANIC. Return True for runner-internal
    sentinel tag filenames (e.g.
    `__rglob_readme_fallback_v1_6_343__.tag`). These persist in
    `phase1/input_doc/` for traceability but must NOT be picked
    as L1 description prose. Chip-AGNOSTIC."""
    if not isinstance(fname, str) or not fname:
        return False
    return bool(_RE_SENTINEL_TAG_FNAME_V1_6_361.match(fname))


# v1.6.363 — for #258 P3 ORGANIC. Pin emitter previously synthesized
# useless `[name.lower(), name.replace("_", "")]` auto-aliases that
# carry no doc evidence. Drop the auto-synth; emit aliases only when
# the doc itself declares one via:
#   (a) pipe-delimited name shape `A|B|C`
#   (b) parenthetical `(alt: X)` / `(alias: X)` / `(aka X)` /
#       `(also X)` in the source row.
# Chip-AGNOSTIC; pattern is a textual convention, no chip-class
# literal participates.
_RE_PIPE_ALIAS_V1_6_363 = re.compile(r"^([A-Za-z_]\w*)\|(.+)$")
_RE_PAREN_ALIAS_V1_6_363 = re.compile(
    r"\(\s*(?:alt|alias|aka|also)\s*[:=]?\s*([A-Za-z_][\w+\-]*)\s*\)",
    re.IGNORECASE,
)


def _v1_6_363_extract_doc_declared_aliases(
        name: str, source_row: str = "") -> list:
    """v1.6.363 — for #258 P3 ORGANIC. Return doc-declared aliases
    only. Sources:
      - pipe-delim in name itself: ``A|B`` → ``['B']``
      - parenthetical: ``(alt: X)`` / ``(alias: X)`` / ``(aka X)``
        in source row.
    Dedup preserving order; exclude exact-name match. Chip-AGNOSTIC.
    """
    aliases: list = []
    m = _RE_PIPE_ALIAS_V1_6_363.match(name or "")
    if m:
        for alt in m.group(2).split("|"):
            alt = alt.strip()
            if alt:
                aliases.append(alt)
    for am in _RE_PAREN_ALIAS_V1_6_363.finditer(source_row or ""):
        aliases.append(am.group(1))
    seen = {name}
    out: list = []
    for a in aliases:
        if a and a not in seen:
            seen.add(a)
            out.append(a)
    return out


def _v1_6_363_strip_pipe_from_name(name: str) -> str:
    """v1.6.363 — for #258 P3 ORGANIC. If `name` carries a pipe-
    delimited alias suffix (e.g. ``RES|PAD``), return only the base
    name (regex group 1). Chip-AGNOSTIC."""
    if not isinstance(name, str) or "|" not in name:
        return name
    m = _RE_PIPE_ALIAS_V1_6_363.match(name)
    if m:
        return m.group(1)
    return name


def _extract_l1_description(extracted: Dict[str, str],
                            ic_name: Optional[str] = None
                            ) -> Tuple[Optional[str], Optional[Dict[str, Any]]]:
    """v1.6.273 — for #138 ORGANIC. Return (description, evidence_dict)
    for L1.description. None when no candidate found.

    v1.6.361 — for #256 P3 ORGANIC. Skip runner-internal sentinel tag
    files (e.g. `__rglob_readme_fallback_v1_6_343__.tag`) and any file
    whose body literally starts with `extraction_strategy:` so the
    L1.description picker never harvests a runner trace marker as the
    chip-level description prose.

    Chip-AGNOSTIC.
    """
    if not extracted:
        return None, None
    # Prefer README files first; many designs ship a top-level README.md /
    # README.rst that contains the canonical intro paragraph.
    # v1.6.361 — drop runner-internal sentinel tag files and any
    # `extraction_strategy:` trace body before any further picking.
    files = [
        (fname, body) for fname, body in extracted.items()
        if not _v1_6_361_is_sentinel_tag_filename(
            fname.rsplit("/", 1)[-1])
        and not (isinstance(body, str)
                 and body.lstrip().startswith("extraction_strategy:"))
    ]
    files.sort(key=lambda kv: (
        0 if "readme" in kv[0].lower() else 1,
        kv[0].lower(),
    ))

    # v1.6.285 — for #150 + #151 + #154 ORGANIC. Walker-state dict;
    # mutated by `_next_paragraph` as side-channel provenance for the
    # cross-file evidence stamping. The winning candidate's evidence
    # block reads from this dict to surface
    # `attribution_url_rejected` (#151) and `list_introducer_handling`
    # (#154). `paragraph_start_index` (#150) records the post-skip
    # line index for callers (README first-prose) that need to stamp
    # the actual paragraph line number rather than the pre-skip
    # candidate line. Per-anchor / per-walk state; not reset between
    # candidate scans because the description picker only uses the
    # state of the WINNING capture.
    walker_state: Dict[str, Any] = {
        "attribution_url_rejected": False,
        "list_introducer_handling": "none",
        "paragraph_start_index": None,
    }

    def _clean(p: str) -> str:
        # Strip surrounding whitespace, leading badges, blockquote
        # markers; collapse internal whitespace.
        #
        # v1.6.295 — for #182 ORGANIC. Strip Markdown inline-link
        # `[label](url)` + HTML `<a href="url">label</a>` wrappers
        # AFTER the badge / blockquote line filter but BEFORE
        # cap so the cleaned description carries label-only text
        # for human-facing renderers + search-index consumers.
        # Chip-AGNOSTIC: pure typographic markup.
        out_lines: List[str] = []
        for ln in p.split("\n"):
            cln = _RE_L1_DESC_BADGE.sub("", ln).strip()
            if cln:
                out_lines.append(cln)
        joined = " ".join(out_lines)
        joined = _v1_6_295_clean_description_markdown(joined)
        return joined[:500]

    def _collect_one_paragraph(
        lines: List[str], start: int
    ) -> Tuple[Optional[List[str]], int]:
        """Collect raw paragraph lines (one block, no _clean). Returns
        (raw_lines_or_None, next_index). Internal helper used by
        `_next_paragraph` so the v1.6.284 (#149) quality filter can
        inspect the raw multi-line shape before joining.

        v1.6.285 — for #150 ORGANIC. Setext-H1 lookahead. When the
        candidate line `lines[i]` is followed by a setext underline
        (`={3,}` / `-{3,}` / ...), it is a setext H1/H2 title and
        NOT a prose paragraph line — advance past the title +
        underline and continue scanning. Prevents the README-walker
        from promoting the chip-name H1 title literally as the
        description paragraph.

        v1.6.285 — also updates
        `walker_state["paragraph_start_index"]` to the post-skip
        line index where the captured paragraph actually begins so
        callers (e.g. README first-prose) can record the correct
        line number for provenance even when setext titles were
        skipped over.
        """
        i = start
        # Skip blank lines.
        while i < len(lines) and not lines[i].strip():
            i += 1
        if i >= len(lines):
            return None, i
        # Skip lines that are pure badge / blockquote / underline.
        while i < len(lines) and _RE_L1_DESC_BADGE.fullmatch(lines[i].strip()):
            i += 1
        if i >= len(lines):
            return None, i
        # v1.6.285 — for #150 ORGANIC. Setext-title lookahead loop.
        # Skip any (title, underline) pair followed by blank lines so
        # subsequent paragraph collection lands on the real prose.
        scanned_any = True
        while scanned_any:
            scanned_any = False
            # Skip blank lines again in case lookahead-advance left
            # blanks ahead.
            while i < len(lines) and not lines[i].strip():
                i += 1
            if i >= len(lines):
                return None, i
            if (i + 1 < len(lines)
                    and lines[i].strip()
                    and _RE_SETEXT_UNDERLINE_LOOKAHEAD.match(
                        lines[i + 1].rstrip())):
                # `lines[i]` is a setext title; advance past title +
                # underline.
                i += 2
                scanned_any = True
                continue
        if i >= len(lines):
            return None, i
        # v1.6.285 — for #150 ORGANIC. Record the true paragraph start
        # index for callers that need the post-skip line number for
        # provenance.
        walker_state["paragraph_start_index"] = i
        para: List[str] = []
        while i < len(lines):
            s = lines[i].strip()
            if not s:
                break
            if s.startswith(("#", "==", "..")):
                break
            # v1.6.285 — for #150 ORGANIC. Stop at setext-title shape
            # mid-paragraph (defensive: if a title appears immediately
            # after a single prose line, treat as block boundary).
            if (i + 1 < len(lines)
                    and _RE_SETEXT_UNDERLINE_LOOKAHEAD.match(
                        lines[i + 1].rstrip())):
                # Treat current line as a title-of-next-block; do not
                # include it in the current paragraph.
                if not para:
                    # No paragraph collected yet — advance past
                    # title + underline so caller's next iteration
                    # picks up real prose.
                    i += 2
                    # Refresh recorded start to post-skip index.
                    walker_state["paragraph_start_index"] = i
                    continue
                break
            para.append(s)
            i += 1
        if not para:
            return None, i
        return para, i

    def _apply_list_introducer_trim_join(
        para: str, lines: List[str], end_idx: int,
    ) -> str:
        """v1.6.285 — for #154 ORGANIC. Post-capture list-introducer
        detection. If `para` ends with a list-introducer sentence
        (trailing `:` / `：`) AND the next non-blank line is a
        catalog-bullet marker, strip the introducer. Mutates
        `walker_state["list_introducer_handling"]` for evidence
        stamping.

        Returns the possibly-trimmed `para`.
        Chip-AGNOSTIC.
        """
        m = _RE_LIST_INTRODUCER_SENTENCE.search(para)
        if not m:
            return para
        # Look ≤2 lines ahead from end-of-para for a bullet.
        next_line_idx = end_idx
        while (next_line_idx < len(lines)
               and not lines[next_line_idx].strip()):
            next_line_idx += 1
        if next_line_idx >= len(lines):
            return para
        if not _RE_DESC_LIST_INTRODUCER_BULLET.match(lines[next_line_idx]):
            return para
        # List-introducer + bullets directly below — apply trim/join.
        trimmed = para[: m.start(1)].rstrip()
        if len(trimmed) >= 8:
            walker_state["list_introducer_handling"] = "trimmed"
            return trimmed
        # Short trimmed prefix → join first 2 bullets via "; ".
        bullet_lines: List[str] = []
        for j in range(2):
            cand_idx = next_line_idx + j
            if cand_idx >= len(lines):
                break
            cand_line = lines[cand_idx]
            if not _RE_DESC_LIST_INTRODUCER_BULLET.match(cand_line):
                break
            bullet_text = re.sub(
                r"^[ \t>]*[-*+]\s+", "", cand_line).rstrip()
            if bullet_text:
                bullet_lines.append(bullet_text)
        if bullet_lines:
            joined = "; ".join(bullet_lines)
            walker_state["list_introducer_handling"] = "joined_with_bullets"
            return (trimmed + ": " + joined) if trimmed else joined
        # Nothing to join — leave the trimmed (possibly-empty)
        # prefix in place; mark as trimmed so provenance is correct.
        if trimmed:
            walker_state["list_introducer_handling"] = "trimmed"
            return trimmed
        return para

    def _next_paragraph(lines: List[str], start: int) -> Tuple[Optional[str], int]:
        """v1.6.284 — for #149 ORGANIC. Walk forward through up to
        `_PARAGRAPH_QUALITY_MAX_FORWARD_SCANS` paragraphs, skipping
        any that match the structural-quality reject filter
        (AsciiDoc author-card, bullet-led structural list, or
        badge-only block). The cap prevents pathological docs (e.g.
        100-bullet sub-feature lists) from looping forever.

        v1.6.285 — for #151 ORGANIC. Extend the quality-reject set
        with `_is_attribution_url_paragraph` so academic / institution
        attribution + bare-URL two-line paragraphs are skipped and
        the walker advances to the next paragraph.

        v1.6.285 — for #154 ORGANIC. Post-capture list-introducer
        trim/join applied to the winning paragraph before return.

        Returns (cleaned_paragraph_str_or_None, next_index).
        Chip-AGNOSTIC: shape-only rejection.
        """
        cursor = start
        scans = 0
        while scans < _PARAGRAPH_QUALITY_MAX_FORWARD_SCANS:
            raw, next_idx = _collect_one_paragraph(lines, cursor)
            if raw is None:
                return None, next_idx
            # v1.6.284 — for #149 ORGANIC. Quality filter — reject
            # author-card, bullet-led, or badge-only paragraphs and
            # advance to the next paragraph.
            #
            # v1.6.285 — for #151 ORGANIC. Add attribution+URL
            # reject. Stamp `attribution_url_rejected` provenance
            # when fires (consumed by the cross-file selector below).
            if _is_attribution_url_paragraph(raw):
                walker_state["attribution_url_rejected"] = True
                cursor = next_idx
                scans += 1
                continue
            if (_is_authorcard_paragraph(raw)
                    or _is_bullet_led_paragraph(raw)
                    or _is_badge_only_paragraph(raw)):
                cursor = next_idx
                scans += 1
                continue
            joined = _clean("\n".join(raw))
            # v1.6.285 — for #154 ORGANIC. Apply list-introducer
            # trim/join post-capture; mutates walker_state for
            # provenance.
            joined = _apply_list_introducer_trim_join(
                joined, lines, next_idx)
            return joined, next_idx
        # Cap exhausted — give up.
        return None, cursor

    # v1.6.281 — for #141 round-2 ORGANIC. CROSS-FILE intro anchor
    # selection. Pre-v1.6.281 the per-file loop returned README's H1
    # chip-name anchor or readme_first_prose as soon as the README
    # produced ANY candidate; later RST files with proper
    # `Introduction\n====` setext blocks never got a chance to compete.
    # Real benchmark: 4 RV chips each ship README.md + intro.rst, and
    # the README's H1 chip-name anchor always returned first, so the
    # `doc_intro_paragraph_rst_two_line` strategy stamp NEVER fired.
    #
    # v1.6.283 — for #145 ORGANIC. AsciiDoc prefix-heading anchor
    # added as a third structural class. New selection order:
    #   (a) any RST setext intro anchor (any file)
    #   (b) any AsciiDoc prefix-heading intro anchor (any file)
    #   (c) any ATX H1/H2/H3 intro anchor (any file)
    #   (d) README H1 chip-name anchor
    #   (e) README first-prose fallback
    # Rationale: RST setext + AsciiDoc prefix are structurally
    # unambiguous (highest specificity); ATX `# Foo` collides with
    # the H1 chip-name title shape, so it gets demoted below the
    # other two structural classes.
    #
    # v1.6.284 — for #148/#149 ORGANIC. Per-kind candidate LISTS
    # (not single-slot) so within each structural class we can sort
    # by (filename_demoted_flag, _score_intro_filename(basename),
    # lexical) and pick the best. This replaces the v1.6.281 "first
    # encounter wins" rule with a deterministic filename-priority
    # sort that puts canonical intro shapes
    # (`intro.rst`, `01_overview__index.txt`) ahead of arbitrary
    # reference-tree files and demotes legal / license / authors
    # files even when they happen to carry a matching heading.
    #
    # Each candidate is a tuple
    #   (filename_demoted_flag, filename_score, src_lexical, src,
    #    line_no, para, side_channel_state)
    # so the simple Python tuple-sort yields the v1.6.284 ranking
    # rule directly. The trailing `side_channel_state` snapshot
    # (#150 paragraph_start_index, #151 attribution_url_rejected,
    # #154 list_introducer_handling) is captured at the time of the
    # `_next_paragraph` call so the winning candidate's provenance
    # is preserved even when later candidates over-mutate the
    # shared walker_state dict.
    #
    # Chip-AGNOSTIC: vocabulary is the same structural set
    # (Introduction / Overview / About / …) for every chip class;
    # filename rank uses the same module-level regex tuple for every
    # chip.
    h1_chipname_candidate: Optional[Tuple[str, int, str,
                                          Dict[str, Any]]] = None
    rst_candidates: List[Tuple[bool, int, str, str, int, str,
                                Dict[str, Any]]] = []
    asciidoc_intro_candidates: List[
        Tuple[bool, int, str, str, int, str, Dict[str, Any]]] = []
    atx_intro_candidates: List[Tuple[bool, int, str, str, int, str,
                                      Dict[str, Any]]] = []
    readme_prose_candidate: Optional[Tuple[str, int, str,
                                            Dict[str, Any]]] = None

    def _snapshot_walker_state() -> Dict[str, Any]:
        """v1.6.285 — capture a per-candidate snapshot of the
        side-channel walker_state so the winning candidate's
        provenance survives later mutations. Chip-AGNOSTIC."""
        return {
            "attribution_url_rejected": bool(
                walker_state.get("attribution_url_rejected")),
            "list_introducer_handling": walker_state.get(
                "list_introducer_handling", "none"),
            "paragraph_start_index": walker_state.get(
                "paragraph_start_index"),
        }

    def _reset_walker_state() -> None:
        """v1.6.285 — reset side-channel state before a fresh
        `_next_paragraph` call so the snapshot reflects only this
        call's state, not residual state from a previous candidate.
        Chip-AGNOSTIC."""
        walker_state["attribution_url_rejected"] = False
        walker_state["list_introducer_handling"] = "none"
        walker_state["paragraph_start_index"] = None

    def _basename_score(src_path: str) -> Tuple[bool, int]:
        """Return (demoted_flag, intro_filename_score) for a src
        path. `demoted_flag` is True when the basename matches any
        v1.6.285 (#153) deny-cluster (legal / verification /
        build) — demoted candidates sort LAST regardless of
        intro_score.

        v1.6.285 — for #153 ORGANIC. Delegates to the shared
        `_basename_demoted` helper so the description-extractor and
        the features-extractor converge on the same vocabulary.
        Functional equivalent of the v1.6.284 `_DEMOTE_BASENAME_DESC`
        path (folded into the helper's legal cluster), plus the
        new verification + build clusters.
        """
        base = src_path.replace("\\", "/").rsplit("/", 1)[-1]
        if "." in base:
            stem = base.rsplit(".", 1)[0]
        else:
            stem = base
        demoted = _basename_demoted(stem)
        return demoted, _score_intro_filename(stem)

    for src, text in files:
        if not text:
            continue
        lines = text.split("\n")
        # Anchor 1 — Markdown H1 matching the chip name. Collect (do
        # NOT return immediately); H1 chip-name is the page title and
        # gets DEMOTED below proper RST/AsciiDoc/ATX intro-heading
        # anchors per the round-2 / v1.6.283 selection rule.
        if (h1_chipname_candidate is None
                and ic_name and ic_name != "UNKNOWN_IC"):
            h1_re = re.compile(
                r"(?im)^\s*#\s+" + re.escape(ic_name) + r"\b"
            )
            for ln_idx, ln in enumerate(lines):
                if h1_re.match(ln):
                    _reset_walker_state()
                    para, _ = _next_paragraph(lines, ln_idx + 1)
                    if para and len(para) >= 8:
                        h1_chipname_candidate = (
                            src, ln_idx + 1, para,
                            _snapshot_walker_state())
                    break
        # Anchor 2/3 — ATX H2/H3 intro heading OR RST setext intro
        # heading. Each is matched independently; v1.6.284 collects
        # every match from every file (one candidate per (file, kind),
        # using the FIRST in-file occurrence) so the post-loop
        # (demoted, score, lexical) sort can pick the best across
        # all files instead of the first one seen.
        atx_m = _RE_L1_DESC_INTRO_HEADING.search(text)
        rst_m = _RE_L1_DESC_RST_INTRO_HEADING.search(text)
        if atx_m:
            ln_idx = text[:atx_m.start()].count("\n")
            _reset_walker_state()
            para, _ = _next_paragraph(lines, ln_idx + 1)
            if para and len(para) >= 8:
                demoted, score = _basename_score(src)
                atx_intro_candidates.append(
                    (demoted, score, src.lower(), src, ln_idx + 1,
                     para, _snapshot_walker_state())
                )
        if rst_m:
            ln_idx = text[:rst_m.start()].count("\n")
            _reset_walker_state()
            para, _ = _next_paragraph(lines, ln_idx + 2)
            if para and len(para) >= 8:
                demoted, score = _basename_score(src)
                rst_candidates.append(
                    (demoted, score, src.lower(), src, ln_idx + 1,
                     para, _snapshot_walker_state())
                )
        # v1.6.283 — for #145 ORGANIC. AsciiDoc prefix-heading intro
        # anchor (`== Introduction` .. `====== Architecture Overview`).
        # The regex restricts `={2,6}` so the chip-name H1 in a real
        # AsciiDoc page title (`= ChipName`) does NOT misfire here.
        # An AsciiDoc-source benchmark chip's `input_doc/
        # overview.txt:40` carries `=== Project Key Features` followed
        # by 5+ bullet `* …` lines — the sibling features anchor
        # below catches it; this anchor catches the matching
        # `== Introduction` / `=== Overview` for L1.description.
        adoc_m = _RE_L1_DESC_ASCIIDOC_INTRO_HEADING.search(text)
        if adoc_m:
            ln_idx = text[:adoc_m.start()].count("\n")
            _reset_walker_state()
            para, _ = _next_paragraph(lines, ln_idx + 1)
            if para and len(para) >= 8:
                demoted, score = _basename_score(src)
                asciidoc_intro_candidates.append(
                    (demoted, score, src.lower(), src, ln_idx + 1,
                     para, _snapshot_walker_state())
                )
        # Anchor 4 — README first prose paragraph fallback.
        if "readme" in src.lower() and readme_prose_candidate is None:
            # v1.6.280 — for #142 ORGANIC. Add `<` to the skip-prefix
            # tuple so HTML embed tags (`<img …/>`, `<p align="…">`,
            # `<a …>`) are pre-filtered out and never promoted as prose.
            i = 0
            while i < len(lines):
                s = lines[i].strip()
                if not s or s.startswith(
                        ("#", "=", "-", "..", "[", "!", "<")):
                    i += 1
                    continue
                if _RE_L1_DESC_BADGE.fullmatch(s):
                    i += 1
                    continue
                # Found prose start.
                _reset_walker_state()
                para, _ = _next_paragraph(lines, i)
                if para and len(para) >= 8:
                    # v1.6.285 — for #150 ORGANIC. Use the walker's
                    # post-skip paragraph_start_index for the recorded
                    # line number when setext H1/H2 titles were
                    # skipped during paragraph collection. Fall back
                    # to the pre-scan index `i` when the walker
                    # didn't record a post-skip index (e.g. no setext
                    # skip happened).
                    snap = _snapshot_walker_state()
                    real_start = snap.get("paragraph_start_index")
                    line_no = (real_start + 1
                               if isinstance(real_start, int)
                               else i + 1)
                    readme_prose_candidate = (
                        src, line_no, para, snap)
                break
    # v1.6.284 — for #148/#149 ORGANIC. Sort each per-kind candidate
    # list by (demoted-flag, filename_score, lexical) so canonical
    # intro filenames (`intro.rst`, `01_overview__index.txt`) outrank
    # arbitrary reference-tree files, and legal / license / authors
    # files are pushed to the end of the ranking regardless of score.
    rst_candidates.sort(key=lambda c: (c[0], c[1], c[2]))
    asciidoc_intro_candidates.sort(key=lambda c: (c[0], c[1], c[2]))
    atx_intro_candidates.sort(key=lambda c: (c[0], c[1], c[2]))

    # v1.6.283 — selection order:
    #   1. RST setext intro anchor (any file)
    #   2. AsciiDoc prefix-heading intro anchor (any file)
    #   3. ATX H2/H3 intro anchor (any file)
    #   4. README H1 chip-name anchor
    #   5. README first-prose fallback
    # v1.6.284 — for #148/#149 ORGANIC. Stamp `filename_score`
    # and `filename_demoted` in evidence so downstream provenance
    # auditing can confirm the v1.6.284 ranking fired correctly.
    # v1.6.285 — for #151 + #154 ORGANIC. Also stamp
    # `attribution_url_rejected` (#151) and
    # `list_introducer_handling` (#154) from the per-candidate
    # side-channel snapshot so provenance audits can verify the
    # v1.6.285 filters fired correctly on the winning candidate.
    def _merge_walker_provenance(ev: Dict[str, Any],
                                  snap: Dict[str, Any]) -> Dict[str, Any]:
        """v1.6.285 — fold the captured walker-state snapshot into
        the evidence dict. Always emit both fields so consumers can
        distinguish 'filter never fired' (False / 'none') from
        'filter not applicable' (key absent)."""
        ev["attribution_url_rejected"] = bool(
            snap.get("attribution_url_rejected"))
        ev["list_introducer_handling"] = snap.get(
            "list_introducer_handling", "none")
        return ev

    if rst_candidates:
        demoted, score, _lex, src, line_no, para, snap = rst_candidates[0]
        ev = {
            "source": f"input/docs/{src}",
            "line": line_no,
            "extraction_strategy": "doc_intro_paragraph_rst_two_line",
            "anchor": "intro_heading_rst_setext",
            "filename_score": score,
            "filename_demoted": demoted,
        }
        return para, _merge_walker_provenance(ev, snap)
    if asciidoc_intro_candidates:
        demoted, score, _lex, src, line_no, para, snap = \
            asciidoc_intro_candidates[0]
        ev = {
            "source": f"input/docs/{src}",
            "line": line_no,
            "extraction_strategy": "doc_intro_paragraph_asciidoc_prefix",
            "anchor": "intro_heading_asciidoc_prefix",
            "filename_score": score,
            "filename_demoted": demoted,
        }
        return para, _merge_walker_provenance(ev, snap)
    if atx_intro_candidates:
        demoted, score, _lex, src, line_no, para, snap = \
            atx_intro_candidates[0]
        ev = {
            "source": f"input/docs/{src}",
            "line": line_no,
            "extraction_strategy": "doc_intro_paragraph",
            "anchor": "intro_heading",
            "filename_score": score,
            "filename_demoted": demoted,
        }
        return para, _merge_walker_provenance(ev, snap)
    if h1_chipname_candidate is not None:
        src, line_no, para, snap = h1_chipname_candidate
        ev = {
            "source": f"input/docs/{src}",
            "line": line_no,
            "extraction_strategy": "doc_intro_paragraph",
            "anchor": "markdown_h1_chip_name",
        }
        return para, _merge_walker_provenance(ev, snap)
    if readme_prose_candidate is not None:
        src, line_no, para, snap = readme_prose_candidate
        ev = {
            "source": f"input/docs/{src}",
            "line": line_no,
            "extraction_strategy": "doc_intro_paragraph",
            "anchor": "readme_first_prose",
        }
        return para, _merge_walker_provenance(ev, snap)
    return None, None


# v1.6.280 — for #143 ORGANIC. README/main-doc Features bullet harvest.
# Pre-v1.6.280 the only Features extractor was the LiteX-style dict
# from `readme_deep_parser.extract_features_block`, which only fires
# when the README uses the LiteX 4-tier `> Features` / `> PHY:` /
# `- Bullet` convention. Plain GitHub READMEs that say:
#
#     ## Features
#     - Bullet one
#     - Bullet two
#
# always emitted `L1.features=None`. This extractor walks every
# extracted doc, locates the FIRST Features heading (ATX `## Features`
# OR RST setext `Features\n========`), and harvests consecutive bullet
# lines into a List[str] (cap 20). Returns `[]` when no Features
# heading is found across any doc.
#
# Chip-AGNOSTIC: pure structural anchor on the "Features" vocabulary;
# no chip-class literal.
def _strip_bullet_markdown(s: str) -> str:
    """Strip inline emphasis / code / link syntax from a bullet line.

    v1.6.294 — for #175 ORGANIC. Pre-v1.6.294 the cleaner stripped
    only inline emphasis / code / link. GFM task-list checkbox prefix
    (`[ ]` / `[x]` / `[X]`) and inline HTML tags (`<sub>`, `<sup>`,
    `<b>`, `<i>`, `<em>`, `<strong>`, `<code>`) leaked verbatim into
    the emitted feature string. GFM checkboxes are the canonical way
    a GitHub README expresses completed-vs-pending features; inline
    HTML tags are common typographic markup in academic chip RST
    trees. Both belong stripped.

    Strip order:
      1. Bullet glyph (handled before this function via the bullet
         regex; this function receives the bullet content).
      2. Leading GFM checkbox `[ ]` / `[x]` / `[X]`.
      3. Inline HTML whitelist (`sub/sup/b/i/em/strong/code`).
      4. Bold / italic emphasis (`**bold**`).
      5. Inline code (backticks).
      6. Markdown link (`[text](url)` → `text`).

    Chip-AGNOSTIC: GFM + a small set of typographic HTML tags.
    """
    s = re.sub(r"^\[[ xX]\]\s+", "", s)
    s = re.sub(
        r"</?(sub|sup|b|i|em|strong|code)\s*/?>",
        "",
        s,
        flags=re.IGNORECASE,
    )
    s = _RE_L1_FEATURES_BULLET_BOLD.sub(r"\1", s)
    s = _RE_L1_FEATURES_BULLET_INLINE_CODE.sub(r"\1", s)
    s = _RE_L1_FEATURES_BULLET_LINK.sub(r"\1", s)
    return s.strip()


# v1.6.294 — for #176 ORGANIC. RST external-spec hyperlink bullet
# reject. Pre-v1.6.294 the features harvester accepted any bullet
# under a Features heading. Academic chip RST trees often cite
# external standards documents in the Features section using the RST
# hyperlink syntax `` `Display Title <https://example.org/path>`_ ``,
# where the bullet body is entirely a hyperlink wrapping an external
# standards document URL. Such a bullet is a compliance citation, not
# a feature. The reject filter checks two structural shapes:
#   (1) The RST `text <url>`_ form whose URL points at an external
#       document (.pdf / .html / etc.).
#   (2) Any bullet where a `<https?://...>` URL span consumes more
#       than 60 percent of the bullet content (the same shape with
#       a short display label preceding the URL).
# Chip-AGNOSTIC: pure structural RST hyperlink shape detection.
_RE_RST_EXTERNAL_SPEC_BULLET = re.compile(
    r"`[^<]+<https?://[^>]+\.(?:pdf|html?)>`_?",
    re.IGNORECASE,
)


def _is_external_citation_bullet(s: str) -> bool:
    """v1.6.294 — for #176 ORGANIC. Return True when the bullet is a
    pure external-spec citation rather than a feature description.

    Chip-AGNOSTIC: structural URL-shape rule only.
    """
    if not isinstance(s, str) or not s:
        return False
    if _RE_RST_EXTERNAL_SPEC_BULLET.search(s):
        return True
    url_match = re.search(r"<https?://[^>]+>", s)
    if url_match:
        url_len = len(url_match.group())
        return (url_len / max(1, len(s))) > 0.60
    return False


def _harvest_bullets_after_heading(text: str, end_off: int) -> List[str]:
    """v1.6.281 — for #143 round-2 ORGANIC. Hoisted out of
    `_extract_l1_features` so the Overview fallback can reuse the same
    walker. `end_off` is the byte offset immediately after the heading
    (ATX: end of heading line; RST: end of underline). Returns up to
    20 cleaned bullets.

    Chip-AGNOSTIC.

    v1.6.480 — for #345 P3 ORGANIC. After the first contiguous bullet
    group terminates at a prose line, continue scanning for follow-on
    bullet groups under the SAME Features heading. The walker now
    only stops at: (a) next heading (ATX `#`, RST `==`/`..`, or RST
    setext underline alone) — confirmed section boundary; (b) end of
    text; (c) accumulated cap of 20 bullets. Intervening prose
    paragraphs (`The core also supports the following:`) are skipped
    rather than terminating the harvest. This recovers the common
    multi-paragraph Features layout seen in academic RV-CPU RST trees.
    """
    rest = text[end_off:]
    lines = rest.split("\n")
    # Drop the immediate leading blank line if present.
    i = 0
    while i < len(lines) and not lines[i].strip():
        i += 1
    bullets: List[str] = []
    seen_bullets: set = set()
    # v1.6.541 — for #365 R1 Fix B. Detect the anchor heading
    # level by looking BACKWARDS from end_off. The walker has no
    # explicit anchor-level parameter; we probe text[:end_off]
    # for the heading line that just ended. The anchor level
    # determines which sub-headings continue vs which sibling
    # headings break the harvest.
    #   * ATX `# title`        → anchor_level = 1
    #   * ATX `## title`       → anchor_level = 2 (etc.)
    #   * RST setext `===`     → anchor_level = 1 (H1)
    #   * RST setext `---`     → anchor_level = 2 (H2)
    #   * RST setext `~~~`     → anchor_level = 3 (H3)
    #   * RST setext `^^^`     → anchor_level = 4 (H4)
    # default = 1 (most permissive — break on every heading) when
    # we can't detect; preserves pre-v1.6.541 caller behaviour.
    # chip-AGNOSTIC: pure Markdown / RST grammar.
    _v1_6_541_anchor_level = 1
    _v1_6_541_pre = text[:end_off]
    _v1_6_541_pre_lines = _v1_6_541_pre.rstrip("\n").split("\n")
    if _v1_6_541_pre_lines:
        _v1_6_541_last = _v1_6_541_pre_lines[-1].strip()
        # ATX `# title` / `## title` ...
        _v1_6_541_m = re.match(r"^(#+)\s+\S", _v1_6_541_last)
        if _v1_6_541_m:
            _v1_6_541_anchor_level = len(_v1_6_541_m.group(1))
        else:
            # AsciiDoc `= title` / `== title` ...
            _v1_6_541_a = re.match(r"^(=+)\s+\S", _v1_6_541_last)
            if _v1_6_541_a:
                _v1_6_541_anchor_level = len(_v1_6_541_a.group(1))
            elif re.fullmatch(r"={3,}", _v1_6_541_last):
                # RST setext H1 underline
                _v1_6_541_anchor_level = 1
            elif re.fullmatch(r"-{3,}", _v1_6_541_last):
                _v1_6_541_anchor_level = 2
            elif re.fullmatch(r"~{3,}", _v1_6_541_last):
                _v1_6_541_anchor_level = 3
            elif re.fullmatch(r"\^{3,}", _v1_6_541_last):
                _v1_6_541_anchor_level = 4
    # v1.6.541 — for #365 R1 Fix B. 1000-line walk-cap safety so a
    # runaway scan can never traverse an entire file. chip-AGNOSTIC.
    _v1_6_541_lines_walked = 0
    _V1_6_541_WALK_CAP = 1000
    for j in range(i, len(lines)):
        # v1.6.541 — for #365 R1 Fix B safety. Bound the walker
        # regardless of bullet-cap state.
        _v1_6_541_lines_walked += 1
        if _v1_6_541_lines_walked > _V1_6_541_WALK_CAP:
            break
        ln = lines[j]
        s = ln.strip()
        # v1.6.541 — for #365 R1 Fix B. Distinguish SIBLING-or-higher
        # headings (real section terminators) from CHILD sub-headings
        # (Features sub-section structure that the harvester should
        # walk across). The pre-v1.6.541 walker broke at the FIRST
        # sibling heading at ANY level, missing bullets under
        # sibling `## Sub` / `### Sub` / RST H3-underline blocks
        # when the anchor was an H1. Field-agent confirmed ic-H
        # benchmark layout was exactly this: `# Features` H1 →
        # multiple `## Sub` H2 sub-sections, each carrying its own
        # bullet list; old walker harvested only the first bucket.
        # New v1.6.541 behaviour: break only when the next heading
        # is at a level <= anchor level (sibling or ancestor);
        # continue past deeper child sub-headings.
        # chip-AGNOSTIC: pure Markdown / RST grammar.
        if s.startswith("#"):
            _v1_6_541_atx_m = re.match(r"^(#+)\s+\S", s)
            if _v1_6_541_atx_m:
                _v1_6_541_seen_level = len(_v1_6_541_atx_m.group(1))
                if _v1_6_541_seen_level <= _v1_6_541_anchor_level:
                    break  # sibling-or-higher heading → terminate
                continue  # child sub-heading → continue harvest
            # Bare `#` line without title — treat as terminator
            # (preserves pre-v1.6.541 caller safety).
            break
        # AsciiDoc `= title` / `== title` / `=== title` headings.
        # v1.6.541 — for #365 R1 Fix B. Same level-comparison rule
        # as ATX. chip-AGNOSTIC.
        _v1_6_541_adoc_m = re.match(r"^(=+)\s+\S", s)
        if _v1_6_541_adoc_m:
            _v1_6_541_seen_level = len(_v1_6_541_adoc_m.group(1))
            if _v1_6_541_seen_level <= _v1_6_541_anchor_level:
                break  # sibling-or-higher AsciiDoc heading → terminate
            continue  # child sub-heading → continue harvest
        if s.startswith(".."):
            # v1.6.487 — for #345 R2 ORGANIC Defect A. Distinguish
            # RST `.. directive::` / `.. _label:` (inline elements
            # to skip) from real section terminators. The `..`
            # leader is never a heading by itself; it is always a
            # directive / anchor / comment.
            if _v1_6_487_is_rst_directive_or_label(ln):
                continue  # skip directive line, continue scan
            break  # any other `..` form treated as separator
        # RST setext underline alone (`====` / `----` / `~~~~` /
        # `^^^^`): determine the level of THIS underline and
        # compare against anchor_level. Higher number = deeper
        # nesting (1=`===`, 2=`---`, 3=`~~~`, 4=`^^^`).
        # v1.6.541 — for #365 R1 Fix B: break only on sibling-or-
        # higher (level <= anchor_level), continue past deeper.
        if re.fullmatch(r"={3,}", s):
            if 1 <= _v1_6_541_anchor_level:
                break
            continue
        if re.fullmatch(r"-{3,}", s):
            if 2 <= _v1_6_541_anchor_level:
                break
            continue
        if re.fullmatch(r"~{3,}", s):
            if 3 <= _v1_6_541_anchor_level:
                break
            continue
        if re.fullmatch(r"\^{3,}", s):
            if 4 <= _v1_6_541_anchor_level:
                break
            continue
        if re.fullmatch(r"[*`]{3,}", s):
            # Other RST underline-only shapes (`***` / ``` ``` ```):
            # treat as sub-section markers — continue.
            continue
        bm = _RE_L1_FEATURES_BULLET.match(ln)
        if bm:
            raw_bullet = bm.group(1)
            # v1.6.294 — for #176 ORGANIC. Reject RST external-spec
            # hyperlink bullets BEFORE cleaning so the citation never
            # lands in `L1.features`.
            if _is_external_citation_bullet(raw_bullet):
                continue
            # v1.6.295 — for #189 ORGANIC. Strip leading GFM / Gitea
            # emoji shortcode prefix (`:recycle:` / `:mag:` / ...)
            # BEFORE the existing cleaner runs so the shortcode never
            # leaks into the cleaned string.
            raw_bullet = _v1_6_295_strip_emoji_shortcode(raw_bullet)
            cleaned = _strip_bullet_markdown(raw_bullet)[:200]
            # v1.6.295 — for #189 ORGANIC. Quality reject: fragmentary
            # bullets (trailing `and`/`or`/`:`/`?`) or interrogative
            # pitch lines (starting with `Looking for`/`Are you`/
            # `How`/`What`/`Which`/`Why`) do not belong in
            # `L1.features`. They are usually section headers misread
            # as bullets or marketing call-to-action copy.
            if cleaned and _v1_6_295_is_rejectable_feature_bullet(cleaned):
                continue
            if cleaned and cleaned not in seen_bullets:
                bullets.append(cleaned)
                seen_bullets.add(cleaned)
            continue
        # Allow blank-line spacing between bullets but only break
        # on the first NON-BULLET non-blank prose line (signals the
        # end of the bullet list).
        if not s:
            # If we've already collected bullets and there are no
            # subsequent bullets within 3 blank lines, we'll break
            # naturally below. Continue scanning.
            continue
        # v1.6.480 — for #345 P3 ORGANIC. Pre-v1.6.480 behaviour:
        # `if bullets: break` — stop at the first non-bullet prose
        # line once we'd seen any bullets. That misses the common
        # multi-paragraph Features pattern:
        #     * Feature A
        #     * Feature B
        #
        #     The core also supports the following:
        #
        #     * Feature C
        # v1.6.480 fix: skip intervening prose paragraphs and keep
        # scanning until we hit a real section boundary (heading)
        # OR run out of text. The bullet cap (20) still bounds the
        # walker so a runaway scan is impossible.
        # Non-bullet, non-heading prose AFTER we've started collecting
        # → continue scanning (cross-group).
        if bullets:
            continue
        # Otherwise (no bullets yet) keep scanning a bit in case
        # the first content line is a leading sentence followed by
        # bullets.
        continue
    # v1.6.537 — for #365 ORGANIC. Filter RST grid-table noise
    # (column-header words, mid-row continuation fragments) before
    # capping. Raise cap from 20 → 64 so legitimate long feature
    # lists are no longer truncated. Filter is per-bullet structural
    # quality check — chip-AGNOSTIC and idempotent.
    # v1.6.281 contract restore: use the NOISE-only predicate (no
    # bare 8-char length floor) so legitimate short Markdown feature
    # bullets (`- one`, `- two`) survive the heading-bullet walker
    # while the v1.6.537 grid-table noise classes are still dropped.
    return [b for b in bullets
            if not _v1_6_537_is_walker_noise(b)][:64]


# v1.6.480 — for #345 P3 ORGANIC. Quantifier-prose feature fallback.
# When the canonical Features heading + bullet harvest returns 0
# items across every doc + Overview fallback + table column, scan
# for the quantifier prose shape "contains N copies of <X>" /
# "instances of <X>" / "channels of <X>" — common in analog /
# mixed-signal datasheets that lack a Features section.
# Chip-AGNOSTIC: structural quantifier-noun pattern.
#
# v1.6.487 — for #345 R2 ORGANIC Defect B. Extend the trailing
# lookahead with `\(` (open-paren) so a parenthetical follow-on
# clause such as `(one of them is shared)` correctly terminates the
# matched `<what>` token. Pre-v1.6.487 the lookahead carried `\)`
# (close-paren) and `,` / `.` / `;` / `:` / `\n` only — an inline
# `(` immediately after the noun extended the match past the
# parenthetical boundary, dropping the whole hit.
_V1_6_480_QUANTIFIER_FEATURE_RE = re.compile(
    r"\bcontains?\s+(?:approximately\s+|up\s+to\s+)?"
    r"(?P<count>\d+|one|two|three|four|five|six|seven|eight|"
    r"nine|ten|eleven|twelve)\s+"
    r"(?P<unit>copies|instances|cores|channels|stages|blocks|"
    r"ports|banks|lanes|slots|engines|paths|domains)\s+of\s+"
    r"(?:an?\s+|the\s+)?(?P<what>[a-z][a-z0-9_\s\-]{4,80}?)"
    r"(?=[\.\,;\:\(\)\n]|\s+(?:and|or|with|using|that|which)\b)",
    re.IGNORECASE,
)


# v1.6.487 — for #345 R2 ORGANIC Defect A. The v1.6.480 cross-
# paragraph walker breaks at every line that starts with `..`, but
# RST `..` covers BOTH (i) directive lines (`.. list-table::`,
# `.. figure::`, `.. code-block::`) and (ii) anchor labels
# (`.. _label:`). These are inline elements, not section
# terminators — the walker should SKIP them and continue harvesting
# bullets after the directive/label. Pre-v1.6.487 the bullet group
# under a `.. list-table::` was dropped wholesale.
#
# A real H1/H2 RST heading uses `==` / `--` underline patterns
# detected separately. The only `..` shape that legitimately ends a
# section is none — `..` is the comment / directive / label
# leader, never a section heading.
#
# Chip-AGNOSTIC: pure RST grammar.
_V1_6_487_RE_RST_DIRECTIVE = re.compile(
    r"^\s*\.\.\s+(?:[a-zA-Z][\w-]*::|_[\w\.-]+:)"
)


def _v1_6_487_is_rst_directive_or_label(line: str) -> bool:
    """v1.6.487 — for #345 R2 ORGANIC. Return True iff `line` is
    an RST `.. directive::` (`.. list-table::`, `.. figure::`,
    `.. code-block::`, `.. note::` etc.) or an anchor label
    (`.. _label:`). These should be skipped, not treated as
    bullet-walker terminators.

    Chip-AGNOSTIC.
    """
    if not line or not isinstance(line, str):
        return False
    return bool(_V1_6_487_RE_RST_DIRECTIVE.match(line))


def _v1_6_480_quantifier_feature_fallback(
        extracted: Dict[str, str]) -> Tuple[List[str], Optional[str]]:
    """v1.6.480 — for #345 P3 ORGANIC. Scan all extracted docs for
    quantifier-prose feature mentions ("contains six copies of
    incremental delta-sigma modulator") and return a list of
    `"<count> <what>"` strings + the first matching source filename.
    Returns ([], None) when no quantifier prose is found. Chip-AGNOSTIC.
    """
    if not extracted:
        return [], None
    seen: set = set()
    out: List[str] = []
    source: Optional[str] = None
    files = list(extracted.items())
    files.sort(key=lambda kv: (
        0 if "readme" in kv[0].lower() else 1,
        kv[0].lower(),
    ))
    for fname, text in files:
        if not isinstance(text, str) or not text:
            continue
        for m in _V1_6_480_QUANTIFIER_FEATURE_RE.finditer(text):
            count = (m.group("count") or "").strip()
            unit = (m.group("unit") or "").strip().lower()
            what = (m.group("what") or "").strip()
            # Clean up what — strip trailing 'modulator(s)' or other
            # trailing whitespace.
            what = re.sub(r"\s+", " ", what).strip(" \t,;:.")
            if not (count and what):
                continue
            phrase = f"{count} {unit} of {what}".strip()
            if phrase.lower() in seen:
                continue
            seen.add(phrase.lower())
            out.append(phrase)
            if source is None:
                source = fname
            if len(out) >= 20:
                break
        if len(out) >= 20:
            break
    return out, source


# v1.6.387 — for #278 P3. Module-scope multi-anchor picker.
# Iterates EVERY anchor candidate from each priority-tier regex,
# sorts by (priority_class, offset), returns the first heading
# whose `_harvest_bullets_after_heading` returns non-empty.
# Closes the bug where the per-tier `.search()` semantics returned
# the FIRST anchor in the doc — if that heading had no bullets,
# later headings (with bullets) in the same doc were never tried.
#
# Returns (offset, end_off, kind, bullets) on hit, None on miss.
# Chip-AGNOSTIC: pure structural multi-candidate walk.
def _v1_6_387_pick_anchor_multi(
        text: str,
        rst_re,
        asciidoc_re,
        atx_re):
    """Returns the first ``(offset, end_off, kind, bullets)`` tuple
    whose heading harvest yields a non-empty bullet list, walking
    every candidate from each tier (RST setext > AsciiDoc prefix
    > ATX) in priority order. Returns ``None`` when no candidate's
    heading harvest is non-empty.
    """
    candidates = []
    for prio, (rx, kind) in enumerate(
            ((rst_re, "rst"),
             (asciidoc_re, "asciidoc"),
             (atx_re, "atx"))):
        if rx is None:
            continue
        for mm in rx.finditer(text or ""):
            candidates.append((prio, mm.start(), mm.end(), kind))
    candidates.sort(key=lambda t: (t[0], t[1]))
    for _prio, start, end, kind in candidates:
        bullets = _harvest_bullets_after_heading(text, end)
        if bullets:
            return start, end, kind, bullets
    return None


# v1.6.289 — for #158 ORGANIC. Table-column harvester for L1.features.
# When a doc table's leftmost header cell literally matches `Features`
# or `Feature` (case-insensitive, trimmed), the rightmost body-row
# cells carry the feature list. Common open-standard convention used
# across many IP cores' README / datasheet tables. The helper detects
# RST grid, Markdown pipe, and AsciiDoc cell-block forms; splits the
# cell on semicolons / commas / embedded bullets; stamps
# `extraction_strategy = "doc_features_table_column_harvest"`.
#
# Chip-AGNOSTIC: pure structural table-detection.
_RE_L1_FEATURES_TABLE_ROW = re.compile(
    r"^[ \t]*\|(?P<cells>[^\n]+)\|[ \t]*$",
    re.MULTILINE,
)


def _extract_l1_features_from_table_column(
        text: str) -> Tuple[List[str], Optional[Dict[str, Any]]]:
    """v1.6.289 — for #158 ORGANIC. Walk `text` for pipe-table rows
    whose header includes a column literally labelled `Features` /
    `Feature`. Harvest that column's body content from every body
    row, splitting on `;` / `,` / embedded bullets.
    Returns (entries, evidence) or ([], None) when no match.

    Chip-AGNOSTIC: pure structural pattern."""
    if not isinstance(text, str) or not text:
        return [], None
    rows = list(_RE_L1_FEATURES_TABLE_ROW.finditer(text))
    if len(rows) < 2:
        return [], None
    for header in rows:
        header_cells = [
            c.strip() for c in header.group("cells").split("|")
        ]
        if not header_cells:
            continue
        # Find the column index whose header literally matches
        # `Features` / `Feature` (case-insensitive, stripped).
        feat_col_idx = None
        for idx, cell in enumerate(header_cells):
            normalised = cell.strip(" *`").lower()
            if normalised in ("features", "feature"):
                feat_col_idx = idx
                break
        if feat_col_idx is None:
            continue
        header_line = text[: header.start()].count("\n")
        all_entries: List[str] = []
        body_line_first = None
        for body in rows:
            if body is header:
                continue
            body_line = text[: body.start()].count("\n")
            if body_line <= header_line:
                continue
            body_text = body.group(0)
            if re.match(r"^[ \t]*\|[ \t\-\+=:]+\|[ \t]*$", body_text):
                continue
            body_cells = [
                c.strip() for c in body.group("cells").split("|")
            ]
            if feat_col_idx >= len(body_cells):
                continue
            cell_val = body_cells[feat_col_idx]
            if not cell_val:
                continue
            parts = re.split(r"[;,*+]|(?:\s\-\s)", cell_val)
            entries = [p.strip(" `*-")
                       for p in parts if p.strip(" `*-")]
            if not entries:
                continue
            if body_line_first is None:
                body_line_first = body_line + 1
            for ent in entries:
                if ent not in all_entries:
                    all_entries.append(ent)
        if all_entries:
            return all_entries, {
                "source": "input/docs/<table>",
                "line": body_line_first or 1,
                "extraction_strategy":
                    "doc_features_table_column_harvest",
                "anchor": "features_table_column_header",
            }
    return [], None


# v1.6.458 — for #330 P3 ORGANIC. AsciiDoc datasheet-tree walker.
# Canonical vendor-doc convention places the comprehensive feature
# bullet list under `datasheet/main.adoc` (or sibling `overview.adoc`
# / `index.adoc`) rather than in the root README. The
# `_extract_l1_features` pass picks ONE source file (README-first
# priority) and stops, so the richer AsciiDoc-tree list is silently
# dropped. This helper scans the canonical paths and returns
# (bullets, source_filename) for UNION merging into the existing
# list.
#
# Chip-AGNOSTIC: pure structural file-naming + AsciiDoc heading
# grammar.
_V1_6_458_FEATURE_FILE_CANDIDATES: Tuple[str, ...] = (
    "datasheet__main",
    "datasheet__overview",
    "datasheet__index",
    "main",
    "overview",
    "index",
)
_V1_6_458_FEATURE_HEADING_RE = re.compile(
    # AsciiDoc prefix-heading shape: 1-3 `=` chars + space + optional
    # `Key ` prefix + `Features` or `Feature`. Anchored to BOL and
    # EOL so headers with trailing suffix (`Features and Benefits`)
    # still match via the open-ended trailing group.
    r"^={1,3}\s+(?:[Kk]ey\s+)?[Ff]eatures?\b[^\n]*$",
    re.MULTILINE,
)

# v1.6.464 — for #330 R2 ORGANIC. The v1.6.458 heading regex requires
# `Features` to sit directly after an optional `Key ` token, so it
# misses real-benchmark variants like `=== Project Key Features` and
# `=== Hardware Features Overview` (any token before `Features` other
# than `Key ` breaks the anchor). v1.6.464 broadens the heading regex
# to `={1,3}\s+[^\n]*\b(?:[Kk]ey\s+)?[Ff]eatures?\b[^\n]*$` so any
# prefix tokens on the heading line are tolerated.
#
# Second v1.6.464 defect closure: the v1.6.458 bullet harvester used
# `([*\-]+)\s+(.+?)` which captures `**` + content as a 2-level
# bullet on lines like `** Component A **` (whitespace around the
# group label). On benchmark docs that bracket bold sub-section
# labels with `**` (3+ groups under one heading, 30+ bullets total),
# the harvester ingested the labels as bullets and corrupted the
# Features list. The v1.6.464 walker recognises `**Bold Group**`
# lines as section separators (skip, keep going) and only the next
# AsciiDoc heading (`^={1,6}\s+`) terminates harvesting.
#
# Pure structural / language-generic; no chip-class literal.
_V1_6_464_FEATURE_HEADING_RE = re.compile(
    r"^={1,3}\s+[^\n]*\b(?:[Kk]ey\s+)?[Ff]eatures?\b[^\n]*$",
    re.MULTILINE,
)
_V1_6_464_BOLD_GROUP_RE = re.compile(r"^\*\*[^*\n]+\*\*\s*$")
_V1_6_464_NEXT_HEADING_RE = re.compile(r"^={1,6}\s+")
_V1_6_464_BULLET_RE = re.compile(r"^\s*[*\-+]\s+(.+)$")


def _v1_6_464_harvest_features_under_heading(
        text: str,
        start_idx: int,
        max_features: int = 200,
) -> List[str]:
    """v1.6.464 — for #330 R2 ORGANIC. Harvest AsciiDoc bullets after
    a Features heading. Walk lines starting at `start_idx`; treat
    `**Bold Group**` lines (e.g. `**Component A**`) as section
    separators (skip, keep going); only the next AsciiDoc heading
    (`^={1,6}\\s+`) terminates harvesting. `max_features` is a
    runaway-safety cap (200 by default; tests can lower).

    Returns the raw bullet text list in source order (no dedup,
    no length floor — the caller decides whether to apply those).

    Chip-AGNOSTIC: pure structural / language-generic; no chip-class
    literal.
    """
    out: List[str] = []
    if not isinstance(text, str) or not text:
        return out
    if start_idx < 0:
        start_idx = 0
    body = text[start_idx:]
    for line in body.splitlines():
        if _V1_6_464_NEXT_HEADING_RE.match(line):
            break  # next heading — stop
        if _V1_6_464_BOLD_GROUP_RE.match(line):
            continue  # bold group separator — keep going
        m = _V1_6_464_BULLET_RE.match(line)
        if m:
            bullet_text = m.group(1).strip()
            if bullet_text:
                out.append(bullet_text)
                if len(out) >= max_features:
                    break
    return out


def _v1_6_458_extract_features_from_adoc_tree(
        extracted: Dict[str, str]
) -> Tuple[List[str], Optional[str]]:
    """v1.6.458 — for #330 P3 ORGANIC. Scan the canonical AsciiDoc-
    datasheet-tree files for a `== Features` heading and harvest its
    bullets. Returns (bullets, source_filename) or ([], None) when
    no canonical file carries a Features section.

    The walker tolerates the flatten convention emitted by
    `extract_text_pipeline` (which encodes `datasheet/main.adoc`
    into the key `datasheet__main` via `__` separator) so the same
    helper works on both raw rglob output and post-flatten dict.

    v1.6.464 — for #330 R2 ORGANIC. Routes through the broader
    v1.6.464 heading regex + the cross-group bullet harvester so
    `=== Project Key Features` and similar prefixed-token headings
    are matched, and `**Bold Group**` separators no longer abort
    or pollute the bullet list. The v1.6.458 narrow heading regex
    is retained as a first-pass for back-compat (so the canonical
    `== Features` path keeps the v1.6.458 strategy stamp for
    downstream provenance audits); the broader v1.6.464 regex acts
    as the rescue when the narrow one misses.

    Chip-AGNOSTIC: pure structural matching; no chip-class literal.
    """
    if not extracted:
        return [], None
    # Build a lookup keyed by lowercase stem (without extension).
    stem_index: Dict[str, Tuple[str, str]] = {}
    for fname, text in (extracted or {}).items():
        if not isinstance(text, str) or not text:
            continue
        # Drop extension if present.
        stem = fname.rsplit("/", 1)[-1]
        stem = stem.rsplit(".", 1)[0].lower()
        stem_index[stem] = (fname, text)
    for cand in _V1_6_458_FEATURE_FILE_CANDIDATES:
        hit = stem_index.get(cand)
        if hit is None:
            continue
        src_fname, text = hit
        # v1.6.464 — try the narrow v1.6.458 anchor first for
        # back-compat, then fall back to the broader v1.6.464
        # anchor. Both share the same downstream harvester now.
        m = _V1_6_458_FEATURE_HEADING_RE.search(text)
        if m is None:
            m = _V1_6_464_FEATURE_HEADING_RE.search(text)
        if m is None:
            continue
        # v1.6.464 — Use the cross-group walker that recognises
        # `**Bold Group**` lines as separators (skip, keep going).
        raw_bullets = _v1_6_464_harvest_features_under_heading(
            text, m.end())
        bullets: List[str] = []
        seen: Set[str] = set()
        for bullet_text in raw_bullets:
            # Drop trailing AsciiDoc markup characters.
            bullet_text = bullet_text.strip("`*_ \t")
            if not bullet_text or len(bullet_text) < 3:
                continue
            key = bullet_text.lower()
            if key in seen:
                continue
            seen.add(key)
            bullets.append(bullet_text)
            if len(bullets) >= 64:
                break
        if bullets:
            return bullets, src_fname
    return [], None


def _extract_l1_features(extracted: Dict[str, str]
                         ) -> Tuple[List[str], Optional[Dict[str, Any]]]:
    """v1.6.280 — for #143 ORGANIC. Return (features_list, evidence)
    for L1.features. `features_list` is `[]` when no Features section
    is found in any doc (no spurious None).

    Walks docs in README-first priority order. Stops at the first
    document that produces ≥1 bullet so a chip's Features list is
    sourced from one canonical doc rather than concatenated from
    multiple half-matches.

    v1.6.281 — for #143 round-2 ORGANIC. When no Features section is
    found across any doc, falls back to harvesting bullets under an
    Overview / About / Introduction / Summary section. Annotated
    with `fallback_source = overview_bullets` so downstream
    consumers can distinguish the canonical Features harvest from
    the degraded Overview-derived list.

    v1.6.283 — for #145 ORGANIC. AsciiDoc prefix-heading anchor
    (`== Features`, `=== Key Features`, `==== Project Key Features`,
    etc.) added as a third structural class. Per-doc selection
    order: RST setext > AsciiDoc prefix > Markdown ATX. The same
    ordering applies in the Overview/About fallback pass.

    Chip-AGNOSTIC.
    """
    if not extracted:
        return [], None
    files = list(extracted.items())
    files.sort(key=lambda kv: (
        0 if "readme" in kv[0].lower() else 1,
        kv[0].lower(),
    ))

    # v1.6.283 — for #145 ORGANIC. Per-doc anchor picker. Returns
    # (offset, end_off, kind, anchor_label) for the first matched
    # anchor in priority order RST setext > AsciiDoc prefix > ATX.
    # `regex_triplet` is (rst_re, asciidoc_re, atx_re) — caller
    # provides canonical Features vs Overview triplets.
    #
    # Chip-AGNOSTIC: anchor selection is structural only.
    #
    # NOTE — v1.6.387 (#278): kept defined for backward compat but
    # no longer reachable from the active emit path. Replaced by
    # ``_v1_6_387_pick_anchor_multi`` (see below) which iterates
    # ALL anchor candidates and returns the first whose bullet
    # harvest is non-empty. The old `.search()`-first semantics
    # caused later headings with bullets to be skipped when an
    # earlier heading matched but had no bullets.
    def _pick_anchor(text: str,
                     rst_re: "re.Pattern[str]",
                     asciidoc_re: "re.Pattern[str]",
                     atx_re: "re.Pattern[str]"
                     ) -> Optional[Tuple[int, int, str]]:
        rst_m = rst_re.search(text)
        adoc_m = asciidoc_re.search(text)
        atx_m = atx_re.search(text)
        # Priority: RST setext > AsciiDoc prefix > ATX. Pick the
        # higher-priority class even when a lower-priority match
        # appears at an earlier offset (per #145 selection rule).
        if rst_m is not None:
            return rst_m.start(), rst_m.end(), "rst"
        if adoc_m is not None:
            return adoc_m.start(), adoc_m.end(), "asciidoc"
        if atx_m is not None:
            return atx_m.start(), atx_m.end(), "atx"
        return None

    # v1.6.387 — for #278 P3. Multi-anchor picker is defined at
    # module scope (see top of file). The call sites below reference
    # the module-level name directly.

    # v1.6.283 — for #145 ORGANIC. PASS 1 — canonical Features
    # heading (RST setext OR AsciiDoc prefix OR Markdown ATX).
    # Suffix-tolerant regex accepts `Features and Typical
    # Applications`, `Features :`, `Key Features (Hardware)`, etc.
    #
    # v1.6.285 — for #153 ORGANIC. Collect candidates from EVERY
    # file (not first-match-wins) so the cross-file selector can
    # demote `coverage_plan` / `verification_plan` / `debug_guide`
    # filenames after `_basename_demoted` matches them. Sort key:
    # (filename_demoted_flag, original_file_order_index) so demoted
    # candidates sort LAST while preserving the v1.6.280 README-first
    # priority among non-demoted candidates.
    pass1_candidates: List[
        Tuple[bool, int, str, str, int, List[str], str]] = []
    for order_idx, (src, text) in enumerate(files):
        if not text:
            continue
        # v1.6.387 — for #278 P3. Use the multi-anchor picker so a
        # doc with an early bulletless anchor (e.g. `Features` empty
        # heading) followed by a later anchor with bullets does NOT
        # get silently skipped. Old code took the first anchor only.
        chosen = _v1_6_387_pick_anchor_multi(
            text,
            _RE_L1_FEATURES_RST_HEADING,
            _RE_L1_FEATURES_ASCIIDOC_HEADING,
            _RE_L1_FEATURES_ATX_HEADING,
        )
        if chosen is None:
            continue
        offset, end_off, kind, bullets = chosen
        line_no = text[:offset].count("\n") + 1
        if not bullets:
            continue
        demoted = _basename_demoted(src)
        pass1_candidates.append(
            (demoted, order_idx, src, src, line_no, bullets, kind))
    pass1_candidates.sort(key=lambda c: (c[0], c[1], c[2]))
    # v1.6.288 — for #153 round-3 NOT VERIFIED. After sort, REJECT
    # the candidate set entirely when sorted-first is demoted. The
    # v1.6.287 sort only PUSHED demoted candidates to last; when
    # every candidate is demoted (e.g. chip's overview/index.rst is
    # pure TOC, only `coverage_plan` / `developer_guide` etc. have
    # bullets), the demoted candidate still won the sort. Now we
    # fall through to PASS 2 instead — and PASS 2 mirror-rejects.
    if pass1_candidates and not pass1_candidates[0][0]:
        _demoted, _ord, _lex_src, src, line_no, bullets, kind = \
            pass1_candidates[0]
        # v1.6.280 contract (#143): L1.features is bounded at 20
        # bullets to keep the field compact. The per-heading walker
        # may harvest up to 64; cap the emitted L1 list at 20.
        bullets = bullets[:20]
        if kind == "rst":
            strategy = "doc_features_bullet_list"
            anchor = "features_heading_rst_setext"
        elif kind == "asciidoc":
            # v1.6.283 — for #145 ORGANIC. Distinct strategy stamp
            # so provenance auditing can attribute the harvest
            # to the AsciiDoc anchor.
            strategy = "doc_features_bullet_list_asciidoc_prefix"
            anchor = "features_heading_asciidoc_prefix"
        else:  # kind == "atx"
            strategy = "doc_features_bullet_list"
            anchor = "features_heading_atx"
        return bullets, {
            "source": f"input/docs/{src}",
            "line": line_no,
            "extraction_strategy": strategy,
            "anchor": anchor,
            "filename_demoted": _demoted,
        }
    # v1.6.281 — for #143 round-2 ORGANIC. PASS 2 — Overview/About
    # fallback. If still no bullets harvested, look for the first
    # `Overview` / `About` / `Introduction` / `Summary` heading
    # across all docs and harvest its bullet list. This is a degraded
    # but better-than-None signal for chips that ship an Overview
    # heading but no separate Features section (a common open-source
    # README shape).
    #
    # v1.6.283 — for #145 ORGANIC. Mirror the per-doc anchor picker
    # over the Overview-vocabulary triplet (RST setext > AsciiDoc
    # prefix > ATX).
    #
    # v1.6.285 — for #153 ORGANIC. Same demotion plumbing as PASS 1
    # — collect candidates from every file then sort by
    # (filename_demoted, order_idx, src).
    pass2_candidates: List[
        Tuple[bool, int, str, str, int, List[str], str]] = []
    for order_idx, (src, text) in enumerate(files):
        if not text:
            continue
        # v1.6.387 — for #278 P3. Same multi-anchor picker used in
        # PASS 1 — closes the same skip-doc-on-first-empty-anchor bug
        # for the Overview/About fallback.
        chosen = _v1_6_387_pick_anchor_multi(
            text,
            _RE_L1_FEATURES_OVERVIEW_RST_HEADING,
            _RE_L1_DESC_ASCIIDOC_INTRO_HEADING,
            _RE_L1_FEATURES_OVERVIEW_ATX_HEADING,
        )
        if chosen is None:
            continue
        offset, end_off, kind, bullets = chosen
        line_no = text[:offset].count("\n") + 1
        if not bullets:
            continue
        demoted = _basename_demoted(src)
        pass2_candidates.append(
            (demoted, order_idx, src, src, line_no, bullets, kind))
    pass2_candidates.sort(key=lambda c: (c[0], c[1], c[2]))
    # v1.6.288 — for #153 round-3 NOT VERIFIED. Mirror PASS 1's
    # REJECT semantics: when sorted-first PASS 2 candidate is
    # demoted, treat all candidates as rejected and return empty.
    # The honest signal is no-features-extracted, not a best-effort
    # emit of `coverage_plan` / `developer_guide` bullets that the
    # field-agent's downstream gates correctly identify as wrong.
    if pass2_candidates and not pass2_candidates[0][0]:
        _demoted, _ord, _lex_src, src, line_no, bullets, kind = \
            pass2_candidates[0]
        # v1.6.280 contract (#143): cap the emitted L1 list at 20.
        bullets = bullets[:20]
        if kind == "rst":
            anchor = "overview_heading_rst_setext"
        elif kind == "asciidoc":
            anchor = "overview_heading_asciidoc_prefix"
        else:  # kind == "atx"
            anchor = "overview_heading_atx"
        return bullets, {
            "source": f"input/docs/{src}",
            "line": line_no,
            "extraction_strategy": "doc_features_bullet_list",
            "anchor": anchor,
            "fallback_source": "overview_bullets",
            "filename_demoted": _demoted,
        }

    # v1.6.289 — for #158 ORGANIC. PASS 3 — table-column harvest.
    # When the canonical heading-anchor passes find nothing, try the
    # pipe-table form whose leftmost header is `Features` / `Feature`.
    # Chip-AGNOSTIC: pure structural pattern.
    for src, text in files:
        if not isinstance(text, str) or not text:
            continue
        bullets, ev = _extract_l1_features_from_table_column(text)
        if bullets:
            if ev is not None:
                ev["source"] = f"input/docs/{src}"
            return bullets, ev
    # v1.6.480 — for #345 P3 ORGANIC. PASS 4 — quantifier-prose
    # fallback. Fires ONLY when every prior pass returned empty.
    # Recovers docs that lack a Features section but enumerate
    # block multiplicity via prose like `contains six copies of
    # an incremental delta-sigma modulator`. Each match emits a
    # `"<count> <unit> of <what>"` string into the feature list.
    # Chip-AGNOSTIC: structural quantifier-noun pattern.
    quant_bullets, quant_src = _v1_6_480_quantifier_feature_fallback(
        extracted)
    if quant_bullets:
        return quant_bullets, {
            "source": f"input/docs/{quant_src}" if quant_src else None,
            "extraction_strategy": "doc_features_quantifier_prose",
            "anchor": "quantifier_prose_fallback",
            "fallback_source": "quantifier_prose",
        }
    return [], None


# v1.6.283 — for #146 ORGANIC. Bold-pseudo-heading per-block
# features harvest. Pre-v1.6.283 the canonical `_extract_l1_features`
# anchor chain required structural prefix characters or RST setext;
# the bold-pseudo-heading shape (`**Key Features**` on its own line)
# used by per-block AsciiDoc / Markdown sub-feature lists never
# matched. Per-block bullets (e.g. one file per peripheral, each
# carrying a `**Key Features**` sub-heading) were never aggregated
# and L1's per-block features audit trail was incomplete.
#
# This function harvests bullets under EVERY bold-pseudo-heading
# match in EVERY doc, scopes them by source filename stem
# (`_derive_block_name_from_stem`), and returns:
#   (features_grouped: Dict[block_name, List[bullet]],
#    evidence_groups: List[Dict] for features_evidence stamping)
#
# The flat `L1.features` list (from `_extract_l1_features`) is
# NEVER affected by this pass — bold-pseudo content lives only in
# `L1.features_grouped[block]`.
#
# Chip-AGNOSTIC: filename-stem transform uses
# `_BLOCK_FILENAME_STEM_STRIP_PREFIXES` (module-level constant);
# no chip-class literal.
def _extract_l1_features_grouped_bold_pseudo(
    extracted: Dict[str, str],
) -> Tuple[Dict[str, List[str]], List[Dict[str, Any]]]:
    """v1.6.283 — for #146 ORGANIC. Return (features_grouped,
    evidence_entries).

      `features_grouped`: `{block_name: [bullets, ...], ...}` —
                          empty dict when no bold-pseudo-heading is
                          found across any doc.
      `evidence_entries`: list of evidence dicts per group with
                          `extraction_strategy =
                          "doc_features_bold_pseudo_heading"` and
                          `block_name = <derived from stem>`.

    Multiple bold-pseudo-headings in the same doc accumulate into
    the same `block_name` bucket (capped at 20 bullets total per
    block to mirror the canonical Features cap).

    Chip-AGNOSTIC.
    """
    if not extracted:
        return {}, []
    files = list(extracted.items())
    files.sort(key=lambda kv: (
        0 if "readme" in kv[0].lower() else 1,
        kv[0].lower(),
    ))
    grouped: Dict[str, List[str]] = {}
    evidence_entries: List[Dict[str, Any]] = []
    for src, text in files:
        if not text:
            continue
        block_name = _derive_block_name_from_stem(src)
        if not block_name:
            continue
        first_line_for_block: Optional[int] = None
        bullet_count_for_block = 0
        for m in _RE_L1_FEATURES_BOLD_PSEUDO_HEADING.finditer(text):
            offset = m.start()
            end_off = m.end()
            line_no = text[:offset].count("\n") + 1
            new_bullets = _harvest_bullets_after_heading(text, end_off)
            if not new_bullets:
                continue
            existing = grouped.setdefault(block_name, [])
            remaining_capacity = 20 - len(existing)
            if remaining_capacity <= 0:
                continue
            # v1.6.480 — for #345 P3 ORGANIC. The walker now reads
            # cross-group bullets under the same heading, so two
            # successive bold-pseudo-headings in the same file can
            # double-count overlap. Dedupe against `existing` before
            # extending so per-block bullets remain unique.
            existing_set = set(existing)
            unique_new = [b for b in new_bullets if b not in existing_set]
            if not unique_new:
                continue
            to_add = unique_new[:remaining_capacity]
            existing.extend(to_add)
            if first_line_for_block is None:
                first_line_for_block = line_no
            bullet_count_for_block += len(to_add)
        if bullet_count_for_block > 0:
            evidence_entries.append({
                "source": f"input/docs/{src}",
                "line": first_line_for_block,
                "extraction_strategy": "doc_features_bold_pseudo_heading",
                "anchor": "features_heading_bold_pseudo",
                "block_name": block_name,
                "count": bullet_count_for_block,
            })
    return grouped, evidence_entries


# v1.6.289 — for #159 ORGANIC. ISA classification extractor for CPU
# IPs. The vocabulary tokens below are open-standard fields published
# in the RISC-V Unprivileged ISA and Privileged ISA specifications:
#
#   * RV-base   `RV(32|64)[EIMACFDPVBZ]+` (with optional `_X*` suffix)
#   * Z-ext     `Z[a-z]{2,12}` (Zicsr, Zifencei, Zbb, ...)
#   * X-ext     `X[A-Z]{2,6}` (XPULP, XCV, ...)
#   * Modes     Machine / Supervisor / User / Hypervisor `mode`
#   * Version   `Machine ISA version X.Y`
#   * Endian    `little-endian` / `big-endian`
#
# Chip-AGNOSTIC: all tokens published by the RISC-V International
# foundation as open-standard ISA vocabulary.
_RE_ISA_BASE = re.compile(
    r"\bRV(?:32|64)[EIMACFDPVBZ]+(?:_[Xx][a-z]+)?\b"
)

# v1.6.542 — for #368 P3 ORGANIC. Case-insensitive ISA-base detector.
# The bare `_RE_ISA_BASE` regex above is case-sensitive and misses
# lowercase / backticked prose like `rv32i`, `rv32imac`, and the
# RISC-V short-string form `rv32i_zicsr_zifencei`. RV-CPU datasheets
# and userguides write the base ISA token in lowercase form,
# especially inside Makefile-style toolchain examples
# (`--with-arch=rv32i_zicsr`) and AsciiDoc cpu chapters which follow
# the RISC-V ecosystem's preferred lowercase short-string spec.
#
# Convention preserved when canonicalising:
#   * RV-major prefix (`RV32` / `RV64`) and first single-letter
#     extension block become UPPERCASE.
#   * `_Z*` / `_X*` multi-letter sub-extension suffixes stay
#     LOWERCASE because the RISC-V short-string spec mandates
#     lowercase for `Z*` / `X*` extensions.
#
# Regex floor preserved — at least one extension letter from
# `[EIMACFDPVBZ]` after the width prefix. `RV` alone or `RV32` (no
# extension) does NOT match. Chip-AGNOSTIC: open-standard RISC-V
# ecosystem vocabulary.
_V1_6_542_RE_ISA_BASE = re.compile(
    r"\bRV(?:32|64)[EIMACFDPVBZ]+(?:_[XxZz][A-Za-z0-9]+)*\b",
    re.IGNORECASE,
)


def _v1_6_542_extract_isa_base(text):
    """v1.6.542 — for #368 P3 ORGANIC. Find an ISA-base token
    case-insensitively in ``text`` and canonicalise to uppercase
    RV-major + single-letter extension block, with `_Z*` / `_X*`
    suffixes preserved in lowercase per RISC-V short-string spec.

    Returns the canonicalised token (e.g. ``RV32I_zicsr_zifencei``)
    or None when no match. Chip-AGNOSTIC.
    """
    if not isinstance(text, str) or not text:
        return None
    m = _V1_6_542_RE_ISA_BASE.search(text)
    if m is None:
        return None
    tok = m.group(0)
    head, sep, tail = tok.partition("_")
    head_canon = head.upper()
    if sep and tail:
        return head_canon + "_" + tail.lower()
    return head_canon


def _v1_6_542_canonicalise_isa_base(tok):
    """v1.6.542 — for #368 P3 ORGANIC. Canonicalise a single
    matched ISA-base token (as produced by
    ``_V1_6_542_RE_ISA_BASE.finditer``) to the uppercase-prefix +
    lowercase-Z/X-suffix form. Helper kept separate so the
    finditer walker can canonicalise per-match without re-running
    the regex.
    """
    if not isinstance(tok, str) or not tok:
        return tok
    head, sep, tail = tok.partition("_")
    head_canon = head.upper()
    if sep and tail:
        return head_canon + "_" + tail.lower()
    return head_canon


# v1.6.432 — for #309 P3 ORGANIC. Canonical-base validator. Per
# RISC-V convention the base ISA MUST start with `I` (integer) or
# `E` (embedded) after the width prefix; tokens like `RV32M`,
# `RV32B`, `RV32ZC`, `RV32A` are RTL EXTENSION-config parameter
# names (e.g. ibex_pkg::rv32m_e), NOT ISA bases. The bare regex
# `_RE_ISA_BASE` cannot tell them apart because `[EIMACFDPVBZ]+`
# accepts any combination of those letters.
#
# Two validity rules:
#   1. The FIRST extension letter after the width prefix must be
#      `I` or `E` (canonical base).
#   2. Width must be one of {32, 64, 128} — but `_RE_ISA_BASE`
#      already restricts to (32|64) so the validator reuses that
#      and tolerates 128 if a future regex widens.
#
# Chip-AGNOSTIC: pure RISC-V ecosystem convention; no chip-class
# string literal participates.
_V1_6_432_RE_ISA_BASE_CANONICAL = re.compile(
    r"^RV(?P<width>32|64|128)(?P<first>[IE])"
    r"(?P<rest>[A-Z]*)(?P<sub_exts>(?:_[XxZz][A-Za-z0-9_]+)*)$"
)


def _v1_6_432_is_valid_isa_base(token) -> bool:
    """v1.6.432 — for #309 P3. Return True only when `token` is a
    canonical RISC-V ISA base (width prefix + I/E base + optional
    extension letters / X-vendor suffix). Rejects single-letter
    extension parameter names like RV32M / RV32B / RV32ZC.
    Chip-AGNOSTIC.
    """
    try:
        if not token or not isinstance(token, str):
            return False
        return bool(_V1_6_432_RE_ISA_BASE_CANONICAL.fullmatch(token))
    except Exception:
        return False
# v1.6.294 — for #174 ORGANIC. Closed RISC-V allowlist regex.
# Pre-v1.6.294 the v1.6.286 open-word regex `\bZ[a-z]{2,12}\b` matched
# any prose word starting with a lowercase Z (Zephyr, Zurich, Zylin —
# common OS / city / vendor names) and the X regex matched any
# uppercase-X word (XLEN, XOR — common RTL parameter macros). The
# RISC-V ISA convention reserves the `Z*` namespace for canonical
# standard sub-extensions and the `X*` namespace for non-standard
# vendor extensions; the canonical names are a small enumerable set.
# Enumerating the allowlist removes the open-word false-positive
# class without losing any legitimate RISC-V token.
# Chip-AGNOSTIC: open-standard RISC-V vocabulary published by RISC-V
# International, no chip-class literals.
_RE_ISA_EXT_Z = re.compile(
    r"\bZ(?:icsr|ifencei|b[abcs]|cm[pt]|c[bm]|f(?:h|inx)|"
    r"aamo|alrsc|k(?:[bnr]|nd|sed)|v[a-z]+)\b"
)
_RE_ISA_EXT_X = re.compile(
    r"\bX(?:pulpv[0-9]+|faux|andes[a-z_]*|vendor[a-z_]+)\b"
)
_RE_PRIV_MODES = re.compile(
    r"\b(Machine|Supervisor|User|Hypervisor)\s+mode\b",
    re.IGNORECASE,
)
_RE_MACHINE_ISA_VER = re.compile(
    r"\bMachine\s+ISA\s+version\s+([0-9]+\.[0-9]+)\b",
    re.IGNORECASE,
)
_RE_PRIV_PAIR = re.compile(
    r"\b[Mm]achine[/\s]+[Uu]ser\b"
)
_RE_ENDIAN = re.compile(
    r"\b(little[-\s]endian|big[-\s]endian)\b", re.IGNORECASE
)

# v1.6.297 — for #193 ORGANIC. Negation-context probe for the L1
# privilege-modes / ISA-extensions evidence scanner. The v1.6.289 +
# v1.6.294 scanners run a pure boundary substring match for tokens
# like `Machine`, `Supervisor`, `User`, `Hypervisor`, and the ISA
# extension letters. Without a context-window check, prose like
#   "Hypervisor mode is not implemented in this core."
#   "The F and D extensions are reserved and shall not be used."
# trips a false positive — the disclaimed token still lands in L1.
# Gate every candidate hit on a ±200-char context window:
#   * Reject when the window matches `_RE_NEGATION_CONTEXT` AND does
#     NOT match `_RE_POSITIVE_SUPPORT`.
#   * Prefer positive when both fire (sentence like
#     "implements X but does not implement Y" — the positive marker
#     closer to the matched token usually wins; both regexes are
#     line-anchor-agnostic so either marker can be on either side).
# Chip-AGNOSTIC: open-standard ISA / spec vocabulary — RISC-V ISA
# spec, ARM AMBA spec, vendor MCU spec all share these conventions.
_V1_6_297_RE_NEGATION_CONTEXT = re.compile(
    r"\b("
    r"not\s+implement(?:ed|s)?|"
    r"shall\s+not|must\s+not|"
    r"reserved|unsupported|unimplemented|"
    r"must\s+be\s+0|read-only\s+zero|"
    r"WIRI|WPRI|WLRL|WARL"
    r")\b",
    re.IGNORECASE,
)

_V1_6_297_RE_POSITIVE_SUPPORT = re.compile(
    r"\b("
    r"supports?|implement(?:s|ed)?|provides?|"
    r"available|present|enabled"
    r")\b",
    re.IGNORECASE,
)

_V1_6_297_ISA_CONTEXT_WINDOW = 200


# v1.6.298 — for #193 round-2 NOT VERIFIED. The v1.6.297 negation
# vocabulary missed two real-benchmark prose patterns:
#
#   (1) Spec-style cross-sentence negation. RISC-V Privileged Spec
#       boilerplate carried verbatim into chip READMEs reads:
#         "RISC-V supports Machine, Supervisor, User, Hypervisor modes.
#          This CPU implements only Machine and User."
#       The constraining sentence ("This CPU implements only ...") is
#       paragraphs away from the inherited spec sentence ("RISC-V
#       supports ..."). v1.6.297 found `supports` closer to `Hypervisor`
#       than any negation marker and accepted Hypervisor.
#
#   (2) Spec-style "M-mode only" phrasing. Cores that explicitly state
#       `"only Machine mode"` / `"M-mode only"` / `"this design does
#       not implement"` were not caught by the v1.6.297 vocabulary
#       (which only listed `not implement`, `shall not`, `reserved`).
#
# The v1.6.298 fix extends the negation vocabulary (Option A) AND adds
# an explicit-privilege-table short-circuit (Option B):
#   * Option A: extra patterns for "this core does not implement" /
#     "this CPU implements only" / "only Machine mode" / "M-mode only".
#   * Option B: when the chip doc contains an explicit markdown table
#     whose header is `| Privilege Mode |`, parse the table rows and
#     use ONLY those as the privilege_modes truth — skip the prose
#     scan entirely. This handles chips that publish a canonical
#     supported-modes table next to spec-verbatim narrative prose.
# Chip-AGNOSTIC: only spec-vocabulary phrases and markdown table
# syntax; no chip-class literals.
_V1_6_298_NEGATION_PATTERNS = (
    r"not\s+implement(?:ed|s)?",
    r"shall\s+not",
    r"must\s+not",
    r"reserved",
    r"unsupported",
    r"unimplemented",
    r"must\s+be\s+0",
    r"read-only\s+zero",
    r"WIRI|WPRI|WLRL|WARL",
    # v1.6.298 — extra spec-style vocabulary that covers cross-sentence
    # constraint phrasing missed by v1.6.297. The
    # `implements?/supports?/provides? only` pattern catches the
    # canonical spec phrasing "This CPU implements only Machine and
    # User." that pulled Hypervisor / Supervisor into v1.6.297 output.
    r"this\s+core\s+(?:does\s+not|never)\s+(?:implement|support)",
    r"(?:does|do)\s+not\s+(?:implement|support|provide)",
    r"never\s+(?:implement|support|provide)s?",
    r"implements?\s+only",
    r"supports?\s+only",
    r"provides?\s+only",
    r"only\s+(?:M|machine)\s*[\-\s]?mode\b",
    r"M[\-\s]?mode\s+only",
)

_V1_6_298_RE_NEGATION_CONTEXT = re.compile(
    r"\b(" + r"|".join(_V1_6_298_NEGATION_PATTERNS) + r")\b",
    re.IGNORECASE,
)

# v1.6.298 — POSITIVE-SUPPORT regex with negative-lookbehind guards to
# stop the embedded POSITIVE word inside a negation phrase from being
# counted as a positive marker. Closes the v1.6.297 corner case where
# "not implemented" was simultaneously a NEG hit (covering the whole
# phrase) AND a POS hit (covering just `implemented`), so the
# `closest_distance` calculation pulled POSITIVE closer than NEG even
# in disclaim-only prose.
#
# The lookbehinds also handle the spec-style "this core does not /
# never implement", "shall not / must not" prefixes. Chip-AGNOSTIC.
_V1_6_298_RE_POSITIVE_SUPPORT = re.compile(
    r"(?<!not\s)"
    r"(?<!never\s)"
    r"(?<!shall\snot\s)"
    r"(?<!must\snot\s)"
    r"(?<!does\snot\s)"
    r"(?<!cannot\s)"
    r"\b(supports?|implement(?:s|ed)?|provides?|"
    r"available|present|enabled)\b",
    re.IGNORECASE,
)


def _v1_6_298_isa_context_accepts(text: str,
                                   match_start: int,
                                   match_end: int) -> bool:
    """v1.6.298 — for #193 round-2 NOT VERIFIED.

    Accept rule:

      1. Find the sentence that fully contains the candidate match.
         If that sentence matches the extended negation vocabulary
         (`implements only`, `M-mode only`, `does not support`,
         `reserved`, `not implemented`, `shall not`, ...), REJECT
         immediately. Sentence-local negation outranks any positive
         marker, ever.

      2. Otherwise, fall back to the v1.6.297 ±200-char closest-
         distance comparison using the extended negation vocabulary.
         The POSITIVE-SUPPORT regex uses negative-lookbehind guards
         so the trailing POSITIVE word inside a NEG phrase
         (`not implemented`) is no longer double-counted.

    The asymmetric tier ordering — SAME-SENT negation is hard reject,
    but SAME-SENT positive does NOT immediately accept — handles the
    real-benchmark pattern where the CHIP-LEVEL CONSTRAINT sentence
    is in a different sentence from the inherited SPEC NARRATIVE
    (which lists every mode). E.g.:

      Sentence A: "RISC-V supports Machine, Supervisor, User,
                   Hypervisor modes."   (positive, names every mode)
      Sentence B: "This CPU implements only Machine and User."
                                        (chip-level constraint)

      For `Supervisor` in sentence A:
        - same-sent has POS but not NEG -> fall through to ±200-char
        - ±200-char closest-distance comparison sees NEG closer
          than POS -> reject.

    Chip-AGNOSTIC: open-standard spec disclaim vocabulary only.
    """
    if not isinstance(text, str) or not text:
        return True
    sent_start = 0
    for m in _V1_6_298_RE_SENTENCE_BOUNDARY.finditer(text, 0, match_start):
        sent_start = m.end()
    m_end = _V1_6_298_RE_SENTENCE_BOUNDARY.search(text, match_end)
    sent_end = m_end.start() if m_end else len(text)
    sentence = text[sent_start:sent_end]
    # Tier 1 hard-reject: SAME-SENT negation always wins.
    if _V1_6_298_RE_NEGATION_CONTEXT.search(sentence):
        return False
    # Tier 2: ±200-char closest-distance fallback (extended vocab).
    w = _V1_6_297_ISA_CONTEXT_WINDOW
    lo = max(0, match_start - w)
    hi = min(len(text), match_end + w)
    d_neg = _v1_6_297_closest_distance(
        text, match_start, _V1_6_298_RE_NEGATION_CONTEXT, lo, hi)
    d_pos = _v1_6_297_closest_distance(
        text, match_start, _V1_6_298_RE_POSITIVE_SUPPORT, lo, hi)
    if d_neg is None:
        return True
    if d_pos is None:
        return False
    return d_pos <= d_neg


# v1.6.298 — Option C constraint-sentence whitelist. When the chip
# doc has a chip-LOCAL constraint sentence ("This CPU implements only
# Machine and User.", "This implementation is M-mode only.") that
# carries a NEG-vocabulary marker (`implements only`, `M-mode only`,
# `does not support`), extract the WHITELIST of canonical modes that
# this constraint sentence permits. The downstream prose scan then
# rejects any mode NOT in the whitelist when the doc has at least
# one constraint sentence. This handles the spec-narrative-vs-chip-
# constraint split that Option A's closest-distance + Option B's
# explicit-table both miss when the doc has neither an explicit
# table NOR a strictly inline negation.
#
# The constraint-sentence detector recognises these forms:
#   (1) `implements? only <mode1> [, <mode2>] [and <mode3>]`
#   (2) `supports? only <mode1> ...`
#   (3) `<M|machine>-mode only` / `only <M|machine> mode`
# Form 3 implies whitelist = {Machine} (M-mode-only architecture).
# Chip-AGNOSTIC: open-standard spec phrasing, RISC-V mode names.
_V1_6_298_RE_CONSTRAINT_SENT_LIST = re.compile(
    r"(?:implements?|supports?|provides?)\s+only\s+"
    r"((?:[A-Za-z]\w*(?:\s+mode)?"
    r"(?:\s*[,/]\s*[A-Za-z]\w*(?:\s+mode)?)*"
    r"(?:\s+and\s+[A-Za-z]\w*(?:\s+mode)?)?))",
    re.IGNORECASE,
)
_V1_6_298_RE_M_MODE_ONLY = re.compile(
    r"\b(?:M[\-\s]?mode\s+only|only\s+(?:M|machine)\s*[\-\s]?mode\b)",
    re.IGNORECASE,
)
_V1_6_298_MODE_NAME_CANON = ("Machine", "Supervisor", "User", "Hypervisor")


def _v1_6_298_find_constraint_mode_whitelist(
        text: str) -> Optional[Set[str]]:
    """v1.6.298 — for #193 round-2 NOT VERIFIED. Scan the doc for a
    chip-LOCAL constraint sentence (`implements only X and Y`,
    `M-mode only`, ...). When found, return the SET of canonical
    mode names this constraint permits. Returns None when no
    constraint sentence is present (caller does NOT apply the
    whitelist gate and falls back to prose scan with v1.6.297
    closest-distance).

    Chip-AGNOSTIC: RISC-V Privileged Spec mode-name vocabulary +
    standard English phrasing.
    """
    if not isinstance(text, str) or not text:
        return None
    whitelist: Set[str] = set()
    # Form 1/2: "implements only X[, Y][ and Z][ modes?]".
    for m in _V1_6_298_RE_CONSTRAINT_SENT_LIST.finditer(text):
        clause = m.group(1) or ""
        # Pull every canonical-mode-name token from the captured
        # clause. The clause syntax is "Machine and User" or
        # "Machine, Supervisor and User" -- comma/and-separated.
        for tok in re.finditer(r"\b([A-Za-z]+)\b", clause):
            cand = tok.group(1).capitalize()
            if cand in _V1_6_298_MODE_NAME_CANON:
                whitelist.add(cand)
    # Form 3: "M-mode only" / "only M-mode" / "only Machine-mode" →
    # implies whitelist = {Machine}.
    if _V1_6_298_RE_M_MODE_ONLY.search(text):
        whitelist.add("Machine")
    return whitelist if whitelist else None


# Option B — explicit-privilege-table anchor. When the chip doc has
# a markdown table whose header is `| Privilege Mode |`, parse the
# rows and use ONLY those as the privilege-modes truth. Skips the
# prose scan entirely — defensive against spec-verbatim narrative
# that names every RISC-V mode while the table lists only the
# implemented subset.
_V1_6_298_RE_EXPLICIT_PRIVILEGE_DECL = re.compile(
    r"^\|\s*Privilege\s+Mode\b[^\n]*\|\s*\n"
    r"^\|[-:\s|]+\|\s*\n",
    re.MULTILINE | re.IGNORECASE,
)

_V1_6_298_RE_PRIV_MODE_NAME = re.compile(
    r"\b(Machine|Supervisor|User|Hypervisor)\b",
    re.IGNORECASE,
)


def _v1_6_298_find_explicit_privilege_table_modes(
        text: str) -> Optional[List[str]]:
    """v1.6.298 — for #193 round-2 NOT VERIFIED. When the doc carries
    an explicit markdown table whose header column is `Privilege Mode`,
    parse the immediately following table rows and return the list of
    mode names that appear in the first cell. Returns None when no
    such table is present (caller falls back to prose scan).

    Chip-AGNOSTIC: standard markdown pipe-table syntax + RISC-V
    privileged-spec mode names only.
    """
    if not isinstance(text, str) or not text:
        return None
    m = _V1_6_298_RE_EXPLICIT_PRIVILEGE_DECL.search(text)
    if not m:
        return None
    # Walk the table body row-by-row starting at the line after the
    # `|---|` separator (which is at m.end()). A row is a line that
    # starts with `|`; stop at the first non-row line.
    body_start = m.end()
    modes: List[str] = []
    seen: Set[str] = set()
    for line in text[body_start:].splitlines():
        stripped = line.strip()
        if not stripped.startswith("|"):
            break
        cells = [c.strip() for c in stripped.split("|") if c.strip()]
        if not cells:
            continue
        # The mode name lives in the first non-empty cell. Match the
        # first canonical mode token within it.
        first_cell = cells[0]
        name_m = _V1_6_298_RE_PRIV_MODE_NAME.search(first_cell)
        if not name_m:
            continue
        mode = name_m.group(1).capitalize()
        if mode in seen:
            continue
        seen.add(mode)
        modes.append(mode)
    return modes if modes else None


def _v1_6_297_closest_distance(text: str, anchor: int,
                                pattern: "re.Pattern[str]",
                                lo: int, hi: int) -> Optional[int]:
    """Return the absolute character distance from `anchor` to the
    nearest `pattern` match within `[lo, hi)` window, or None when
    `pattern` doesn't match anywhere in the window.

    Distance is measured from `anchor` to the closest edge of the
    match span (not midpoint), so adjacent prose has distance 0..1.
    """
    closest: Optional[int] = None
    for m in pattern.finditer(text, lo, hi):
        # Closest edge of match span to anchor.
        if m.end() <= anchor:
            d = anchor - m.end()
        elif m.start() >= anchor:
            d = m.start() - anchor
        else:
            d = 0
        if closest is None or d < closest:
            closest = d
    return closest


def _v1_6_297_isa_context_accepts(text: str,
                                   match_start: int,
                                   match_end: int) -> bool:
    """v1.6.297 — for #193 ORGANIC. Decide whether a candidate
    ISA-extension / privilege-mode token match should be accepted as
    a real positive evidence hit.

    Walks the ±200-char window around the match and looks for the
    CLOSEST negation marker and the CLOSEST positive support marker.
    Reject the match when:
      (a) only the negation marker is present in window, OR
      (b) both markers are present but the negation marker is
          STRICTLY CLOSER to the match span than the positive
          marker.

    The closest-keyword logic implements the issue-body guidance
    `"the per-token window must include the closest keyword"` — a
    paragraph like `"supports Zicsr ... The Zfh extension is
    reserved"` rejects Zfh because `reserved` is closer to Zfh than
    `supports`.

    Chip-AGNOSTIC: open-standard spec disclaim vocabulary.
    """
    if not isinstance(text, str) or not text:
        return True
    w = _V1_6_297_ISA_CONTEXT_WINDOW
    lo = max(0, match_start - w)
    hi = min(len(text), match_end + w)
    d_neg = _v1_6_297_closest_distance(
        text, match_start, _V1_6_297_RE_NEGATION_CONTEXT, lo, hi)
    d_pos = _v1_6_297_closest_distance(
        text, match_start, _V1_6_297_RE_POSITIVE_SUPPORT, lo, hi)
    if d_neg is None:
        # No negation prose anywhere in window — accept.
        return True
    if d_pos is None:
        # Negation in window, no positive marker — reject.
        return False
    # Both markers present — prefer the closer one. Equal distance
    # falls through to accept (positive wins on tie).
    return d_pos <= d_neg


# v1.6.309 — for #208 ORGANIC. Width-anchor + negation-window helpers
# used by `_extract_l1_isa_classification` to filter inherited RISC-V
# Privileged-Spec boilerplate that mentions RV64* tokens in 32-bit-only
# cores (and vice-versa). The bare `_RE_ISA_BASE` regex previously
# matched every RV(32|64)... token regardless of whether the chip
# itself declares a specific datapath width, so any doc tree that
# quotes the reference appendix verbatim leaked the wrong-width tokens
# into `L1.isa_base`. The two helpers below operate independently:
#   * `_v1_6_309_isa_base_width_constraint` returns the chip's declared
#     width when it appears anchored to a noun like "processor" /
#     "core" / "ISA" / "CPU"; otherwise None.
#   * `_v1_6_309_isa_base_negation_window` returns True when a
#     ±100-char prose window around the token contains common
#     negation language ("does not support", "future work", etc.).
# Chip-AGNOSTIC: anchor + negation vocabulary is shared across the
# RISC-V ecosystem regardless of which core's docs land in front of
# the picker.
def _v1_6_309_isa_base_width_constraint(text: str) -> Optional[str]:
    """v1.6.309 — for #208 ORGANIC. Return `"RV32"` / `"RV64"` /
    `None` if the document anchors a specific datapath width by
    naming `<width>-bit (processor|core|ISA|CPU)` in prose. The
    helper is intentionally conservative — if the doc never anchors
    a width, both widths are still allowed through the caller
    (existing v1.6.308- behaviour preserved).
    """
    if not isinstance(text, str) or not text:
        return None
    if re.search(r"\b32[\-\s]bit\s+(processor|core|ISA|CPU)",
                 text, re.IGNORECASE):
        return "RV32"
    if re.search(r"\b64[\-\s]bit\s+(processor|core|ISA|CPU)",
                 text, re.IGNORECASE):
        return "RV64"
    return None


def _v1_6_309_isa_base_negation_window(text: str,
                                        match_start: int,
                                        match_end: int) -> bool:
    """v1.6.309 — for #208 ORGANIC. Return True when a ±100-char
    window around `[match_start, match_end)` contains negation /
    disclaimer prose: "not", "does not support",
    "compatible with", "future work", "future extension",
    "excludes" / "exclude", "shall not". The exact patterns that
    appear in inherited Privileged-Spec appendices when a core
    explicitly lists the standard tokens it does NOT implement.
    Chip-AGNOSTIC: open-standard RISC-V ecosystem vocabulary.
    """
    if not isinstance(text, str) or not text:
        return False
    window = text[max(0, match_start - 100): match_end + 100]
    return bool(re.search(
        r"\b(not|does\s+not\s+support|compatible\s+with|"
        r"future\s+(?:work|extension)|excludes?|"
        r"shall\s+not)\b",
        window, re.IGNORECASE))


# v1.6.437 — for #313 P2 ORGANIC. Reference-PDF / appendix shape
# deny-list for ISA detector. Vendor doc trees commonly ship the
# RISC-V International standards-body reference PDFs (asm spec,
# privileged spec, unprivileged spec, debug spec, c-api, calling
# convention, semihosting) as appendix material alongside the
# chip's own implementation docs. The standards-body PDFs document
# the entire ISA universe (RV32 + RV64 + Hypervisor + every
# extension) regardless of what the chip implements, so when the
# ISA-base regex mines those PDFs it leaks wrong-width / wrong-set
# tokens into `L1.isa_base`. Real-world evidence: a 32-bit-only
# RV core saw `RV64I` / `RV64E` promoted from
# `references/<ISA-spec-A>.pdf` evidence.
#
# Fix: a filename-shape deny-list (path patterns + canonical
# standards-body PDF stem patterns). Any extracted doc whose
# source filename matches the deny-list is excluded from the
# ISA-classification walker entirely. Chip-AGNOSTIC: the patterns
# describe standards-body distribution shape, not any particular
# chip's source path.
_V1_6_437_REFERENCE_PDF_DENY = (
    r"(?:^|/)references?/",
    r"(?:^|/)reference[_\-]?docs?/",
    r"(?:^|/)appendix(?:es|s)?/",
    r"(?:^|/)appendices/",
    r"(?:^|/)standards?/",
    # canonical RISC-V International stem-name patterns
    r"riscv[_\-]?spec",
    r"riscv[_\-]?(?:asm|c[_\-]?api|privileged|unprivileged|"
    r"debug[_\-]?spec(?:ification)?|calling|semihosting)",
    r"unprivileged[_\-]?(?:isa|spec)",
    r"privileged[_\-]?(?:spec|architecture|isa)",
    # other ISA-spec patterns (MIPS, ARM, AMBA reference manuals)
    r"(?:mips|arm|amba)[_\-]?(?:isa|reference[_\-]?manual)",
)


def _v1_6_437_is_reference_appendix(filename: str) -> bool:
    """v1.6.437 — for #313 P2 ORGANIC. Return True when `filename`
    looks like a standards-body reference / appendix doc shipped
    alongside the chip's implementation docs. Such docs document
    the entire ISA universe and pollute the ISA-base detector with
    wrong-width / wrong-set tokens. Chip-AGNOSTIC: filename-shape
    only, no chip-name literals."""
    if not isinstance(filename, str) or not filename:
        return False
    fn = filename.lower()
    for pat in _V1_6_437_REFERENCE_PDF_DENY:
        if re.search(pat, fn, re.IGNORECASE):
            return True
    return False


# v1.6.438 — for #314 P2 ORGANIC. L9 chip_top_interfaces /
# interface_types corroboration filter. The base detector flags any
# prose mention of a bus / interface acronym (TileLink, AXI, AHB,
# Wishbone, Ethernet, PCIe, etc.) as if the IC implements it. On
# real benchmarks vendor docs commonly contain aside / comparison
# / legal-notice prose that mentions interfaces the chip does NOT
# implement ("like TileLink or the AMBA AXI", "sophisticated
# interfaces like Ethernet"). Those false positives propagate
# downstream into Phase 2 spec-to-rtl, generating wrong protocol
# wrappers; FPGA pin maps reserve PHY pads that don't exist; STA
# floorplans reserve area for IP that isn't there.
#
# Corroboration rule: a candidate interface must have at least one
# structural signal in the chip-tree text:
#   * a heading line whose anchor names the interface
#   * a port-name shape that carries the interface token
#   * a dedicated doc/rtl file whose name contains the interface
#     token (the runner inspects the project tree as additional
#     evidence)
# If no signal corroborates, the candidate is rejected as aside
# prose. Chip-AGNOSTIC: pure structural anchors.
def _v1_6_438_corroborate_interface_list(
        iface_list, text, project=None):
    """v1.6.438 — for #314 P2 ORGANIC. Filter the
    `detect_interface_types_from_readme` output through a
    corroboration gate. Returns the filtered list; preserves
    order and any extra dict keys. Inputs / outputs:
      * `iface_list` — list of dicts as emitted by
        `detect_interface_types_from_readme`; each dict has at
        least `name` and `matched_token`.
      * `text` — the same concatenated chip-tree text the detector
        saw (readme + chip_root_docs + sphinx subtrees).
      * `project` — optional Path; when supplied, the helper also
        scans the chip's doc/rtl directory tree for filenames
        carrying the interface token as a third corroboration
        signal (`dedicated_file`).
    """
    if not iface_list:
        return iface_list
    if not isinstance(text, str):
        text = ""
    text_lower = text.lower()
    # Optional file-tree scan.
    tree_filenames = []
    if project is not None:
        try:
            for sub in ("docs", "rtl", "input/docs", "input/rtl",
                        "phase1/input_doc"):
                p = project / sub
                if p.is_dir():
                    for fp in p.rglob("*"):
                        if fp.is_file():
                            tree_filenames.append(fp.name.lower())
        except Exception:
            tree_filenames = []
    filtered = []
    for entry in iface_list:
        if not isinstance(entry, dict):
            continue
        name = entry.get("name")
        token = entry.get("matched_token") or name
        if not name or not isinstance(name, str):
            continue
        if _v1_6_438_is_corroborated_interface(
                str(name), str(token or name), text_lower, tree_filenames):
            filtered.append(entry)
    return filtered


def _v1_6_438_is_corroborated_interface(
        iface_name, iface_token, text_lower, tree_filenames):
    """v1.6.438 — for #314 P2 ORGANIC. Return True when the
    interface candidate has at least one of three structural
    corroboration signals in `text_lower` / `tree_filenames`:
      (a) heading_anchor — a markdown/RST/AsciiDoc heading line
          whose own text contains the interface token
      (b) port_table — a port-name shape carrying the interface
          token (e.g. `axi_awvalid`, `awvalid_o`, `tlul_*`,
          `eth_tx_*`); pipe-table cells `|<port>|` count too
      (c) dedicated_file — a filename under the chip's doc/rtl
          tree whose base name contains the interface token
    """
    name_low = (iface_name or "").lower()
    token_low = (iface_token or iface_name or "").lower()
    candidate_anchors = {a for a in (name_low, token_low) if a}
    if not candidate_anchors:
        return False
    # Avoid bare 1-or-2-char tokens that match noise; require at
    # least 3 chars to anchor a heading or port name.
    canonical = max(candidate_anchors, key=len)
    if len(canonical) < 3:
        # Short tokens fall through to port_table / dedicated_file
        # signals only — heading-anchor for 2-char names like `i2c`
        # is still meaningful, but anything shorter is noise.
        if len(canonical) < 2:
            return False
    # (a) heading_anchor — match line that starts with #/=/-/*/+
    # markup followed by the canonical token. The anchor only needs
    # to begin a word-boundary; trailing chars are open so that
    # `axi4` corroborates the `axi` anchor (variant suffix), but
    # `flexitarian` does NOT (no word-boundary before `axi`).
    for anchor in candidate_anchors:
        if not anchor:
            continue
        # Markdown ATX heading: `# AXI`, `## AXI4 Interface`
        if re.search(
                r"^[ \t]*\#{1,6}[ \t]+[^\n]*\b" + re.escape(anchor),
                text_lower, re.MULTILINE):
            return True
        # AsciiDoc / RST level-N: `== AXI ==` / `=== AXI ===`
        if re.search(
                r"^[ \t]*={1,6}[ \t]+[^\n]*\b" + re.escape(anchor),
                text_lower, re.MULTILINE):
            return True
        # RST underline shape: token on its own line followed by
        # = / - / ~ / ^ / * underline.
        if re.search(
                r"^[ \t]*[^\n]*\b" + re.escape(anchor) + r"[^\n]*\n"
                r"[ \t]*[=\-~\^\*]{3,}[ \t]*$",
                text_lower, re.MULTILINE):
            return True
    # (b) port_table — port-name shape carrying the token (allow
    # 1-3 char wildcards on each side for prefix/suffix variants).
    for anchor in candidate_anchors:
        if not anchor:
            continue
        # Pipe-table cell with a port-name containing the anchor:
        # `| axi_awvalid |`, `| tlul_a_valid |`.
        if re.search(
                r"\|\s*[A-Za-z0-9_]*\b" + re.escape(anchor) +
                r"[A-Za-z0-9_]*\s*\|",
                text_lower):
            return True
        # Verilog port declaration: `axi_awvalid_i`,
        # `output logic eth_tx_valid`. Look for the anchor inside an
        # identifier-shape token.
        if re.search(
                r"\b[A-Za-z0-9_]*" + re.escape(anchor) +
                r"_[A-Za-z0-9_]+\b",
                text_lower):
            return True
    # (c) dedicated_file — filename in the project tree carrying the
    # interface token.
    for fname in tree_filenames or ():
        for anchor in candidate_anchors:
            if not anchor:
                continue
            if anchor in fname:
                # Reject standards-body reference shapes (handled by
                # v1.6.437) — those are aside material, not chip
                # corroboration.
                if _v1_6_437_is_reference_appendix(fname):
                    continue
                return True
    return False


# v1.6.457 — for #329 P2 ORGANIC. Extend the
# `_INTERFACE_TOKEN_PATTERNS` vocab living in
# `readme_class_detector.py` with common peripheral protocol
# buckets that the base table misses. Real-benchmark evidence:
# the canonical README enumerates 11 peripherals (`SPI`, `SDI`,
# `TWI`, `TWD`, `ONEWIRE`/`1-wire`, `JTAG`, `GPIO`, `PWM`, plus
# custom open-source IPs); the base detector captures only the
# bus-class tokens (UART / AXI / SDcard / I2C / SPI is missing
# from the AXI-centric base table) — 3 of 11 land in
# `L9.chip_top_interfaces`.
#
# Strategy: post-pass extension. After
# `detect_interface_types_from_readme` returns, run a sibling
# scan with the extended vocab and union its corroborated hits
# into the existing list. The same v1.6.438 corroboration gate
# applies — each candidate must have a heading anchor OR port-
# name shape OR dedicated-file before landing.
#
# Chip-AGNOSTIC: every token is an open industry-standard
# protocol name (no chip-class literals).
_V1_6_457_EXTRA_INTERFACE_PATTERNS: List[Tuple[str, "re.Pattern[str]"]] = [
    ("spi",      re.compile(r"\bSPI\b(?!\-?slave)", re.IGNORECASE)),
    ("jtag",     re.compile(
        r"\bJTAG(?:[-\s]?(?:DTM|TAP|debug))?\b", re.IGNORECASE)),
    ("gpio",     re.compile(
        r"\bGPIO\b|\bgeneral[-\s]?purpose\s+I/?O\b", re.IGNORECASE)),
    ("pwm",      re.compile(
        r"\bPWM\b|\bpulse[-\s]?width\s+modulation\b", re.IGNORECASE)),
    # I2C variants — TWI / TWD are the open-spec alternate names
    # for I²C / I2C (NXP / Atmel / Microchip canonical convention).
    ("i2c",      re.compile(
        r"\bI[²2]C\b|\bTWI\b|\bTWD\b|\btwo[-\s]?wire\b", re.IGNORECASE)),
    ("onewire",  re.compile(
        r"\b(?:1[-\s]?Wire|OneWire|ONEWIRE|one[-\s]?wire)\b",
        re.IGNORECASE)),
    ("can",      re.compile(
        r"\bCAN[-\s]?(?:FD|bus)?\b", re.IGNORECASE)),
    ("i2s",      re.compile(
        r"\bI[²2]S\b", re.IGNORECASE)),
    ("spi-slave",re.compile(
        r"\bSDI\b|\bSPI[-\s]?slave\b", re.IGNORECASE)),
    ("sdio",     re.compile(
        r"\bSDIO\b|\bSD/?MMC\b", re.IGNORECASE)),
]


# v1.6.479 — for #344 P2 ORGANIC. CAN-bus vocab collides with the
# English modal verb `can` in IGNORECASE prose. Field-agent at
# v1.6.477 (8-IC benchmark): 4 of 8 RV-CPU ICs emit spurious
# `chip_top_interfaces[].name = "can"` because README prose has
# hundreds of `the core can issue`, `can be configured`, `can
# transition` occurrences — the bare lowercase token matches the
# v1.6.457 regex `\bCAN[-\s]?(?:FD|bus)?\b` under IGNORECASE.
#
# Fix shape (chip-AGNOSTIC, post-filter at hit time):
#   1. If the matched literal is ALL-CAPS (`CAN`, `CANbus`, `CAN-FD`,
#      `CAN-bus`), accept — protocol acronym convention.
#   2. If the matched literal is mixed-case (`Can`, `CanBus`,
#      `Canbus` — vendor doc capitalisation) accept.
#   3. If the matched literal is lowercase (`can`, `canbus`, `can-fd`),
#      REQUIRE a CAN-context noun within ±80 chars: bus / controller
#      / frame / bit-rate / protocol / transceiver / PHY / node / FD /
#      payload / arbitration / `controller area network`. Reject when
#      no context noun is found (English modal verb leak).
# Chip-AGNOSTIC: CAN is a public open-standard protocol; the context
# vocab is also open-standard (transceiver / frame / arbitration /
# bit-rate are universal CAN terminology).
_V1_6_479_CAN_CONTEXT_RE = re.compile(
    r"\b(?:"
    r"bus|controller|frame|bit[\-\s]?rate|protocol|"
    r"transceiver|PHY|node|FD|payload|arbitration|"
    r"controller\s+area\s+network"
    r")\b",
    re.IGNORECASE,
)


def _v1_6_479_can_match_is_modal_verb(
        matched_literal: str, text: str, match_offset: int) -> bool:
    """v1.6.479 — for #344 P2 ORGANIC. Return True iff the matched
    literal looks like the English modal verb `can` (lowercase + no
    CAN-context noun within ±80 chars) rather than the CAN-bus
    protocol acronym. Mixed-case / all-caps literals always pass
    (False return). Chip-AGNOSTIC.
    """
    if not matched_literal or not isinstance(matched_literal, str):
        return False
    lit = matched_literal.strip()
    if not lit:
        return False
    # Acronym shape (any uppercase letter present) → accept.
    if any(ch.isupper() for ch in lit):
        return False
    # Pure lowercase → context check required.
    if not text or not isinstance(text, str):
        return True  # no surrounding text to corroborate
    span_lo = max(0, int(match_offset) - 80)
    span_hi = min(len(text), int(match_offset) + len(lit) + 80)
    window = text[span_lo:span_hi]
    return _V1_6_479_CAN_CONTEXT_RE.search(window) is None


# v1.6.486 — for #344 R2 ORGANIC. v1.6.479's acronym-shape branch
# accepted *any* uppercase letter as evidence of the CAN-bus protocol
# acronym, which let sentence-start `Can ` (English modal-verb
# capitalisation) and other mixed-case modal-verb shapes such as
# `Can be used` slip through. v1.6.479's context vocab (`bus`,
# `node`, `frame`) was also too broad — those are universal CPU /
# SoC nouns and they trip the lowercase branch in pure RV prose
# such as `the system bus` / `node in the pipeline` / `frame of
# data`.
#
# Tighten:
#   (a) Only ALL-CAPS `CAN` (or all-caps `CAN-FD` / `CAN-bus` /
#       `CANbus` etc.) is accepted unconditionally — the acronym
#       convention is strict.
#   (b) Mixed-case `Can` / lowercase `can` now require an explicit
#       CAN-bus vocab token (`can bus`, `canopen`, `can-fd`,
#       `iso 11898`, `controller area network`, `can transceiver`,
#       `can controller`) inside the ±80-char window. The narrow
#       vocab eliminates `bus` / `node` / `frame` false positives.
#
# Chip-AGNOSTIC: CAN is a public open-standard protocol; CANopen
# and ISO 11898 are open industry standards; no chip-class literal
# participates.
_V1_6_486_CAN_CONTEXT_VOCAB: Tuple[str, ...] = (
    "can bus", "canopen", "canfd", "can-fd", "can 2.0",
    "iso 11898", "controller area network",
    "can transceiver", "can controller",
)


def _v1_6_486_is_can_bus_acronym(
        literal: str, context_window: str) -> bool:
    """v1.6.486 — for #344 R2 ORGANIC. Strict: return True iff the
    matched literal is the CAN-bus protocol acronym (not the English
    modal verb).

    Rules:
      - All-caps `CAN` (or any all-caps shape such as `CAN-FD`,
        `CANbus`) → accept unconditionally.
      - Mixed-case `Can` / lowercase `can` → accept only when an
        explicit CAN-bus vocab token (`can bus`, `canopen`,
        `can-fd`, `can 2.0`, `iso 11898`, `controller area
        network`, `can transceiver`, `can controller`) is present
        anywhere in the ±80-char window passed by the caller.

    Chip-AGNOSTIC: pure open-standard vocab.
    """
    if not literal or not isinstance(literal, str):
        return False
    lit = literal.strip()
    if not lit:
        return False
    # (a) All-caps standalone `CAN` → accept (acronym convention).
    if lit == "CAN":
        return True
    # All-caps `CAN` head — e.g. `CAN-FD`, `CAN-bus`, `CAN bus`,
    # `CANbus`, `CAN-BUS`, `CANBUS`, `CANFD`. The acronym head
    # `CAN` itself must be all upper-case. Pre-v1.6.486 the test
    # was `any uppercase letter`, which let `Can` / `CanBus`
    # (sentence-start / vendor mixed-case modal-verb shapes)
    # through.
    if lit.startswith("CAN") and (
            len(lit) == 3 or not lit[3].isalpha() or lit[3].isupper()):
        return True
    # (b) Mixed-case `Can` / lowercase `can` requires explicit
    # CAN-bus vocab token in the window.
    ctx_lc = (context_window or "").lower()
    return any(v in ctx_lc for v in _V1_6_486_CAN_CONTEXT_VOCAB)


def _v1_6_457_detect_extra_interfaces(text: str) -> List[Dict[str, Any]]:
    """v1.6.457 — for #329 P2 ORGANIC. Scan `text` for the
    extended peripheral-protocol vocab. Returns a list of dicts
    matching the `detect_interface_types_from_readme` shape:
        {"name": str, "matched_token": str, "occurrences": int}.

    Chip-AGNOSTIC: pure open-standard protocol-name vocab; no
    chip-class literal participates.

    v1.6.479 — for #344 P2 ORGANIC. CAN-bus vocab gets an extra
    post-filter: when the matched literal is lowercase, require a
    CAN-context noun (`bus`, `controller`, `frame`, `bit-rate`,
    `protocol`, `transceiver`, `PHY`, `node`, `FD`, `payload`,
    `arbitration`, `controller area network`) within ±80 chars;
    reject otherwise as English modal-verb false-positive. The
    filter is bucket-scoped to `"can"` so SPI / JTAG / GPIO / etc.
    behave identically to pre-v1.6.479.

    v1.6.486 — for #344 R2 ORGANIC. Supersede v1.6.479: the
    acronym-shape branch (`any uppercase letter present → accept`)
    let sentence-start `Can ` (English modal-verb capitalisation)
    through, and the v1.6.479 context vocab (`bus` / `node` /
    `frame`) was too broad — those are universal CPU / SoC nouns.
    The v1.6.486 helper requires ALL-CAPS `CAN` for unconditional
    acceptance and narrows the context vocab to CAN-bus-specific
    terms only (`can bus`, `canopen`, `can-fd`, `iso 11898`,
    `controller area network`, `can transceiver`, `can
    controller`). Other buckets (SPI / JTAG / GPIO / etc.) remain
    unchanged.
    """
    if not text or not isinstance(text, str):
        return []
    out: List[Dict[str, Any]] = []
    for bucket_name, pat in _V1_6_457_EXTRA_INTERFACE_PATTERNS:
        hits = list(pat.finditer(text))
        if not hits:
            continue
        # v1.6.486 — for #344 R2 ORGANIC. CAN-bucket strict acronym
        # gate. Supersedes the v1.6.479 modal-verb filter: only
        # all-caps `CAN` (or any all-caps composite such as `CAN-FD`)
        # is accepted unconditionally; mixed-case `Can` / lowercase
        # `can` requires an explicit CAN-bus vocab token within the
        # ±80-char window (`can bus`, `canopen`, `can-fd`,
        # `iso 11898`, `controller area network`, `can transceiver`,
        # `can controller`). Eliminates the sentence-start `Can be
        # used` leak and the over-broad context vocab (`bus` /
        # `node` / `frame`) of v1.6.479.
        if bucket_name == "can":
            real_hits = []
            for h in hits:
                span_lo = max(0, h.start() - 80)
                span_hi = min(len(text), h.end() + 80)
                window = text[span_lo:span_hi]
                if _v1_6_486_is_can_bus_acronym(h.group(0), window):
                    real_hits.append(h)
            if not real_hits:
                # All matches were English modal-verb usages; drop
                # the bucket entirely.
                continue
            hits = real_hits
        # Pick the first match's literal as the canonical
        # matched_token (preserving original casing).
        token = hits[0].group(0)
        out.append({
            "name": bucket_name,
            "matched_token": token,
            "occurrences": len(hits),
            "extraction_strategy":
                "readme_interface_vocab_extended_v1_6_457",
        })
    return out


def _v1_6_457_merge_extra_interfaces(
        iface_list: List[Dict[str, Any]],
        text: str,
        project=None) -> List[Dict[str, Any]]:
    """v1.6.457 — merge the extended-vocab hits into `iface_list`,
    deduping by canonical bucket name. Each new candidate runs
    through the v1.6.438 corroboration gate before landing so
    aside / comparison prose (`like SPI or JTAG`) is rejected.

    Chip-AGNOSTIC: structural pipeline only.
    """
    extras = _v1_6_457_detect_extra_interfaces(text or "")
    if not extras:
        return iface_list or []
    # Corroborate the extras through the v1.6.438 gate so aside
    # prose ("like SPI or JTAG") never lands.
    corroborated_extras = _v1_6_438_corroborate_interface_list(
        extras, text or "", project)
    if not corroborated_extras:
        return iface_list or []
    existing_names = set()
    for entry in iface_list or []:
        if isinstance(entry, dict):
            n = entry.get("name")
            if isinstance(n, str):
                existing_names.add(n.lower())
    merged = list(iface_list or [])
    for entry in corroborated_extras:
        n = entry.get("name", "").lower()
        if n and n not in existing_names:
            merged.append(entry)
            existing_names.add(n)
    return merged


def _extract_l1_isa_classification(
        extracted: Dict[str, str]) -> Dict[str, Any]:
    """v1.6.289 — for #159 ORGANIC. Walk every extracted doc text +
    return a dict with typed `isa_base` / `isa_extensions` /
    `privilege_modes` / `endianness` / `machine_isa_version` keys
    and matching `_evidence` siblings. Empty mapping when no token
    matches. Chip-AGNOSTIC: open-standard ISA vocabulary only.

    v1.6.437 — for #313 P2 ORGANIC. Filter out evidence whose source
    filename matches the standards-body reference / appendix deny
    list. Vendor doc trees ship copies of the RISC-V International
    reference PDFs as appendix material; those documents mention
    the entire ISA universe regardless of what the chip implements
    and were polluting `L1.isa_base` with wrong-width tokens."""
    out: Dict[str, Any] = {}
    if not extracted:
        return out
    isa_bases: List[str] = []
    isa_exts: List[str] = []
    priv_modes: List[str] = []
    endians: List[str] = []
    machine_ver: Optional[str] = None
    base_ev: List[Dict[str, Any]] = []
    ext_ev: List[Dict[str, Any]] = []
    priv_ev: List[Dict[str, Any]] = []
    endian_ev: List[Dict[str, Any]] = []
    seen_base: Set[str] = set()
    seen_ext: Set[str] = set()
    seen_priv: Set[str] = set()
    seen_endian: Set[str] = set()
    # v1.6.298 — for #193 round-2 NOT VERIFIED. Option B: when ANY
    # extracted doc has an explicit `| Privilege Mode |` markdown
    # table, use that table as the canonical privilege-modes truth
    # and short-circuit the prose scan for privilege modes. ISA-base
    # / ISA-extension / endianness scans still run normally because
    # the table only covers privilege modes.
    priv_table_short_circuit: Optional[List[str]] = None
    priv_table_source_file: Optional[str] = None
    priv_table_source_line: Optional[int] = None
    for fname, text in extracted.items():
        if not isinstance(text, str) or not text:
            continue
        # v1.6.437 — for #313 P2 ORGANIC. Skip standards-body
        # reference / appendix PDFs entirely; they describe the full
        # ISA universe regardless of chip implementation.
        if _v1_6_437_is_reference_appendix(fname):
            continue
        priv_table_modes = (
            _v1_6_298_find_explicit_privilege_table_modes(text))
        if priv_table_modes:
            priv_table_short_circuit = priv_table_modes
            priv_table_source_file = fname
            tab_m = _V1_6_298_RE_EXPLICIT_PRIVILEGE_DECL.search(text)
            if tab_m:
                priv_table_source_line = (
                    text[: tab_m.start()].count("\n") + 1)
            break
    # v1.6.298 — for #193 round-2 NOT VERIFIED. Option C: collect
    # a UNION constraint-sentence whitelist across all docs. When at
    # least one doc has a chip-LOCAL constraint ("implements only X",
    # "M-mode only"), enforce the whitelist on the prose-scan output
    # so the inherited RISC-V Privileged Spec narrative
    # ("RISC-V supports Machine, Supervisor, User, Hypervisor") does
    # not flood every mode into L1.privilege_modes.
    priv_constraint_whitelist: Optional[Set[str]] = None
    for fname, text in extracted.items():
        if not isinstance(text, str) or not text:
            continue
        # v1.6.437 — for #313 P2 ORGANIC. Reference-PDF deny.
        if _v1_6_437_is_reference_appendix(fname):
            continue
        per_doc_wl = _v1_6_298_find_constraint_mode_whitelist(text)
        if per_doc_wl:
            if priv_constraint_whitelist is None:
                priv_constraint_whitelist = set()
            priv_constraint_whitelist.update(per_doc_wl)
    for fname, text in extracted.items():
        if not isinstance(text, str) or not text:
            continue
        # v1.6.437 — for #313 P2 ORGANIC. Reference-PDF deny. The
        # standards-body PDFs describe the entire ISA universe
        # (RV32 + RV64 + every privilege mode + every extension)
        # and were polluting `L1.isa_base` with wrong-width tokens
        # on 32-bit-only RV cores. Skip those docs from this main
        # walker entirely.
        if _v1_6_437_is_reference_appendix(fname):
            continue
        # v1.6.309 — for #208 ORGANIC. Compute the chip's declared
        # datapath width once per doc so wrong-width ISA-base tokens
        # quoted from the standard RISC-V Privileged-Spec appendix
        # get rejected. Helper returns None when the doc never
        # anchors a width, in which case existing behaviour is
        # preserved (both widths allowed through). Chip-AGNOSTIC:
        # pure RISC-V ecosystem prose-anchor pattern.
        chip_width_v1_6_309 = _v1_6_309_isa_base_width_constraint(text)
        # v1.6.542 — for #368 P3 ORGANIC. Switch the ISA-base walker
        # to the case-insensitive regex and canonicalise per-match
        # (uppercase RV-major + single-letter ext block, lowercase
        # Z*/X* suffixes preserved). The old `_RE_ISA_BASE` regex
        # missed lowercase / backticked `rv32i` prose tokens common
        # in AsciiDoc cpu chapters and Makefile toolchain examples.
        for m in _V1_6_542_RE_ISA_BASE.finditer(text):
            tok = _v1_6_542_canonicalise_isa_base(m.group(0))
            if tok in seen_base:
                continue
            # v1.6.309 — for #208 ORGANIC. Width-constraint reject:
            # if the chip anchors a specific width and the token's
            # width prefix doesn't match, drop the hit. Wrong-width
            # token leaks happen on cores whose doc tree quotes the
            # RV Privileged-Spec appendix verbatim.
            if chip_width_v1_6_309 and not tok.startswith(
                    chip_width_v1_6_309):
                continue
            # v1.6.309 — for #208 ORGANIC. Negation-window reject:
            # if the ±100-char prose window around the token
            # contains common negation / disclaimer language, drop
            # the hit. Common pattern in inherited spec appendices
            # ("does not support RV64I", "future work"). Chip-
            # AGNOSTIC: open-standard RISC-V ecosystem vocabulary.
            if _v1_6_309_isa_base_negation_window(
                    text, m.start(), m.end()):
                continue
            # v1.6.432 — for #309 P3 ORGANIC. Canonical-base validator
            # rejects RTL extension-config parameter names (RV32M /
            # RV32B / RV32ZC / RV32A) that the bare regex over-matches.
            # Route invalid bases to isa_extensions when not already
            # seen there.
            if not _v1_6_432_is_valid_isa_base(tok):
                if tok not in seen_ext:
                    seen_ext.add(tok)
                    isa_exts.append(tok)
                    ext_ev.append({
                        "file": f"input/docs/{fname}",
                        "line": text[: m.start()].count("\n") + 1,
                        "matched_substring": tok,
                        "extraction_strategy":
                            "isa_base_demoted_to_extension_v1_6_432",
                    })
                continue
            seen_base.add(tok)
            isa_bases.append(tok)
            base_ev.append({
                "file": f"input/docs/{fname}",
                "line": text[: m.start()].count("\n") + 1,
                "matched_substring": tok,
            })
        for m in _RE_ISA_EXT_Z.finditer(text):
            tok = m.group(0)
            if tok in seen_ext:
                continue
            # v1.6.297 — for #193 ORGANIC. Reject hits whose ±200-char
            # window is dominated by negation prose (`not implemented`,
            # `reserved`, `shall not`, WIRI/WPRI/...) and carries no
            # positive support marker.
            # v1.6.298 — extended vocabulary for spec-style negation.
            if not _v1_6_298_isa_context_accepts(
                    text, m.start(), m.end()):
                continue
            seen_ext.add(tok)
            isa_exts.append(tok)
            ext_ev.append({
                "file": f"input/docs/{fname}",
                "line": text[: m.start()].count("\n") + 1,
                "matched_substring": tok,
            })
        for m in _RE_ISA_EXT_X.finditer(text):
            tok = m.group(0)
            if tok in seen_ext:
                continue
            # v1.6.297 — for #193 ORGANIC. Negation-context reject.
            # v1.6.298 — extended vocabulary.
            if not _v1_6_298_isa_context_accepts(
                    text, m.start(), m.end()):
                continue
            seen_ext.add(tok)
            isa_exts.append(tok)
            ext_ev.append({
                "file": f"input/docs/{fname}",
                "line": text[: m.start()].count("\n") + 1,
                "matched_substring": tok,
            })
        # v1.6.298 — Option B short-circuit for privilege modes. When
        # an explicit `| Privilege Mode |` table is present in any
        # doc, use ONLY that table — skip the prose-based scan
        # entirely for privilege modes.
        if priv_table_short_circuit is None:
            for m in _RE_PRIV_MODES.finditer(text):
                mode = m.group(1).capitalize()
                if mode in seen_priv:
                    continue
                # v1.6.297 — for #193 ORGANIC. Negation-context reject.
                # `"Hypervisor mode is not implemented"` no longer adds H.
                # v1.6.298 — extended vocabulary.
                if not _v1_6_298_isa_context_accepts(
                        text, m.start(), m.end()):
                    continue
                seen_priv.add(mode)
                priv_modes.append(mode)
                priv_ev.append({
                    "file": f"input/docs/{fname}",
                    "line": text[: m.start()].count("\n") + 1,
                    "matched_substring": m.group(0),
                })
            # `Machine/User`-shorthand pair: split into both modes.
            for m in _RE_PRIV_PAIR.finditer(text):
                # v1.6.297 — for #193 ORGANIC. Negation-context reject.
                # v1.6.298 — extended vocabulary.
                if not _v1_6_298_isa_context_accepts(
                        text, m.start(), m.end()):
                    continue
                for tok in ("Machine", "User"):
                    if tok in seen_priv:
                        continue
                    seen_priv.add(tok)
                    priv_modes.append(tok)
                    priv_ev.append({
                        "file": f"input/docs/{fname}",
                        "line": text[: m.start()].count("\n") + 1,
                        "matched_substring": m.group(0),
                    })
        for m in _RE_ENDIAN.finditer(text):
            endian = m.group(1).lower().replace(" ", "-")
            if endian in seen_endian:
                continue
            seen_endian.add(endian)
            endians.append(endian)
            endian_ev.append({
                "file": f"input/docs/{fname}",
                "line": text[: m.start()].count("\n") + 1,
                "matched_substring": m.group(0),
            })
        if machine_ver is None:
            mv = _RE_MACHINE_ISA_VER.search(text)
            if mv:
                machine_ver = mv.group(1)
    if isa_bases:
        out["isa_base"] = isa_bases
        out["isa_base_evidence"] = base_ev
    if isa_exts:
        out["isa_extensions"] = isa_exts
        out["isa_extensions_evidence"] = ext_ev
    # v1.6.298 — for #193 round-2 NOT VERIFIED. Option B: if an
    # explicit `| Privilege Mode |` table was found, use ONLY that
    # table — overwrites the prose-scan result (which was already
    # short-circuited during the per-doc loop, but defensively
    # enforce again here so the explicit table is canonical).
    if priv_table_short_circuit is not None:
        priv_modes = list(priv_table_short_circuit)
        priv_ev = [
            {
                "file": (f"input/docs/{priv_table_source_file}"
                         if priv_table_source_file else None),
                "line": priv_table_source_line,
                "matched_substring": (
                    f"| Privilege Mode | (table row: {mode})"),
            }
            for mode in priv_modes
        ]
    elif priv_constraint_whitelist is not None:
        # v1.6.298 — Option C: chip-local constraint whitelist gate.
        # Filter the prose-scan output to keep ONLY modes that the
        # constraint sentence permits. Evidence entries follow the
        # filter.
        filtered_modes: List[str] = []
        filtered_ev: List[Dict[str, Any]] = []
        for mode, ev in zip(priv_modes, priv_ev):
            if mode in priv_constraint_whitelist:
                filtered_modes.append(mode)
                filtered_ev.append(ev)
        priv_modes = filtered_modes
        priv_ev = filtered_ev
    if priv_modes:
        out["privilege_modes"] = priv_modes
        out["privilege_modes_evidence"] = priv_ev
    if endians:
        out["endianness"] = endians
        out["endianness_evidence"] = endian_ev
    if machine_ver:
        out["machine_isa_version"] = machine_ver
    return out


# ---------------------------------------------------------------------------
# v1.6.295 — for #180 / #181 / #182 / #185 / #186 / #188 / #189 / #190
# ORGANIC. Shared module-level helpers + regex constants used by the
# Phase 1 (doc-extraction) follow-on batch. All helpers + regex are chip-AGNOSTIC.
# ---------------------------------------------------------------------------

# v1.6.295 — for #180 + #185 ORGANIC. Class label sets used by L2's
# protocol_overview emitter (#180) and ic_class_hint heuristic (#185)
# to suppress fabricated protocol metadata on classes that don't have
# a bus-protocol layer. Vocabulary mirrors the L1 class detector
# (readme_class_detector); not a chip-class literal.
_V1_6_295_NON_PROTOCOL_CLASS_PATHS = frozenset({
    "processor_cpu",
    "pure_analog",
    "analog_data_converter",
})

# v1.6.295 — for #180 ORGANIC. Minimum number of distinct
# half-duplex / single-wire shape signals required before
# protocol_overview is allowed to claim half_duplex / wire_count.
# Single-mention prose ("supports UART debug interface") does not
# qualify; the emitter then writes protocol_overview=null + the
# no_protocol_overview_in_input flag.
_V1_6_295_HD_SHAPE_SIGNAL_MIN = 2

# v1.6.295 — for #185 ORGANIC. CPU / ISA vocabulary veto. When any
# of these open-standard ISA tokens appears in the doc text, the
# multi_protocol_transport_library short-circuit must not fire —
# CPU IPs whose docs enumerate optional peripherals look like
# multi-protocol libraries to a naive acronym scan. Pattern is the
# RISC-V / MIPS / ARM published ISA vocabulary, no chip literals.
_V1_6_295_CPU_VETO_RE = re.compile(
    r"\b(RV32|RV64|RISC-?V|MIPS|ARM\s+Cortex|"
    r"pipeline\s+stage|instruction\s+set|"
    r"\bISA\b|core\s+pipeline|"
    r"(?:5|6|7|8)[-\s]?stage\s+pipeline)\b",
    re.IGNORECASE,
)


def _v1_6_295_resolve_class_path(project: Path) -> Optional[str]:
    """v1.6.295 — for #180 / #181 / #185 ORGANIC. Single source of
    truth: read L1.class_path back from disk if L1 already emitted.
    Returns None when L1 has not yet been written OR L1 carries
    null class_path. Caller decides what to do with the result.

    Chip-AGNOSTIC: pure filesystem read.
    """
    try:
        l1 = _try_load_l_doc(project, "L1_DATASHEET")
    except Exception:
        return None
    if not isinstance(l1, dict):
        return None
    cp = l1.get("class_path")
    if isinstance(cp, str) and cp.strip():
        return cp.strip()
    return None


def _v1_6_331_provisional_class_path(
    project: Path,
    extracted: Optional[Dict[str, str]] = None,
) -> Optional[str]:
    """v1.6.331 — for #229 P2 ORGANIC. Provisional class-path resolver
    used by L emit sites that run BEFORE the post-emit pass
    ``_post_emit_ic_class_into_L9_L1`` has stamped L1.class_path.

    Resolution order (mirrors `_post_emit_ic_class_into_L9_L1`):

      1. If L1.class_path has already been written to disk, return it
         (``_v1_6_295_resolve_class_path`` outcome). This preserves the
         pre-v1.6.331 behaviour on the path where L1 is reachable.
      2. Otherwise, invoke ``readme_class_detector.detect_class_from_readme``
         on the project README. The detector returns a class_path or None.
      3. Otherwise, fall back to ``_detect_ic_class_evidence_strength``
         which scans the project for has_inout_id_bus / has_command_protocol
         / has_analog / has_fsm signals.
      4. Returns None when no detector fires (caller must treat None as
         "permissive — preserve pre-v1.6.331 legacy semantics").

    Chip-AGNOSTIC: dispatches to the existing detectors that
    `_post_emit_ic_class_into_L9_L1` uses; no chip-class literal.

    The optional ``extracted`` argument is reserved for future use; the
    current resolution order does not require an in-memory concat
    because the underlying detectors already read from `project`.
    """
    # Step 1 — already-on-disk L1.class_path.
    cp = _v1_6_295_resolve_class_path(project)
    if cp:
        return cp
    # Step 2 — README class detector.
    try:
        sys.path.insert(0, str(Path(__file__).resolve().parent))
        from readme_class_detector import (
            detect_class_from_readme as _readme_detect,
        )
        readme_text = _read_input_readme_text(project)
        detected_class, _ev = _readme_detect(readme_text)
        if isinstance(detected_class, str) and detected_class.strip():
            return detected_class.strip()
    except Exception:
        pass
    # Step 3 — canonical evidence-strength detector.
    try:
        detected = _detect_ic_class_evidence_strength(project)
        if isinstance(detected, str) and detected.strip():
            return detected.strip()
    except Exception:
        pass
    # Step 4 — no detector fired.
    _ = extracted  # reserved for future in-memory concat path
    return None


# v1.6.295 — for #180 ORGANIC. Half-duplex / single-wire shape
# signal counter. Counts the number of DISTINCT shape signals
# present in the concatenated extracted text. A "shape signal"
# is any of the canonical half-duplex / one-wire keywords AND
# any structural sentence-anchored evidence (single-wire +
# bidirectional language, half-duplex + protocol noun, etc.).
# Returns an integer >= 0.
#
# Chip-AGNOSTIC: structural vocabulary only.
_V1_6_295_HD_SHAPE_SIGNAL_RES = (
    re.compile(r"\bhalf[\s\-]?duplex\b", re.IGNORECASE),
    re.compile(r"\bsingle[\s\-]?wire\b", re.IGNORECASE),
    re.compile(r"\b1[\s\-]?wire\b", re.IGNORECASE),
    re.compile(r"\bone[\s\-]?wire\b", re.IGNORECASE),
    re.compile(r"\bbidirectional\b", re.IGNORECASE),
    re.compile(r"\btransmit\s+and\s+receive\b", re.IGNORECASE),
    re.compile(r"\breceive\s+and\s+(?:transmit|send)\b", re.IGNORECASE),
    re.compile(r"半[\s]*[雙双][\s]*工"),
    re.compile(r"單[\s]*線|單[\s]*根線|單[\s]*條線"),
)


def _v1_6_295_count_half_duplex_shape_signals(text: str) -> int:
    """v1.6.295 — for #180 ORGANIC. Count distinct half-duplex /
    single-wire / bidirectional shape-signal regex classes that
    fire at least once in `text`.

    Chip-AGNOSTIC.
    """
    if not isinstance(text, str) or not text:
        return 0
    n = 0
    for pat in _V1_6_295_HD_SHAPE_SIGNAL_RES:
        if pat.search(text):
            n += 1
    return n


def _v1_6_295_should_emit_protocol_overview(class_path: Optional[str],
                                             hd_signal_count: int,
                                             ) -> bool:
    """v1.6.295 — for #180 ORGANIC. Class-gate guard for the L2
    protocol_overview emitter.

    Returns False when:
      * `class_path` is a CPU / analog class (no bus-protocol
        layer applies — `processor_cpu` / `pure_analog` /
        `analog_data_converter`). These three are the only veto
        classes; every other input falls through to the legacy
        `protocol_evidence_found` semantics in the caller.

    `hd_signal_count` is accepted as a hint and reserved for
    future tighter gating; the current default (return True for
    any non-veto class) preserves the pre-v1.6.295 behaviour for
    every IP whose L1.class_path is unresolved at L2 emit time
    (the common case — `_post_emit_ic_class_into_L9_L1` runs
    after every L emitter). Only chips whose class is positively
    resolved as CPU / analog see the suppression.

    Chip-AGNOSTIC.
    """
    if class_path in _V1_6_295_NON_PROTOCOL_CLASS_PATHS:
        return False
    # Defensive future-tightening hook: when class_path is None AND
    # hd_signal_count is 0 (no shape signal at all) AND the caller's
    # protocol_evidence is weak (handled outside this helper), the
    # caller can apply additional gates. The helper itself stays
    # permissive to preserve every pre-v1.6.295 protocol emit.
    _ = hd_signal_count  # reserved for future-tightening callers
    return True


# v1.6.295 — for #182 ORGANIC. Markdown inline-link + HTML anchor
# regex used by the L1.description cleaner. `[label](url)` and
# `<a href="url">label</a>` collapse to bare `label`.
# Chip-AGNOSTIC: pure typographic markup.
_V1_6_295_RE_MD_INLINE_LINK = re.compile(
    r"\[([^\]\n]+?)\]\(([^)]+?)\)"
)
_V1_6_295_RE_HTML_ANCHOR = re.compile(
    r"<a\s+[^>]*?href=['\"][^'\"]+['\"][^>]*?>([^<]+)</a>",
    re.IGNORECASE,
)

# v1.6.336 — for #234 P3 ORGANIC. Additional markdown markers that
# the v1.6.295 cleaner did not strip. Three forms surfaced on the
# benchmark:
#
#   1. Italic asterisk `*x*` — collapse to `x`. MUST NOT match
#      `**bold**` (the `**` boundary would otherwise yield empty
#      replacements and corrupt the surrounding text).
#   2. Italic underscore `_x_` — collapse to `x`. MUST NOT match
#      `__bold__` (same reason) and MUST NOT match underscores in
#      the middle of an identifier like `RV32I_M` (those underscores
#      are part of a word, not formatting).
#   3. Single-backtick code-span `` `x` `` — collapse to `x`. MUST
#      NOT touch triple-backtick code blocks (rare in L1.description
#      but handled defensively).
#
# Chip-AGNOSTIC: pure markdown grammar; no chip-class literal.
_V1_6_336_RE_MD_ITALIC_ASTERISK = re.compile(
    # Negative lookbehind / lookahead so `**bold**` is NOT touched.
    r"(?<![*\w])\*([^*\n]+?)\*(?!\*)"
)
_V1_6_336_RE_MD_ITALIC_UNDERSCORE = re.compile(
    # Word-boundary lookarounds keep `RV32I_M`, `single_wire`, and
    # `__bold__` from being touched.
    r"(?<![_\w])_([^_\n]+?)_(?![_\w])"
)
_V1_6_336_RE_MD_INLINE_CODESPAN = re.compile(
    # Single-backtick code span. The `(?<!`)` lookbehind / `(?!`)`
    # lookahead reject triple-backtick fence boundaries.
    r"(?<!`)`([^`\n]+?)`(?!`)"
)


# v1.6.445 — for #321 P3 ORGANIC. Sphinx / RST inline role
# stripper. Sphinx-flavoured RST documents use inline cross-
# reference roles `:numref:`, `:ref:`, `:doc:`, `:class:`,
# `:meth:`, `:func:`, `:attr:`, `:mod:`, `:term:`, `:cite:` etc.
# At render time Sphinx resolves these to "Fig. 1" / "(see X)" /
# the linked target text, but in plain-text extraction the raw
# role token leaks through. Real-world: an L1.description ended
# with "with the core and :numref:`blockdiagram` and the FPU.",
# polluting downstream RTL doc-strings and human-facing
# rendered docs.
#
# Strategy: cross-reference roles (numref/ref/doc/class/meth/
# func/attr/mod/term/cite) are dropped entirely; content roles
# (title/abbr/strong/emphasis/literal) are replaced with their
# wrapped-text content. Both the `:role:`target`` (backtick)
# AND `:role:target` (bare) forms are handled. Chip-AGNOSTIC:
# pure Sphinx-RST grammar vocabulary; no chip-name literal.
_V1_6_445_SPHINX_CROSSREF_ROLES = frozenset({
    "numref", "ref", "doc", "class", "meth", "func", "attr",
    "mod", "term", "cite", "label",
})
_V1_6_445_SPHINX_CONTENT_ROLES = frozenset({
    "title", "abbr", "strong", "emphasis", "literal",
    "guilabel", "menuselection", "command", "file", "envvar",
    "math", "kbd",
})
_V1_6_445_RE_SPHINX_INLINE_ROLE = re.compile(
    r":([A-Za-z][A-Za-z0-9_\-]*):"
    r"(?:`(?P<bk>[^`]+)`|(?P<bare>[A-Za-z0-9_\-./]+))",
)


def _v1_6_445_strip_sphinx_inline_roles(text):
    """v1.6.445 — for #321 P3 ORGANIC. Strip Sphinx / RST
    inline cross-reference roles from `text`. Cross-ref roles
    (numref/ref/doc/class/meth/func/attr/mod/term/cite/label)
    are removed entirely; content roles (title/abbr/strong/
    emphasis/literal/...) collapse to their wrapped-text
    content. Unknown roles fall back to wrapped-text content
    so the prose is never lost. Chip-AGNOSTIC."""
    if not isinstance(text, str) or not text:
        return text or ""

    def _sub(m):
        role = (m.group(1) or "").lower()
        target = m.group("bk") or m.group("bare") or ""
        if role in _V1_6_445_SPHINX_CROSSREF_ROLES:
            return ""
        if role in _V1_6_445_SPHINX_CONTENT_ROLES:
            return target
        # Unknown role: keep the target text to avoid dropping
        # content the role was wrapping.
        return target

    out = _V1_6_445_RE_SPHINX_INLINE_ROLE.sub(_sub, text)
    # Collapse repeated whitespace that may result from
    # cross-ref drops (e.g. " :numref:`x` " → "  " → " ").
    out = re.sub(r"[ \t]{2,}", " ", out)
    # Also tighten spacing before sentence-terminating punctuation
    # if the cross-ref drop left a stray space (e.g. "core .").
    out = re.sub(r"\s+([,.;:!?])", r"\1", out)
    return out.strip()


# v1.6.452 — for #326 P3 ORGANIC. Orphan-verb sentence sentinels.
# Common Sphinx-prose verb-leading patterns where the role
# itself was the subject. After v1.6.445 strips the role, the
# remaining "shows / describes / lists ..." fragment is a
# grammatically orphan predicate that leaks into L1.description
# as ungrammatical leading text (e.g. `". shows a block diagram
# of the top level..."`). The sentinels here are reporting verbs
# that appear AT THE START of a sentence in Sphinx prose; they
# all imply a subject like ":numref:`fig` shows ..." was the
# original.
#
# The sentinel list is conservative — only verbs that are
# essentially unused as sentence-initial subjects in normal
# English. Generic verbs (`is`, `has`, `provides`, `supports`)
# are deliberately excluded because they are also commonly used
# in legitimate imperative or topic-sentence prose.
#
# Chip-AGNOSTIC: pure English reporting-verb sentinels.
_V1_6_452_ORPHAN_VERB_SENTINELS = (
    "shows",
    "describes",
    "lists",
    "illustrates",
    "depicts",
    "indicates",
    "presents",
    "summarizes",
    "summarises",
    "details",
    "specifies",
    "outlines",
    "highlights",
    "tabulates",
    "displays",
)


def _v1_6_452_drop_orphan_verb_sentences(text: str) -> str:
    """v1.6.452 — for #326 P3 ORGANIC. Drop sentences whose
    leading word is one of `_V1_6_452_ORPHAN_VERB_SENTINELS`
    in lowercase, AFTER a sentence-terminator. Such fragments
    are the leftover predicate when a Sphinx role was stripped
    from the sentence's subject position. The companion
    v1.6.445 strip removes the role token cleanly but doesn't
    detect that the remainder is grammatically orphan; without
    this helper L1.description shows fragments like
    `". shows a block diagram of the top level..."`.

    Sentence boundaries: ASCII period / question mark /
    exclamation point + at least one whitespace character.

    Capitalised verb forms (`Shows`, `Describes`, ...) are NOT
    matched — when the verb is sentence-cased it more often
    signals an intentional imperative or topic sentence than
    an orphan from a role strip.

    Chip-AGNOSTIC: pure English reporting-verb sentinels; no
    chip-class identifiers in the pattern.
    """
    if not isinstance(text, str) or not text:
        return text or ""
    sentinels = "|".join(_V1_6_452_ORPHAN_VERB_SENTINELS)
    # Match a sentence-terminator followed by whitespace,
    # followed by a lowercase orphan verb, followed by everything
    # up to and including the next sentence terminator.
    pat = re.compile(
        r"([.!?])\s+(?:" + sentinels + r")\b[^.!?]*?[.!?]",
    )
    # Repeated substitution: a long orphan run "X. shows A. shows
    # B. shows C." should collapse all three orphan sentences.
    prev = None
    out = text
    while prev != out:
        prev = out
        out = pat.sub(r"\1", out)
    # Also handle the case where the text STARTS with an orphan
    # verb (no preceding sentence terminator — e.g. role was at
    # the very start of the description).
    leading_pat = re.compile(
        r"^\s*(?:" + sentinels + r")\b[^.!?]*?[.!?]\s*",
    )
    out = leading_pat.sub("", out)
    # Collapse any duplicated whitespace introduced by the drops.
    out = re.sub(r"[ \t]{2,}", " ", out)
    out = re.sub(r"\s+([,.;:!?])", r"\1", out)
    return out.strip()


def _v1_6_295_clean_description_markdown(text: str) -> str:
    """v1.6.295 — for #182 ORGANIC. Strip markdown inline-link and
    HTML anchor wrappers from a description string, leaving the
    label-only text. Returns the trimmed cleaned string.

    v1.6.336 — for #234 P3 ORGANIC. Extended with three additional
    substitutions executed AFTER the existing link / anchor strips:
      * `*x*` → `x` (italic asterisk; not `**bold**`)
      * `_x_` → `x` (italic underscore; not `__bold__`, not in-word)
      * `` `x` `` → `x` (inline code-span; not triple-backtick fences)

    v1.6.445 — for #321 P3 ORGANIC. Strip Sphinx / RST inline
    cross-reference roles (`:numref:` / `:ref:` / `:doc:` etc.)
    AFTER the markdown / italic / code-span strips so the
    cleaner removes raw role tokens that would otherwise leak
    into L1.description.

    Chip-AGNOSTIC.
    """
    if not isinstance(text, str) or not text:
        return text or ""
    text = _V1_6_295_RE_MD_INLINE_LINK.sub(r"\1", text)
    text = _V1_6_295_RE_HTML_ANCHOR.sub(r"\1", text)
    # v1.6.336 — italic + code-span strips.
    text = _V1_6_336_RE_MD_INLINE_CODESPAN.sub(r"\1", text)
    text = _V1_6_336_RE_MD_ITALIC_ASTERISK.sub(r"\1", text)
    text = _V1_6_336_RE_MD_ITALIC_UNDERSCORE.sub(r"\1", text)
    # v1.6.445 — for #321 P3 ORGANIC. Sphinx inline role strip.
    text = _v1_6_445_strip_sphinx_inline_roles(text)
    # v1.6.452 — for #326 P3 ORGANIC. Orphan-verb post-pass. After
    # v1.6.445 drops a Sphinx role that was the subject of a
    # sentence (e.g. `:numref:`x` shows a block diagram ...`), the
    # remainder is a verb-leading fragment that has no subject and
    # leaks into L1.description as ungrammatical prose. Drop those
    # sentences before the trailing `strip()`.
    text = _v1_6_452_drop_orphan_verb_sentences(text)
    return text.strip()


# v1.6.295 — for #186 ORGANIC. Tapeout metadata extractor for L1.
# `die_dimensions` matches "1300 x 1300 um" / "1.3 x 1.3 mm" style.
# `foundry / process_node` matches open-source foundry tokens and
# generic `<vendor> NNN nm` form.
# Chip-AGNOSTIC: open-standard semiconductor vocabulary.
_V1_6_295_RE_DIE_DIMENSIONS = re.compile(
    r"\b(\d{1,5}(?:\.\d+)?)\s*[x×]\s*"
    r"(\d{1,5}(?:\.\d+)?)\s*(um|µm|mm)\b",
    re.IGNORECASE,
)

# v1.6.333 — for #231 P2 ORGANIC. Unit-less die-dimensions fallback.
# Academic / IEEE-format datasheets often state die size in prose
# without an inline unit suffix (e.g. "chip dimensions are 1300 x
# 1300 (without seal ring)"); the v1.6.295 regex requires a
# `(um|µm|mm)\b` suffix and silently drops those matches. The
# fallback regex is anchored on a prose introducer noun ("chip
# dimensions" / "die area" / "die size" / "active area" / "core
# area") followed by the `<W> [x×] <H>` numeric pair. The introducer
# anchor keeps the regex from matching every `1300 x 1300` numeric
# pair in throughput / frequency tables.
#
# Width range: 2-5 digits (10..99999) — die sizes for academic ICs
# are typically 100-5000 um (or 0.1-5.0 mm if scaled). Excludes
# 1-digit numbers (would match `1 x 1` in unrelated prose).
#
# When the fallback fires, a ±500-char window scan recovers the
# nearby unit token (um / µm / mm); when none is found, the
# canonical academic-IC default `um` is used and
# `die_dimensions_unit_inferred=True` is stamped so downstream
# consumers can detect the fallback.
#
# Chip-AGNOSTIC: open-vocabulary prose anchor; no chip-class literal.
_V1_6_333_RE_DIE_DIMENSIONS_NO_UNIT = re.compile(
    r"\b(?:chip\s+dimensions?|die\s+(?:area|size|dimensions?)|"
    r"active\s+area|core\s+area|chip\s+(?:area|size))\s*"
    r"(?:are|is|of|=|:|measures?)?\s*"
    # Number pair: either 2-5 digit integer (`1300`, `800`, `42`)
    # OR any-length decimal (`1.5`, `0.75`, `12.5`). Single-digit
    # integer is rejected to keep `chip area 1 x 1` (noise prose)
    # from surfacing. The decimal form is needed for mm-scale
    # academic-IC dimensions like `1.5 x 1.5 mm`.
    r"((?:\d{2,5})|(?:\d+\.\d+))\s*[x×]\s*"
    r"((?:\d{2,5})|(?:\d+\.\d+))\b",
    re.IGNORECASE,
)

# v1.6.333 — window size for the unit-fallback scan (±chars
# around the match). Wide enough to catch a unit token mentioned
# in an adjacent sentence or table caption.
_V1_6_333_DIE_UNIT_WINDOW = 500
_V1_6_333_DIE_UNIT_DEFAULT = "um"


def _v1_6_333_infer_die_dim_unit(text: str, match_pos: int) -> str:
    """v1.6.333 — for #231 P2 ORGANIC. Scan a ±500-char window
    around `match_pos` for the canonical die-dimension unit tokens
    (`um` / `µm` / `mm`). Returns the first unit token found, or
    `_V1_6_333_DIE_UNIT_DEFAULT` ("um") when none is present.

    The window-scan order prefers `µm` and `um` (the academic-IC
    default) over `mm` to avoid pulling in a `mm` token that
    appears in unrelated package-size prose.

    Chip-AGNOSTIC: open-vocabulary unit token scan.
    """
    if not isinstance(text, str):
        return _V1_6_333_DIE_UNIT_DEFAULT
    start = max(0, match_pos - _V1_6_333_DIE_UNIT_WINDOW)
    end = min(len(text), match_pos + _V1_6_333_DIE_UNIT_WINDOW)
    window = text[start:end]
    # Prefer um / µm (the academic default).
    for unit in ("µm", "um"):
        if re.search(rf"(?<!\w){re.escape(unit)}(?!\w)", window,
                     re.IGNORECASE):
            return unit.replace("µ", "u")
    if re.search(r"(?<!\w)mm(?!\w)", window, re.IGNORECASE):
        return "mm"
    return _V1_6_333_DIE_UNIT_DEFAULT
_V1_6_295_RE_FOUNDRY_OPEN = re.compile(
    r"\b(IHP\s*SG13G2|SkyWater\s*SKY130|"
    r"GlobalFoundries\s*GF180|Global\s*Foundries\s*180|"
    r"TSMC|UMC|Samsung|Intel|GF|GlobalFoundries|"
    r"IHP|SkyWater)\b",
    re.IGNORECASE,
)
_V1_6_295_RE_PROCESS_NODE = re.compile(
    r"\b(\d{2,4})\s*nm\b",
    re.IGNORECASE,
)

# v1.6.297 — for #191 ORGANIC. The v1.6.295 foundry extractor matched
# generic semiconductor-house tokens (TSMC / UMC / Intel / GF / etc.)
# anywhere in the doc with no context-window check. Real benchmark
# READMEs for FPGA-targeted soft cores read
#   "Synthesised with <FPGA Toolchain> X.Y for <FPGA Family>"
# or list the FPGA vendor in a Targets table — the bare-substring match
# pulled the vendor token into `L1.tapeout_metadata.foundry` despite
# the doc never mentioning a process node, wafer fab, or silicon
# tape-out. The fix is a two-part context probe:
#   1. FPGA-tool / FPGA-vendor deny pattern that fires on FPGA-only
#      mentions (Quartus / Vivado / Cyclone / Stratix / Artix / Spartan
#      / Kintex / Virtex / Zynq / Lattice / Gowin / Cologne / MicroSemi
#      / Intel-tied-to-FPGA / AMD-tied-to-FPGA).
#   2. ASIC-tapeout positive-context probe that fires on real tape-out
#      vocabulary (taped out / fabricated / process node / wafer /
#      silicon / mask set / reticle / MPW / shuttle).
# After a candidate foundry-token match, capture the surrounding 200-
# char window. Reject the match when the window matches the FPGA deny
# AND does NOT match the positive ASIC-tapeout context. When both
# triggers fire in the same window, prefer positive — some docs say
# "Taped out in 130 nm at <Foundry>; FPGA prototype on Cyclone" in the
# same paragraph and the positive marker must win.
# Chip-AGNOSTIC: only published FPGA toolchain / FPGA family / fab /
# tape-out vocabulary; no chip-class literals.
_V1_6_297_RE_FPGA_TOOL_VENDOR_DENY = re.compile(
    r"\b("
    r"Quartus|Vivado|Cyclone|Stratix|Artix|Spartan|Kintex|"
    r"Virtex|Zynq|"
    r"Lattice|Gowin|Cologne|MicroSemi|"
    r"Intel(?=\s+(?:Quartus|FPGA|Cyclone|Stratix))|"
    r"AMD(?=\s+(?:Vivado|FPGA|Artix|Kintex|Virtex|Spartan))"
    r")\b",
    re.IGNORECASE,
)

_V1_6_297_RE_FOUNDRY_POSITIVE_CONTEXT = re.compile(
    r"\b("
    r"taped\s+out|tape-out|tapeout|fabricat(?:ed|ion)|"
    r"process\s+node|wafer|silicon|"
    r"mask\s+set|reticle|MPW|shuttle"
    r")\b",
    re.IGNORECASE,
)

_V1_6_297_FOUNDRY_CONTEXT_WINDOW = 200


def _v1_6_297_foundry_context_accepts(text: str,
                                       match_start: int,
                                       match_end: int) -> bool:
    """v1.6.297 — for #191 ORGANIC. Decide whether a candidate
    foundry-token match at [match_start, match_end) in `text` should
    be accepted as a real ASIC-tapeout foundry hit.

    Returns False (reject) when the surrounding 200-char window
    matches the FPGA-tool/vendor deny AND does NOT match the
    ASIC-tapeout positive context. Returns True otherwise.

    Chip-AGNOSTIC: open-standard FPGA / tape-out vocabulary.
    """
    if not isinstance(text, str) or not text:
        return True
    w = _V1_6_297_FOUNDRY_CONTEXT_WINDOW
    lo = max(0, match_start - w)
    hi = min(len(text), match_end + w)
    window = text[lo:hi]
    has_fpga_deny = bool(
        _V1_6_297_RE_FPGA_TOOL_VENDOR_DENY.search(window))
    has_positive = bool(
        _V1_6_297_RE_FOUNDRY_POSITIVE_CONTEXT.search(window))
    if has_fpga_deny and not has_positive:
        return False
    return True


# v1.6.298 — for #191 round-2 NOT VERIFIED. The v1.6.297 ±200-char
# positive-context window proved too permissive on real benchmark docs:
#
#   (a) Multi-FPGA-vendor sentence + generic ASIC-tapeout claim — e.g.
#       README that says
#         "on AMD, Intel, Lattice, Microchip, Gowin and Cologne Chip
#          FPGAs.\nThe processor has also been taped out several times
#          as an ASIC."
#       The `taped out` positive marker lands inside the 200-char window
#       of `Intel`, so v1.6.297 accepts Intel as foundry. But the "taped
#       out as an ASIC" sentence is a generic claim — it does NOT refer
#       to any specific foundry token; it lives in a DIFFERENT sentence.
#
#   (b) FPGA tool-suite README heading — e.g. `# Intel VJTAG` in a
#       `doc/vjtag/README.md` file. `VJTAG` was not in the v1.6.297
#       FPGA-tool-vendor deny list, so the bare `Intel` token before
#       `VJTAG` slipped through as standalone foundry.
#
# The v1.6.298 fix tightens the positive-context window to SAME-SENTENCE
# scope. Sentence boundaries are `[.!?]\s` / `\n\n` / start-of-text /
# end-of-text. The accept rule:
#   1. Find the sentence that fully contains the foundry-token match.
#   2. If the SAME sentence matches `_RE_FPGA_TOOL_VENDOR_DENY` -> reject.
#   3. If the SAME sentence matches `_RE_FOUNDRY_POSITIVE_CONTEXT` ->
#      accept.
#   4. Otherwise -> reject (positive marker must be in the same
#      sentence as the foundry token, NOT just nearby).
#
# Additionally extend the deny list with FPGA-tool / JTAG-tool / hex-
# format vocabulary so the bare-Intel-before-VJTAG variant is caught.
# Chip-AGNOSTIC: only public FPGA / JTAG / EDA-tool vocabulary; no
# chip-class literals.
_V1_6_298_RE_FPGA_TOOL_VENDOR_DENY = re.compile(
    r"\b("
    r"Quartus|Vivado|Cyclone|Stratix|Artix|Spartan|Kintex|"
    r"Virtex|Zynq|"
    r"Lattice|Gowin|Cologne|MicroSemi|"
    r"VJTAG|VJtag|Hex\s+Format|"
    r"Intel(?=\s+(?:Quartus|FPGA|Cyclone|Stratix|VJTAG|VJtag))|"
    r"AMD(?=\s+(?:Vivado|FPGA|Artix|Kintex|Virtex|Spartan))"
    r")\b",
    re.IGNORECASE,
)

_V1_6_298_RE_SENTENCE_BOUNDARY = re.compile(r"[.!?;]\s|\n\n")


def _v1_6_298_foundry_context_accepts(text: str,
                                       match_start: int,
                                       match_end: int) -> bool:
    """v1.6.298 — for #191 round-2 NOT VERIFIED. Decide whether a
    candidate foundry-token match should be accepted by checking the
    SAME-SENTENCE positive / deny context (not ±200-char window).

    Sentence containing the match is bounded by:
      * The nearest preceding sentence-terminator (`[.!?]\\s` /
        `\\n\\n`) before `match_start`, defaulting to 0.
      * The next sentence-terminator at or after `match_end`,
        defaulting to len(text).

    Reject when the enclosing sentence matches the FPGA-tool-vendor
    deny. Accept ONLY when the same sentence also matches the ASIC-
    tapeout positive context. Bare foundry tokens in a sentence with
    no positive vocabulary are rejected — that prevents company-name
    casts that have no semantic tape-out claim.

    Chip-AGNOSTIC: open-standard FPGA + tape-out vocabulary, no chip
    literals.
    """
    if not isinstance(text, str) or not text:
        return True
    # Locate sentence start: the most recent sentence-boundary match
    # whose end <= match_start. Iterate finditer over [0, match_start).
    sent_start = 0
    for m in _V1_6_298_RE_SENTENCE_BOUNDARY.finditer(text, 0, match_start):
        sent_start = m.end()
    # Locate sentence end: the first sentence-boundary match starting
    # at or after match_end.
    m_end = _V1_6_298_RE_SENTENCE_BOUNDARY.search(text, match_end)
    sent_end = m_end.start() if m_end else len(text)
    sentence = text[sent_start:sent_end]
    if _V1_6_298_RE_FPGA_TOOL_VENDOR_DENY.search(sentence):
        return False
    if _V1_6_297_RE_FOUNDRY_POSITIVE_CONTEXT.search(sentence):
        return True
    return False


# v1.6.346 — for #243 P3 ORGANIC. Doc-generator config file deny-list.
# The `_V1_6_295_RE_DIE_DIMENSIONS` regex matches `<num> x <num> (um|mm)`
# anywhere — including doc-generator config files (Doxyfile, conf.py,
# Makefile, .editorconfig, .bib, *.tex) that contain comment lines like
# "PAPER_TYPE — a4 (210 x 297 mm)". The paper-size literal then ships
# into `L1.tapeout_metadata.die_dimensions_evidence` as a false-positive
# die size (A4 paper, A5 envelope, letter size, etc.).
#
# Add a basename / suffix deny-list. When the source file is a known
# doc-generator config, the die-dimensions emit is skipped. Other
# tapeout-metadata fields (foundry / process_node) are also skipped
# because doc-generator configs are never a chip-spec authority.
#
# Chip-AGNOSTIC: pure filename heuristic over open-standard doc-tool
# config names. No chip-class literal participates.
_V1_6_346_DOC_GENERATOR_CONFIG_BASENAMES = frozenset({
    "doxyfile", "doxyfile.in", "doxygen.conf",
    "conf.py", "sphinx.conf",
    "makefile", "makefile.in", "makefile.am", "make.bat",
    ".editorconfig",
    "package.json", "package-lock.json",
    "setup.cfg", "setup.py", "pyproject.toml",
    "cmakelists.txt", "cmakelists.txt.in",
})

_V1_6_346_DOC_GENERATOR_CONFIG_SUFFIXES = (
    ".bib", ".cfg", ".ini", ".toml",
    ".tex", ".aux", ".log",
)


def _v1_6_346_is_doc_generator_config(fname: str) -> bool:
    """v1.6.346 — for #243 P3 ORGANIC. Return True when `fname` is a
    doc-generator / build-tool config file whose literal numeric
    pairs (paper size, font size, page dimensions) must NOT be
    treated as chip die-dimensions evidence.

    Chip-AGNOSTIC: pure filename heuristic over open-standard
    doc-tool config names.
    """
    if not isinstance(fname, str) or not fname:
        return False
    try:
        base = Path(fname).name.lower()
    except Exception:
        return False
    if base in _V1_6_346_DOC_GENERATOR_CONFIG_BASENAMES:
        return True
    if base.endswith(_V1_6_346_DOC_GENERATOR_CONFIG_SUFFIXES):
        return True
    return False


def _v1_6_295_extract_tapeout_metadata(text: str
                                        ) -> Optional[Dict[str, Any]]:
    """v1.6.295 — for #186 ORGANIC. Extract tapeout metadata
    (die_size_um, foundry, process_node) from a doc text blob.
    Returns None when nothing matches.

    Chip-AGNOSTIC: open-standard foundry / process node vocabulary.

    v1.6.297 — for #191 ORGANIC. The foundry match is now gated on
    an ASIC-tapeout positive-context probe. FPGA-only mentions
    (`Synthesised with <FPGA Toolchain> for <FPGA Family>`) no
    longer pull the FPGA vendor token into `foundry`.
    """
    if not isinstance(text, str) or not text:
        return None
    out: Dict[str, Any] = {}
    m = _V1_6_295_RE_DIE_DIMENSIONS.search(text)
    if m:
        try:
            w = float(m.group(1))
            h = float(m.group(2))
            unit = (m.group(3) or "").lower().replace("µ", "u")
            if unit == "mm":
                w *= 1000.0
                h *= 1000.0
            out["die_size_um"] = [
                int(w) if float(w).is_integer() else w,
                int(h) if float(h).is_integer() else h,
            ]
            out["die_dimensions_evidence"] = m.group(0).strip()[:80]
        except (TypeError, ValueError):
            pass
    # v1.6.333 — for #231 P2 ORGANIC. Unit-less prose fallback. When
    # the primary regex did not fire (no inline unit suffix), try
    # the prose-anchored regex and infer the unit from a ±500-char
    # window. Stamp `die_dimensions_unit_inferred=True` so downstream
    # consumers can distinguish unit-explicit matches from inferred
    # ones. Chip-AGNOSTIC: open-vocabulary prose anchor.
    if "die_size_um" not in out:
        m2 = _V1_6_333_RE_DIE_DIMENSIONS_NO_UNIT.search(text)
        if m2:
            try:
                w = float(m2.group(1))
                h = float(m2.group(2))
                unit = _v1_6_333_infer_die_dim_unit(text, m2.start())
                if unit == "mm":
                    w *= 1000.0
                    h *= 1000.0
                out["die_size_um"] = [
                    int(w) if float(w).is_integer() else w,
                    int(h) if float(h).is_integer() else h,
                ]
                out["die_dimensions_evidence"] = (
                    m2.group(0).strip()[:80]
                )
                out["die_dimensions_unit_inferred"] = True
            except (TypeError, ValueError):
                pass
    # v1.6.297 — for #191 ORGANIC. Walk every candidate foundry-token
    # match (not just the first) so an early FPGA-vendor mention that
    # gets rejected doesn't suppress a later ASIC-tapeout hit in the
    # same doc. First accepted match wins.
    #
    # v1.6.298 — for #191 round-2 NOT VERIFIED. The v1.6.297 helper
    # used a ±200-char positive-context window; real benchmark READMEs
    # had a generic "taped out as an ASIC" sentence land inside the
    # 200-char window of `Intel` even though the FPGA vendor was in a
    # DIFFERENT sentence. The v1.6.298 helper tightens to
    # SAME-SENTENCE scope and also broadens the deny list with
    # VJTAG / VJtag / Hex Format tokens.
    for fm in _V1_6_295_RE_FOUNDRY_OPEN.finditer(text):
        if not _v1_6_298_foundry_context_accepts(
                text, fm.start(), fm.end()):
            continue
        out["foundry"] = fm.group(1).strip()
        break
    pm = _V1_6_295_RE_PROCESS_NODE.search(text)
    if pm:
        try:
            out["process_node"] = int(pm.group(1)) and f"{int(pm.group(1))}nm"
        except (TypeError, ValueError):
            pass
    if not out:
        return None
    return out


# v1.6.295 — for #188 ORGANIC. Badge / shields.io / CI workflow URL
# deny patterns + image-embed name prefix detector. Used by
# readme_deep_parser to reject markdown image-badge entries from
# L1.references.
_V1_6_295_RE_BADGE_URL = re.compile(
    r"(shields\.io|badge\.svg|workflow\.svg|"
    r"github\.com/[^/]+/[^/]+/actions/workflow|"
    r"github\.com/[^/]+/[^/]+/workflows/[^/]+/badge|"
    r"coveralls|codecov\.io/[^\s]*svg|"
    r"travis-ci|circleci\.com/[^\s]*svg|"
    r"img\.shields\.io|api\.travis-ci)",
    re.IGNORECASE,
)


def _v1_6_295_is_badge_reference(name_text: str, url_text: str) -> bool:
    """v1.6.295 — for #188 ORGANIC. Return True when the (name, url)
    pair is a CI status badge / shields.io image / image-embed
    rather than a real citation.

    Chip-AGNOSTIC: generic URL deny + image-embed shape detection.
    """
    if isinstance(name_text, str) and name_text.lstrip().startswith("!["):
        return True
    if isinstance(url_text, str) and _V1_6_295_RE_BADGE_URL.search(url_text):
        return True
    return False


# v1.6.295 — for #189 ORGANIC. Features-bullet quality regexes.
# GFM / Gitea emoji shortcode (`:name:` syntax), fragmentary
# trailing-connective bullets (ending in `and`/`or` or a `:`),
# interrogative pitch lines (starting with `Looking for`/`Are
# you`/`How`/`What`/`Which`/`Why`).
# Chip-AGNOSTIC: pure typographic markup + English-prose shape.
_V1_6_295_RE_EMOJI_SHORTCODE = re.compile(
    r"^:[a-z0-9_+\-]+:\s*", re.IGNORECASE
)
_V1_6_295_RE_FRAGMENTARY_TAIL = re.compile(
    r"\b(?:and|or)\s*$|[:：]\s*$|\?\s*$",
    re.IGNORECASE,
)
_V1_6_295_RE_INTERROGATIVE_HEAD = re.compile(
    r"^(?:looking\s+for|are\s+you|do\s+you|how|what|which|why)\b",
    re.IGNORECASE,
)


def _v1_6_295_strip_emoji_shortcode(s: str) -> str:
    """v1.6.295 — for #189 ORGANIC. Strip leading GFM emoji
    shortcode prefix(es) from a bullet body.

    Chip-AGNOSTIC.
    """
    if not isinstance(s, str) or not s:
        return s or ""
    # Strip multiple leading shortcodes (`:recycle: :mag: rest`).
    while True:
        m = _V1_6_295_RE_EMOJI_SHORTCODE.match(s)
        if not m:
            break
        s = s[m.end():]
    return s


def _v1_6_295_is_rejectable_feature_bullet(s: str) -> bool:
    """v1.6.295 — for #189 ORGANIC. Return True when `s` is a
    fragmentary / interrogative bullet that should not land in
    L1.features. Caller is expected to call
    `_v1_6_295_strip_emoji_shortcode` first.

    Chip-AGNOSTIC.
    """
    if not isinstance(s, str):
        return False
    s = s.strip()
    if not s:
        return True
    if _V1_6_295_RE_FRAGMENTARY_TAIL.search(s):
        return True
    if _V1_6_295_RE_INTERROGATIVE_HEAD.search(s):
        return True
    return False


# v1.6.537 — for #365 ORGANIC. L1.features RST grid-table noise
# filter. Sphinx-based RTL doc trees commonly use RST `list-table::`
# / `csv-table::` / grid-table directives. The Features-section
# bullet walker (`_extract_l1_features_bullets_after_anchor`) sees
# table-cell content as `-`-prefixed bullets and harvests obvious
# column-header words (`Version`, `Configurability`,
# `Always enabled`, `Yes`, `No`, etc.) and mid-row continuation
# fragments (`- I: Integer base ISA`, `- M: Multiply extension`)
# as if they were real features. Field-agent verified this on
# 8-IC benchmark: 3 - 17 of 20 captured items per IC were RST
# grid-table noise rather than actual features. v1.6.537 adds a
# per-bullet quality check and raises the hard cap from 20 → 64
# so legitimate long feature lists are no longer truncated.
#
# Chip-AGNOSTIC: pure structural English / RST grammar; no
# chip-class string literal participates.
_V1_6_537_RST_TABLE_HEADER_WORDS = frozenset({
    "version", "configurability", "always enabled",
    "yes", "no", "n/a", "—", "-", "ready", "default",
    "name", "type", "description", "value", "unit",
    "row", "column", "header", "footer",
    # Common asciidoc / RST register-cell shorthand:
    "true", "false", "tbd", "tba",
})

_V1_6_537_RST_MID_ROW_CONTINUATION_RE = re.compile(
    # ``- I:``, ``- M:``, ``- C:`` — short letter followed by
    # colon-prefixed value, very common in RV-extension catalogues
    # extracted as text. The walker strips the leading ``- ``
    # marker via ``_strip_bullet_markdown`` before this predicate
    # sees the bullet, so the leading marker is optional and the
    # ``^[A-Za-z]{1,5}\s*:`` shape is the operative test. The
    # colon-separator differentiates these from legitimate
    # bullets starting with a 1-5 char acronym followed by a
    # space + multi-word phrase (acronym idiom).
    r"^\s*(?:-\s+)?(?P<short>[A-Za-z]{1,5})\s*:",
)


def _v1_6_537_is_feature_quality(item):
    """v1.6.537 — for #365 ORGANIC. Per-bullet structural quality
    floor for L1.features. Reject RST grid-table column-header
    words (``Version`` / ``Always enabled`` / ``Yes`` / etc.),
    mid-row continuation fragments (``- I: ...``), and bullets
    shorter than the legitimate-feature minimum (8 chars).

    Returns True for legitimate feature bullets (multi-word
    phrases, full sentences, standard-name strings) — i.e. the
    walker keeps them; False to drop.

    Chip-AGNOSTIC: pure structural string predicate.

    v1.6.541 — for #365 R1 Fix A. Accept LEGITIMATE RST list-table
    rows (``- M: Standard Extension for Integer Multiplication and
    Division``) BEFORE the v1.6.537 mid-row guard kicks in. The
    v1.6.537 guard was over-correcting: it killed real feature
    rows whose ``- X: <description>`` shape matches the mid-row
    fragment shape but whose body is substantive (≥ 10 chars).
    Discriminator: legitimate row has substantive description
    body. chip-AGNOSTIC.
    """
    if not isinstance(item, str):
        return False
    s = item.strip()
    if len(s) < 8:
        return False
    low = s.lower().rstrip(".:,-")
    if low in _V1_6_537_RST_TABLE_HEADER_WORDS:
        return False
    # v1.6.541 — for #365 R1 Fix A. Accept legitimate RST list-
    # table rows with ≥ 10-char description body BEFORE the
    # v1.6.537 mid-row guard rejects them. RV-extension catalogue
    # rows (``- M: Standard Extension for Integer Multiplication
    # and Division``) MUST land in L1.features even though the
    # row shares the ``^- X:`` prefix shape with the mid-row
    # continuation fragment. chip-AGNOSTIC.
    if _v1_6_541_is_list_table_row_with_desc(s):
        return True
    if _V1_6_537_RST_MID_ROW_CONTINUATION_RE.match(s):
        return False
    return True


def _v1_6_537_is_walker_noise(item) -> bool:
    """v1.6.281 contract restore. Walker-level NOISE predicate for
    `_harvest_bullets_after_heading`. Rejects ONLY the structural
    noise classes v1.6.537 targeted — RST grid-table header words
    (`Version` / `Yes` / `Default` / ...) and bare mid-row
    continuation fragments (`- I:` / `- M:`) — WITHOUT the bare
    8-char length floor of `_v1_6_537_is_feature_quality`.

    Rationale: the 8-char floor in the public predicate exists for
    direct grid-table-cell screening, but applying it unconditionally
    in the heading-bullet walker wrongly drops LEGITIMATE short
    Markdown feature bullets (`- one`, `- two`) that the v1.6.281
    Features-anchor contract requires to survive. The structural
    noise classes (header word, mid-row fragment) remain rejected so
    the v1.6.537 walker e2e behaviour is preserved.

    Returns True when `item` is structural noise (drop it).
    chip-AGNOSTIC: pure structural string predicate.
    """
    if not isinstance(item, str):
        return True
    s = item.strip()
    if not s:
        return True
    low = s.lower().rstrip(".:,-")
    if low in _V1_6_537_RST_TABLE_HEADER_WORDS:
        return True
    # Legitimate RST list-table row (substantive body) is NOT noise.
    if _v1_6_541_is_list_table_row_with_desc(s):
        return False
    if _V1_6_537_RST_MID_ROW_CONTINUATION_RE.match(s):
        return True
    return False


# v1.6.541 — for #365 R1 Fix A. RST list-table row acceptance
# regex + helper. v1.6.537's `_V1_6_537_RST_MID_ROW_CONTINUATION_RE`
# (`^\s*(?:-\s+)?[A-Za-z]{1,5}\s*:`) was designed to reject mid-row
# continuation fragments like ``- M:`` (no body), but it also kills
# LEGITIMATE RST list-table rows like ``- M: Standard Extension for
# Integer Multiplication and Division`` where the description body
# IS the feature content. Field-agent verified on real benchmark:
# RV-extension list-tables (8+ rows per IC) get nuked. Discriminator:
# a legitimate row has substantive description body (≥ 10 chars
# after the colon). chip-AGNOSTIC: pure structural shape.
_V1_6_541_RST_LIST_TABLE_ROW_RE = re.compile(
    # The optional leading ``- `` mirrors v1.6.537's mid-row regex
    # — the bullet glyph is normally stripped before this predicate
    # runs (the walker pre-strips it via the bullet regex capture
    # group), but the optional form keeps the predicate usable as
    # a stand-alone helper. ``\S.{8,300}`` enforces description
    # body length ≥ 10 chars (1 non-space + 8 wildcard, the
    # 10th-char floor that distinguishes a real list-table row
    # from a bare mid-row fragment).
    r"^\s*(?:-\s+)?(?P<short>[A-Za-z][\w]{0,4})\s*:\s+"
    r"(?P<desc>\S.{8,300})",
)


def _v1_6_541_is_list_table_row_with_desc(item) -> bool:
    """v1.6.541 — for #365 R1 Fix A. Return True iff ``item`` is a
    legitimate RST list-table row with a substantive description
    body (≥ 10 chars after the colon). Used to accept rows like
    ``- M: Standard Extension for Integer Multiplication and
    Division`` that v1.6.537's mid-row guard would otherwise
    reject. chip-AGNOSTIC."""
    if not isinstance(item, str) or not item:
        return False
    return _V1_6_541_RST_LIST_TABLE_ROW_RE.match(item) is not None


# v1.6.295 — for #183 ORGANIC. Register array-index name pattern.
# Canonical syntax for "element N of a register array": `PREFIX[N]`.
# Chip-AGNOSTIC: standard CSR-spec convention.
_V1_6_295_RE_ARRAY_INDEX_REG = re.compile(
    r"^([A-Za-z_][A-Za-z0-9_]*)\[(\d+)\]$"
)


# v1.6.450 — for #324 P2 ORGANIC. AsciiDoc / Markdown table
# ellipsis continuation row recognition. The canonical "indicate
# range" idiom in AsciiDoc / GFM register tables is a single
# `| ... | ... | ... |` row sandwiched between the low-index
# rows (`REG[0]`, `REG[1]`) and the high-index rows (`REG[N-1]`,
# `REG[N]`). Without this recognition the v1.6.295 collapser
# breaks at the ellipsis row and emits two tiny `array_size=2`
# arrays instead of a single `array_size=N+1` array — losing the
# in-between elements entirely.
#
# The token matched here is either three ASCII dots (`...`) or the
# Unicode ellipsis `…` (`…`), optionally surrounded by
# backticks / apostrophes / single quotes / plain whitespace. The
# match is conservative — a row qualifies as the ellipsis row ONLY
# when its `name` cell is one of those ellipsis variants. Address /
# description columns aren't consulted because AsciiDoc users
# routinely leave them blank or fill them with their own `...`.
#
# Chip-AGNOSTIC: pure documentation idiom; no chip-class literals.
_V1_6_450_ELLIPSIS_TOKENS = frozenset({
    "...", "…", ". . .", "....", ".....",
})


def _v1_6_450_is_ellipsis_row(row) -> bool:
    """v1.6.450 — for #324 P2 ORGANIC. True iff the row's `name`
    field is the AsciiDoc / Markdown table ellipsis idiom — three
    ASCII dots, the Unicode ellipsis, or one of the spaced
    variants. Backticks / quotes / surrounding whitespace are
    stripped before comparison. False for any non-dict row, for
    rows without a string `name`, and for rows whose name has
    real alpha-numeric content.

    Chip-AGNOSTIC.
    """
    if not isinstance(row, dict):
        return False
    name = row.get("name")
    if not isinstance(name, str):
        return False
    stripped = name.strip().strip("`'\"")
    return stripped in _V1_6_450_ELLIPSIS_TOKENS


# v1.6.454 — for #324 R2 ORGANIC. AsciiDoc / Markdown pipe-table
# ellipsis-row sentinel detector. The v1.6.450 collapser correctly
# expands `REG[0] ... REG[N]` to `array_size = N + 1` IF and ONLY
# IF an ellipsis-row sentinel sits between the low-side and high-
# side rows in the `registers` list. Pre-v1.6.454 the upstream
# table walkers (`_reg_row_re_rst_grid`, `_reg_row_re_adoc`) used
# `addr` group `0x[0-9A-Fa-f]` and `name` group `[a-zA-Z_][\w.\[\]]`
# which both reject the ellipsis row shape `| ... | ... | ... |`,
# so the row was dropped at the regex level and never reached the
# v1.6.450 collapser. The chain `array_size_source =
# register_array_ellipsis_inferred_v1_6_450` therefore fired zero
# times on real benchmarks.
#
# This regex matches an AsciiDoc / Markdown pipe-table row that
# consists ENTIRELY of ellipsis cells. Each cell is `...`,
# `` `...` ``, `'...'`, or `"..."` with surrounding whitespace.
# The row must have AT LEAST two ellipsis cells (one ellipsis +
# one delimiter means an isolated bullet line, not a table row).
#
# Chip-AGNOSTIC: pure AsciiDoc / Markdown table idiom; no chip-
# class string literal.
#
# The regex accepts BOTH the Markdown / GFM canonical shape
# `| ... | ... | ... |` (every cell delimited by a leading AND
# trailing pipe — trailing pipe present) AND the AsciiDoc
# canonical shape `| ... | ... | ...` (no trailing pipe; the
# trailing cell is delimited by end-of-line). Cells may be
# wrapped in backticks (`` `...` ``), single quotes (`'...'`), or
# double quotes (`"..."`). Whitespace inside cells is permitted.
# Minimum cell count is 2 (one ellipsis + one delimiter is not a
# table row — it would be a stray bullet).
#
# Two-alternation shape:
#   (A) Markdown trailing-pipe form — `| <ell> | <ell> | ... |`
#       (2+ ellipsis cells, every one delimited by leading and
#       trailing pipe).
#   (B) AsciiDoc no-trailing-pipe form — `| <ell> | <ell> | ...`
#       (2+ ellipsis cells; trailing cell ends at end-of-line).
_V1_6_454_ELL_CELL = r"\s*[`'\"]?\.{3}[`'\"]?\s*"
_V1_6_454_RE_ELLIPSIS_ROW_MULTI_COL = re.compile(
    r"^\s*\|"
    r"(?:"
    # (A) trailing-pipe form: 2+ "<ell>|" groups
    + r"(?:" + _V1_6_454_ELL_CELL + r"\|){2,}"
    + r"|"
    # (B) no-trailing-pipe form: 1+ "<ell>|" groups + 1 final <ell>
    + r"(?:" + _V1_6_454_ELL_CELL + r"\|){1,}"
    + _V1_6_454_ELL_CELL
    + r")"
    r"\s*$"
)


def _v1_6_454_is_ellipsis_row_line(line: str) -> bool:
    """v1.6.454 — for #324 R2 ORGANIC. True iff the given table-row
    line is an all-ellipsis sentinel (2+ pipe-separated cells each
    containing only ``...``, ```...```, ``'...'``, or
    ``\"...\"``). False on real data rows, partial matches, and
    non-table lines.

    Chip-AGNOSTIC: pure AsciiDoc / Markdown table idiom.
    """
    if not isinstance(line, str) or not line:
        return False
    return bool(_V1_6_454_RE_ELLIPSIS_ROW_MULTI_COL.match(line))


def _v1_6_454_inject_ellipsis_sentinels(
        registers: List[Dict[str, Any]],
        text: str,
        fname: str) -> int:
    """v1.6.454 — for #324 R2 ORGANIC. Inject ellipsis-row sentinels
    into the ``registers`` list so the downstream v1.6.450
    collapser can extrapolate array_size across the abbreviated
    range. Operates as a per-file post-pass on the slice of
    ``registers`` whose ``evidence`` matches the current file.

    Detection algorithm (chip-AGNOSTIC, no chip-class literals):
      1. Find each ellipsis-row line in ``text``.
      2. Find the LAST and FIRST register entries in ``registers``
         whose evidence matches ``input/docs/{fname}`` AND whose
         name carries the canonical ``PREFIX[N]`` shape on either
         side of the ellipsis position (text-position-ordered by
         hex-address occurrence in ``text``).
      3. If a same-prefix gap exists (high_idx > low_idx + 1),
         insert one sentinel row between them with
         ``_ellipsis_marker = True`` and
         ``extraction_strategy = asciidoc_table_ellipsis_marker_v1_6_454``.
      4. ALSO flag any v1.6.326-collapsed array record whose
         raw-rows span the ellipsis row with
         ``_v1_6_388_ellipsis_seen = True``. That bypasses the
         v1.6.332 density floor so the collapsed-but-sparse record
         survives instead of being re-emitted as two flat rows.

    Returns the total number of sentinels injected (case 3) plus
    collapsed records flagged (case 4).
    """
    if not isinstance(text, str) or not text:
        return 0
    if not isinstance(registers, list) or not registers:
        return 0
    # Find ellipsis-row positions in the text.
    ellipsis_positions: List[int] = []
    pos = 0
    for raw_line in text.splitlines(keepends=False):
        if _v1_6_454_is_ellipsis_row_line(raw_line):
            ellipsis_positions.append(pos)
        # +1 for the newline stripped by splitlines
        pos += len(raw_line) + 1
    if not ellipsis_positions:
        return 0
    evidence_match = f"input/docs/{fname}"
    injected = 0

    # === Case 3: flat PREFIX[N] / PREFIX[M] rows with a gap ===
    # Build text-position index of flat register entries from this
    # file whose name matches the canonical ``BASE[N]`` shape.
    file_register_positions: List[Tuple[int, int]] = []  # (text_pos, list_idx)
    for li, r in enumerate(registers):
        if not isinstance(r, dict):
            continue
        if r.get("evidence") != evidence_match:
            continue
        nm = r.get("name")
        addr = r.get("address")
        if not isinstance(nm, str) or not isinstance(addr, str):
            continue
        if not _V1_6_295_RE_ARRAY_INDEX_REG.match(nm):
            continue
        # Locate the register's first text-position via address. The
        # ordering relative to the ellipsis row is what matters for
        # the v1.6.450 walker, not the exact column. Address tokens
        # are usually unique-ish in a register table so the false-
        # ordering risk is small.
        try:
            t_pos = text.find(addr)
        except Exception:
            t_pos = -1
        if t_pos < 0:
            continue
        file_register_positions.append((t_pos, li))
    if file_register_positions:
        file_register_positions.sort(key=lambda p: p[0])
        # Iterate from the LAST ellipsis row to the FIRST so list
        # indices for earlier ellipsis rows remain stable as we
        # insert sentinels into ``registers``.
        for ell_pos in reversed(ellipsis_positions):
            low_idx: Optional[int] = None
            high_idx: Optional[int] = None
            for (tp, li) in file_register_positions:
                if tp < ell_pos:
                    low_idx = li
                elif tp > ell_pos and high_idx is None:
                    high_idx = li
                    break
            if low_idx is None or high_idx is None:
                continue
            low_row = registers[low_idx]
            high_row = registers[high_idx]
            lm = _V1_6_295_RE_ARRAY_INDEX_REG.match(low_row.get("name", ""))
            hm = _V1_6_295_RE_ARRAY_INDEX_REG.match(high_row.get("name", ""))
            if lm is None or hm is None:
                continue
            if lm.group(1) != hm.group(1):
                continue
            try:
                low_n = int(lm.group(2))
                high_n = int(hm.group(2))
            except (TypeError, ValueError):
                continue
            if high_n <= low_n + 1:
                # No gap to span — abbreviation is unnecessary.
                continue
            sentinel = {
                "name": "...",
                "address": "...",
                "_ellipsis_marker": True,
                "extraction_strategy": (
                    "asciidoc_table_ellipsis_marker_v1_6_454"
                ),
                "evidence": evidence_match,
            }
            registers.insert(low_idx + 1, sentinel)
            injected += 1

    # === Case 4: v1.6.326-collapsed array record bypass flag ===
    # When the base passes the length floor (``MYREG[N]`` etc.) the
    # rows were already folded by ``_v1_6_326_handle_array_register``
    # into ONE array record carrying ``first_index`` / ``last_index``
    # and raw-row addresses. The v1.6.332 density floor would then
    # reject the sparse-span record (count 2, span 16384). Flagging
    # ``_v1_6_388_ellipsis_seen`` short-circuits that rejection.
    if ellipsis_positions:
        for r in registers:
            if not isinstance(r, dict):
                continue
            if not r.get("array"):
                continue
            if (r.get("extraction_strategy")
                    != "array_index_collapse_v1_6_326"):
                continue
            if r.get("evidence") != evidence_match:
                continue
            if r.get("_v1_6_388_ellipsis_seen"):
                continue
            raw_rows = r.get("_v1_6_332_raw_rows") or []
            if len(raw_rows) < 2:
                continue
            # Locate first and last raw-row addresses in text.
            row_positions: List[int] = []
            for rr in raw_rows:
                if not isinstance(rr, dict):
                    continue
                addr = rr.get("address")
                if not isinstance(addr, str):
                    continue
                try:
                    t = text.find(addr)
                except Exception:
                    t = -1
                if t >= 0:
                    row_positions.append(t)
            if len(row_positions) < 2:
                continue
            lo = min(row_positions)
            hi = max(row_positions)
            # Flag the record only if at least one ellipsis row sits
            # between the first and last raw row in the source.
            if any(lo < ep < hi for ep in ellipsis_positions):
                r["_v1_6_388_ellipsis_seen"] = True
                injected += 1
    return injected


# v1.6.455 — for #324 R3 ORGANIC. Partial-ellipsis row detector with
# positional alignment. v1.6.454's whole-row regex requires EVERY
# pipe-table cell to be the ellipsis token (`...`). Real benchmark
# AsciiDoc register tables abbreviate the indexed-name + address
# columns but PRESERVE shared columns such as the bit-range cell
# (`31:0`) and access-type cell (`(r)/(w)`) — for example:
#     | ... | ... | 31:0 | (r)/(w) | ... |
# The v1.6.454 regex returns False on that row → the sentinel
# injector never fires → the v1.6.450 collapser remains dead code
# on the real fixture even after R2 wiring. This v1.6.455 detector
# accepts partial-ellipsis rows by checking:
#   1. At least two cells in the row are exactly the ellipsis token
#      (`...`, Unicode `…`, or `..`), with optional backtick / quote
#      wrap and surrounding whitespace.
#   2. At least one of those ellipsis cell positions aligns with a
#      cell of `BASE[N]` shape in the row immediately above OR below.
# Carry-over (non-ellipsis) cells like `31:0` or `(r)/(w)` are
# permitted because they're disambiguated by the positional-alignment
# rule — the abbreviation has to ALIGN with a real indexed-name cell
# somewhere in the neighbouring row.
# Chip-AGNOSTIC: pure AsciiDoc / Markdown table idiom; no chip-class
# string literal in the decision logic.
_V1_6_455_RE_INDEXED_CELL = re.compile(
    r"^[`'\"]?\s*[A-Za-z_]\w*\s*\[\s*\d+\s*\]\s*[`'\"]?$"
)
_V1_6_455_ELLIPSIS_CHARS = ("...", "…", "..")  # ASCII + unicode


def _v1_6_455_cell_is_ellipsis(cell) -> bool:
    """v1.6.455 — for #324 R3 ORGANIC. True iff the cell (after
    whitespace / backtick / quote strip) is the ASCII triple-dot,
    the Unicode ellipsis `…`, or the two-dot abbreviation
    `..`. Empty / non-string / non-ellipsis cells return False.

    Chip-AGNOSTIC.
    """
    if not isinstance(cell, str) or not cell:
        return False
    stripped = cell.strip().strip("`'\"").strip()
    return stripped in _V1_6_455_ELLIPSIS_CHARS


def _v1_6_455_cell_is_indexed_name(cell) -> bool:
    """v1.6.455 — for #324 R3 ORGANIC. True iff the cell (after
    whitespace / backtick / quote strip) matches the canonical
    `BASE[N]` indexed-name shape used by register / slot / channel
    arrays (e.g. `REG[0]`, `slot[16383]`). Backtick-wrapped form
    accepted. Returns False on the ellipsis token, on prose cells,
    and on hex addresses.

    Chip-AGNOSTIC.
    """
    if not isinstance(cell, str) or not cell:
        return False
    stripped = cell.strip()
    return bool(_V1_6_455_RE_INDEXED_CELL.match(stripped))


def _v1_6_455_split_row_into_cells(line: str):
    """v1.6.455 — for #324 R3 ORGANIC. Split a pipe-table row into
    cell strings. Handles both Markdown trailing-pipe form
    (`| a | b | c |`) and AsciiDoc no-trailing-pipe form
    (`| a | b | c`). Leading whitespace tolerated (for `.. table::`
    directive-indented grids). Returns the list of cell strings
    (un-stripped). Returns an empty list when the line is not a
    pipe-table row.

    Chip-AGNOSTIC.
    """
    if not isinstance(line, str) or not line:
        return []
    stripped = line.lstrip()
    if not stripped.startswith("|"):
        return []
    # Drop leading pipe; preserve interior cells exactly.
    body = stripped[1:]
    # Drop trailing pipe (if present) and trailing whitespace.
    rstripped = body.rstrip()
    if rstripped.endswith("|"):
        rstripped = rstripped[:-1]
    # `split("|")` is safe because pipe-table cells are never
    # allowed to contain literal pipes — they'd need escaping which
    # is rare in register tables and not present in the failing
    # benchmark row. False splits don't break the partial-ellipsis
    # heuristic because positional alignment still has to hold.
    return rstripped.split("|")


def _v1_6_455_is_partial_ellipsis_row(
        row_cells, prev_row_cells=None, next_row_cells=None) -> bool:
    """v1.6.455 — for #324 R3 ORGANIC. Accept a row as a partial-
    ellipsis sentinel when:
      - It has at least two cells that are exactly the ellipsis
        token (`...`, `…`, or `..`).
      - At least one of those ellipsis-cell positions aligns
        positionally with a `BASE[N]`-shape cell in the row above
        OR below (whichever is available).
    Carry-over (non-ellipsis) cells in other positions are allowed.

    Chip-AGNOSTIC.
    """
    if not isinstance(row_cells, list) or not row_cells:
        return False
    ellipsis_positions = [
        i for i, c in enumerate(row_cells)
        if _v1_6_455_cell_is_ellipsis(c)
    ]
    if len(ellipsis_positions) < 2:
        return False
    for pos in ellipsis_positions:
        for neighbor in (prev_row_cells, next_row_cells):
            if (isinstance(neighbor, list)
                    and pos < len(neighbor)
                    and _v1_6_455_cell_is_indexed_name(neighbor[pos])):
                return True
    return False


def _v1_6_455_inject_partial_ellipsis_sentinels(
        registers, text, fname) -> int:
    """v1.6.455 — for #324 R3 ORGANIC. Fallback partial-ellipsis
    injector. The v1.6.454 strict whole-row injector handles rows
    where EVERY cell is `...`. v1.6.455 catches rows where only
    SOME cells are `...` and the rest are carry-over content
    (`31:0`, `(r)/(w)`, etc.), as long as the ellipsis cells align
    positionally with a `BASE[N]`-shape cell in the adjacent row.

    Wiring is identical to v1.6.454: emit a sentinel between the
    surrounding low-side and high-side `PREFIX[N]` / `PREFIX[M]`
    rows so the v1.6.450 collapser can extrapolate `array_size =
    high_idx + 1`. Sentinel carries `extraction_strategy =
    asciidoc_table_partial_ellipsis_marker_v1_6_455`.

    Returns the number of sentinels injected.

    Chip-AGNOSTIC: positional-alignment rule only; no chip-class
    string literal.
    """
    if not isinstance(text, str) or not text:
        return 0
    if not isinstance(registers, list) or not registers:
        return 0
    raw_lines = text.splitlines(keepends=False)
    if not raw_lines:
        return 0
    # Pre-split every line into cell arrays. Non-pipe-table lines
    # become empty lists which the partial-row detector rejects.
    rows_with_cells = [
        _v1_6_455_split_row_into_cells(rl) for rl in raw_lines
    ]
    # v1.6.455 — text-position offset for each line, so we can find
    # the line's character offset in `text` (matches the v1.6.454
    # injector's `ellipsis_positions` convention).
    line_text_pos: list = []
    pos = 0
    for rl in raw_lines:
        line_text_pos.append(pos)
        pos += len(rl) + 1
    partial_positions: list = []  # text offsets of partial rows
    for i, row in enumerate(rows_with_cells):
        # Skip rows that match the v1.6.454 strict (100% ellipsis)
        # detector — they're already handled by the earlier pass.
        if _v1_6_454_is_ellipsis_row_line(raw_lines[i]):
            continue
        prev_cells = rows_with_cells[i - 1] if i > 0 else None
        next_cells = (rows_with_cells[i + 1]
                      if i + 1 < len(rows_with_cells) else None)
        if _v1_6_455_is_partial_ellipsis_row(row, prev_cells, next_cells):
            partial_positions.append(line_text_pos[i])
    if not partial_positions:
        return 0
    evidence_match = f"input/docs/{fname}"
    injected = 0
    # Build text-position index of flat register entries from this
    # file whose name matches the canonical `BASE[N]` shape — same
    # convention as the v1.6.454 injector.
    file_register_positions: list = []  # (text_pos, list_idx)
    for li, r in enumerate(registers):
        if not isinstance(r, dict):
            continue
        if r.get("evidence") != evidence_match:
            continue
        nm = r.get("name")
        addr = r.get("address")
        if not isinstance(nm, str) or not isinstance(addr, str):
            continue
        if not _V1_6_295_RE_ARRAY_INDEX_REG.match(nm):
            continue
        try:
            t_pos = text.find(addr)
        except Exception:
            t_pos = -1
        if t_pos < 0:
            continue
        file_register_positions.append((t_pos, li))
    if not file_register_positions:
        # No surrounding indexed-name rows exist — there is nothing
        # to sentinel between. Bail out without recording.
        return 0
    file_register_positions.sort(key=lambda p: p[0])
    # Iterate from the LAST partial-ellipsis row backward so list
    # indices for earlier rows remain stable as we insert sentinels.
    for ell_pos in reversed(partial_positions):
        low_idx = None
        high_idx = None
        for (tp, li) in file_register_positions:
            if tp < ell_pos:
                low_idx = li
            elif tp > ell_pos and high_idx is None:
                high_idx = li
                break
        if low_idx is None or high_idx is None:
            continue
        low_row = registers[low_idx]
        high_row = registers[high_idx]
        lm = _V1_6_295_RE_ARRAY_INDEX_REG.match(low_row.get("name", ""))
        hm = _V1_6_295_RE_ARRAY_INDEX_REG.match(high_row.get("name", ""))
        if lm is None or hm is None:
            continue
        if lm.group(1) != hm.group(1):
            continue
        try:
            low_n = int(lm.group(2))
            high_n = int(hm.group(2))
        except (TypeError, ValueError):
            continue
        if high_n <= low_n + 1:
            # Adjacent indices — abbreviation would be unnecessary.
            continue
        sentinel = {
            "name": "...",
            "address": "...",
            "_ellipsis_marker": True,
            "extraction_strategy": (
                "asciidoc_table_partial_ellipsis_marker_v1_6_455"
            ),
            "evidence": evidence_match,
        }
        registers.insert(low_idx + 1, sentinel)
        injected += 1
    return injected


def _v1_6_450_infer_stride_from_pair(rows):
    """v1.6.450 — for #324 P2 ORGANIC. Given the first two element
    rows of an array, return the integer stride (in bytes)
    between them. Returns None when either address is missing or
    unparseable. Used to extrapolate across the ellipsis row when
    the high-side anchor row's index proves the size.

    Chip-AGNOSTIC.
    """
    if not isinstance(rows, list) or len(rows) < 2:
        return None
    try:
        addrs = []
        for r in rows[:2]:
            a = r.get("address") if isinstance(r, dict) else None
            if isinstance(a, str) and a.lower().startswith("0x"):
                addrs.append(int(a, 16))
            elif isinstance(a, int):
                addrs.append(a)
            else:
                return None
        return addrs[1] - addrs[0]
    except Exception:
        return None


def _v1_6_295_collapse_register_arrays(rows: List[Dict[str, Any]]
                                        ) -> List[Dict[str, Any]]:
    """v1.6.295 — for #183 ORGANIC. Collapse adjacent register
    rows whose names share a common prefix + bracketed-index suffix
    (`PREFIX[0]`, `PREFIX[1]`, ...) AND have identical access tag
    AND have ascending addresses into a single array record.

    Each collapsed record carries:
      * name = the bare prefix
      * array_size = number of elements
      * base_addr = address of element 0 (when extractable)
      * stride_bytes = address gap between adjacent elements (when
        uniform; else None)
      * access / width / description = inherited from element 0
      * elements[] = original per-element rows (preserved so
        downstream equivalence-check consumers can still emit
        per-element checks)

    Rows whose name does not match the bracketed-index shape pass
    through unchanged. Returns the new list.

    Chip-AGNOSTIC.
    """
    if not isinstance(rows, list) or not rows:
        return rows
    out: List[Dict[str, Any]] = []
    i = 0
    n = len(rows)
    while i < n:
        row = rows[i]
        name = row.get("name") if isinstance(row, dict) else None
        m = (_V1_6_295_RE_ARRAY_INDEX_REG.match(name)
             if isinstance(name, str) else None)
        if not m:
            out.append(row)
            i += 1
            continue
        prefix = m.group(1)
        try:
            idx0 = int(m.group(2))
        except (TypeError, ValueError):
            out.append(row)
            i += 1
            continue
        # Walk forward collecting contiguous rows sharing the prefix
        # with ascending integer suffix and identical access tag.
        access_anchor = row.get("access")
        elements: List[Dict[str, Any]] = [row]
        expected_idx = idx0 + 1
        j = i + 1
        while j < n:
            nxt = rows[j]
            if not isinstance(nxt, dict):
                break
            nxt_name = nxt.get("name")
            nxt_m = (_V1_6_295_RE_ARRAY_INDEX_REG.match(nxt_name)
                     if isinstance(nxt_name, str) else None)
            if not nxt_m:
                break
            if nxt_m.group(1) != prefix:
                break
            try:
                nxt_idx = int(nxt_m.group(2))
            except (TypeError, ValueError):
                break
            if nxt_idx != expected_idx:
                break
            if nxt.get("access") != access_anchor:
                break
            elements.append(nxt)
            expected_idx += 1
            j += 1
        # v1.6.450 — for #324 P2 ORGANIC. AsciiDoc / Markdown
        # ellipsis-row range continuation. If the loop broke
        # because we hit a `...` / `…` row AND the row AFTER it
        # is a same-prefix indexed row with a higher index, treat
        # the gap as an inferred contiguous range. We don't add
        # the in-between rows as concrete elements (they aren't
        # in the source), but we DO set `array_size` to the high
        # anchor's index + 1 and record the inferred stride.
        ellipsis_size_inferred: Optional[int] = None
        ellipsis_stride_inferred: Optional[int] = None
        ellipsis_high_anchor_rows: List[Dict[str, Any]] = []
        if j < n and _v1_6_450_is_ellipsis_row(rows[j]):
            # Look one past the ellipsis row for the high-side
            # anchor. We walk as many same-prefix indexed rows as
            # are contiguous (e.g. REG[16382] then REG[16383]).
            k = j + 1
            high_anchors: List[Dict[str, Any]] = []
            expected_high_idx: Optional[int] = None
            while k < n:
                hr = rows[k]
                if not isinstance(hr, dict):
                    break
                hr_name = hr.get("name")
                hr_m = (_V1_6_295_RE_ARRAY_INDEX_REG.match(hr_name)
                         if isinstance(hr_name, str) else None)
                if not hr_m or hr_m.group(1) != prefix:
                    break
                try:
                    hr_idx = int(hr_m.group(2))
                except (TypeError, ValueError):
                    break
                if hr.get("access") != access_anchor:
                    break
                if expected_high_idx is None:
                    expected_high_idx = hr_idx + 1
                elif hr_idx != expected_high_idx:
                    break
                else:
                    expected_high_idx += 1
                high_anchors.append(hr)
                k += 1
            if high_anchors:
                try:
                    first_high_m = _V1_6_295_RE_ARRAY_INDEX_REG.match(
                        high_anchors[0].get("name"))
                    last_high_m = _V1_6_295_RE_ARRAY_INDEX_REG.match(
                        high_anchors[-1].get("name"))
                    if first_high_m and last_high_m:
                        first_high_idx = int(first_high_m.group(2))
                        last_high_idx = int(last_high_m.group(2))
                        if last_high_idx > idx0:
                            ellipsis_size_inferred = (
                                last_high_idx - idx0 + 1)
                            ellipsis_high_anchor_rows = list(
                                high_anchors)
                            # Stride preference: from low-side
                            # pair (most precise); fall back to
                            # last-low-to-first-high pair.
                            ellipsis_stride_inferred = (
                                _v1_6_450_infer_stride_from_pair(
                                    elements)
                            )
                            if (ellipsis_stride_inferred is None
                                    and elements
                                    and high_anchors):
                                # Two-row stride from {first_high
                                # ... first_high+1} when low side
                                # had only one row.
                                ellipsis_stride_inferred = (
                                    _v1_6_450_infer_stride_from_pair(
                                        high_anchors)
                                )
                            # Advance j past ellipsis + all high
                            # anchor rows so outer loop resumes
                            # after the range.
                            j = k
                except Exception:
                    ellipsis_size_inferred = None
                    ellipsis_high_anchor_rows = []
        if len(elements) < 2 and ellipsis_size_inferred is None:
            # Not actually an array — keep the single element as-is.
            out.append(row)
            i += 1
            continue
        # Compute base_addr + stride_bytes from element addresses.
        base_addr = row.get("address")
        stride_bytes: Optional[int] = None
        try:
            addrs = []
            for e in elements:
                a = e.get("address")
                if isinstance(a, str) and a.lower().startswith("0x"):
                    addrs.append(int(a, 16))
                elif isinstance(a, int):
                    addrs.append(a)
                else:
                    addrs.append(None)
            if all(a is not None for a in addrs) and len(addrs) >= 2:
                gaps = [addrs[k + 1] - addrs[k]
                        for k in range(len(addrs) - 1)]
                if all(g == gaps[0] for g in gaps):
                    stride_bytes = gaps[0]
        except Exception:
            stride_bytes = None
        collapsed: Dict[str, Any] = dict(row)
        collapsed["name"] = prefix
        # v1.6.450 — for #324 P2 ORGANIC. Ellipsis-row inference
        # promotes `array_size` to the high anchor's last index
        # plus 1; the concrete `elements[]` list still carries
        # only the actually-present rows (low side + high side)
        # so downstream consumers can still iterate, while the
        # `array_size` reflects the true range and gates that
        # depend on it (memory-map gap detection, register-bank
        # sizing, equivalence check coverage) get the right
        # number.
        if ellipsis_size_inferred is not None:
            collapsed["array_size"] = ellipsis_size_inferred
            collapsed["array_size_source"] = (
                "register_array_ellipsis_inferred_v1_6_450")
            if ellipsis_stride_inferred is not None:
                stride_bytes = ellipsis_stride_inferred
            elements_extended = list(elements) + list(
                ellipsis_high_anchor_rows)
            elements = elements_extended
        else:
            collapsed["array_size"] = len(elements)
        if base_addr is not None:
            collapsed["base_addr"] = base_addr
        if stride_bytes is not None:
            collapsed["stride_bytes"] = stride_bytes
        collapsed["elements"] = elements
        collapsed["extraction_strategy"] = (
            row.get("extraction_strategy")
            or "register_array_collapsed_v1_6_295"
        )
        # v1.6.497 — for #347 R6 Class B. Pre-collapse element rows may
        # carry per-instance reset_value; the previous logic kept only
        # element[0]'s value (or None when element[0] had none — e.g.
        # the SoC summary-table row had no reset column but downstream
        # CSR-doc per-element rows did). Union distinct non-empty values
        # across all elements: if exactly 1 unique value, assign as the
        # collapsed reset_value with provenance flag; if multiple
        # distinct values, emit them as a sorted list so downstream
        # consumers can present a per-instance breakdown. Only fires
        # when the collapsed entry's reset_value slot is currently
        # empty / placeholder (never overwrites a non-empty value).
        # Chip-AGNOSTIC: pure structural set-of-values reduction.
        _rv_seen_v1_6_497: set = set()
        for _el_v1_6_497 in elements:
            if not isinstance(_el_v1_6_497, dict):
                continue
            _rv_v1_6_497 = _el_v1_6_497.get("reset_value")
            if (isinstance(_rv_v1_6_497, str) and _rv_v1_6_497
                    and _rv_v1_6_497 not in (
                        "__TODO__", "TBD", "unspecified")):
                _rv_seen_v1_6_497.add(_rv_v1_6_497)
        _existing_rv_v1_6_497 = collapsed.get("reset_value")
        if _existing_rv_v1_6_497 in (
                None, "", "__TODO__", "TBD", "unspecified"):
            if len(_rv_seen_v1_6_497) == 1:
                collapsed["reset_value"] = next(iter(_rv_seen_v1_6_497))
                collapsed["reset_value_source"] = (
                    "register_array_collapse_union_v1_6_497"
                )
            elif len(_rv_seen_v1_6_497) > 1:
                collapsed["reset_value"] = sorted(_rv_seen_v1_6_497)
                collapsed["reset_value_source"] = (
                    "register_array_collapse_union_v1_6_497"
                )
        out.append(collapsed)
        i = j
    return out


# v1.6.295 — for #184 ORGANIC. Testbench / sim-only deny-list for
# the L9 submodule walker. Path + module-name patterns cover the
# conventional `tb/` / `testbench/` / `sim/` / `verif/` directories
# plus `tb_<name>` / `<name>_tb` / `sim_<name>` / `<name>_sim`
# module-name shapes.
# Chip-AGNOSTIC: open-standard verification naming convention.
_V1_6_295_RE_SIM_DENY_FILE = re.compile(
    r"(?:^|/)(tb_|_tb\.|testbench|sim_|_sim\.|verif|cocotb|svut)",
    re.IGNORECASE,
)
_V1_6_295_RE_SIM_DENY_NAME = re.compile(
    r"(?:_tb$|_testbench$|_sim$|^tb_|^sim_|^test_|_top_tb$)",
    re.IGNORECASE,
)


def _v1_6_295_is_sim_only(evidence_path: Optional[str],
                           module_name: Optional[str]) -> bool:
    """v1.6.295 — for #184 ORGANIC. Return True when the submodule
    candidate is a testbench / sim-only entity by either its
    evidence file path OR its module name. Caller routes hits to
    `L9.sim_only_modules` for provenance and skips `L9.submodules`.

    Chip-AGNOSTIC.
    """
    if isinstance(evidence_path, str) and evidence_path \
            and _V1_6_295_RE_SIM_DENY_FILE.search(evidence_path):
        return True
    if isinstance(module_name, str) and module_name \
            and _V1_6_295_RE_SIM_DENY_NAME.search(module_name):
        return True
    return False


def _v1_6_295_propagate_class_path_to_layer_docs(
        project: Path,
        target_layers: Optional[List[str]] = None) -> int:
    """v1.6.295 — for #181 ORGANIC. After every L emitter has run +
    `_post_emit_ic_class_into_L9_L1` has stamped L1.class_path, walk
    every L doc for N in 2..13 and stamp `class_path` from L1's
    resolved value. Returns the count of layers actually updated.

    `target_layers` lets callers restrict propagation to a subset;
    default is the full L2..L13 family.

    Chip-AGNOSTIC: pure filesystem read+write.
    """
    cp = _v1_6_295_resolve_class_path(project)
    if cp is None:
        return 0
    if target_layers is None:
        target_layers = [
            "L2_FRS",
            "L3_CMD_PROTOCOL",
            "L4_REGMAP",
            "L5_ADI_SPEC",
            "L6_CONTROL_LOGIC",
            "L7_TEST_DEBUG",
            "L8_RTL_CONSTANTS",
            "L8_TIMING_WAVEFORM",
            "L9_INTEGRATION_SPEC",
            "L10_TEST_CASES",
            "L11_OTP_CONTENT",
            "L12_BEHAVIORAL_SEQUENCES",
            "L13_LAB_CALIBRATION",
        ]
    gd = _pl.generated_docs_dir(project)
    if not gd.is_dir():
        return 0
    updated = 0
    for layer in target_layers:
        path = gd / f"{layer}.json"
        if not path.is_file():
            continue
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except Exception:
            continue
        if not isinstance(data, dict):
            continue
        existing = data.get("class_path")
        # Only stamp when missing / null / empty — never overwrite an
        # author-supplied value on a layer that has its own picker.
        if isinstance(existing, str) and existing.strip():
            continue
        data["class_path"] = cp
        try:
            _stamp.dump(path, data)
            updated += 1
        except Exception:
            continue
    return updated


# ORGANIC-20260803b — the run's PDK, set from `--pdk` in main(). None means
# "not stated"; every extraction then behaves exactly as it did before.
_CLI_PDK: Optional[str] = None

# A frequency or a period literal, with its unit, anywhere on a line.
_PDK_ROW_FREQ_RE = re.compile(
    r"(\d+(?:\.\d+)?)\s*(GHz|MHz|kHz|ns|ps|us)\b", re.IGNORECASE)
# The row must be ABOUT the clock. Without this, a row that merely names the
# process and happens to carry a time literal ("<pdk> setup time 3 ns") would
# be read as a clock-period declaration. Same vocabulary the prose-fmax
# walker's own `_RE_L2_CLOCK_VOCAB` gate uses, kept in step with it.
_PDK_ROW_CLOCK_VOCAB_RE = re.compile(
    r"(?i)\b(?:clock|clk|fmax|f_?max|frequency|period|"
    r"operating[\s\-]?freq(?:uency)?)\b")


def _rclk_pdk_scoped_clock_rows(project: Path):
    """Every clock-target row in the design docs that NAMES a process.

    Returns a list of ``(pdk_token, freq_mhz, source_rel, line_no, line_text)``
    in document order, one entry per (row, process-name) pair. A row that names
    two processes yields two entries; a row that names none yields nothing.

    This is the population `_v1_9_65_pdk_scoped_clock_mhz` picks THIS run's
    process out of. It is separated so the caller can tell the two silences
    apart: "this document does not speak in per-process clock rows at all"
    (nothing to arbitrate — prose stands) versus "this document DOES, and none
    of its rows is about the process being built" (the design has not stated a
    target for this process, and the other processes' targets are not
    substitutes for it).

    chip-AGNOSTIC: PDK-name namespace + time/frequency units only.
    """
    rows = []
    for base in (project / "input" / "docs", project / "phase1" / "input_doc"):
        if not base.is_dir():
            continue
        for f in sorted(base.rglob("*")):
            if not f.is_file() or f.suffix.lower() in (
                    ".png", ".jpg", ".pdf", ".gds", ".zip"):
                continue
            try:
                text = f.read_text(errors="replace")[:200_000]
            except OSError:
                continue
            try:
                rel = str(f.relative_to(project))
            except ValueError:
                rel = f.name
            for n, row in enumerate(text.split("\n"), start=1):
                if not _PDK_ROW_CLOCK_VOCAB_RE.search(row):
                    continue
                toks = []
                for m in _OPEN_PDK_TOKEN_RE.finditer(row):
                    if _match_is_inside_path_token(row, m.start(), m.end()):
                        continue
                    if _FOUNDRY_NEGATION_RE.search(
                            row[max(0, m.start() - 24):m.end()]):
                        continue
                    tok = re.sub(r"^ihp[- ]?", "",
                                 m.group(1).lower()).replace(" ", "")
                    if tok and tok not in toks:
                        toks.append(tok)
                if not toks:
                    continue
                mhz = None
                for fm in _PDK_ROW_FREQ_RE.finditer(row):
                    val, unit = float(fm.group(1)), fm.group(2).lower()
                    if val <= 0:
                        continue
                    if unit == "ghz":
                        mhz = val * 1000.0
                    elif unit == "mhz":
                        mhz = val
                    elif unit == "khz":
                        mhz = val / 1000.0
                    elif unit == "ns":
                        mhz = 1000.0 / val
                    elif unit == "us":
                        mhz = 1.0 / val
                    elif unit == "ps":
                        mhz = 1_000_000.0 / val
                    if mhz is not None:
                        break
                if mhz is None:
                    continue
                for tok in toks:
                    rows.append((tok, mhz, rel, n, row.strip()[:200]))
    return rows


def _rclk_pdk_row_names_run_pdk(want: str, tok: str) -> bool:
    """Does a row's process token name the process this run is building?

    Exact, or the FAMILY this revision belongs to (`<family>` covers
    `<family>D`). One-directional, the same rule the declared-vs-resolved
    guard uses: a row naming a DIFFERENT revision does not match.
    """
    return bool(want) and (
        want == tok or (
            len(want) == len(tok) + 1
            and want.startswith(tok)
            and want[len(tok):].isalpha()))


def _v1_9_65_pdk_scoped_clock_mhz(project: Path, pdk: Optional[str]):
    """The clock frequency a design document assigns TO THIS PDK, or None.

    WHY THIS EXISTS
    ---------------
    A design that targets more than one process states its timing target once
    per process, as a table keyed by the process name:

        | Target clock period — <PDK-A> | 10 ns (100 MHz) |
        | Target clock period — <PDK-B> | 20 ns  (50 MHz) |

    Phase 1's prose-fmax walker takes the FIRST such row it meets and demotes
    every other to `alternate_frequency_mentions[]`. That is a coin-flip the
    document already answered: which row applies is decided by which process
    the run is building.

    WHAT IS READ
    ------------
    Only a line that BOTH names this run's process AND carries a time or
    frequency literal. The process name must not sit inside a file path (a
    citation of a tool config file is not a timing statement) and must not be
    negated. When no line satisfies all of that, this returns None; the caller
    then decides between "no per-process rows at all" (leave the prose alone)
    and "per-process rows exist but none is ours" (NOT_DETERMINED).

    Returns (freq_mhz, source_rel, line_no, line_text) or None.

    chip-AGNOSTIC: a PDK-name namespace the file already owns, plus time /
    frequency units. No chip literal, no per-design rule.
    """
    if not pdk:
        return None
    want = pdk.strip().lower()
    if not want:
        return None
    for tok, mhz, rel, n, row in _rclk_pdk_scoped_clock_rows(project):
        if _rclk_pdk_row_names_run_pdk(want, tok):
            return (mhz, rel, n, row)
    return None


def _rclk_refuse_foreign_pdk_clock(project: Path) -> bool:
    """Refuse another process's clock target instead of adopting it.

    Precondition: this run named a process and no per-process clock row names
    it. When the document carries per-process clock rows for OTHER processes,
    the L8 primary clock currently holds one of them (the prose walker takes
    the first row it meets). That value is a foreign target. Replace it with
    an explicit NOT_DETERMINED carrying a named reason: which process was
    looked for, and which rows were found instead.

    NO-OP when the document declares no per-process clock rows at all — a
    single-process design that states its frequency in free prose is not
    ambiguous and this function has no opinion on it.

    Returns True when a file was rewritten.
    """
    if not _CLI_PDK:
        return False
    want = _CLI_PDK.strip().lower()
    rows = _rclk_pdk_scoped_clock_rows(project)
    if not rows:
        return False
    if any(_rclk_pdk_row_names_run_pdk(want, tok) for tok, *_ in rows):
        return False        # unreachable via the caller; kept honest anyway
    found = [f"{tok}={mhz:g} MHz at {rel}:{n}"
             for tok, mhz, rel, n, _ in rows]
    reason = (f"the design document declares a clock target per process, but "
              f"none of its rows names '{_CLI_PDK}'; it declares "
              + "; ".join(found) +
              f". A target declared for another process is not this "
              f"process's target.")
    gd = _pl.generated_docs_dir(project)
    if not gd.is_dir():
        return False
    any_updated = False
    for layer in ("L8_RTL_CONSTANTS", "L8_TIMING_WAVEFORM"):
        path = gd / f"{layer}.json"
        if not path.is_file():
            continue
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except Exception:
            continue
        if not isinstance(data, dict):
            continue
        changed = False
        cleared_names: Set[str] = set()
        domains = data.get("clock_domains")
        if isinstance(domains, list):
            for d in domains:
                if not isinstance(d, dict) or d.get("role") != "primary":
                    continue
                prev = d.get("freq_mhz")
                if prev is None and d.get("period_ns") is None:
                    continue
                if prev is not None:
                    _cc.record_alternate_mention(d, {
                        "freq_mhz": float(prev),
                        "freq_hz": int(float(prev) * 1e6),
                        "role": "withdrawn_not_declared_for_this_pdk",
                        "source": (d.get("evidence") or {}).get("file"),
                        "extraction_strategy": d.get("extraction_strategy"),
                    })
                d["freq_mhz"] = None
                d["freq_low_mhz"] = None
                d["freq_high_mhz"] = None
                d["freq_hz"] = None
                d["period_ns"] = None
                d["extraction_strategy"] = "clock_target_not_determined"
                d["pdk_scoped_target"] = _CLI_PDK
                d["clock_target_resolution"] = {
                    "status": "NOT_DETERMINED",
                    "pdk": _CLI_PDK,
                    "reason": reason,
                    "rows_found": found,
                }
                changed = True
                _nm = (d.get("name") or "").strip()
                if _nm:
                    cleared_names.add(_nm.lower())
        if not changed:
            continue
        clocks = data.get("clocks")
        if isinstance(clocks, list):
            for c in clocks:
                if not isinstance(c, dict):
                    continue
                _cn = (c.get("name") or "").strip().lower()
                if not _cn or _cn not in cleared_names:
                    continue
                _prev = c.get("freq_mhz")
                if _prev is not None:
                    _cc.record_alternate_mention(c, {
                        "freq_mhz": float(_prev),
                        "freq_hz": int(float(_prev) * 1e6),
                        "role": "withdrawn_not_declared_for_this_pdk",
                        "source": (c.get("evidence") or {}).get("file"),
                        "extraction_strategy": c.get("extraction_strategy"),
                    })
                c["freq_mhz"] = None
                c["freq_hz"] = None
                c["period_ns"] = None
                c["extraction_strategy"] = "clock_target_not_determined"
                c["pdk_scoped_target"] = _CLI_PDK
        if "clock_mhz" in data:
            data["clock_mhz"] = None
        data["clock_target_resolution"] = {
            "status": "NOT_DETERMINED",
            "pdk": _CLI_PDK,
            "reason": reason,
            "rows_found": found,
        }
        try:
            _stamp.dump(path, data)
            any_updated = True
        except Exception:
            continue
    if any_updated:
        print(f"[phase1] PDK-SCOPED CLOCK: NOT_DETERMINED for '{_CLI_PDK}' — "
              + reason)
    return any_updated


def _v1_9_65_post_emit_l8_pdk_scoped_clock(project: Path) -> bool:
    """Re-point L8's primary clock at the row this run's PDK owns.

    Runs AFTER the prose walker has emitted `clock_domains[]`, so the
    displaced frequency survives in `alternate_frequency_mentions[]` exactly
    as the walker's own losers do — nothing the design said is discarded, and
    the swap records its own evidence (`pdk_scoped_*` keys) so a reader can
    see which row was chosen and why.

    NO-OP unless the run named a PDK AND a document row assigns a frequency
    to it AND that frequency differs from the one already adopted. Returns
    True when a file was rewritten.
    """
    hit = _v1_9_65_pdk_scoped_clock_mhz(project, _CLI_PDK)
    if hit is None:
        # rclk — the row for THIS process is absent. Two silences, and only
        # one of them is harmless. If the document never speaks in per-process
        # clock rows, there is nothing to arbitrate and the prose target
        # stands. But if it DOES declare per-process targets and none of them
        # is this process's, then the design has not stated a target here —
        # and another process's target is not a substitute for it. Keeping it
        # is how a backend closes timing against a period this design never
        # asked for on this process. Refuse, by name.
        return _rclk_refuse_foreign_pdk_clock(project)
    mhz, rel, line_no, row_text = hit
    gd = _pl.generated_docs_dir(project)
    if not gd.is_dir():
        return False
    any_updated = False
    for layer in ("L8_RTL_CONSTANTS", "L8_TIMING_WAVEFORM"):
        path = gd / f"{layer}.json"
        if not path.is_file():
            continue
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except Exception:
            continue
        if not isinstance(data, dict):
            continue
        domains = data.get("clock_domains")
        if not isinstance(domains, list):
            continue
        changed = False
        repointed_names: Set[str] = set()
        for d in domains:
            if not isinstance(d, dict) or d.get("role") != "primary":
                continue
            prev = d.get("freq_mhz")
            if prev is not None and abs(float(prev) - mhz) < 1e-9:
                continue
            if prev is not None:
                _cc.record_alternate_mention(d, {
                    "freq_mhz": float(prev),
                    "freq_hz": int(float(prev) * 1e6),
                    "role": "displaced_by_pdk_scoped_row",
                    "source": (d.get("evidence") or {}).get("file"),
                    "extraction_strategy": "clock_domain_doc_prose_fmax",
                })
            d["freq_mhz"] = mhz
            d["freq_low_mhz"] = mhz
            d["freq_high_mhz"] = None
            d["freq_hz"] = int(mhz * 1e6)
            d["period_ns"] = 1000.0 / mhz
            d["extraction_strategy"] = "clock_domain_pdk_scoped_row"
            d["pdk_scoped_target"] = _CLI_PDK
            d["evidence"] = {"file": rel, "line": line_no,
                             "matched_substring": row_text[:120]}
            changed = True
            _nm = (d.get("name") or "").strip()
            if _nm:
                repointed_names.add(_nm.lower())
        if not changed:
            continue
        # ORGANIC-20260805 — mirror the re-point onto the `clocks[]` view of
        # the SAME physical clock. `_post_emit_seed_l8b_clocks_from_l1_v1_6_571`
        # already ran (call order: seeder line ~59512, this line ~59791) and
        # seeded `clocks[]` by INHERITING the period `clock_domains[]` held at
        # that moment — i.e. the PRE-re-point value. Re-pointing only
        # `clock_domains[]` therefore leaves the two containers owning the same
        # name with different periods, which is exactly what
        # `clock_contract_conflicts` refuses ("two clock records own the name
        # and pin different periods"). Re-point both, or neither. Chip-AGNOSTIC.
        clocks = data.get("clocks")
        if isinstance(clocks, list):
            for c in clocks:
                if not isinstance(c, dict):
                    continue
                _cn = (c.get("name") or "").strip().lower()
                if not _cn or _cn not in repointed_names:
                    continue
                _prev = c.get("freq_mhz")
                if _prev is not None and abs(float(_prev) - mhz) < 1e-9:
                    continue
                if _prev is not None:
                    _cc.record_alternate_mention(c, {
                        "freq_mhz": float(_prev),
                        "freq_hz": int(float(_prev) * 1e6),
                        "role": "displaced_by_pdk_scoped_row",
                        "source": (c.get("evidence") or {}).get("file"),
                        "extraction_strategy": c.get("extraction_strategy"),
                    })
                c["freq_mhz"] = mhz
                c["freq_hz"] = int(mhz * 1e6)
                c["period_ns"] = 1000.0 / mhz
                c["extraction_strategy"] = "clock_domain_pdk_scoped_row"
                c["pdk_scoped_target"] = _CLI_PDK
                c["evidence"] = {"file": rel, "line": line_no,
                                 "matched_substring": row_text[:120]}
        if data.get("clock_mhz") is not None:
            data["clock_mhz"] = mhz
        try:
            _stamp.dump(path, data)
            any_updated = True
        except Exception:
            continue
    if any_updated:
        print(f"[phase1] PDK-SCOPED CLOCK: the design document assigns "
              f"{mhz:g} MHz ({1000.0 / mhz:g} ns) to '{_CLI_PDK}' at "
              f"{rel}:{line_no} — L8 primary clock re-pointed at that row; "
              f"the displaced value is kept in "
              f"alternate_frequency_mentions[].")
    return any_updated


def _v1_6_295_post_emit_l8_clock_mhz_back_fill(project: Path) -> bool:
    """v1.6.295 — for #190 ORGANIC. Back-fill the L8 scalar
    `clock_mhz` slot from the first `clock_domains[]` entry whose
    `role` is `primary` and whose `freq_mhz` is non-null.

    Walks BOTH L8_RTL_CONSTANTS AND L8_TIMING_WAVEFORM so consumers
    on either file see a populated scalar when a primary domain
    exists. Returns True when at least one file was rewritten.

    Chip-AGNOSTIC.
    """
    gd = _pl.generated_docs_dir(project)
    if not gd.is_dir():
        return False
    any_updated = False
    for layer in ("L8_RTL_CONSTANTS", "L8_TIMING_WAVEFORM"):
        path = gd / f"{layer}.json"
        if not path.is_file():
            continue
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except Exception:
            continue
        if not isinstance(data, dict):
            continue
        if data.get("clock_mhz") is not None:
            continue
        domains = data.get("clock_domains") or []
        if not isinstance(domains, list):
            continue
        primary = None
        for d in domains:
            if not isinstance(d, dict):
                continue
            role = d.get("role")
            freq = d.get("freq_mhz")
            if role == "primary" and freq is not None:
                primary = d
                break
        if primary is None:
            continue
        data["clock_mhz"] = primary["freq_mhz"]
        # Flip the flag so the doc remains internally consistent —
        # we now have a populated scalar.
        if data.get("no_clock_mhz_in_input") is True:
            data["no_clock_mhz_in_input"] = False
        try:
            _stamp.dump(path, data)
            any_updated = True
        except Exception:
            continue
    return any_updated


# v1.6.575 — for #391 P3 ORGANIC. Handwritten Markdown spec stubs
# (`L*_handwritten.md`) use a universal author convention of fielded
# bullets `- **<snake_key>**: <value>` to encode design metadata.
# The canonical RST/MD grid-table and prose extractors do not walk
# this shape, so typed L1 fields (channel_count, converter_type,
# die_size_um, pdk, tapeout_date, affiliation, source_url) silently
# drop into an empty `extraction_evidence`. A key allow-list maps
# the bullet key to the canonical L1 section/field. Idempotent —
# only fills None/empty fields, so the explicit walker wins.
# Chip-AGNOSTIC: pure markdown bullet grammar + open-standard
# snake_case metadata keys.
_V1_6_575_HANDWRITTEN_BULLET_RE = re.compile(
    r"^\s*[-*+]\s+\*\*(?P<key>[a-z][a-z0-9_]+)\*\*\s*:\s*"
    r"(?P<value>.+?)\s*$",
    re.MULTILINE,
)

# Map snake-case key → (L1 section, field). The section name
# matches the canonical L1 content dict shape already used by
# `gen_l1_datasheet`. Open-standard metadata keys; no chip-class
# string literal participates.
_V1_6_575_HANDWRITTEN_KEY_MAP: Dict[str, Tuple[str, str]] = {
    # tapeout_metadata
    "tapeout_date":  ("tapeout_metadata", "tapeout_date"),
    "tapeout_month": ("tapeout_metadata", "tapeout_date"),
    "tapeout_year":  ("tapeout_metadata", "tapeout_year"),
    "shuttle":       ("tapeout_metadata", "shuttle"),
    "die_size_um":   ("tapeout_metadata", "die_size_um"),
    "die_size_mm":   ("tapeout_metadata", "die_size_mm"),
    # package_info
    "pdk":           ("package_info", "pdk"),
    "foundry":       ("package_info", "foundry"),
    "package_type":  ("package_info", "package_type"),
    "pin_count":     ("package_info", "pin_count"),
    # electrical_specs (typed scalar fields)
    "channel_count":   ("electrical_specs", "channel_count"),
    "resolution_bits": ("electrical_specs", "resolution_bits"),
    # functional_overview
    "converter_type":  ("functional_overview", "converter_type"),
    # provenance
    "affiliation":     ("provenance", "affiliation"),
    "author":          ("provenance", "author"),
    "source_url":      ("provenance", "source_url"),
}


def _v1_6_575_iter_handwritten_bullet_matches(text: str):
    """v1.6.575 — for #391 P3. Yield (key, value, match) tuples
    for every `- **<snake_key>**: <value>` bullet in `text`.
    Returns nothing if text is empty / non-string. Chip-AGNOSTIC."""
    if not isinstance(text, str) or not text:
        return
    for m in _V1_6_575_HANDWRITTEN_BULLET_RE.finditer(text):
        k = (m.group("key") or "").strip().lower()
        v = (m.group("value") or "").strip()
        if not k or not v:
            continue
        yield k, v, m


def _v1_6_575_iter_source_files_for_l1_bullets(
        extracted: Dict[str, str]):
    """v1.6.575 — for #391 P3. Iterate (filename, text) tuples
    that should be scanned for handwritten bullet fields. Strategy:
    prioritise files whose basename matches `*_handwritten.md`
    (the canonical spec-stub convention) but also fall through to
    any `.md` / `.txt` extracted-doc whose body contains the
    fielded-bullet shape. Chip-AGNOSTIC: pure filename pattern
    plus structural content shape."""
    if not extracted:
        return
    handwritten_keys = []
    md_keys = []
    other_keys = []
    for fname in extracted.keys():
        if not isinstance(fname, str):
            continue
        lower = fname.lower()
        if "_handwritten" in lower and lower.endswith(
                (".md", ".txt", ".markdown")):
            handwritten_keys.append(fname)
        elif lower.endswith((".md", ".markdown")):
            md_keys.append(fname)
        else:
            other_keys.append(fname)
    for fname in handwritten_keys + md_keys + other_keys:
        text = extracted.get(fname)
        if not isinstance(text, str) or not text:
            continue
        # Skip files that obviously won't contain bullet metadata.
        # Cheap content check: must contain `**` + `:` somewhere.
        if "**" not in text or ":" not in text:
            continue
        yield fname, text


def _v1_6_575_extract_handwritten_bullets_into_l1(
        l1: Dict[str, Any],
        extracted: Dict[str, str],
        evidence: Dict[str, List[Dict[str, str]]]) -> int:
    """v1.6.575 — for #391 P3 ORGANIC. Scan every extracted
    markdown / text file for `- **<snake_key>**: <value>` bullets;
    route each bullet through the key allow-list into the canonical
    L1 sections. Idempotent (only fills None/empty fields).
    Returns the number of bullets that landed in L1. Records
    provenance into `extraction_evidence[<file>]` with
    `extraction_strategy="handwritten_bullet_v1_6_575"`.

    Chip-AGNOSTIC: pure markdown bullet grammar + open-standard
    snake_case metadata keys."""
    if not isinstance(l1, dict) or not isinstance(extracted, dict):
        return 0
    landed = 0
    for fname, text in _v1_6_575_iter_source_files_for_l1_bullets(
            extracted):
        ev_key = f"input/docs/{fname}" if not str(
            fname).startswith("input/docs/") else str(fname)
        for key, value, _m in (
                _v1_6_575_iter_handwritten_bullet_matches(text)):
            mapping = _V1_6_575_HANDWRITTEN_KEY_MAP.get(key)
            if not mapping:
                continue
            section, field = mapping
            sec_dict = l1.get(section)
            if not isinstance(sec_dict, dict):
                # Create the section dict on the fly when the
                # canonical extractor left it None (the bullet is
                # the only signal). Mirrors the behaviour of
                # other v1.6.5XX post-passes.
                sec_dict = {}
                l1[section] = sec_dict
            existing = sec_dict.get(field)
            if existing not in (None, "", [], {}):
                # Idempotent: explicit walker output wins.
                continue
            sec_dict[field] = value
            landed += 1
            # Record evidence under the standard extraction_evidence
            # dict shape; downstream provenance gates walk this key.
            ev_list = evidence.setdefault(ev_key, [])
            ev_list.append({
                "literal": value[:120],
                "label": f"L1.{section}.{field}",
                "key": key,
                "extraction_strategy": (
                    "handwritten_bullet_v1_6_575"),
            })
    # Also flip the corresponding "no_<section>_in_input" sentinel
    # flag to False for any section we populated, so downstream
    # gates that read the sentinel see the truthful value. The
    # canonical sentinels emitted by gen_l1_datasheet use the
    # naming convention `no_tapeout_metadata_in_input`,
    # `no_package_in_input` (NOT `no_package_info_in_input`), etc.
    if landed > 0:
        _v1_6_575_section_to_flag = {
            "tapeout_metadata": "no_tapeout_metadata_in_input",
            "package_info": "no_package_in_input",
        }
        for section, flag in _v1_6_575_section_to_flag.items():
            if l1.get(flag) is True and l1.get(section):
                l1[flag] = False
    return landed


# v1.6.582 — for #398 P3 ORGANIC. Features bullet-list cleanup
# regexes + helpers. The pre-v1.6.582 feature harvester left raw
# bullet prefixes in `L1.features[]` (`- Extension`,
# `- C: Standard Extension for Compressed Instructions`), accepted
# one-token parent-category headers as standalone features, and
# leaked nested sub-bullet labels as if they were full features.
# Three coordinated fixes A+B+C applied as a single finalize-stage
# post-pass in `gen_l1_datasheet`. Chip-AGNOSTIC: bullet hygiene
# is universal across markdown / RST IC documentation; no
# chip-class string literal participates.

_V1_6_582_BULLET_PREFIX_RE = re.compile(r"^[-*+]\s+")

# Parent-category tokens that, when seen as standalone single-word
# "features", mark a categorisation header rather than a feature
# claim. Sub-bullets under these get the `[sub]` prefix instead of
# being dropped (so the nested content is still surfaced). Universal
# vocabulary across IC / RV / hardware documentation; no chip-class
# literal.
_V1_6_582_PARENT_CATEGORY_TOKENS = frozenset({
    "extension", "extensions",
    "implementation", "implementations",
    "feature", "features",
    "standard", "standards",
    "architecture", "architectures",
    "support", "supports", "supported",
    "configuration", "configurations",
    "capability", "capabilities",
    "option", "options",
    "interface", "interfaces",
    "instruction", "instructions",
    "mode", "modes",
})


def _v1_6_582_strip_bullet_prefix(s) -> str:
    """v1.6.582 — for #398 P3 ORGANIC. Strip the leading
    `- ` / `* ` / `+ ` markdown bullet token. Returns the bare
    text or empty string for non-string / empty input.
    Chip-AGNOSTIC."""
    if not isinstance(s, str):
        return ""
    return _V1_6_582_BULLET_PREFIX_RE.sub("", s.strip()).strip()


def _v1_6_582_is_short_or_parent_header(s) -> bool:
    """v1.6.582 — for #398 P3 ORGANIC. Return True iff `s` is a
    one-token (or one-word-with-colon) parent-category header
    that should NOT be emitted as a standalone feature.

    Rules:
      - Empty / non-string → True (drop).
      - 1 token that is a known PARENT-CATEGORY token → True (drop)
        — bare word like "Extension" / "Features" / "Modes".
      - 1 token ending in `:` whose base is a parent-category token
        → True (drop) — `Extension:`.

    Two-token names (e.g. `Compressed Instructions`) are kept as
    real features.

    v1.6.281/458 contract restore: a single-token bullet that is
    NOT a parent-category token (e.g. `alpha`, `beta`) is a
    legitimate short feature and MUST be kept. The earlier blanket
    `len(tokens) == 1 → drop` wrongly nuked every one-word feature.

    Chip-AGNOSTIC: pure structural shape check + the published
    parent-category vocabulary."""
    if not isinstance(s, str):
        return True
    s = s.strip()
    if not s:
        return True
    tokens = s.split()
    if not tokens:
        return True
    if len(tokens) == 1:
        # Drop ONLY when the lone token is a recognised parent-
        # category header (`Extension` / `Features` / `Modes` /
        # ...); keep genuine one-word features otherwise.
        base = tokens[0].lower().rstrip(":")
        return base in _V1_6_582_PARENT_CATEGORY_TOKENS
    # Two tokens where the first ends with colon is a sub-bullet
    # label like `C: Compressed`. Those are routed through the
    # sub-bullet path (kept with [sub] prefix), not dropped here.
    return False


def _v1_6_582_clean_feature_list(features) -> List[str]:
    """v1.6.582 — for #398 P3 ORGANIC. Apply the three coordinated
    cleanup passes A+B+C to `L1.features[]`:

      A — strip leading `- ` / `* ` / `+ ` bullet prefix.
      B — reject one-token parent-category headers (dropped).
          Record the parent category so sub-bullets under it get
          the `[sub]` prefix instead of being lost.
      C — when a sub-bullet shape `<short>: <body>` (one-letter
          / two-letter prefix + colon + body) is seen AFTER a
          recorded parent category, prefix the bullet with
          `[sub] ` so downstream consumers can distinguish.

    Returns a new list; original is not mutated. Chip-AGNOSTIC."""
    if not isinstance(features, list):
        return []
    cleaned: List[str] = []
    seen_parent_categories: Set[str] = set()
    for raw in features:
        stripped = _v1_6_582_strip_bullet_prefix(raw)
        if not stripped:
            continue
        # Idempotency: `[sub]` markers already present pass through.
        if stripped.startswith("[sub] "):
            # Already-cleaned sub-bullet from a prior cleanup pass.
            cleaned.append(stripped)
            continue
        if _v1_6_582_is_short_or_parent_header(stripped):
            # Drop the header but record it for child sub-bullet
            # detection.
            first_word = (
                stripped.split()[0].lower().rstrip(":"))
            if first_word in _V1_6_582_PARENT_CATEGORY_TOKENS:
                seen_parent_categories.add(first_word)
            continue
        # Detect sub-bullet shape `<short>: <body>` — short prefix
        # (≤ 2 chars) + colon + body.
        first_seg = stripped.split(":", 1)[0].strip()
        if (len(first_seg) <= 2
                and ":" in stripped
                and seen_parent_categories):
            stripped = (
                f"[sub] {stripped}"
                if "[sub] " not in stripped else stripped)
        cleaned.append(stripped)
    return cleaned


def gen_l1_datasheet(project: Path,
                     extracted: Dict[str, str]) -> LDocResult:
    """L1: pin table + electrical specs + package."""
    ic_name = _ic_name_from_docs(extracted, project)
    pins: List[Dict[str, Any]] = []
    e_specs: List[Dict[str, Any]] = []
    evidence: Dict[str, List[Dict[str, str]]] = {}

    # v1.6.337 — for #235 P3 ORGANIC. Precompute whether ANY of the
    # extracted docs contains an electrical-spec token (LVTTL /
    # LVCMOS / SSTL / HSTL / LVDS / CMOS / TTL). When false, the
    # `io_standard` emit must return None for non-power-non-ground
    # pins instead of fabricating a `3.3-V LVTTL*` default. Used by
    # `_add_pin` and the legacy line-scan emit below.
    # Chip-AGNOSTIC: open-standard JEDEC / IEEE I/O standard set.
    #
    # v1.6.339 — for #235 Round-2 ORGANIC. The has-token check now
    # requires a voltage prefix (e.g. `3.3-V CMOS`) rather than a
    # bare token. Closes the `CMOs` (Cache Management Operations
    # plural) false-positive that opened the gate on RISC-V
    # Privileged Spec ingest. See `_V1_6_339_RE_IO_STANDARD_PHRASE`.
    _v1_6_337_concat = "\n".join(extracted.values()) if extracted else ""
    _v1_6_337_has_io_token = _v1_6_337_doc_has_io_standard_token(
        _v1_6_337_concat)

    # #638 — collect the backticked module-name token(s) from any
    # Comportable intro sentence ("the module `<name>` has the following
    # hardware interface..."). The narrative line-scan must NOT promote
    # this token as a phantom port. Lower-cased for case-insensitive deny.
    # Chip-AGNOSTIC: the token is whatever the doc's convention sentence
    # names — no chip-class literal is hard-coded.
    _v638_module_name_deny: Set[str] = set()
    for _v638_text in extracted.values():
        _v638_mn = _v638_comportable_module_name(_v638_text)
        if _v638_mn:
            _v638_module_name_deny.add(_v638_mn.lower())

    # Look for pin table — any doc with input/output/inout/bidir keywords.
    # v1.6.266 — for #125 ORGANIC. `pin_index` maps name → index in
    # `pins` so a second emit can score against the first instead of
    # silently dropping. `pin_seen` retained as a compatibility view
    # over `pin_index.keys()` for the legacy line-scan path.
    pin_index: Dict[str, int] = {}

    class _PinSeenView(set):
        def __contains__(self, x):  # type: ignore[override]
            return x in pin_index
        def add(self, x):  # type: ignore[override]
            pin_index.setdefault(x, -1)
    pin_seen = _PinSeenView()

    def _add_pin(name: str, mode: str, fname: str,
                 width: Optional[str] = None,
                 description: Optional[str] = None,
                 extraction_strategy: str = "pin_table_keyword_scan",
                 source_row: str = "",
                 optional: Optional[bool] = None,
                 ) -> None:
        """v1.6.248 — shared pin-emit helper. Used by the legacy
        `input|output|inout` keyword scan AND the new RST grid /
        Verilog port-decl extractors so all sources reach
        L1.pin_table via the same canonical record shape.

        v1.6.265 — for #123 ORGANIC. Every emitter routes width
        through this helper. Two universal augmentations:
        (a) if the signal `name` carries a bracket suffix (Shape C
            `irq_fast_i[14:0]`), strip and treat it as the width;
        (b) parse the resulting width string via
            `_parse_port_width` so downstream gets typed `width`
            (int) + `msb` / `lsb` + optional `width_symbolic`.

        v1.6.266 — for #125 ORGANIC. Width-aware dedup. On name
        collision, score the new candidate against the existing
        entry and keep whichever is richer (more typed fields,
        structured extractor over bind). The loser's typed fields
        that the winner lacks are inherited so neither extractor's
        evidence is dropped.

        v1.6.363 — for #258 P3 ORGANIC. `aliases` is now emitted
        only from doc-declared sources via
        `_v1_6_363_extract_doc_declared_aliases`. The legacy
        ``[name.lower(), name.replace("_", "")]`` auto-synth is
        dropped — it manufactured aliases that carry no doc
        evidence and inflated downstream alias-coverage gates.
        `source_row` carries the doc row context if the caller has
        it; pipe-delim aliases in `name` are recovered even when
        `source_row` is empty.
        """
        # Shape C: recover the bracket from the name if present.
        bare_name, name_bracket = _strip_name_bracket(name) if name else (name, None)
        if name_bracket and not width:
            width = name_bracket
        name = bare_name
        if not name:
            return
        # v1.6.363 — for #258 P3 ORGANIC. Compute aliases BEFORE
        # stripping the pipe so the pipe-alias suffix on `name`
        # contributes to the alias list, then strip pipe so the
        # emitted base name (regex group 1) is clean.
        _v1_6_363_aliases = _v1_6_363_extract_doc_declared_aliases(
            name, source_row=source_row)
        name = _v1_6_363_strip_pipe_from_name(name)
        # v1.0.44 — for #664 ORGANIC. Pass this emit's PROVENANCE
        # (extraction_strategy + mode) to `_is_real_port_token` so its
        # structured-port-table exemption fires: a 1-char datapath port
        # (x / y / p / q) deliberately enumerated from a port TABLE
        # (strategy ∈ `_PORT_TABLE_STRATEGIES`) is a real port and must
        # not be dropped by the 1-char-floor / version-code SHAPE
        # rejectors. The v455 walker (#627) already supplied this
        # provenance via its own emit dict; the structured 4COL / DIR2 /
        # NCOL walkers route through `_add_pin`, which previously called
        # the rejector with `pin=None`, so the same legitimate short bus
        # ports were dropped on THIS path. Chip-AGNOSTIC: provenance
        # flag + mode, no chip/vendor literal.
        if not _is_real_port_token(
                name, ic_name,
                pin={"extraction_strategy": extraction_strategy,
                     "mode": mode}):
            return
        # v1.6.337 — for #235 P3 ORGANIC. Use the gated helper so
        # io_standard is None (and `no_io_standard_in_input=true`)
        # when no electrical-spec token (LVTTL / LVCMOS / …) is
        # present in any extracted doc. Power / ground rails still
        # carry the canonical POWER / GROUND label.
        _v1_6_337_iostd = _v1_6_337_infer_io_standard_gated(
            name, _v1_6_337_concat)
        entry: Dict[str, Any] = {
            "name": name,
            "mode": mode,
            "aliases": _v1_6_363_aliases,
            "rtl_name": name.lower(),
            "board_name": name,
            "io_standard": _v1_6_337_iostd,
            "no_io_standard_in_input": (
                _v1_6_337_iostd is None and not _v1_6_337_has_io_token
            ),
            # v1.6.273 — for #136 ORGANIC. Pass `mode` so the inference
            # helper resolves mode/function contradictions (e.g. an
            # `*_INSTR` pin whose mode is `output` no longer emits
            # `function=input` via incidental "IN" substring match).
            "function": (description if description
                         else _infer_pin_function(name, mode=mode)),
            "evidence": f"input/docs/{fname}",
            "extraction_strategy": extraction_strategy,
        }
        if width:
            entry["width"] = width
            # v1.6.265 — for #123 ORGANIC. Stamp typed width / msb /
            # lsb / width_symbolic on every emitter via the shared
            # parser. `width` field above keeps the original textual
            # form for backward compatibility; the parsed integer is
            # only stamped when resolvable.
            w_int, msb, lsb, w_sym = _parse_port_width(width)
            if w_int is not None:
                entry["width"] = w_int
                if msb is not None:
                    entry["msb"] = msb
                if lsb is not None:
                    entry["lsb"] = lsb
            elif w_sym is not None:
                entry["width_symbolic"] = w_sym
        if description:
            entry["description"] = description
        # v0.3.4 — ORGANIC #491 R4. Doc-declared optionality survives
        # to L1.pin_table (and from there to L9.top_ports) so the
        # L9↔RTL consistency gate can treat a doc-optional pin absent
        # from the RTL top as advisory, not FAIL.
        if optional:
            entry["optional"] = True
        existing_idx = pin_index.get(name)
        if existing_idx is None or existing_idx < 0:
            pins.append(entry)
            pin_index[name] = len(pins) - 1
            return
        # v1.6.266 — name collision. Score and pick the winner;
        # then forward-inherit fields the winner lacks from the
        # loser.
        prev = pins[existing_idx]
        new_score = _port_entry_score(entry)
        prev_score = _port_entry_score(prev)
        winner, loser = (entry, prev) if new_score > prev_score else (prev, entry)
        for k in ("width", "msb", "lsb", "width_symbolic",
                  "description", "io_standard"):
            if winner.get(k) in (None, "", "see datasheet") \
                    and loser.get(k) not in (None, "", "see datasheet"):
                winner[k] = loser[k]
        # v0.3.4 — #491 R4: optionality is sticky across extractor
        # merges — if EITHER extractor saw the doc-optional marker the
        # merged entry keeps it.
        if loser.get("optional") and not winner.get("optional"):
            winner["optional"] = True
        if winner is entry:
            pins[existing_idx] = entry

    for fname, text in extracted.items():
        # v1.6.248 — for #110. Filename / suffix deny-list:
        # Doxyfile / Makefile / conf.py / *.yml etc. never
        # contribute to L1.pin_table.
        if not _is_port_source_allowed(fname):
            continue
        # v1.6.248 — for #108. RST grid Signal|Width|Dir|Description
        # Interface table → L1.pin_table. The same parser feeds L7
        # debug_observability via the v1.6.241 path; this is the
        # second sink (L9 inherits from L1.pin_table).
        ev = evidence.setdefault(f"input/docs/{fname}", [])
        # ORGANIC #553 — pre-compute ID-column-2 zones once per file so
        # the 4COL / NCOL_SUFFIX loops can suppress width extraction from
        # tables whose second column is a position/ID field.
        _id_col2_zones = _rst_col2_id_char_ranges(text or "")
        for m in _RE_L1_L9_RST_IFACE_4COL.finditer(text or ""):
            signal = m.group("signal").strip()
            # Reject column-header rows.
            if signal.lower() in {"signal", "name", "port",
                                  "direction", "type", "dir",
                                  "description", "width"}:
                continue
            # v1.6.249 — for #108 field-agent round-2 feedback.
            # Normalise abbreviated direction cells (`in`/`out`/
            # `io`) back to full canonical form (`input`/`output`/
            # `inout`) so downstream consumers see one shape.
            raw_dir = m.group("dir").lower()
            mode_full = _DIR_ABBR_TO_FULL.get(raw_dir, raw_dir)
            # v1.6.423 — for #302 R2. Route the captured width
            # through `_v1_6_420_parse_width_cell` so parametric /
            # placeholder cells (`*`, `N`, `DATA_WIDTH-1`,
            # `(variable)`, `-`) preserve the row instead of being
            # dropped. Numeric → str(int); parametric → None with
            # strategy suffix `+width_parametric_v1_6_423`.
            # ORGANIC #553 — suppress width if this row is inside a table
            # whose second column is an ID/position column, not a width.
            if _in_id_col2_zone(m.start(), _id_col2_zones):
                width_raw_str = ""
            else:
                width_raw_str = (m.group("width") or "").strip()
            try:
                _w_int, _w_sym = _v1_6_420_parse_width_cell(width_raw_str)
            except NameError:
                _w_int = int(width_raw_str) if width_raw_str.isdigit() else None
                _w_sym = width_raw_str
            if _w_int is not None:
                _width_arg = str(_w_int)
                _strategy_v1_6_423 = "rst_grid_interface_table"
            elif _w_sym:
                # v1.0.44 — for #664 ORGANIC. `_v1_6_420_parse_width_cell`
                # only resolves a BARE integer; the `<N>-bit` / `N-bit`
                # idiom and a bracketed `[M:L]` / `[WIDTH-1:0]` cell now
                # match the permissive row regex but were arriving here as
                # an unresolved parametric string and emitting NO typed
                # width. Hand the RAW cell to `_add_pin`, whose
                # `_parse_port_width` resolves `8-bit`→8 / `[31:0]`→32 /
                # `[WIDTH-1:0]`→width_symbolic, so the multi-bit bus no
                # longer lands null in L1.pin_table → L9.top_ports.
                # Chip-AGNOSTIC: pure idiom; no chip literal.
                _width_arg = width_raw_str
                _strategy_v1_6_423 = (
                    "rst_grid_interface_table+width_parametric_v1_6_423"
                )
            else:
                _width_arg = None
                _strategy_v1_6_423 = "rst_grid_interface_table"
            _add_pin(
                name=signal,
                mode=mode_full,
                fname=fname,
                width=_width_arg,
                description=(m.group("desc") or "").strip() or None,
                extraction_strategy=_strategy_v1_6_423,
            )
            if len(ev) < 24:
                ev.append({"literal": m.group(0).strip()[:120],
                           "label": "pin (RST grid Interface table)"})
        # v0.2.62 (#431) — the `signal | DIR | WIDTH | desc` column-order
        # sibling of the 4COL parser above (see _RE_L1_L9_RST_IFACE_4COL_DIR2
        # rationale). Same header-reject + dir normalisation + permissive
        # width routing; `_add_pin` score-merge dedups across both orders.
        for m in _RE_L1_L9_RST_IFACE_4COL_DIR2.finditer(text or ""):
            signal = m.group("signal").strip()
            if signal.lower() in {"signal", "name", "port",
                                  "direction", "type", "dir",
                                  "description", "width"}:
                continue
            raw_dir = m.group("dir").lower()
            mode_full = _DIR_ABBR_TO_FULL.get(raw_dir, raw_dir)
            width_raw_str = (m.group("width") or "").strip()
            try:
                _w_int, _w_sym = _v1_6_420_parse_width_cell(width_raw_str)
            except NameError:
                _w_int = int(width_raw_str) if width_raw_str.isdigit() else None
                _w_sym = width_raw_str
            _add_pin(
                name=signal,
                mode=mode_full,
                fname=fname,
                width=str(_w_int) if _w_int is not None else None,
                description=(m.group("desc") or "").strip() or None,
                extraction_strategy="rst_grid_interface_table_dir2col_v0262",
            )
            if len(ev) < 24:
                ev.append({"literal": m.group(0).strip()[:120],
                           "label": "pin (RST grid Interface table)"})
        # v1.6.250 — for #108 field-agent round-3 feedback. 2-column
        # RST grid rows (signal | description only, no width / dir
        # cells) are common in real RV `integration.rst`. Direction
        # inferred from canonical RTL suffix convention. Dedup by
        # `pin_seen` inside `_add_pin`; 4-col parser above runs first.
        for m in _RE_L1_L9_RST_IFACE_2COL.finditer(text or ""):
            signal = m.group("signal").strip()
            desc = (m.group("desc") or "").strip()
            # v1.6.265 — for #123 Shape C. Split bracket suffix
            # BEFORE the anti-prose suffix check so the suffix
            # check sees the bare name.
            bare_sig, _bracket = _strip_name_bracket(signal)
            sig_low = bare_sig.lower()
            if sig_low in {"signal", "name", "port", "direction",
                           "type", "dir", "description", "width"}:
                continue
            # v1.6.272 — for #123 round-3 NOT VERIFIED feedback.
            # Removed `if bare_sig in pin_seen: continue` gate.
            # Field-agent traced the Shape-C residual gap: an
            # earlier `verilog_port_bind` extractor populates
            # `pin_seen[<name>]` from a bare `.<name> ()` line in
            # an instantiation block; the 2-col / N-col path then
            # short-circuited before reaching `_add_pin`, so the
            # v1.6.266 score-based merge never had the chance to
            # let the richer (bracket → width) entry win.
            # `_add_pin` itself already dedupes by `pin_index` +
            # score-merges on name collision, so the outer guard
            # was both redundant and harmful for cross-extractor
            # enrichment.
            # Anti-prose guard: real port signals carry a canonical
