        for caption, header, body_rows in _rst_list_table_iter_blocks(text or ""):
            col_idx = _rst_list_table_port_columns(header)
            if not col_idx:
                continue
            name_col = col_idx["name"]
            dir_col = col_idx["direction"]
            width_col = col_idx.get("width")
            desc_col = col_idx.get("description")
            for row in body_rows:
                if name_col >= len(row) or dir_col >= len(row):
                    continue
