                raw_dir = (row[dir_col] or "").strip("` ").strip().lower()
                if not sig or not raw_dir:
                    continue
                mode_full = _DIR_ABBR_TO_FULL.get(raw_dir)
                if mode_full is None:
                    continue
                # Reject any leaked column-header row.
                if sig.lower() in {"signal", "name", "port", "pin",
                                   "direction", "type", "dir",
                                   "description", "width", "i/o"}:
                    continue
                # v1.6.420 — for #302 P3. Parametric / placeholder
                # width cells (`*`, `N`, `WIDTH`, `DATA_WIDTH-1`,
