                width_raw = None
                width_raw_symbolic = None
                if width_col is not None and width_col < len(row):
                    wraw = (row[width_col] or "").strip("` ").strip()
                    w_int, w_sym = _v1_6_420_parse_width_cell(wraw)
                    if w_int is not None:
                        width_raw = str(w_int)
                    elif w_sym:
                        width_raw_symbolic = w_sym
