def _v1_6_435_post_emit_lift_unknown_strategy_lc(
        project: Path) -> None:
    """v1.6.435 — for #305 R2 ORGANIC. Best-effort second pass:
    scan L9.submodules for already-emitted entries whose strategy
    tag is missing / `unknown` / `auto` / `none` / `""`, and lift
    their `low_confidence` flag when the other three structural
    gates (snake_case shape, source path with section hint,
    no DSL-suffix) all pass.

    Legacy walkers (pre-v1.6.428) sometimes stamped no strategy at
    all, so v1.6.428 / v1.6.435's whitelist gate alone never
    promoted them. This post-pass is gated identically — same
    4-of-4 structural contract — just routes through the unknown-
    strategy fallback helper instead of the whitelist.

    Chip-AGNOSTIC: no chip-class string literal participates.
    """
    try:
        gd = _pl.generated_docs_dir(project)
    except Exception:
        return
    l9_path = gd / "L9_INTEGRATION_SPEC.json"
    if not l9_path.is_file():
        return
    try:
        l9 = json.loads(l9_path.read_text(encoding="utf-8"))
    except Exception:
        return
    if not isinstance(l9, dict):
        return
    subs = l9.get("submodules")
    if not isinstance(subs, list) or not subs:
        return
    changed = False
    for entry in subs:
        if not isinstance(entry, dict):
            continue
        # Only consider entries currently flagged low_confidence.
        if entry.get("low_confidence") is not True:
            continue
        name = entry.get("name")
        strategy = entry.get("extraction_strategy")
        ev = entry.get("evidence")
        src = None
        if isinstance(ev, dict):
            src = ev.get("file") or ev.get("source") or ev.get("path")
        if not src:
            src = entry.get("source_file")
        if _v1_6_435_fallback_unknown_strategy_promote(
                name, strategy, src, project):
            entry["low_confidence"] = False
            changed = True
    if not changed:
        return
    try:
        _stamp.dump(l9_path, l9)
    except Exception:
        pass


# v1.6.524 — for #360 P3 ORGANIC. L9.chip_top_interfaces grouped-
# signal walker. Pre-v1.6.524 the only chip_top_interfaces emitter
# was the v1.6.294 mirror from `interface_types`, which emits one
# `{name, matched_token}` entry per bus-keyword hit (`OBI` /
# `TileLink` / `AHB` / `AXI`). Field-agent benchmark showed real
# RST/AsciiDoc Interfaces tables ship 4-11 named groups (Clock and
# Reset / Special control / Configuration / Instruction memory /
# Data memory / Interrupt / Debug …) with explicit signal lists per
# group; the keyword walker collapses this to a single entry and
# the per-group signal list is lost at the Phase 1 (doc-extraction) → Phase 2
# handoff boundary.
#
# Fix is a post-emit walker that scans extracted_docs for an
# `Interfaces` / `Interface` heading immediately followed by a
# table block (RST grid table / AsciiDoc table / Markdown pipe
# table), partitions rows by group-divider rows (AsciiDoc
# `4+^| **Group Name**` colspan rows OR RST bold-only `**Group
# Name**` rows), and emits one chip_top_interfaces entry per
# group with `signals: [...]` rolled up from rows under that
# divider.
#
# Coexistence: the v1.6.294 keyword-match emit is preserved as
# fallback when no Interfaces table is found in any doc. When a
# table IS found, the new grouped entries are APPENDED to the
# existing list (de-duped on group-name slug); both shapes ship
# in the same list so consumers that read either field see the
# data they need.
#
# Idempotent: re-run skips when entries with
# `extraction_strategy='interfaces_section_v1_6_524'` are already
# present.
#
# Chip-AGNOSTIC: pure RST / AsciiDoc / Markdown table grammar +
# bold-text divider convention; no chip-class string literal
# participates.
_V1_6_524_INTERFACE_HEADING_RE = re.compile(
    r"^[ \t]*(?:[#=*]+\s*)?"
    r"(?P<name>Interface[s]?)\s*$",
    re.IGNORECASE | re.MULTILINE,
)

_V1_6_524_GROUP_DIVIDER_RE = re.compile(
    # AsciiDoc colspan section: `4+^| **Clock and Reset**`
    # (also accepts `2+^|`, `3+^|`, etc., with optional alignment
    # spec `<` / `>` / `^` after digits).
    r"^[ \t]*\d+\+[\^<>]?\|\s*\*\*"
    r"(?P<group_a>[A-Za-z][\w \-/]+?)\*\*"
    r"|"
    # RST/Markdown bold-only standalone line:
    # `**Clock and Reset**` (no surrounding non-bold text).
    r"^[ \t]*\*\*(?P<group_b>[A-Za-z][\w \-/]+?)\*\*[ \t]*$",
    re.MULTILINE,
)

# Recogniser for what looks like a signal name (snake_case token
# of length 2-40, possibly with `_i` / `_o` / `_n` suffix). Used
# to extract signals from raw table-row text. Chip-AGNOSTIC.
_V1_6_524_SIGNAL_TOKEN_RE = re.compile(
    r"\b(?P<sig>[a-z][a-z0-9_]{1,39})\b",
)


def _v1_6_524_group_slug(group_name: str) -> str:
    """v1.6.524 — slugify a group name (`Clock and Reset` →
    `clock_and_reset`). Pure structural transform — no chip-class
    literal participates. Idempotent on already-slugified input.
    """
    if not isinstance(group_name, str):
        return ""
    s = group_name.strip().lower()
    # Collapse whitespace and dashes / slashes to `_`.
    s = re.sub(r"[\s\-/]+", "_", s)
    s = re.sub(r"[^a-z0-9_]", "", s)
    s = re.sub(r"_+", "_", s).strip("_")
    return s


def _v1_6_524_find_table_block_end(text: str, start: int) -> int:
    """v1.6.524 — find where the Interfaces table block ends.
    The block runs from ``start`` until the first non-table line
    (a non-blank line that does not contain `|`, does not start
    with `+-`, `=`, or whitespace + `*`). Returns the offset
    within ``text`` (or ``len(text)`` if the block extends to
    end-of-doc).

    Heuristic: tolerate a single blank-line gap inside the table
    (RST grid tables embed blank lines between sub-rows). Two
    consecutive blank lines or a non-table prose line ends the
    block.

    v1.6.531 — for #360 R3. Two fixes:
    1. RST heading-underline (`---` or `===` lines after a text
       heading) is NOT a table row by itself. Don't set
       ``in_table=True`` solely from ``^[=\\-]{3,}$`` — require a
       true table marker (``|``-containing line, or ``+-`` /
       ``+=`` grid-border) to enter table state.
    2. RST directive lines ``.. <name>::`` (e.g. ``.. table::``,
       ``.. list-table::``, ``.. csv-table::``) AND their
       indented option lines (``:name:``, ``:widths:``,
       ``:header-rows:`` …) are part of the PRELUDE to the table
       when ``in_table=False``. They don't end the search; the
       walker continues past them looking for the real table.
       Prelude budget raised from 256 chars to 1024 chars to
       accommodate directive + 5-6 option lines + blank line
       before the actual grid table.
    Chip-AGNOSTIC.
    """
    if not isinstance(text, str) or start >= len(text):
        return len(text)
    lines = text[start:].splitlines(keepends=True)
    consec_blank = 0
    consumed = 0
    in_table = False
    for ln in lines:
        consumed += len(ln)
        stripped = ln.strip()
        if not stripped:
            consec_blank += 1
            if consec_blank >= 2 and in_table:
                # Two blank lines in a row — end the table block.
                return start + consumed - len(ln)
            continue
        consec_blank = 0
        # v1.6.531 — for #360 R3. Strict table-row detection:
        # require ``|``-containing line OR ``+-`` / ``+=`` grid
        # border. Heading-underline ``^[=\-]{3,}$`` alone is NOT
        # a table row (it's preceded by a heading title in RST
        # and must not promote ``in_table``).
        is_strict_table_row = (
            "|" in stripped
            or stripped.startswith("+-")
            or stripped.startswith("+=")
        )
        # Bold-only divider rows are kept inside an already-open
        # table (preserves v1.6.524's divider grammar).
        is_bold_divider = bool(re.match(r"^\*\*[A-Za-z]", stripped))
        if is_strict_table_row:
            in_table = True
            continue
        if in_table and is_bold_divider:
            continue
        if in_table:
            # Already inside table; non-table line ends it.
            return start + consumed - len(ln)
        # v1.6.531 — for #360 R3. Prelude tolerance. Before
        # ``in_table`` flips, treat three line shapes as prelude
        # (don't return — keep walking forward looking for the
        # real table):
        #   (a) heading-underline (``---`` / ``===`` / etc.)
        #       following the section heading;
        #   (b) RST directive line (``.. <name>::``);
        #   (c) directive option line (``:option: value``).
        is_heading_underline = bool(
            re.match(r"^[=\-+~^'`]{3,}$", stripped))
        is_rst_directive = bool(
            re.match(r"^\.\.\s+[a-z][\w\-]*::", stripped))
        is_directive_option = bool(
            re.match(r"^:[a-z][\w\-]*:", stripped))
        if (is_heading_underline
                or is_rst_directive
                or is_directive_option):
            # Prelude — keep walking, don't enter table.
            if consumed > 1024:
                # If we walked too far in prelude with no table,
                # give up.
                return start
            continue
        # Non-table, non-prelude line BEFORE table entered.
        # Same give-up logic as before but with a wider budget
        # (1024 chars) so RST directives + option blocks fit.
        if consumed > 1024:
            return start
    return start + consumed


def _v1_6_524_extract_signals_from_row(row_text: str) -> List[str]:
    """v1.6.524 — pull signal-name-shaped tokens from a single
    table-row text. Filters out RST/AsciiDoc table-structure noise
    (`px`, `nx`, single-letter cells, common English words).

    Chip-AGNOSTIC: pure shape filter on identifier text.
    """
    if not isinstance(row_text, str) or not row_text:
        return []
    # Common English / table-structure words to deny — these
    # often show up as cell content but are not RTL signals.
    # Pure English stop-words + table glue; no chip-class
    # literal.
    deny = {
        "input", "output", "inout", "in", "out", "io",
        "the", "and", "or", "of", "to", "for", "from", "with",
        "type", "name", "description", "width", "direction",
        "clock", "reset",  # group-level keywords, not signals
        "yes", "no", "true", "false", "n", "a", "an",
        "bit", "bits", "byte", "bytes", "signal", "signals",
        "wire", "logic", "reg", "see", "note", "if",
        "default", "active", "high", "low", "edge", "level",
    }
    out: List[str] = []
    seen: Set[str] = set()
    for m in _V1_6_524_SIGNAL_TOKEN_RE.finditer(row_text):
        sig = m.group("sig")
        if len(sig) < 2:
            continue
        if sig in deny:
            continue
        # Signals usually have an underscore OR end in _i/_o/_n
        # to be distinguishable from English words. Be strict
        # to keep false-positive surface low.
        looks_like_signal = (
            "_" in sig
            or sig.endswith(("_i", "_o", "_n"))
        )
        if not looks_like_signal:
            continue
        if sig in seen:
            continue
        seen.add(sig)
        out.append(sig)
    return out


# v1.6.528 — for #360 R2. defaultdict alias for the prefix-cluster
# helper. Localised import alias to avoid touching the module
# header for one bucket-walker.
from collections import defaultdict as _v1_6_528_defaultdict

sys.path.insert(0, str(Path(__file__).resolve().parent))
import _progress_run as _pr  # noqa: E402


def _v1_6_528_partition_by_signal_prefix(
        rows: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """v1.6.528 — group signal rows by common snake_case prefix
    when no explicit group dividers exist.

    v1.6.533 — for #360 R4. Three-tier strategy to handle the full
    spread of real-benchmark Interfaces table signal-naming
    conventions, not just length>=3 + size>=2 RTL families:

    Pass A (v1.6.528 baseline): len(prefix)>=3 AND
        len(signals_in_bucket)>=2. Strictest — preferred when the
        signal-name family naturally has 3-letter+ prefixes
        (`instr_*` / `data_*` / `debug_*` / `irq_*`).

    Pass B (v1.6.533 — for length-2 RTL idiom names): when Pass A
        yields 0 buckets AND total_signals>=6, relax to
        len(prefix)>=2 AND len(signals_in_bucket)>=3. Catches
        canonical 2-letter RTL groupings (`dm_*`, `rf_*`, `ld_*`,
        `st_*`) ONLY when the family is meaningfully large.

    Pass C (v1.6.533 — implicit-all-group fallback): when Pass A+B
        both yield 0 AND total_signals>=4, emit ONE entry with
        all signals and `interfaces_section_implicit_all_v1_6_533`
        stamp. Phase 2 at least sees the full signal list rather
        than a silent zero.

    Each entry has shape:
        {name: 'X_group' / 'all_interfaces',
         group: 'X' / 'all',
         signals: [...],
         extraction_strategy: '...'}

    Buckets are sorted by group name for deterministic output.
    Idempotent: rows-list-in deterministic outputs-list-out.
    Returns [] only when total_signals < 4.

    Chip-AGNOSTIC: pure snake_case shape filter; no chip-class
    string literal participates.
    """
    if not isinstance(rows, list) or not rows:
        return []
    # v1.6.533 — for #360 R4. Harvest signals once; reused across
    # the three passes (avoids re-walking rows per pass).
    signals: List[str] = []
    seen_sig: Set[str] = set()
    for r in rows:
        if not isinstance(r, dict):
            continue
        # The row dict may use various keys for the signal name;
        # try common ones in order.
        sig = (r.get("signal_name")
               or r.get("name")
               or r.get("signal")
               or "")
        if not isinstance(sig, str):
            continue
        sig = sig.strip()
        if not sig or len(sig) < 2:
            continue
        if sig in seen_sig:
            continue
        seen_sig.add(sig)
        signals.append(sig)
    if not signals:
        return []
    # ----- Pass A — v1.6.528 baseline: len(prefix)>=3 + size>=2 ----
    buckets_a: Dict[str, List[str]] = _v1_6_528_defaultdict(list)
    for sig in signals:
        if "_" in sig:
            prefix = sig.split("_", 1)[0]
        else:
            prefix = sig
        # Length floor 3 — reject 1-2 char prefixes (`a_b`,
        # `i_o`) that cluster too aggressively across unrelated
        # signals.
        if len(prefix) < 3:
            continue
        buckets_a[prefix].append(sig)
    out_a: List[Dict[str, Any]] = []
    for prefix, sigs in buckets_a.items():
        if len(sigs) < 2:
            continue  # singletons discarded
        out_a.append({
            "name": f"{prefix}_group",
            "group": prefix,
            "signals": sigs,
            "extraction_strategy":
                "interfaces_section_prefix_cluster_v1_6_528",
        })
    if out_a:
        # Sort by group name for deterministic ordering across runs.
        out_a.sort(key=lambda e: e["group"])
        return out_a
    # ----- Pass B — v1.6.533 dynamic floor: len>=2 + size>=3 -------
    # Only relax to 2-letter prefixes when the family is
    # meaningfully large (>=6 total signals AND >=3 per bucket) so
    # we don't conjure groups out of small singleton-heavy lists.
    if len(signals) >= 6:
        buckets_b: Dict[str, List[str]] = _v1_6_528_defaultdict(list)
        for sig in signals:
            if "_" in sig:
                prefix = sig.split("_", 1)[0]
            else:
                prefix = sig
            if len(prefix) < 2:
                continue
            buckets_b[prefix].append(sig)
        out_b: List[Dict[str, Any]] = []
        for prefix, sigs in buckets_b.items():
            if len(sigs) < 3:
                continue
            out_b.append({
                "name": f"{prefix}_group",
                "group": prefix,
                "signals": sigs,
                "extraction_strategy":
                    "interfaces_section_prefix_cluster_v1_6_533",
            })
        if out_b:
            out_b.sort(key=lambda e: e["group"])
            return out_b
    # ----- Pass C — v1.6.533 implicit-all-group fallback -----------
    # When Pass A + B both produce 0 buckets and there are still
    # >=4 signals total, emit ONE entry containing every signal so
    # Phase 2 sees the full I/O list rather than a silent empty
    # array. Floor 4 keeps spurious 1-2-signal emits out.
    if len(signals) >= 4:
        return [{
            "name": "all_interfaces",
            "group": "all",
            "signals": signals,
            "extraction_strategy":
                "interfaces_section_implicit_all_v1_6_533",
        }]
    return []


def _v1_6_524_walk_interface_table(text: str) -> List[Dict[str, Any]]:
    """v1.6.524 — for #360 P3 ORGANIC. Walk an Interfaces section
    in ``text``; partition the following table block by group-
    divider rows (AsciiDoc `4+^| **Group**` or RST `**Group**`),
    and emit one entry per group with `signals[]` rolled up from
    row content between dividers.

    Returns a list of dicts shaped:
        {name: slug, group: human_name,
         signals: [signal_name, ...],
         extraction_strategy: 'interfaces_section_v1_6_524'}

    v1.6.528 — for #360 R2. When the block contains an Interfaces
    table but NO divider rows fire (the real-benchmark majority
    case — plain row-per-signal RST tables), fall back to
    `_v1_6_528_partition_by_signal_prefix` on the rows harvested
    from the table block. Divider grammar wins when present;
    prefix-cluster only fires on the no-divider path.

    Empty list when no Interfaces heading + table block is
    detected.

    Chip-AGNOSTIC: structural-only — no chip-class string literal
    participates.
    """
    out: List[Dict[str, Any]] = []
    if not isinstance(text, str) or not text:
        return out

    for hm in _V1_6_524_INTERFACE_HEADING_RE.finditer(text):
        block_start = hm.end()
        block_end = _v1_6_524_find_table_block_end(text, block_start)
        if block_end <= block_start:
            continue
        block = text[block_start:block_end]
        if not block.strip():
            continue
        # Collect group-divider positions inside the block.
        dividers = []
        for dm in _V1_6_524_GROUP_DIVIDER_RE.finditer(block):
            group_name = dm.group("group_a") or dm.group("group_b")
            if not group_name:
                continue
            dividers.append((dm.start(), dm.end(), group_name.strip()))
        if not dividers:
            # v1.6.528 — for #360 R2. No divider rows in this
            # Interfaces table block — fall back to prefix-cluster
            # partition on signals harvested from the whole block.
            # Divider-based grouping takes priority when present
            # (this branch only runs when the divider walker
            # produced zero groups).
            block_signals = _v1_6_524_extract_signals_from_row(block)
            if not block_signals:
                continue
            rows = [{"signal_name": s} for s in block_signals]
            fallback = _v1_6_528_partition_by_signal_prefix(rows)
            if fallback:
                out.extend(fallback)
                # First Interfaces heading wins — same convention
                # as the divider-based path below.
                break
            continue
        # Partition the block by dividers: each group's row text
        # runs from end-of-its-divider until start-of-next-
        # divider (or end-of-block).
        seen_slugs: Set[str] = set()
        for i, (d_start, d_end, group_name) in enumerate(dividers):
            section_start = d_end
            section_end = (
                dividers[i + 1][0] if i + 1 < len(dividers)
                else len(block))
            row_text = block[section_start:section_end]
            signals = _v1_6_524_extract_signals_from_row(row_text)
            slug = _v1_6_524_group_slug(group_name)
            if not slug or slug in seen_slugs:
                continue
            seen_slugs.add(slug)
            out.append({
                "name": slug,
                "group": group_name,
                "signals": signals,
                "extraction_strategy":
                    "interfaces_section_v1_6_524",
            })
        if out:
            # First Interfaces heading wins — don't dilute with
            # noise from secondary repeated headings.
            break
    return out


def _v1_6_524_post_emit_chip_top_interfaces_groups(
        project: Path, extracted: Dict[str, str]) -> None:
    """v1.6.524 — for #360 P3 ORGANIC. Walk extracted_docs for an
    Interfaces table and emit grouped chip_top_interfaces entries
    when found. Idempotent — re-run skips when entries tagged
    `interfaces_section_v1_6_524` are already in the list.
    Coexists with the existing v1.6.294 keyword-match emit
    (append-not-replace).

    Chip-AGNOSTIC.
    """
    if not extracted:
        return
    try:
        gd = _pl.generated_docs_dir(project)
    except Exception:
        return
    l9_path = gd / "L9_INTEGRATION_SPEC.json"
    if not l9_path.is_file():
        return
    try:
        l9 = json.loads(l9_path.read_text(encoding="utf-8"))
    except Exception:
        return
    if not isinstance(l9, dict):
        return
    cti = l9.get("chip_top_interfaces")
    if not isinstance(cti, list):
        cti = []

    # Idempotent re-run skip.
    for entry in cti:
        if (isinstance(entry, dict)
                and entry.get("extraction_strategy")
                == "interfaces_section_v1_6_524"):
            return

    new_entries: List[Dict[str, Any]] = []
    for fname, text in extracted.items():
        if not isinstance(text, str) or not text:
            continue
        entries = _v1_6_524_walk_interface_table(text)
        for e in entries:
            e["evidence_file"] = fname
        new_entries.extend(entries)
        if new_entries:
            # First doc with an Interfaces table wins.
            break

    if not new_entries:
        return

    # Dedupe across the merged list on slug.
    seen_slugs: Set[str] = set()
    for entry in cti:
        if isinstance(entry, dict):
            n = entry.get("name")
            if isinstance(n, str) and n:
                seen_slugs.add(n)
    for e in new_entries:
        if e["name"] in seen_slugs:
            continue
        seen_slugs.add(e["name"])
        cti.append(e)

    l9["chip_top_interfaces"] = cti
    try:
        _stamp.dump(l9_path, l9)
    except Exception:
        pass


# v1.6.526 — for #362 P3 ORGANIC. L9.submodules ASCII-art module-
# hierarchy walker.
#
# Pre-v1.6.526 the submodule walker family covered: Markdown
# pipe-table rows, Markdown bullet under heading, RST inline
# backtick `.sv` references, RST Sphinx `:file:` role, RST H3
# underline heading. None of them detected the ASCII text-tree
# block style commonly found in open-source RTL README files
# (especially CPU + SoC projects with non-Sphinx doc trees):
#
#     # Hierarchy
#     core_top
#     |- core_controller
#     |  |- decoder
#     |  `- regfile
#     |- core_alu
#     `- core_mem
#
# Field-agent benchmark on one RV-CPU IC showed all ~10
# submodules + 1 parent dropped from L9.submodules because the
# entire hierarchy was documented as one ASCII tree at lines
# 11-30 of `input/docs/rtl_README.md` and no walker recognised
# the shape.
#
# Fix: trigger ONLY after a hierarchy-anchor heading (`Hierarchy`
# / `Module Tree` / `Block Diagram` — case-insensitive). Within
# the following text block, walk tree-node-shaped lines (≥ 3
# consecutive lines matching the node regex with tree connectors
# `|`, `` ` ``, `+`, `-`, indent whitespace). Emit unique node
# identifiers as submodules with `instances=1` and
# `extraction_strategy='ascii_art_hierarchy_walker_v1_6_526'`.
# Apply a short-token / English-vocab deny-list so generic prose
# words (`module`, `tree`, `hierarchy`, `block`, `diagram`,
# `core`, `the`) don't leak in.
#
# Chip-AGNOSTIC: pure ASCII-tree convention + English vocab deny;
# no chip-class string literal participates.
_V1_6_526_HIERARCHY_HEADING_RE = re.compile(
    r"^(?:[#=*]+\s*)?(?:Module\s+)?Hierarchy\s*$"
    r"|^(?:[#=*]+\s*)?Module\s+Tree\s*$"
    r"|^(?:[#=*]+\s*)?Block\s+Diagram\s*$",
    re.IGNORECASE | re.MULTILINE,
)

# v1.6.530 — for #362 R2. Real README files (e.g. ic-B
# `rtl_README.txt`) use a PROSE anchor for the hierarchy block
# rather than a clean heading:
#
#     The real RTL hierarchy is the following:
#
#     root_mod -|
#     |- sub_a
#     |- sub_b
#
# v1.6.526's heading regex required the entire line to be
# `Hierarchy` / `Module Tree` / `Block Diagram` (with optional
# `#`/`=`/`*` prefix). The prose form has additional words BEFORE
# and AFTER the hierarchy keyword, so the regex rejected it and
# the ASCII-art tree walker never triggered.
#
# Widen the regex with a 4th alternation that accepts a line
# containing one of the hierarchy keywords AND ending with `:`
# (the colon being the syntactic introducer of the tree block).
# The `:` anchor keeps the false-positive surface bounded — a
# normal sentence that mentions "hierarchy" without ending in
# `:` is still rejected.
#
# Chip-AGNOSTIC: pure English-prose grammar — no chip-class
# string literal participates.
_V1_6_530_HIERARCHY_HEADING_RE = re.compile(
    r"^(?:[#=*]+\s*)?(?:Module\s+)?Hierarchy\s*$"
    r"|^(?:[#=*]+\s*)?Module\s+Tree\s*$"
    r"|^(?:[#=*]+\s*)?Block\s+Diagram\s*$"
    # v1.6.530 — prose-form anchor (sentence containing
    # 'hierarchy'/'module tree'/'block diagram' ending with `:`):
    r"|^[^\n]*\b(?:RTL\s+hierarchy|module\s+hierarchy|hierarchy"
    r"|module\s+tree|block\s+diagram)\b"
    r"[^\n]*:\s*$",
    re.IGNORECASE | re.MULTILINE,
)

# Tree-connector glyphs that anchor an ASCII tree line: `|`,
# backtick (often used for `` `- ``), `+`, `-`, leading whitespace.
# A line qualifies as an ASCII-tree line iff it starts with one of
# these connectors (or whitespace + connector) AND contains an
# identifier-shape token.
_V1_6_526_ASCII_TREE_NODE_RE = re.compile(
    r"^[ \t]*(?:[|`+\-][| `+\-]*\s*)?"
    r"(?P<node>[a-z_][a-z0-9_]+)\s*"
    r"(?:[|`\-]+|$)",
    re.IGNORECASE | re.MULTILINE,
)

# Vocab deny-list — pure English / generic words that often
# appear inside an ASCII tree block (heading text, comments,
# section markers) but are NOT submodule identifiers.
_V1_6_526_NODE_DENY = frozenset({
    "module", "modules", "tree", "hierarchy", "block", "diagram",
    "core", "the", "and", "or", "of", "in", "to", "is", "are",
    "this", "that", "from", "with", "for", "see", "note",
    "fig", "figure", "level", "above", "below",
})


# v1.6.532 — for #362 R3. Connector-only spacer tolerance.
# Real ASCII trees use bare `|` (or `|`+whitespace+`+/-/\``)
# lines between sibling nodes as visual breathing-room. v1.6.526's
# `_V1_6_526_ASCII_TREE_NODE_RE` rejects such lines because no
# identifier-shape token follows — the previous collection loop
# then hit `if started: break`, truncating valid trees at 2 lines
# and failing the ≥3-tree-line floor (→ 0 emit on real ic-B).
#
# Treat a line that contains ONLY connector glyphs (whitespace +
# any of `|`/`+`/`-`/`\``/`\`) as part of the in-progress block
# (continue collecting); break only on a non-connector,
# non-tree-node line (genuine prose).
#
# Chip-AGNOSTIC — pure typographical grammar; no chip-class string
# literal participates.
_V1_6_532_CONNECTOR_ONLY_RE = re.compile(r"^[\s|`+\-\\]+$")

# v1.0.38 — for #648. Box-drawing-aware connector-only spacer.
# Modern hierarchy trees (the de-facto `tree(1)` / Markdown / SoC
# documentation convention) draw the connectors with Unicode
# box-drawing glyphs (└ ─ ├ │ ┌ ┐ ┘ ┴ ┬ ┤) rather than ASCII
# `|`/`-`/`` ` ``. A bare box-vertical spacer line (`│`) between
# siblings must be tolerated exactly like the ASCII `|` spacer so
# the walker does not truncate the tree at the first box-glyph
# breathing-room line. chip-AGNOSTIC — pure typographical glyph
# class; no chip-class string literal participates.
_V1_0_38_BOX_GLYPHS = "└─├│┌┐┘┴┬┤"
_V1_0_38_CONNECTOR_ONLY_RE = re.compile(
    r"^[\s|`+\-\\" + _V1_0_38_BOX_GLYPHS + r"]+$")


# v1.6.534 — for #362 R4. Real ASCII trees commonly have trailing
# parenthetical annotation after a node identifier:
#   `|- core_top (2x instruction)`
#   `|- dma_ctrl (optional)`
#   `|- mem_ctrl (1x per cluster)`
# v1.6.526's NODE_RE required trailing connector glyph or EOL
# after the identifier, rejecting all such annotated nodes — when
# the walker hit such a line it executed `if started: break` and
# truncated the tree at the first annotated sibling. v1.6.532's
# connector-only-spacer rescue does NOT apply to these lines
# because they carry identifier + prose, not bare connectors.
#
# Widen the trailer alternation from 2-way to 4-way, BUT gate the
# two new alternations on the presence of a leading connector
# glyph (so plain prose lines like ``Some unrelated text here.``
# without any connector still do NOT match — preserving the
# v1.6.532 "break at prose" walker contract):
#
#   (a) connector glyph trailer (regression preserved — v1.6.526)
#       — always allowed;
#   (b) EOL alone (regression preserved — v1.6.526) — always
#       allowed (so a connector-less root like ``core_top`` still
#       matches as a tree-root line);
#   (c) NEW — space + parenthetical ``(...)`` annotation at EOL,
#       ONLY when a leading connector was matched;
#   (d) NEW — space + non-connector prose at EOL, ONLY when a
#       leading connector was matched; ``|`` excluded from the
#       prose char class to protect grid-table-like shapes
#       (``| name | desc |``).
#
# Implementation: use the ``(?(1)yes|no)`` conditional-regex
# feature — group(1) is the leading-connector capture (made
# REQUIRED-to-be-captured by promoting it to an unnamed group).
# When group(1) matched, the 4-way trailer is allowed; when it
# did not, only the 2-way regression trailer is allowed.
#
# Connector-only spacer lines (``            |``, ``+--``, etc.)
# still do NOT match this regex (no identifier follows) — they
# continue to be handled by ``_V1_6_532_CONNECTOR_ONLY_RE``
# upstream.
#
# Chip-AGNOSTIC — pure typographical grammar; no chip-class
# string literal participates.
_V1_6_534_ASCII_TREE_NODE_RE = re.compile(
    r"^[ \t]*(?:([|`+\-][| `+\-]*)\s*)?"
    r"(?P<node>[a-z_][a-z0-9_]+)"
    r"(?(1)"
    # Leading connector present → 4-way trailer:
    r"(?:"
    # (a) connector-glyph trailer (regression):
    r"\s*[|`\-]+\s*$"
    r"|"
    # (b) EOL trailer (regression):
    r"\s*$"
    r"|"
    # (c) v1.6.534 NEW — parenthetical annotation:
    r"\s+\([^)]*\)\s*$"
    r"|"
    # (d) v1.6.534 NEW — non-connector prose, `|` excluded:
    r"\s+[^|`\-\s][^|]*$"
    r")"
    r"|"
    # No leading connector → 2-way trailer (regression-safe;
    # prevents plain prose from being mistaken for tree nodes):
    r"(?:\s*[|`\-]+\s*$|\s*$)"
    r")",
    re.IGNORECASE | re.MULTILINE,
)


# v1.0.38 — for #648. Box-drawing + parenthetical-root ASCII tree
# node regex. The v1.6.534 NODE_RE's leading-connector class is
# `[|`+\-]` which EXCLUDES the Unicode box-drawing glyphs
# (└ ─ ├ │ ┌ ┐ ┘ ┴ ┬ ┤) that modern hierarchy trees (`tree(1)`,
# GitHub-rendered Markdown, SoC integration docs) use to draw the
# connectors — so a canonical
#     top_wrapper
#     └── child_a
#         └── child_b
# tree had every connector-drawn child line rejected. Two widenings:
#   (1) the leading-connector char class now ALSO accepts the box
#       glyphs, so `└── child_a` / `    └── child_b` match and yield
#       `child_a` / `child_b`;
#   (2) the NO-leading-connector branch (a tree ROOT printed without
#       a connector, e.g. `top_wrapper (top)`) now ALSO accepts a
#       trailing `(...)` parenthetical annotation — a near-universal
#       convention for tagging the root (`(top)`, `(top-level)`).
#       Without (2) the connector-less annotated root broke the
#       block at its very first line.
# The v1.6.534 constant is left byte-for-byte untouched so tests
# that import it directly still pass; only the walker call-site is
# rewired to this widened regex.
#
# Group layout is identical to v1.6.534 (group(1) = leading
# connector capture used by the `(?(1)yes|no)` conditional;
# `node` = the identifier).
#
# chip-AGNOSTIC — pure typographical grammar; box-drawing trees are
# a universal hierarchical-documentation convention. No chip-class
# string literal participates.
_V1_0_38_ASCII_TREE_NODE_RE = re.compile(
    r"^[ \t]*(?:([|`+\-" + _V1_0_38_BOX_GLYPHS +
    r"][| `+\-" + _V1_0_38_BOX_GLYPHS + r"]*)\s*)?"
    r"(?P<node>[a-z_][a-z0-9_]+)"
    r"(?(1)"
    # Leading connector present → 4-way trailer (regression-parity
    # with v1.6.534):
    r"(?:"
    r"\s*[|`\-]+\s*$"          # (a) connector-glyph trailer
    r"|"
    r"\s*$"                     # (b) EOL trailer
    r"|"
    r"\s+\([^)]*\)\s*$"        # (c) parenthetical annotation
    r"|"
    r"\s+[^|`\-\s][^|]*$"      # (d) non-connector prose (`|` excluded)
    r")"
    r"|"
    # No leading connector → root line. v1.0.38 widens the
    # regression 2-way trailer to ALSO accept a trailing
    # parenthetical (`top_wrapper (top)`), `|`-excluded prose still
    # rejected so plain sentences are not mistaken for tree nodes.
    r"(?:\s*[|`\-]+\s*$|\s*$|\s+\([^)]*\)\s*$)"
    r")",
    re.IGNORECASE | re.MULTILINE,
)


# v1.6.536 — for #363 (filed as #364) ORGANIC. L1.vendor harvester
# missing — 8/8 benchmark ICs emitted ``vendor=None`` at v1.6.534
# despite their READMEs carrying obvious vendor / organization
# anchors. Existing ``readme_vendor_extractor.extract_vendor``
# covered SPDX-copyright / `(C)` lines / Markdown
# ``Maintainer: [name](url)`` / ``Maintained|Authored|Designed by
# <name>`` / bare ``github.com/<org>/<repo>`` URL, but missed:
#
#   (1) Shields-style badge embedded image links of the form
#       ``[![ci](https://github.com/<ORG>/<repo>/workflows/...)]``
#       which is the dominant README opener for modern RTL repos;
#   (2) Free-prose attribution like ``... by <Name>``,
#       ``... contributed to <Org>``;
#   (3) Same-IC README mentioning ``github.com/<ORG>/<repo>`` in
#       a hyperlinked anchor (the legacy GitHub-badge regex
#       requires no scheme prefix and matched too narrowly).
#
# Three-tier extractor:
#   Tier 1 — embedded-image badge URL ``[![...](...github.com/<ORG>/<repo>...)]``
#   Tier 2 — free-prose attribution
#            ``(by|contributed to|maintained by|developed at) <Name>``
#   Tier 3 — bare ``https?://github.com/<ORG>/<repo>`` URL.
#
# First hit wins; downstream emit goes through ``_v1_6_536_trim_vendor``
# (local copy of the v1.6.393 4-token cap + trailing-punctuation
# strip) for the prose tier so non-greedy capture cannot slide.
#
# Chip-AGNOSTIC — pure typographical anchor grammar; no chip-class
# string literal participates. Universal RTL-repo README convention.
_V1_6_536_VENDOR_BADGE_URL_RE = re.compile(
    r"\[\!\[[^\]]*\]\(https?://github\.com/(?P<org>[A-Za-z0-9_\-]+)/"
    r"[A-Za-z0-9_\-]+",
)

_V1_6_536_VENDOR_BY_PROSE_RE = re.compile(
    # Anchor: start of string, start of line (MULTILINE), end of
    # previous sentence, or open paren. MULTILINE is critical —
    # real READMEs split anchor sentences across lines, so without
    # it the only matches would be the very first sentence.
    r"(?:^|\.\s+|\(\s*|\n)\s*(?:[A-Z][a-z]+\s+)?"
    r"(?:by|contributed\s+to|maintained\s+by|developed\s+at)\s+"
    r"(?P<name>[A-Z][A-Za-z0-9_\-\s]{2,40})"
    r"(?:[\.,\)]|\s+(?:on|at|under)\b)",
    re.IGNORECASE | re.MULTILINE,
)

# v1.6.540 — for #364 R1. The v1.6.536 prose regex used
# `re.IGNORECASE | re.MULTILINE` which neutralized the `[A-Z]`
# Title-Case constraint on the captured vendor name. Result:
# `"by a simplified two stage"` matched (lowercase `a`). Real
# benchmark README containing "composed by a simplified
# two stage pipeline" — Tier-2 captured the prose fragment
# and Tier-3 (correct GitHub-URL vendor strategy) never fired.
#
# Fix: keep IGNORECASE on the anchor vocab (`by/contributed
# to/...` may appear at sentence start as `By/Contributed
# to/...`), but wrap the capture group in an inline
# `(?-i:...)` modifier so the `[A-Z]` first-char constraint
# is genuinely case-sensitive. Combined with the stop-word
# filter (`_v1_6_540_vendor_prose_acceptable`) below, this
# rejects ic-B-shape `"by a simplified ..."` and lets
# Tier-3 GitHub-URL strategy fire. chip-AGNOSTIC.
_V1_6_540_VENDOR_BY_PROSE_RE = re.compile(
    r"(?:^|\.\s+|\(\s*|\n)\s*(?:[A-Z][a-z]+\s+)?"
    r"(?:by|contributed\s+to|maintained\s+by|developed\s+at)\s+"
    # Inline (?-i:...) re-enables case-sensitivity for the
    # capture group only — `[A-Z]` first char is genuine
    # Title-Case (lowercase `a` rejected at the regex level).
    r"(?-i:(?P<name>[A-Z][A-Za-z0-9_\-\s]{2,40}))"
    r"(?:[\.,\)]|\s+(?:on|at|under)\b)",
    re.IGNORECASE | re.MULTILINE,
)

_V1_6_540_VENDOR_PROSE_STOPWORDS = frozenset({
    "A", "An", "The", "This", "That", "Some", "Few", "Several",
    "One", "Two", "Any", "Each", "All", "No", "More", "Less",
})


def _v1_6_540_vendor_prose_acceptable(candidate):
    """v1.6.540 — for #364 R1. Defense-in-depth on top of the
    case-sensitive regex: reject if first token is in the
    stopword set (capitalized determiners / quantifiers) OR
    the first token is all-lowercase. Returns True if the
    candidate is acceptable as a vendor name. chip-AGNOSTIC —
    pure linguistic stopword filter; no chip-class literal."""
    if not candidate:
        return False
    stripped = candidate.strip()
    if not stripped:
        return False
    first = stripped.split()[0]
    if first in _V1_6_540_VENDOR_PROSE_STOPWORDS:
        return False
    if first.islower():
        return False
    return True


_V1_6_536_VENDOR_GITHUB_REPO_URL_RE = re.compile(
    r"\bhttps?://github\.com/(?P<org>[A-Za-z0-9_\-]+)/[A-Za-z0-9_\-]+",
)


def _v1_6_536_trim_vendor(raw):
    """v1.6.536 — for #364 ORGANIC. Local copy of the v1.6.393
    word-cap + trailing-punctuation strip — used for the Tier-2
    prose-attribution capture so a non-greedy match cannot slide
    into the trailing sentence. Chip-AGNOSTIC."""
    tokens = (raw or "").strip().split()
    capped = " ".join(tokens[:4])
    return capped.rstrip(".,;:")


def _v1_6_536_extract_vendor(readme_text):
    """v1.6.536 — for #364 ORGANIC. Three-tier README vendor
    harvester. First hit wins:

      Tier 1 — embedded-image badge URL (highest confidence — CI
               URL identifies the hosting org).
      Tier 2 — free-prose attribution (``by/contributed to/
               maintained by/developed at <Name>``).
      Tier 3 — bare ``https?://github.com/<ORG>/<repo>`` URL.

    Returns ``(vendor_or_None, strategy_or_None)`` so the caller
    can populate both ``L1.ordering_info.vendor`` and
    ``L1.ordering_info.vendor_extraction_strategy``.

    The prose-tier capture is post-trimmed by
    ``_v1_6_536_trim_vendor`` (4-token cap + trailing-punctuation
    strip — local copy of v1.6.393's helper) so any non-greedy
    capture cannot slide past the intended vendor token.

    Chip-AGNOSTIC — pure structural regex with no chip-class
    string literal in the pattern, helper, or marker window.
    """
    if not isinstance(readme_text, str) or not readme_text:
        return None, None
    m = _V1_6_536_VENDOR_BADGE_URL_RE.search(readme_text)
    if m:
        org = (m.group("org") or "").strip()
        if org and len(org) >= 2:
            return org, "vendor_badge_url_v1_6_536"
    # v1.6.540 — for #364 R1. Switch Tier-2 to v1.6.540 regex
    # (case-sensitive `[A-Z]` first char restored — IGNORECASE
    # dropped) + stopword-filter gate. Rejected → fall through
    # to Tier-3 GitHub-URL strategy. chip-AGNOSTIC.
    m = _V1_6_540_VENDOR_BY_PROSE_RE.search(readme_text)
    if m:
        raw = (m.group("name") or "").strip()
        trimmed = _v1_6_536_trim_vendor(raw)
        if (trimmed and len(trimmed) >= 2 and
                _v1_6_540_vendor_prose_acceptable(trimmed)):
            return trimmed, "vendor_by_prose_v1_6_540"
    m = _V1_6_536_VENDOR_GITHUB_REPO_URL_RE.search(readme_text)
    if m:
        org = (m.group("org") or "").strip()
        if org and len(org) >= 2:
            return org, "vendor_github_repo_url_v1_6_536"
    return None, None


# v1.6.538 — for #366 ORGANIC. L8.synthesis_targets prose-form
# fmax walker. README / datasheet / overview prose commonly
# declares maximum operating frequency in free-prose shape:
#   "can run at up to <N> MHz"
#   "maximum operating frequency of <N> MHz"
#   "maximum frequency of <N> MHz"
#   "clocked at <N> MHz"
#   "clocked up to <N> MHz"
#   "target <N> MHz"
#   "up to <N> MHz on <FPGA-family>"
# The v1.6.510 / #352 walker handles MD pipe-table /
# code-block / HTML <sub> fmax row shapes — this one fills the
# prose gap so synthesis_targets[] is no longer empty for ICs
# whose only fmax claim is in line-1 of an overview doc.
# Chip-AGNOSTIC: pure English-prose grammar; the trailing
# `(?:on|using|with) <Name>` group captures the target FPGA
# family generically. Vendor / family names never enumerated.
_V1_6_538_FMAX_PROSE_RE = re.compile(
    r"(?:can\s+run\s+at\s+)?"
    r"(?:"
    r"up\s+to"
    r"|maximum(?:\s+operating)?\s+frequency\s+of"
    r"|maximum\s+frequency\s+of"
    r"|clocked\s+at"
    r"|clocked\s+up\s+to"
    r"|target(?:\s+of)?"
    r"|runs\s+at"
    r"|runs\s+up\s+to"
    r")\s+"
    r"(?P<n>\d+(?:\.\d+)?)\s*MHz"
    # Optional target group: requires "on/using/with" + optional
    # filler-article + uppercase-anchored multi-word phrase
    # bounded by sentence-end punctuation or EOL. The
    # `(?:the|an?)\s+` filler swallows English articles before
    # the real proper noun (`on the SoC backbone`,
    # `on a Cyclone V`). The capture is greedy on `[A-Za-z0-9_\-
    # \s]` then required to land on a sentence terminator —
    # safer than the non-greedy `{1,40}?` form which truncated
    # multi-word vendor names like `Cyclone V family` at the
    # first whitespace.
    r"(?:\s+(?:on|using|with)\s+(?:the|an?)?\s*"
    r"(?P<target>[A-Z][A-Za-z0-9_\-\s]{0,80})"
    r")?"
    r"(?=[\.\,\)\;]|$)",
    re.IGNORECASE | re.MULTILINE,
)


# v1.6.543 — for #369 P3 ORGANIC. Extend v1.6.538 prose-fmax walker
# with three new verb-form anchors observed in real RV-CPU
# integration docs:
#
#   * `synthe[ts]i[sz]ed\s+at`
#     — single compact alternation covering four spellings of the
#       same word:
#         - synthesized (US standard)
#         - synthesised (UK standard)
#         - synthetized (typo / hispano-european reduction
#                        observed in multiple .rst lines)
#         - synthetised (typo / less common but seen)
#   * `implement(?:ed)?\s+at`
#     — covers `implemented at N MHz` synthesis-report convention.
#   * `operates?\s+at`
#     — covers `operates at N MHz` / `operate at N MHz` claims.
#
# v1.6.538 verb-forms (can run at up to / maximum frequency of /
# clocked at / clocked up to / target / runs at / runs up to) are
# carried through unchanged.
#
# Chip-AGNOSTIC: pure English-prose verb-form variation; no
# chip-class string literal participates.
_V1_6_543_FMAX_PROSE_RE = re.compile(
    r"(?:can\s+run\s+at\s+)?"
    r"(?:"
    r"up\s+to"
    r"|maximum(?:\s+operating)?\s+frequency\s+of"
    r"|maximum\s+frequency\s+of"
    r"|clocked\s+at"
    r"|clocked\s+up\s+to"
    r"|target(?:\s+of)?"
    r"|runs\s+at"
    r"|runs\s+up\s+to"
    r"|synthe[ts]i[sz]ed\s+at"   # NEW v1.6.543 — synthesi/zed,
                                  # synthesi/sed, syntheti/zed,
                                  # syntheti/sed (typo)
    r"|implement(?:ed)?\s+at"    # NEW v1.6.543
    r"|operates?\s+at"           # NEW v1.6.543
    r")\s+"
    r"(?P<n>\d+(?:\.\d+)?)\s*MHz"
    r"(?:\s+(?:on|using|with)\s+(?:the|an?)?\s*"
    r"(?P<target>[A-Z][A-Za-z0-9_\-\s]{0,80})"
    r")?"
    r"(?=[\.\,\)\;]|$)",
    re.IGNORECASE | re.MULTILINE,
)


def _v1_6_538_extract_fmax_prose(text):
    """v1.6.538 — for #366 ORGANIC. Walk free-prose maximum-
    frequency claims and emit ``L8.synthesis_targets[]`` entries.

    Returns a list of dicts shaped::

        {
          "name": "fmax_prose_<n>mhz" + ("_on_<slug>" if target),
          "fmax_mhz": float(n),
          "target_fpga": target_or_None,
          "role": "synthesis_fmax" (target) | "chip_internal_proposed",
          "extraction_strategy": "fmax_prose_v1_6_538",
        }

    Deduplication is the caller's responsibility (key
    ``(n, target)``); this helper emits one entry per regex match.

    Chip-AGNOSTIC: pure English-prose grammar; no chip-class
    string literal participates in the regex, helper, or any
    300-char window around the v1.6.538 markers.
    """
    out = []
    if not isinstance(text, str) or not text:
        return out
    seen = set()
    # v1.6.543 — for #369 P3 ORGANIC. Switch to extended regex that
    # additionally covers `synthet[i|he]si[sz]ed at` /
    # `implement(ed)? at` / `operates? at` verb-form anchors common
    # in RV-CPU integration docs. v1.6.538 emit shape preserved.
    for m in _V1_6_543_FMAX_PROSE_RE.finditer(text):
        n_str = m.group("n")
        try:
            n = float(n_str)
        except (TypeError, ValueError):
            continue
        target_raw = m.group("target")
        target = (target_raw.strip() if isinstance(target_raw, str)
                  else None) or None
        # v1.6.538 — guard against the article-only edge case:
        # ``on the .`` would leave ``target`` empty after article
        # stripping in the regex; the empty / 1-char target is
        # promoted to None so role flips to chip_internal_proposed.
        if target and len(target) < 2:
            target = None
        key = (n, target)
        if key in seen:
            continue
        seen.add(key)
        slug = (target.lower().replace(" ", "_")
                if target else None)
        name = f"fmax_prose_{n_str}mhz"
        if slug:
            name = f"{name}_on_{slug}"
        out.append({
            "name": name,
            "fmax_mhz": n,
            "target_fpga": target,
            "role": ("synthesis_fmax" if target
                     else "chip_internal_proposed"),
            "extraction_strategy": "fmax_prose_v1_6_538",
        })
    return out


def _v1_6_526_walk_ascii_art_hierarchy(
        text: str) -> List[Dict[str, Any]]:
    """v1.6.526 — for #362 P3 ORGANIC. Walk an ASCII text-tree
    hierarchy block in ``text``; emit unique node identifiers as
    submodule entries with `instances=1`.

    Returns a list of dicts shaped:
        {name: identifier, instances: 1,
         extraction_strategy: 'ascii_art_hierarchy_walker_v1_6_526'}

    Trigger conditions (ALL required):
      1. A hierarchy-style heading (``Hierarchy`` / ``Module Tree``
         / ``Block Diagram``) must precede the block — keeps
         false-positive surface bounded.
      2. The block must contain ≥ 3 contiguous lines (with no
         more than 1 intervening blank-line gap) that match the
         ASCII tree-node regex.
      3. Each node identifier must (a) be ≥ 3 chars, (b) not
         match the English-vocab deny-list, (c) be unique.

    Block end: a non-blank line that does NOT match the tree-node
    regex OR a two-consecutive-blank-line gap.

    Empty list when no heading + ≥3-line tree block is found.

    Chip-AGNOSTIC.
    """
    out: List[Dict[str, Any]] = []
    if not isinstance(text, str) or not text:
        return out

    seen: Set[str] = set()
    # v1.6.530 — for #362 R2. Use the widened heading regex which
    # additionally accepts prose-form anchors ending with `:`
    # (e.g. ic-B `rtl_README.txt` "The real RTL hierarchy is the
    # following:"). Clean headings (`Hierarchy`, `Module Tree`,
    # `Block Diagram`) keep working unchanged via the first three
    # alternations.
    for hm in _V1_6_530_HIERARCHY_HEADING_RE.finditer(text):
        block_start = hm.end()
        # Collect consecutive tree-node lines after the heading.
        # Allow 1 blank-line gap between lines; 2 blanks or 1
        # non-tree line ends the block.
        block_text = text[block_start: block_start + 8192]
        # Skip leading blank line(s) immediately after heading.
        lines = block_text.splitlines()
        tree_lines: List[str] = []
        consec_blank = 0
        started = False
        for ln in lines:
            stripped = ln.strip()
            if not stripped:
                consec_blank += 1
                if started and consec_blank >= 2:
                    break
                continue
            consec_blank = 0
            # v1.0.38 — for #648. Use the box-drawing-aware NODE_RE
            # which, on top of the v1.6.534 trailing-parenthetical /
            # prose trailer, ALSO accepts Unicode box-drawing
            # connector glyphs (└ ─ ├ │ …) and a connector-less root
            # carrying a `(...)` annotation. The v1.6.534 regex
            # rejected every box-glyph-drawn child line, so a modern
            # `tree(1)`-style hierarchy yielded 0 nodes.
            m = _V1_0_38_ASCII_TREE_NODE_RE.match(ln)
            if m is None:
                # v1.6.532 — for #362 R3. Connector-only spacer
                # tolerance. Real ASCII trees use bare `|` lines
                # between siblings as breathing-room; v1.6.526's
                # NODE_RE rejects them because no identifier
                # token follows. Treat them as in-block lines so
                # the surrounding nodes still aggregate, instead
                # of truncating the block at the first spacer.
                # v1.0.38 — for #648. Box-glyph spacers (`│`) are
                # tolerated identically to the ASCII `|` spacer.
                if started and _V1_0_38_CONNECTOR_ONLY_RE.match(
                        ln.rstrip("\n")):
                    tree_lines.append(ln)
                    if len(tree_lines) >= 256:
                        break
                    continue
                if started:
                    break
                # Pre-tree prose between heading and tree: tolerate
                # a few lines, then give up after ~6.
                if len(tree_lines) == 0 and len(ln) < 80:
                    # Heading-trailing text often is heading-
                    # underline (`===`) or label; tolerate.
                    if re.match(
                            r"^[=\-~^'`*#]{3,}\s*$", stripped):
                        continue
                # Give up — no tree block under this heading.
                break
            tree_lines.append(ln)
            started = True
            if len(tree_lines) >= 256:
                break
        if len(tree_lines) < 3:
            # Need at least 3 tree-shaped lines to call this a
            # real hierarchy block (defence against single-line
            # noise).
            continue
        # Extract node identifiers from tree_lines.
        # v1.0.38 — for #648. Same box-drawing-aware NODE_RE so
        # box-glyph-drawn nodes (`└── foo`) and annotated nodes
        # (`|- foo (annotation)`) yield their identifier here too;
        # otherwise tree_lines would carry the line but the second
        # pass would drop it.
        block_nodes: List[str] = []
        for tl in tree_lines:
            m = _V1_0_38_ASCII_TREE_NODE_RE.match(tl)
            if m is None:
                continue
            node = (m.group("node") or "").lower().strip()
            if not node or len(node) < 3:
                continue
            if node in _V1_6_526_NODE_DENY:
                continue
            # v1.0.38 — for #648. Each emitted node must pass the
            # shared `_is_real_submodule_name` RTL-shape gate so a
            # box-drawing tree cannot fabricate a non-module token
            # (table glyph / all-caps abbreviation / English word)
            # as a submodule. chip-AGNOSTIC structural filter.
            if not _is_real_submodule_name(node):
                continue
            if node in seen:
                continue
            seen.add(node)
            block_nodes.append(node)
        # v1.6.532 — for #362 R3. Connector-only spacer lines
        # collected by the loop above count toward `tree_lines`
        # but do NOT yield identifiers. Enforce ≥3 unique node
        # identifiers (independent of line count) so a degenerate
        # block of 2 real nodes padded with spacer lines cannot
        # cross the gate.
        if len(block_nodes) < 3:
            # Rollback `seen` additions from this rejected block
            # so a later valid block under a different heading is
            # not blocked by dedup on these short-listed names.
            for n in block_nodes:
                seen.discard(n)
            continue
        for n in block_nodes:
            out.append({
                "name": n,
                "instances": 1,
                "extraction_strategy":
                    "ascii_art_hierarchy_walker_v1_6_526",
            })
        if out:
            # First valid hierarchy heading wins — same first-
            # block convention as v1.6.524 + v1.6.351.
            break
    return out


def _v1_6_526_post_emit_ascii_art_hierarchy(
        project: Path, extracted: Dict[str, str]) -> None:
    """v1.6.526 — for #362 P3 ORGANIC. Walk extracted_docs for an
    ASCII text-tree hierarchy block under a hierarchy-anchor
    heading; emit unique node identifiers as L9.submodules
    entries with `instances=1`. Idempotent — re-run skips when
    `extraction_strategy='ascii_art_hierarchy_walker_v1_6_526'`
    entries are already present.

    Coexists with all other submodule walkers — appends to the
    existing list, dedupes on `name`.

    Chip-AGNOSTIC.
    """
    if not extracted:
        return
    try:
        gd = _pl.generated_docs_dir(project)
    except Exception:
        return
    l9_path = gd / "L9_INTEGRATION_SPEC.json"
    if not l9_path.is_file():
        return
    try:
        l9 = json.loads(l9_path.read_text(encoding="utf-8"))
    except Exception:
        return
    if not isinstance(l9, dict):
        return
    subs = l9.get("submodules")
    if not isinstance(subs, list):
        subs = []

    # Idempotent re-run skip.
    for entry in subs:
        if (isinstance(entry, dict)
                and entry.get("extraction_strategy")
                == "ascii_art_hierarchy_walker_v1_6_526"):
            return

    existing_names: Set[str] = set()
    for entry in subs:
        if isinstance(entry, dict):
            n = entry.get("name")
            if isinstance(n, str) and n:
                existing_names.add(n.lower())

    new_entries: List[Dict[str, Any]] = []
    for fname, text in extracted.items():
        if not isinstance(text, str) or not text:
            continue
        entries = _v1_6_526_walk_ascii_art_hierarchy(text)
        for e in entries:
            # v1.6.578 — for #394 P3 ORGANIC. Emit the canonical
            # `evidence: {file: ...}` nested shape (not the legacy
            # flat `evidence_file` key) so downstream gates probing
            # `submodule["evidence"]["file"]` resolve correctly.
            # Schema unification across every L9 submodule emitter
            # closes the no_evidence false-positive on the ASCII-art
            # walker path. Chip-AGNOSTIC.
            e["evidence"] = {"file": fname}
        new_entries.extend(entries)
        if new_entries:
            # First doc with a hierarchy block wins.
            break

    if not new_entries:
        return

    appended = 0
    for e in new_entries:
        if e["name"] in existing_names:
            continue
        existing_names.add(e["name"])
        subs.append(e)
        appended += 1

    if appended == 0:
        return

    l9["submodules"] = subs
    if l9.get("no_submodules_in_input"):
        l9["no_submodules_in_input"] = False
    try:
        _stamp.dump(l9_path, l9)
    except Exception:
        pass


def _v1_6_578_normalize_submodule_evidence(
        submodules: List[Dict[str, Any]]) -> int:
    """v1.6.578 — for #394 P3 ORGANIC. Migrate legacy flat
    `evidence_file: "<str>"` key into the canonical nested
    `evidence: {file: "<str>"}` shape used by all current
    L9.submodules emitters. Returns the number of records
    migrated. Idempotent: records that already carry an
    `evidence` dict are left untouched. Records that carry both
    keys (transient state) get unified into the dict, with the
    flat `evidence_file` removed. Chip-AGNOSTIC: pure schema
    invariant."""
    if not isinstance(submodules, list) or not submodules:
        return 0
    migrated = 0
    for s in submodules:
        if not isinstance(s, dict):
            continue
        if "evidence" in s and isinstance(s["evidence"], dict):
            # Already canonical. If a stale `evidence_file` slot
            # is present, drop it for cleanliness; idempotent.
            if "evidence_file" in s:
                s.pop("evidence_file", None)
            continue
        ef = s.get("evidence_file")
        if isinstance(ef, str) and ef:
            s["evidence"] = {"file": ef}
            s.pop("evidence_file", None)
            migrated += 1
        elif "evidence" in s and isinstance(s["evidence"], str):
            # Defense: some legacy emitters used `evidence` as a
            # bare string (instead of a dict). Migrate to nested.
            s["evidence"] = {"file": s["evidence"]}
            migrated += 1
    return migrated


def _v1_6_578_normalize_l9_submodule_evidence(project: Path) -> None:
    """v1.6.578 — for #394 P3 ORGANIC. Reads `L9_INTEGRATION_SPEC.json`
    from disk, migrates submodule evidence keys via
    `_v1_6_578_normalize_submodule_evidence`, and re-writes the
    file when at least one record was migrated. Idempotent + safe
    on missing / unreadable / non-dict L9. Chip-AGNOSTIC."""
    try:
        gd = _pl.generated_docs_dir(project)
    except Exception:
        return
    l9_path = gd / "L9_INTEGRATION_SPEC.json"
    if not l9_path.is_file():
        return
    try:
        l9 = json.loads(l9_path.read_text(encoding="utf-8"))
    except Exception:
        return
    if not isinstance(l9, dict):
        return
    subs = l9.get("submodules")
    if not isinstance(subs, list):
        return
    migrated = _v1_6_578_normalize_submodule_evidence(subs)
    if migrated == 0:
        return
    try:
        _stamp.dump(l9_path, l9)
    except Exception:
        pass


# v1.6.154 (#62) — register-name promotion from L12 prose to L4.
# Crypto-class READMEs explicitly enumerate register names ("config
# register", "control register", "status register", "key register
# words", "ADDR_CTRL register") inside usage-sequence sections. L12
# captures these as prose steps; this hook scans those steps for
# register-name phrases and synthesises L4.registers entries with
# `extraction_strategy: register_name_promotion_from_l12` +
# `low_confidence: true` so the strict audit can distinguish
# prose-promoted entries from datasheet-table-extracted ones.
# chip-AGNOSTIC: pattern is `<word> register` / `<CAPS_WORD>
# (?:API )?register` in step prose, regardless of chip class.
_RE_REGISTER_PHRASE = re.compile(
    r"(?i)\b([A-Za-z][A-Za-z0-9_]{1,30})\s+register(?:s)?(?:\s+words?)?\b"
)
_RE_REGISTER_NAMED_CAPS = re.compile(
    r"\b([A-Z][A-Z0-9_]{2,30})\b\s+(?:API\s+)?register(?:s)?\b"
)
_RE_CONTROL_BIT = re.compile(
    r"(?i)\b(init|next|start|stop|ready|done|busy|valid|enable|reset)"
    r"\s+bit\b"
)
# Words that mean "register" but are NOT register names (filler /
# adjectives). chip-AGNOSTIC: any chip-class with usage-sequence
# prose can drop these tokens.
_REGISTER_NAME_DENYLIST = frozenset({
    "the", "a", "an", "this", "that", "these", "those", "any",
    "all", "some", "each", "every", "no", "one", "two", "three",
    "first", "second", "third", "last", "next", "previous",
    "above", "below", "same", "other", "another",
    "input", "output", "read", "write", "set", "clear",
    "value", "data", "address", "addr",
    # generic register-modifier adjectives
    "internal", "external", "primary", "secondary", "main",
    "auxiliary", "shared",
})

# v1.6.258 — for #119 ORGANIC. Tokens that surface immediately
# before "register(s)" in README narrative but are USUALLY
# qualifiers / adjectives / type-of-register descriptors, NOT the
# register's actual name. Used by `_post_emit_promote_registers_
# from_readme` to require a structured anchor (pipe-table row OR
# markdown heading) before promoting these. Real register names
# (CONTROL/STATUS/DATA etc.) ARE on this list because their prose
# form is ambiguous — the anchor check separates "the CONTROL
# register" (with `| CONTROL | 0x100 |` table row → keep) from
# "16 upper registers" (no table anchor → drop UPPER).
# Chip-AGNOSTIC: structural English vocabulary.
_REGISTER_NARRATIVE_ADJECTIVE_TOKENS = frozenset({
    "upper", "lower", "respective", "individual", "separate",
    "dedicated", "hardware", "software",
    "generic", "custom", "specific", "special",
    "status", "control", "mask", "pointer", "default", "dummy",
    "configuration", "debug", "test",
    "base", "current", "previous",
})


def _post_emit_promote_registers_from_l12(project: Path) -> None:
    """v1.6.154 (#62) — scan L12.behavioral_sequences[].steps[] for
    register-name references; append synthesised L4.registers
    entries marked low_confidence + strategy=register_name_promotion_from_l12.

    Skips if L4 already has table-extracted registers (no need to
    pollute a clean L4 with prose-promoted entries). Only fires
    when L4 is empty.
    """
    gd = _pl.generated_docs_dir(project)
    l4_path = gd / "L4_REGMAP.json"
    l12_path = gd / "L12_BEHAVIORAL_SEQUENCES.json"
    if not l4_path.is_file() or not l12_path.is_file():
        return
    try:
        l4 = json.loads(l4_path.read_text(encoding="utf-8"))
        l12 = json.loads(l12_path.read_text(encoding="utf-8"))
    except Exception:
        return
    if not isinstance(l4, dict) or not isinstance(l12, dict):
        return
    # Only run when L4 has no table-extracted registers. We don't
    # want to dilute a real regmap.
    existing = l4.get("registers") or []
    if existing:
        return
    sequences = l12.get("behavioral_sequences") or []
    if not isinstance(sequences, list) or not sequences:
        return

    promoted: List[Dict[str, Any]] = []
    seen: Set[str] = set()
    field_map: Dict[str, List[Dict[str, Any]]] = {}

    def _add(name: str, role: str, step_idx: int, step_text: str,
             seq_idx: int) -> None:
        key = name.upper()
        if key in seen:
            return
        seen.add(key)
        promoted.append({
            "name": key,
            "role": role,
            "extraction_strategy": "register_name_promotion_from_l12",
            "low_confidence": True,
            "evidence": {
                "source": "L12_BEHAVIORAL_SEQUENCES",
                "sequence_index": seq_idx,
                "step_index": step_idx,
                "step_text": step_text[:200],
            },
        })

    def _role_from_step(step: str) -> str:
        s = step.lower()
        if "status" in s:
            return "status"
        if "control" in s or "ctrl" in s:
            return "control"
        if any(v in s for v in (" config", "configure", " set ")):
            return "config"
        if "load" in s or "write" in s or "input" in s:
            return "data_in"
        if "read" in s or "result" in s or "output" in s:
            return "data_out"
        return "unspecified"

    for si, seq in enumerate(sequences):
        if not isinstance(seq, dict):
            continue
        steps = seq.get("steps") or []
        if not isinstance(steps, list):
            continue
        for ti, step in enumerate(steps):
            text = step if isinstance(step, str) else (
                step.get("action") if isinstance(step, dict) else None
            )
            if not isinstance(text, str):
                continue
            # Pass A: SCREAMING_SNAKE register names (ADDR_CTRL etc).
            for m in _RE_REGISTER_NAMED_CAPS.finditer(text):
                tok = m.group(1)
                if tok.lower() in _REGISTER_NAME_DENYLIST:
                    continue
                _add(tok, _role_from_step(text), ti, text, si)
            # Pass B: "<word> register" lowercase / mixed-case phrases.
            for m in _RE_REGISTER_PHRASE.finditer(text):
                tok = m.group(1)
                if tok.lower() in _REGISTER_NAME_DENYLIST:
                    continue
                # If a SCREAMING_SNAKE name already matched the same
                # token, skip the lowercase duplicate.
                if tok.upper() in seen:
                    continue
                _add(tok, _role_from_step(text), ti, text, si)
            # Pass C: control/status bits attached to register from
            # this step (best-effort association).
            bits = [bm.group(1).lower()
                    for bm in _RE_CONTROL_BIT.finditer(text)]
            if bits:
                low = text.lower()
                if "control register" in low or "ctrl register" in low:
                    field_map.setdefault("CONTROL", []).extend(bits)
                elif "status register" in low:
                    field_map.setdefault("STATUS", []).extend(bits)

    if not promoted:
        return

    # Attach observed bits as `fields` on matching entries.
    for reg in promoted:
        bits = field_map.get(reg["name"], [])
        if bits:
            seen_bits: Set[str] = set()
            fields = []
            for b in bits:
                if b in seen_bits:
                    continue
                seen_bits.add(b)
                role = ("status_bit"
                        if reg["role"] == "status" else "ctrl_bit")
                fields.append({
                    "name": b,
                    "role": role,
                    "extraction_strategy":
                        "register_name_promotion_from_l12",
                    "low_confidence": True,
                })
            if fields:
                reg["fields"] = fields

    l4["registers"] = promoted
    if l4.get("no_registers_in_input"):
        l4["no_registers_in_input"] = False
    l4["registers_extraction_strategy"] = (
        "register_name_promotion_from_l12"
    )
    try:
        _stamp.dump(l4_path, l4)
    except Exception:
        pass


def _post_emit_crypto_arch_into_L1(project: Path) -> None:
    """v1.6.106 (#36 Bug 4 P1) — crypto-class architecture picker.

    Reads L1.class_path; if in `_CRYPTO_CLASSES`, scans the input
    README for digest_width_bits / message_block_bits / state_bits /
    rounds / latency_cycles_per_block prose. Merges matched fields
    plus per-field `<field>_evidence` into L1.architecture (without
    overwriting any author-supplied value).
    """
    gd = _pl.generated_docs_dir(project)
    if not gd.is_dir():
        return
    l1_path = gd / "L1_DATASHEET.json"
    if not l1_path.is_file():
        return

    try:
        l1 = json.loads(l1_path.read_text(encoding="utf-8"))
    except Exception:
        return
    if not isinstance(l1, dict):
        return
    class_path = l1.get("class_path")
    if class_path not in _CRYPTO_CLASSES:
        return

    readme_text = _read_input_readme_text(project)
    if not readme_text:
        return

    try:
        sys.path.insert(0, str(Path(__file__).resolve().parent))
        from crypto_arch_extractor import extract_crypto_arch
    except Exception:
        return

    crypto_arch = extract_crypto_arch(readme_text)
    if not crypto_arch:
        return

    arch = l1.get("architecture")
    if not isinstance(arch, dict):
        arch = {}
    # Don't overwrite author-supplied values; only fill gaps.
    for k, v in crypto_arch.items():
        if k not in arch:
            arch[k] = v
    l1["architecture"] = arch
    try:
        _stamp.dump(l1_path, l1)
    except Exception:
        pass


def _load_extracted_docs_for_post_pass(project: Path) -> Dict[str, str]:
    """v1.6.289 — for #166 ORGANIC. Re-load text-shaped docs from the
    canonical extracted_docs / input/docs locations so post-emit
    drivers (e.g. `_emit_secondary_clock_domains_from_docs`) can scan
    them without depending on the runner's in-memory dict.

    Chip-AGNOSTIC: pure filesystem walk over the known phase1 layout."""
    out: Dict[str, str] = {}
    for sub in ("phase1/input_doc", "extracted_docs", "input/docs"):
        d = project / sub
        if not d.is_dir():
            continue
        for p in sorted(d.iterdir()):
            if not p.is_file():
                continue
            if p.suffix.lower() not in (
                ".txt", ".md", ".rst", ".adoc",
            ):
                continue
            try:
                out[p.name] = p.read_text(
                    encoding="utf-8", errors="ignore")
            except Exception:
                continue
    return out


def _post_emit_typed_clock_domains(project: Path) -> None:
    """v1.6.89 (#21 Bug 1 P0) — late-binding sibling of
    _post_fix_l8_rtl_consts_flag. Reads L8_RTL_CONSTANTS +
    L8_TIMING_WAVEFORM AFTER L9_INTEGRATION_SPEC has been emitted,
    then invokes _emit_typed_clock_domains so the L9.top_ports
    synthesise-from-clk-shaped-pins branch can finally execute.
    Without this, #20 Bug 4's fix shipped INERT (the call site at
    step 9 always saw L9 absent on disk).
    Chip-AGNOSTIC."""
    try:
        rtl = _try_load_l_doc(project, "L8_RTL_CONSTANTS")
    except Exception:
        return
    if not isinstance(rtl, dict):
        return
    clock_domains = rtl.get("clock_domains") or []
    if not isinstance(clock_domains, list):
        clock_domains = []
    timing_constants = rtl.get("timing_constants") or []
    before_count = len(clock_domains)
    _emit_typed_clock_domains(project, clock_domains, timing_constants)
    # v1.6.289 — for #166 ORGANIC. Layer secondary domains derived
    # from prescaler tables + named peripheral clock pins on top of
    # the typed primary clocks. extracted is loaded lazily because
    # this driver runs after the main extraction pass.
    try:
        _post_extract = _load_extracted_docs_for_post_pass(project)
    except Exception:
        _post_extract = {}
    if _post_extract:
        _emit_secondary_clock_domains_from_docs(_post_extract, clock_domains)
    rtl["clock_domains"] = clock_domains
    if clock_domains:
        rtl["no_clock_domains_in_input"] = False
    _ensure_bool_flags(rtl)
    out = _pl.generated_docs_dir(project) / "L8_RTL_CONSTANTS.json"
    _stamp.dump(out, rtl)
    # v1.6.312 — for #211 P2 ORGANIC. Pre-v1.6.312 the
    # L8_TIMING_WAVEFORM mirror block sat under an outer
    # `if len(clock_domains) != before_count:` guard. The guard
    # only fired on the call that first grew the L8_RTL_CONSTANTS
    # list; any subsequent runner invocation (including the common
    # second-run / cached-L8 shape) saw `before_count` equal to
    # `len(clock_domains)`, the guard evaluated false, and the
    # mirror was skipped entirely. Result: L8_RTL_CONSTANTS stayed
    # populated but L8_TIMING_WAVEFORM stayed empty. Drop the outer
    # guard; the inner condition `isinstance(wfm_cd, list) and not
    # wfm_cd and clock_domains` is sufficient — only mirror when
    # the destination is empty AND the source list is non-empty.
    # Chip-AGNOSTIC: pure structural emptiness check; no chip-class
    # literal participates.
    try:
        wfm = _try_load_l_doc(project, "L8_TIMING_WAVEFORM")
    except Exception:
        wfm = None
    if isinstance(wfm, dict):
        wfm_cd = wfm.get("clock_domains") or []
        if (isinstance(wfm_cd, list) and not wfm_cd
                and clock_domains):
            wfm["clock_domains"] = list(clock_domains)
            _ensure_bool_flags(wfm)
            wfm_out = (_pl.generated_docs_dir(project)
                       / "L8_TIMING_WAVEFORM.json")
            _stamp.dump(wfm_out, wfm)


#: L docs that carry the clock contract. Both are checked because a name at
#: 10 ns in one and 8 ns in the other is contradictory wherever it sits.
_CLOCK_CONTRACT_DOCS = ("L8_RTL_CONSTANTS", "L8_TIMING_WAVEFORM")


def _post_emit_enforce_clock_contract(project: Path) -> List[str]:
    """Final producer-side clock-contract enforcement — runs LAST.

    `_write_l_doc` already applies `clock_contract.enforce` to every L doc it
    writes, but a dozen post-emit hooks re-open the L8 docs and rewrite them
    with `write_text` directly (the typed-clock-domains mirror, the staged-SDC
    ingest, the `clocks[]` seeder, the AID-scaffold purge). Any of them can
    reintroduce a second period for a clock AFTER the chokepoint has run, so
    the contract is re-enforced here, after every hook, on what is actually on
    disk.

    Returns the conflicts that SURVIVED reconciliation — records that each own
    the clock name and pin different periods. There is no principled winner
    between them, so nothing is picked: the conflict is written into the
    document as `clock_contract_conflicts[]` and returned, and the runner
    fails on it. Chip-AGNOSTIC.
    """
    messages: List[str] = []
    for doc_name in _CLOCK_CONTRACT_DOCS:
        try:
            doc = _try_load_l_doc(project, doc_name)
        except Exception:
            continue
        if not isinstance(doc, dict):
            continue
        before = json.dumps(doc, sort_keys=True, ensure_ascii=False)
        _cc.enforce(doc)
        after = json.dumps(doc, sort_keys=True, ensure_ascii=False)
        if after != before:
            try:
                out = _pl.generated_docs_dir(project) / f"{doc_name}.json"
                _stamp.dump(out, doc)
            except OSError:
                pass
        messages.extend(_cc.conflict_messages(doc, where=doc_name))
    return messages


def _post_emit_sdc_constraints(project: Path) -> None:
    """ORGANIC #554 (a) — ingest staged ``input/constraints/*.sdc`` and
    ``input/reference_flow/**/*.sdc`` into L8 (clock_domains[].freq_mhz
    / freq_hz / period_ns) and L19 (fields.constraints_present /
    fields.sdc_constraints_path).

    Pre-#554 phase1 never read these staged files: when the prose docs
    didn't state a clock frequency, L8.clock_domains[].freq_mhz stayed
    `null` and L19.fields.constraints_present stayed `false` even though
    the project staged a real `create_clock -period <ns>` constraint —
    so phase3's SDC-period resolution fell back to the 20ns default.

    The staged SDC is upstream-verified ground truth, so its
    `create_clock -period` WINS over any prose-derived freq/period
    already present on the primary clock_domains entry.

    Chip-AGNOSTIC: standard SDC `create_clock` syntax only; runs
    regardless of `ic_class`.
    """
    sdc_files = _sdc.collect_sdc_files(project)
    if not sdc_files:
        return

    # --- L19_CONSTRAINTS_PDK: constraints_present + path ---
    l19 = _try_load_l_doc(project, "L19_CONSTRAINTS_PDK")
    if isinstance(l19, dict):
        fields = l19.get("fields")
        if not isinstance(fields, dict):
            fields = {}
            l19["fields"] = fields
        fields["constraints_present"] = True
        if not fields.get("sdc_constraints_path"):
            # The former `except ValueError: str(sdc_files[0])` fallback wrote
            # an ABSOLUTE path into the L document whenever the SDC sat
            # outside the project. Unreachable for a file this function
            # collected, but it is the same defect the shared helper exists
            # to refuse — so route both branches through it.
            fields["sdc_constraints_path"] = project_relative_source(
                sdc_files[0], project)[0]
        out = _pl.generated_docs_dir(project) / "L19_CONSTRAINTS_PDK.json"
        _stamp.dump(out, l19)

    primary = _sdc.primary_clock(project)
    if primary is None:
        return
    period_ns = primary["period_ns"]
    freq_hz = int(round(1.0e9 / period_ns)) if period_ns > 0 else None
    port_name = primary.get("port_name")

    # EVERY DECLARED CLOCK, NOT ONLY THE FIRST. `collect_create_clocks`
    # returns one record per `create_clock` in the staged SDC, and this
    # function used to stamp `primary_clock()` alone. A design whose SDC
    # declares more than one clock therefore got ONE typed clock_domains
    # entry and left the rest exactly as shallow as they were before it
    # staged an SDC at all -- while `l8_clock_domains_typed_check` measures
    # EVERY clock name the L layers carry and reports each untyped one.
    #
    # MEASURED on opentitan_aes (2026-09-02): the design declares clk_i AND
    # clk_edn_i, `collect_create_clocks` returned both at period_ns=10.0,
    # only clk_i was stamped, and the gate reported
    #     1/9 clock entries too shallow. Examples: clk_edn_i: missing
    #     freq_hz/freq_mhz/period_ns,role/source
    # -- naming a clock the design HAD declared, in a file this function had
    # already opened and read.
    #
    # A clock the SDC declares and L8 does not carry is APPENDED. That is the
    # design stating a domain, not this runner inventing one: the value and
    # its provenance both come from the design's own staged constraints, and
    # a project with no SDC still reaches none of this. Chip-AGNOSTIC: keyed
    # on the SDC's own port names, no design or vendor literal.
    _declared = [c for c in _sdc.collect_create_clocks(project)
                 if isinstance(c, dict) and c.get("period_ns")]
    _primary_port = str(port_name or "")

    def _same_clock(entry: dict, port: str) -> bool:
        """Whether `entry` already describes the SDC clock on `port`."""
        if not port:
            return False
        for key in ("source_pin", "name", "clock", "port", "port_name"):
            v = entry.get(key)
            if isinstance(v, str) and v.strip() == port:
                return True
        return False

    # --- L8: stamp the primary clock_domains entry from staged SDC ---
    for doc_name in ("L8_RTL_CONSTANTS", "L8_TIMING_WAVEFORM"):
        l8 = _try_load_l_doc(project, doc_name)
        if not isinstance(l8, dict):
            continue
        clock_domains = l8.get("clock_domains")
        if not isinstance(clock_domains, list) or not clock_domains:
            continue
        target = next((d for d in clock_domains
                        if isinstance(d, dict)
                        and d.get("domain_kind") == "primary"), None)
        if target is None:
            target = next((d for d in clock_domains
                            if isinstance(d, dict)), None)
        if target is None:
            continue
        target["freq_hz"] = freq_hz
        target["freq_mhz"] = (freq_hz / 1_000_000.0) if freq_hz else None
        target["period_ns"] = period_ns
        target["source"] = "input/constraints/*.sdc"
        # PROJECT-RELATIVE. `sdc_constraints.collect_create_clocks` stamps
        # `"source": str(sdc)` off an absolute project glob — correct for its
        # report-only consumers, wrong here, because this value is written
        # into L8, a design artefact the flow reads back and diffs. Measured
        # on a fresh minimal project against current main: this line emitted
        # `<abs>/input/constraints/clock.sdc` into BOTH L8 documents, so the
        # four absolute paths in the published corpus are a LIVE defect, not
        # a stale artefact. Note the sibling `source` two lines up and
        # `sdc_constraints_path` above were already relative — only this one
        # value escaped. See l_doc_consumer_contract.project_relative_source.
        target["evidence"] = project_relative_source(
            primary["source"], project)[0]
        if port_name and not target.get("source_pin"):
            target["source_pin"] = port_name
        if port_name and not target.get("name"):
            target["name"] = port_name

        # Every OTHER clock the SDC declares: stamp its existing entry, or
        # append one. `secondary` is what the SDC says it is -- a declared
        # clock that is not the primary -- and never an inferred role.
        for rec in _declared:
            rport = str(rec.get("port_name") or "").strip()
            if not rport or rport == _primary_port:
                continue
            rperiod = rec["period_ns"]
            rfreq = int(round(1.0e9 / rperiod)) if rperiod > 0 else None
            slot = next((d for d in clock_domains
                         if isinstance(d, dict) and _same_clock(d, rport)),
                        None)
            if slot is None:
                slot = {"name": rport, "source_pin": rport,
                        "domain_kind": "secondary",
                        "reset_strategy": "unspecified"}
                clock_domains.append(slot)
            slot["freq_hz"] = rfreq
            slot["freq_mhz"] = (rfreq / 1_000_000.0) if rfreq else None
            slot["period_ns"] = rperiod
            slot["source"] = "input/constraints/*.sdc"
            slot["evidence"] = project_relative_source(
                rec["source"], project)[0]
            slot.setdefault("role", "secondary")
            slot.setdefault("domain_kind", "secondary")
            slot.setdefault("name", rport)
            slot.setdefault("source_pin", rport)

        out = _pl.generated_docs_dir(project) / f"{doc_name}.json"
        _stamp.dump(out, l8)


def _post_emit_l22_coverage_goals(project: Path) -> int:
    """SALVAGE #315 — lift measurable coverage targets stated in the design's
    OWN inputs into ``L22.fields.coverage_goals[]``, the layer that CONSUMES
    them. Returns the number of goals emitted (0 when there is nothing to
    lift, or when L22 / the consumer gate is absent).

    `l22_verification_plan_measurable_check` already FINDS the target — it
    reports `coverage_target_hits_input_docs` — and then FAILs the run with
    TARGET_OUTSIDE_CONSUMING_LAYER because nothing ever writes it back, so no
    downstream coverage gate has a number to compare a measurement against.
    The detection is a solved deterministic problem; only the write-back was
    missing.

    The emitter borrows THAT GATE'S OWN ``_COVERAGE_TARGET_RE`` and
    ``framed_hits()`` rather than reimplementing the predicate — a private
    predicate could drift and emit goals the gate still rejects.

    REFUSES rather than guesses: with no stated target it emits nothing and
    the gate keeps FAILing, which is correct — a fabricated goal would turn a
    real gap into a false PASS. Existing goals are never modified and
    re-running is idempotent. Fail-open on any import/IO error, like its
    `_post_emit_*` neighbours. chip-AGNOSTIC: document vocabulary and
    structure only; no design, PDK or vendor literal.
    """
    try:
        from l22_coverage_goal_emit import run as _l22_cov_emit
    except Exception:
        return 0
    rep = _l22_cov_emit(project)
    n = rep.get("emitted_count", 0) if isinstance(rep, dict) else 0
    if n:
        print(f"      L22 coverage goals: lifted {n} measurable target(s) "
              f"from the design's own inputs")
    return n


def _post_emit_l19_constraint_tokens(project: Path) -> int:
    """Lift constraints stated in design prose into their L19 consumer.

    The existing SDC and floorplan adapters read staged machine-readable
    files.  This adapter covers the complementary input shape: a specification
    that states flow settings in a table or quotes SDC directives but ships no
    deck/config.  It must run after the L19 skeleton exists and before neutral
    protocol overlays can write a contradicting ``constraints_present=false``
    placeholder.

    ``l19_constraint_token_emit`` emits a named SKIPPED/ERROR state.  Preserve
    that distinction here: an expected no-op is zero declarations, while an
    unreadable L19 is raised to the caller and reported by the runner's
    fail-open boundary.  A broken adapter must never disappear as a silent 0.
    """
    from l19_constraint_token_emit import run as _l19_emit

    rep = _l19_emit(project)
    if not isinstance(rep, dict):
        raise RuntimeError("l19_constraint_token_emit returned no report")
    status = rep.get("status")
    if status == "SKIPPED":
        print(f"      L19 prose constraints: SKIPPED — {rep.get('reason')}")
        return 0
    if status != "OK":
        raise RuntimeError(
            f"l19_constraint_token_emit {status}: {rep.get('reason')}")

    n = rep.get("emitted_count", 0)
    if n:
        print(f"      L19 prose context: lifted {n} declaration(s) stated "
              f"in the design's own prose")
    return n


def _post_emit_l9_l19_contract_carrythrough(project: Path) -> int:
    """Lift cross-layer requirements into the L9/L19 consumer fields.

    This producer is ADVISORY to runner execution but load-bearing for Phase-1
    completeness: an extraction failure is named and the completeness gate
    remains non-green. It reads only design inputs and preserves missing input
    as missing; it never manufactures a design verdict.
    """
    from l9_l19_contract_carrythrough import run as _carry

    rep = _carry(project)
    if not isinstance(rep, dict):
        raise RuntimeError("l9_l19_contract_carrythrough returned no report")
    status = rep.get("status")
    if status == "SKIPPED":
        print(f"      L9/L19 contract carry-through: SKIPPED — "
              f"{rep.get('reason')}")
        return 0
    if status != "OK":
        raise RuntimeError(
            f"l9_l19_contract_carrythrough {status}: {rep.get('reason')}")
    n = int(rep.get("emitted_count", 0) or 0)
    if n:
        print(f"      L9/L19 contracts: lifted {n} design-owned consumer "
              "field(s)")
    return n


