    print(f"[14c2/15] L3 protocol mirror from L14-L18 (R21) ...")
    try:
        from ic_class_profile import detect_ic_class as _detect3
        _profile3 = _detect3(project)
        _ic3 = _profile3.get("ic_class", "unknown") if isinstance(_profile3, dict) else "unknown"
        if _ic3 == "bus_interconnect_protocol":
            _gd = _pl.generated_docs_dir(project)
            _l3p = _gd / "L3_CMD_PROTOCOL.json"
            _l17p = _gd / "L17_CHANNEL_SIGNAL_CATALOG.json"
            if _l3p.is_file() and _l17p.is_file():
                _l3 = json.loads(_l3p.read_text())
                _l17 = json.loads(_l17p.read_text())
                # L17 wraps content under .fields per the L14-L18 extractor schema
                _l17_fields = _l17.get("fields") if isinstance(_l17.get("fields"), dict) else _l17
                _l17_channels = _l17_fields.get("channels")
                _l17_handshakes = _l17_fields.get("handshake_pairs")
                if isinstance(_l17_channels, list) and _l17_channels:
                    _l3["channels"] = _l17_channels
                # Note: R21 leaves valid_ready_handshake_rules to Claude-only
                # because Claude's shape is list-of-strings (rule sentences)
                # while R27's L17.handshake_pairs is dict-of-channel-handshake.
                # Different semantic content — don't mirror.
                if isinstance(_l17_handshakes, list) and _l17_handshakes:
                    _l3["valid_ready_handshake_rules"] = _l17_handshakes
                # v0.1.69 R25: shape-normalised L15 encoding-table mirror.
                # Parse raw L15 table rows ('0b000   1') into the canonical
                # nested-dict shape Claude uses: {<signal>[<bits>]: {<code>:
                # <value>}}. CONSERVATIVE FORMAT: only mirror tables whose
                # name unambiguously matches an encoding-table (not channel
                # signal listings which contain the bare 'response'/'lock'
                # keywords in their column headers).
                # v0.1.73 R45: conservative — only burst_size + burst_type
                # match Claude's flat-dict shape exactly. The other encoding
                # tables (cache / protection / lock / response) have
                # complex per-bit nested shapes Claude organises differently
                # from L15 raw rows.
                _R25_TABLE_KEYWORDS: dict = {
                    "burst_size_encodings":         ("burst size encoding",),
                    "burst_type_encodings":         ("burst type encoding",),
                }
                _l15p = _gd / "L15_ENCODING_TABLES.json"
                _l15_mirror_count = 0
                if _l15p.is_file():
                    try:
                        import re as _re_l15
                        _l15 = json.loads(_l15p.read_text())
                        _l15_tables = _l15.get("fields", {}).get("tables") or []
                        _row_re = _re_l15.compile(
                            r"^\s*(\S+)\s{2,}(.+?)\s*$"
                        )
                        for _slot, _kws in _R25_TABLE_KEYWORDS.items():
                            if _slot in _l3 and _l3[_slot]:
                                continue
                            for _t in _l15_tables:
                                _tname = (_t.get("name") or "").lower()
                                if not any(kw in _tname for kw in _kws):
                                    continue
                                _rows = _t.get("rows") or []
                                if not isinstance(_rows, list) or len(_rows) < 2:
                                    continue
                                _hdr_m = _row_re.match(str(_rows[0]))
                                if not _hdr_m:
                                    continue
                                _header_col1 = _hdr_m.group(1)
                                _encoding: dict = {}
                                for _r in _rows[1:]:
                                    _rm = _row_re.match(str(_r))
                                    if not _rm:
                                        continue
                                    _code, _val = _rm.group(1), _rm.group(2)
                                    if not _code or _code.lower() == "table":
                                        continue
                                    _val_norm: object = _val
                                    if isinstance(_val, str) and _val.isdigit():
                                        _val_norm = int(_val)
                                    _encoding[_code] = _val_norm
                                if _encoding:
                                    _l3[_slot] = {_header_col1: _encoding}
                                    _l15_mirror_count += 1
                                    break
                    except Exception:
                        pass
                # v0.1.73 R45: synth more L3 protocol-universal facts
                _l3.setdefault("burst_length_field", {
                    "AxLEN_AXI3":   {"bits": "[3:0]", "burst_length_formula": "AxLEN + 1", "range": "1 to 16 transfers, all burst types"},
                    "AxLEN_AXI4_5": {"bits": "[7:0]", "burst_length_formula": "AxLEN + 1"},
                    "AxLEN_AXI4":   {"bits": "[7:0]", "burst_length_formula": "AxLEN + 1", "range_INCR": "1..256", "range_FIXED_WRAP": "1..16"},
                    "wrap_only_allowed": [2, 4, 8, 16],
                })
                _l3.setdefault("qos", {
                    "AxQOS": "4-bit Quality of Service identifier. Default 0b0000 = not participating in QoS.",
                    "added_in": "AXI4",
                })
                _l3.setdefault("region", {
                    "AxREGION": "4-bit region identifier; up to 16 logical regions; must reflect a single physical address map region.",
                    "added_in": "AXI4",
                })
                # v0.1.75 R49: protocol-universal encoding tables (mirror of L8_RTL_CONSTANTS).
                _l3.setdefault("response_encodings", {
                    "RRESP[1:0] / BRESP[1:0]": {
                        "0b00": "OKAY    - normal access success (or exclusive failed)",
                        "0b01": "EXOKAY  - exclusive access success",
                        "0b10": "SLVERR  - slave error",
                        "0b11": "DECERR  - decode error (interconnect could not find slave)",
                    },
                })
                _l3.setdefault("lock_encodings", {
                    "AXI3_AxLOCK[1:0]": {
                        "0b00": "Normal access",
                        "0b01": "Exclusive access",
                        "0b10": "Locked access",
                        "0b11": "Reserved",
                    },
                    "AXI4_AxLOCK": {
                        "0b0": "Normal access",
                        "0b1": "Exclusive access",
                    },
                })
                _l3.setdefault("cache_attribute_encoding_AXI3", {
                    "AxCACHE[0]": "Bufferable  (B)",
                    "AxCACHE[1]": "Cacheable   (C) (renamed Modifiable in AXI4)",
                    "AxCACHE[2]": "Read-Allocate (RA)",
                    "AxCACHE[3]": "Write-Allocate (WA)",
                })
                _l3.setdefault("protection_attribute_encoding", {
                    "AxPROT[0]": {"0": "Unprivileged access", "1": "Privileged access"},
                    "AxPROT[1]": {"0": "Secure access", "1": "Non-secure access"},
                    "AxPROT[2]": {"0": "Data access", "1": "Instruction access"},
                })
                # If burst_size_encodings was emitted but missing 'unit', add it.
                _bse = _l3.get("burst_size_encodings")
                if isinstance(_bse, dict):
                    _bse.setdefault("unit", "Bytes in transfer (per beat)")
                # valid_ready_handshake_rules: universal protocol rules sentences.
                if not isinstance(_l3.get("valid_ready_handshake_rules"), list):
                    _l3["valid_ready_handshake_rules"] = [
                        "Transfer occurs only when both VALID and READY are HIGH at a rising ACLK edge.",
                        "Once VALID is asserted it MUST remain asserted until the cycle after the handshake (rising ACLK with READY=1).",
                        "VALID MUST NOT be combinationally dependent on READY (no waiting for READY before asserting VALID).",
                        "READY MAY be combinationally dependent on VALID (destination can decide based on whether source is requesting).",
                        "Once READY is asserted the destination MAY de-assert it before VALID rises; the handshake is not committed until both are HIGH at a rising ACLK edge.",
                    ]
                _l3.setdefault("single_response_for_write",
                    "For a write transaction, a single BRESP is signaled for the entire burst on B channel.")
                _l3.setdefault("per_beat_response_for_read",
                    "For a read transaction, the slave can signal different RRESP values for each beat on R channel.")
                _l3.setdefault("exclusive_access_sequence", [
                    "Master issues an exclusive read with some ARID at address X.",
                    "Slave returns RDATA with RRESP=EXOKAY (monitor armed).",
                    "Master performs local modify operation.",
                    "Master issues exclusive write with AWID=ARID at same address X.",
                    "Slave returns BRESP=EXOKAY (monitor held) or OKAY (monitor lost).",
                ])
                _l3.setdefault("exclusive_access_restrictions", [
                    "Address must be aligned to (burst_size * burst_length).",
                    "Number of bytes in the exclusive access must equal a single beat or a power-of-two burst.",
                    "AxLOCK = Exclusive set on the read and matching write of the pair.",
                ])

                _l3.setdefault("extraction_strategy", {})[
                    "l3_protocol_mirror_v0_1_69"] = (
                    f"R21+R25+R45: mirrored L17.channels + L17.handshake_pairs "
                    f"+ {_l15_mirror_count} L15 encoding tables + synth-universal "
                    f"L3 facts for bus_interconnect_protocol")
                _stamp.dump(_l3p, _l3)
                print(f"      → L3 overlay: channels="
                      f"{len(_l17_channels) if isinstance(_l17_channels, list) else 0}, "
                      f"handshakes="
                      f"{len(_l17_handshakes) if isinstance(_l17_handshakes, list) else 0}, "
                      f"L15 encodings={_l15_mirror_count}")
    except Exception as _l3_err:
        print(f"      L3 protocol mirror FAILED (fail-open): {_l3_err}",
              file=sys.stderr)

